        #region 日付型変換メソッド

        private DateTime? ChangeDateTime(object date)
        {
            if (date == DBNull.Value)
            {
                return null;
            }
            else if (date == null)
            {
                return null;
            }
            else
            {
                return (DateTime)date;
            }
        }
