        #region 文字列連結メソッド
        /// <summary>
        /// 文字列連結用
        /// </summary>
        /// <returns>連結後文字列</returns>
        private string RenketuString(string strA, string strB)
        {
            // 文字列連結用
            StringBuilder moziRenketu = new StringBuilder();

            // 文字列strAをセット
            moziRenketu.Append(strA);

            // 文字列strBをセット
            moziRenketu.Append(strB);

            // 連結された文字列を返す
            return ComATool.Function.AnyToString(moziRenketu);
        }

        /// <summary>
        /// 文字列連結用
        /// </summary>
        /// <returns>連結後文字列</returns>
        private string RenketuString(string strA, string strB, string strC)
        {
            // 文字列連結用
            StringBuilder moziRenketu = new StringBuilder();

            // 文字列strAをセット
            moziRenketu.Append(strA);

            // 文字列strBをセット
            moziRenketu.Append(strB);

            // 文字列strCをセット
            moziRenketu.Append(strC);

            // 連結された文字列を返す
            return ComATool.Function.AnyToString(moziRenketu);
        }

