        /// <param name="rowNo"></param>
        /// <param name="colmnNo"></param>
        /// <returns></returns>
        private string GetStringColumnValue(int valuetype, int rowNo, int colmnNo)
        {
            if (valuetype == KBN_KOUMOKUCHK_INPUT || valuetype == KBN_KOUMOKUCHK_AFTERSETVALUE)
            {
                if (colmnNo >= COL_COUNT)
                {
                    //待避用項目
                    return ComATool.Function.AnyToString(tempActiveInputDataRow[colmnNo]);
                }
                else
                {
                    return ((WinAToolUI.Obic7TextString)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, colmnNo)).Value;
                }
            }
            else
            {
                return ComATool.Function.AnyToString(obic7MultilineCheckGridDetail.GetDisplayedData().Table.DefaultView[rowNo][colmnNo]);
            }
        }

