                    return ComATool.Function.AnyToString(tempActiveInputDataRow[RenketuString(taishakuname, ctlname)]);
                }
                else
                {
                    return ((WinAToolUI.Obic7TextString)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, RenketuString(STRCTLNAME, taishakuname, ctlname))).Value;
