                }
                else
                {
                    if (colmnNo >= COL_COUNT)
                    {
                        //待避用項目
                        tempActiveInputDataRow[colmnNo] = ((DateTime)value).ToString("yyyy/MM/dd");
                    }
                    else
                    {
                        ((WinAToolUI.Obic7TextDatetime)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, colmnNo)).Text = ((DateTime)value).ToString("yyyy/MM/dd");
                    }
                }
            }
            else
