        private void SetDatetimeColumnValue(int valuetype, int rowNo, string taishakuname, string ctlname, DateTime? value)
        {
            if (valuetype == KBN_KOUMOKUCHK_INPUT || valuetype == KBN_KOUMOKUCHK_AFTERSETVALUE)
            {
                if (value == null)
                {
                    if (obic7MultilineCheckGridDetail.GetColumnObject(rowNo, RenketuString(DATCTLNAME, taishakuname, ctlname)) == null)
                    {
                        //待避用項目
                        tempActiveInputDataRow[RenketuString(taishakuname, ctlname)] = DBNull.Value;
                    }
                    else
                    {
                        ((WinAToolUI.Obic7TextDatetime)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, RenketuString(DATCTLNAME, taishakuname, ctlname))).Value = null;
                    }
                }
                else
                {
                    if (obic7MultilineCheckGridDetail.GetColumnObject(rowNo, RenketuString(DATCTLNAME, taishakuname, ctlname)) == null)
                    {
                        //待避用項目
                        tempActiveInputDataRow[RenketuString(taishakuname, ctlname)] = ((DateTime)value).ToString("yyyy/MM/dd");
                    }
                    else
                    {
                        ((WinAToolUI.Obic7TextDatetime)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, RenketuString(DATCTLNAME, taishakuname, ctlname))).Text = ((DateTime)value).ToString("yyyy/MM/dd");
                    }
                }

            }
            else
            {
                if (value == null)
                {
                    obic7MultilineCheckGridDetail.GetDisplayedData().Table.DefaultView[rowNo][RenketuString(taishakuname, ctlname)] = DBNull.Value;
                }
                else
                {
                    obic7MultilineCheckGridDetail.GetDisplayedData().Table.DefaultView[rowNo][RenketuString(taishakuname, ctlname)] = ((DateTime)value).ToString("yyyy/MM/dd");
                }
            }
        }

