        #region マルチコントロールを実体化
        /// <summary>
        /// マルチラインコントロールを実体化
        /// </summary>
        private void SetMultiLineControl()
        {
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //メモ情報ボタンの画面制御を行う
            //借方・貸方メモ情報のタイトル・ボタンを Visible = False とし、借方・貸方メモ情報が空白の分、
            //明細の各項目と合計金額を左に詰める
            if (this.memoSiyouFlag == KBN_MEMOSIYOU_NO)
            {
                this.obic7LabelStringKariMemo.Visible = false;
                this.obic7ButtonWithLogicKariMemo.Location = new System.Drawing.Point(this.obic7ButtonWithLogicKariMemo.Location.X, this.obic7ButtonWithLogicKariMemo.Location.Y + this.obic7PanelLine.Size.Height);
                this.obic7LabelStringKasiMemo.Visible = false;
                this.obic7ButtonWithLogicKasiMemo.Location = new System.Drawing.Point(this.obic7ButtonWithLogicKasiMemo.Location.X, this.obic7ButtonWithLogicKasiMemo.Location.Y + this.obic7PanelLine.Size.Height);
                this.SetNewLocationByMemoFlag();
            }
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
            //マルチライン作成
            obic7MultilineCheckGridDetail = new WinAToolUI.Obic7MultilineCheckGrid();
            //明細コントロール横幅
            obic7MultilineCheckGridDetail.BaseWidth = 0;
            //カラム数設定(非表示カラム分もカウントする)
            obic7MultilineCheckGridDetail.MaxColNumber = COL_COUNT;
            //表示行数設定
            obic7MultilineCheckGridDetail.MaxRowNumber = DSPLAY_ROW_COUNT;
            //明細パネルをセット
            obic7MultilineCheckGridDetail.Initialize(obic7PanelLine);
            //イベントを関連付ける
            //RowValidating
            obic7MultilineCheckGridDetail.RowValidating += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.RowCancelEventHandler(obic7MultilineCheckGridDetail_RowValidating);
            //RowInserting
            obic7MultilineCheckGridDetail.RowInserting += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.InsertRowCancelEventHandler(obic7MultilineCheckGridDetail_RowInserting);
            //RowUpdating
            obic7MultilineCheckGridDetail.RowUpdating += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.UpdateRowCancelEventHandler(obic7MultilineCheckGridDetail_RowUpdating);
            //RowDeleting
            obic7MultilineCheckGridDetail.RowDeleting += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.DeleteRowCancelEventHandler(obic7MultilineCheckGridDetail_RowDeleting);
            //ColumnItemValidating
            obic7MultilineCheckGridDetail.ColumnItemValidating += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.MultilineItemCancelEventHandler(obic7MultilineCheckGridDetail_ColumnItemValidating);
            //ColumnItemEnter
            obic7MultilineCheckGridDetail.ColumnItemEnter += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.MultilineItemEventHandler(obic7MultilineCheckGridDetail_ColumnItemEnter);
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //ColumnButtonClick
            obic7MultilineCheckGridDetail.ColumnButtonClick += new WinAToolUI.Obic7MultilineAbstract.ClickEventHandler(obic7MultilineCheckGridDetail_ColumnButtonClick);
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
            //RowInserted
            obic7MultilineCheckGridDetail.RowInserted += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.InsertRowEventHandler(obic7MultilineCheckGridDetail_RowInserted);
            //Leave
            obic7MultilineCheckGridDetail.Leave += new Obic7fx.Win.A0000.Tool.UI.Obic7MultilineAbstract.LeaveEventHandler(obic7MultilineCheckGridDetail_Leave);
            //MoveScrollAfter
            obic7MultilineCheckGridDetail.MoveScrollAfter += new EventHandler(obic7MultilineCheckGridDetail_MoveScrollAfter);
        }
