        /// <summary>
        /// Job操作権限一覧を参照しコンボボックスにアイテムを追加
        /// </summary>
        private void SetOperationMode()
        {
            //処理モードコンボボックスを初期化
            obic7ComboBoxMode.Items.Clear();
            if (CheckOperationAuthority(ComATool.Function.AnyToString(ComATool.Obic7JobSecurities.DataInsert), base.jobOperationAuthority))
            {
                //新規モードが使用可能であればコンボボックスに追加
                this.obic7ComboBoxMode.Items.Add(MODE_INSERT);
            }
            if (CheckOperationAuthority(ComATool.Function.AnyToString(ComATool.Obic7JobSecurities.DataUpdate), base.jobOperationAuthority))
            {
                //修正モードが使用可能であればコンボボックスに追加
                this.obic7ComboBoxMode.Items.Add(MODE_UPDATE);
            }
            if (CheckOperationAuthority(ComATool.Function.AnyToString(ComATool.Obic7JobSecurities.DataDelete), base.jobOperationAuthority))
            {
                //削除モードが使用可能であればコンボボックスに追加
                this.obic7ComboBoxMode.Items.Add(MODE_DELETE);
            }
            if (CheckOperationAuthority(ComATool.Function.AnyToString(ComATool.Obic7JobSecurities.DataSelect), base.jobOperationAuthority))
            {
                //照会モードが使用可能であればコンボボックスに追加
                this.obic7ComboBoxMode.Items.Add(MODE_SELECT);
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            //「添付」モードはプルダウンの最後に出したいため、直前でDataUpdateの使用可否を見ている箇所とは別に分岐を実装
            if (CheckOperationAuthority(ComATool.Function.AnyToString(ComATool.Obic7JobSecurities.DataUpdate), base.jobOperationAuthority))
            {
                //添付モードが使用可能であればコンボボックスに追加
                this.obic7ComboBoxMode.Items.Add(MODE_TENPU);
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            //選択可能行が存在すれば最上位の項目を選択
            if (this.obic7ComboBoxMode.Items.Count > 0)
            {
                this.obic7ComboBoxMode.SelectedIndex = 0;
            }
            else
            {
                this.obic7ComboBoxMode.SelectedIndex = -1;
            }
        }

        #endregion

        #region 操作が可能かどうかを返却する。
        /// <summary>
        /// 指定された操作IDについてJob操作権限一覧を照会。
        /// 操作が可能かどうかを返却する。
        /// </summary>
        /// <param name="operationID">チェック対象操作ID</param>
        /// <param name="authority">Job操作権限一覧</param>
        /// <returns>
        ///     true :操作可能
        ///     false:操作不可能
        /// </returns>
        private bool CheckOperationAuthority(string operationID, DataTable authority)
        {
            //チェック結果
            bool result = false;
            //Select結果
            DataRow[] rowSelect;
            //有効なデータテーブルでなければチェックを行わずにfalseを返却
            if (ComATool.Function.IsValidDataTable(authority))
            {
                //指定された操作IDの行から操作権限を取得
                rowSelect = authority.Select(" JobOperationID = " + ComATool.Function.RowFilterEscape(operationID) + " ");
                //イレギュラーケースだが、該当するJob操作IDがない場合を考慮
                if (rowSelect.Length <= 0)
                {
                    //該当するJob操作IDがなければ（JobOperationテーブルに未登録であれば）権限ありとみなす
                    result = true;
                }
                else
                {
                    //権限テーブルよりユーザの使用権限を取得
                    result = ComATool.Function.AnyToBool(rowSelect[0]["OperationAuthority"], false);
                }
            }
            return result;
        }
        #endregion

