            {
                //未承認伝票参照可能区分セット
                denpyouSanshouKBN = ComATool.Function.AnyToInt32(dtDenSec.Rows[0]["DenpyouSanshouKBN"]);
                //未承認伝票参照ランクセット
                denpyouSanshouRank = ComATool.Function.AnyToString(dtDenSec.Rows[0]["DenpyouSanshouRank"]);
            }

            //事業所セキュリティ取得
            using (DataTable dtZigSec = WinMToolSearchCom.M0000MS_MA_Security.GetZigyoushoSecurity(ComATool.Logic.CurrentUser.UserID))
            {
                //セキュリティパターンコードセット
                zigyoushoSecurityPatternCD = ComATool.Function.AnyToString(dtZigSec.Rows[0]["SecurityPatternCD"]);
                //セキュリティ状態区分セット
                zigyoushoSecurityJoutaiKBN = ComATool.Function.AnyToInt32(dtZigSec.Rows[0]["SecurityJoutaiKBN"]);
            }

            //部門セキュリティ取得
            using (DataTable dtBumSec = WinMToolSearchCom.M0000MS_MA_Security.GetBumonSecurity(ComATool.Logic.CurrentUser.UserID))
            {
                //セキュリティパターンコードセット
                bumonSecurityPatternCD = ComATool.Function.AnyToString(dtBumSec.Rows[0]["SecurityPatternCD"]);
            }

            //総勘定科目セキュリティ
            using (DataTable dtkanSec = WinMToolSearchCom.M0000MS_MA_Security.GetKanjouSecurity(ComATool.Logic.CurrentUser.UserID))
            {
                //セキュリティパターンコードセット
                kanjouSecurityPatternCD = ComATool.Function.AnyToString(dtkanSec.Rows[0]["SecurityPatternCD"]);
            }

            //伝票区分セキュリティ
            using (DataTable dtdenSec = WinMToolSearchCom.M0000MS_MA_Security.GetDenpyouKBNSecurity(ComATool.Logic.CurrentUser.UserID))
            {
                //セキュリティパターンコードセット
                denKBNSecurityPatternCD = ComATool.Function.AnyToString(dtdenSec.Rows[0]["SecurityPatternCD"]);
            }

            //初期事業所コード取得
            using (DataTable dtDefZig = WinMToolSearchCom.M0000MS_MA_Security.GetDefaultZigyoushoCD(ComATool.Logic.CurrentUser.UserID))
            {
                //初期表示事業所コードセット
                defaultZigyoushoCD = ComATool.Function.AnyToString(dtDefZig.Rows[0]["ZigyoushoCD"]);
            }

            //本支店セキュリティフラグ取得
            using (DataTable dthonsiten = WinMToolSearchCom.M0000MS_MA_Security.GetHonsitenSecurity(ComATool.Logic.CurrentUser.UserID))
            {
                //本支店セキュリティフラグセット
                honsitenSecurityFlag = ComATool.Function.AnyToInt32(dthonsiten.Rows[0]["HonsitenSecurityFlag"]);
            }

        }
