                bunsekiCD4NyuuryokuSeigyoFlg = ComATool.Function.AnyToByte(dtBunsekiCDSeigyoFlg.Rows[0]["BunsekiCD4NyuuryokuSeigyoFlg"]);
                //分析コード5入力制御フラグ
                bunsekiCD5NyuuryokuSeigyoFlg = ComATool.Function.AnyToByte(dtBunsekiCDSeigyoFlg.Rows[0]["BunsekiCD5NyuuryokuSeigyoFlg"]);
                //資金コード入力制御フラグ
