        /// <summary>
        /// ユーザグループコード取得
        /// </summary>
        private void GetUserGroupCD()
        {
            StringBuilder sqlSelect = new StringBuilder();

            // セキュリティ情報の取得
            sqlSelect.Append(" SELECT ");
            sqlSelect.Append("       M0000MS_MA_UserGroupMember.UserGroupCD ");
            sqlSelect.Append(" FROM    M0000MS_MA_UserGroupMember AS M0000MS_MA_UserGroupMember ");
            sqlSelect.Append(" WHERE  M0000MS_MA_UserGroupMember.UserID = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");

            //ユーザグループCD取得
            userGroupCD = ComATool.Function.AnyToString(businessDB.ExecuteScalar(sqlSelect.ToString()));
        }
