        /// <summary>
        /// 会計コントロールマスタの情報を取得
        /// </summary>
        private void GetKaikeiControlMaster()
        {
            using (DataTable dtKaikeiControlM = WinMToolSearchCom.M0000MS_MA_KaikeiControl.SelectByKey(1, ""))
            {
                //取得値有効チェック
                if ((dtKaikeiControlM != null) && (dtKaikeiControlM.Rows.Count != 0))
                {
                    //入力可能伝票行数を取得
                    inputKanouGyouCount = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["DenpyouGyousuu"]);
                    //事業所部門パターンチェック区分を取得
                    zigyoushoBumonCheckKBN = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["ZigyoushoBumonCheckKBN"]);
                    //取引先パターンチェック区分を取得
                    torihikisakiCheckKBN = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["TorihikisakiCheckKBN"]);
                    //税区分入力制限フラグを取得
                    zeiKBNNyuuryokuFlag = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["ZeiKBNNyuuryokuFlag"]);
                    //科目変更時部門表示フラグを取得
                    henkouHyouziFlag = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["HenkouHyouziFlag"]);
                    //税フォーカスフラグを取得
                    zeiFocusFlag = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["ZeiFocusFlag"]);
                    //分析コードフォーカスフラグを取得
                    bunsekiCDFocusFlag = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["BunsekiCDFocusFlag"]);
                    //本店集中制度適用フラグを取得
                    hontenShuutyuuFlag = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["HontenShuutyuuFlag"]);
                    //本社事業所セキュリティフラグを取得
                    honshaZigyoushoSecurityFlag = 0;
                    //基準区分取得
                    kijunKbn = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["KijunKbn"]);
                    //部門科目種別パターンチェック区分
                    this.bumonKamokuShubetuPatternCheckKBN = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["BumonKamokuShubetuPatternCheckKBN"]);
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    sonotaTenpuFileRiyouFLG = ComATool.Function.AnyToInt32(dtKaikeiControlM.Rows[0]["TenpuFileRiyouFlag"]);
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
                }
            }
        }

        /// <summary>
        /// 財務コントロールマスタの情報を取得
        /// </summary>
        private void GetZaimuControlMaster()
        {
            using (DataTable dtControlM = WinMToolSearchCom.M0000MS_MA_Control.SelectByKey(1, ""))
            {
                //取得値有効チェック
                if ((dtControlM != null) && (dtControlM.Rows.Count != 0))
                {
                    //承認要否区分
                    shouninKBN = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["ShouninKBN"]);
                    //基準日を取得
                    if (dtControlM.Rows[0]["KijunDate"] == DBNull.Value)
                    {
                        kijunYMD = null;
                    }
                    else
                    {
                        kijunYMD = (DateTime)dtControlM.Rows[0]["KijunDate"];
                    }
                    //決算伝票締日
                    if (dtControlM.Rows[0]["KessanDenpyouSimeDate"] == DBNull.Value)
                    {
                        kessanDenpyouSimeDate = null;
                    }
                    else
                    {
                        kessanDenpyouSimeDate = (DateTime)dtControlM.Rows[0]["KessanDenpyouSimeDate"];
                    }
                    //伝票採番区分
                    denpyouSaibanKBN = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["DenpyouSaibanKBN"]);
                    //仮伝票採番区分
                    kariDenpyouSaibanKBN = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["KariDenpyouSaibanKBN"]);
                    //伝票即伝発行フラグ
                    sokudenFlag = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["SokudenFlag"]);
                    //伝票番号カウンタ桁数
                    denpyouNOKetasuu = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["DenpyouNOKetasuu"]);
                    //仕訳伝票出力用紙区分
                    denpyouYousiKBN = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["DenpyouYousiKBN"]);
                    //過年度遡及伝票締日
                    if (dtControlM.Rows[0]["KanendoSokyuuDenpyouSimeDate"] == DBNull.Value)
                    {
                        kanendoSokyuuDenpyouSimeDate = null;
                    }
                    else
                    {
                        kanendoSokyuuDenpyouSimeDate = (DateTime)dtControlM.Rows[0]["KanendoSokyuuDenpyouSimeDate"];
                    }
                    //締管理区分
                    simeKanriKbn = ComATool.Function.AnyToInt32(dtControlM.Rows[0]["SimeKanriKBN"]);
                    // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                    //分析別残高更新区分
                    bunsekibetuZandakaSiyouKBN = ComATool.Function.AnyToByte(dtControlM.Rows[0]["BunsekibetuZandakaSiyouKBN"]);
                    // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    //追加添付使用区分
                    tuikaTenpuSiyouKBN = ComATool.Function.AnyToByte(dtControlM.Rows[0]["TuikaTenpuSiyouKBN"]);
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                }
            }
        }
        //  2016/02/02  追加 T.Sato  (36050)決算伝票締日がチェックされない場合がある  終了

