        #region 会計共通ユーザグループ設定マスタの情報を取得
        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
        /// <summary>
        /// 会計共通ユーザグループ設定マスタの情報を取得
        /// </summary>
        private void GetKaikeiUserGroupSetteiMaster()
        {
            //[会計共通ユーザグループ設定マスタクラス]より、メモ使用フラグを取得
            var result = WinMToolSearchCom.M0000MS_MA_KaikeiUserGroupSettei.GetMemoSiyouFlag(ComATool.Logic.CurrentUser.UserID);
            //該当データが存在しない場合、メモ使用フラグ=1として処理を行う
            this.memoSiyouFlag = result != null ? ComATool.Function.AnyToInt32(result) : 1;
        }
