        #region 初期表示セット
        /// <summary>
        /// 初期表示セット
        /// </summary>
        private void SetDefDisplay()
        {
            //事業所コードセット
            obic7TextStringZigyoushoCD.Value = defaultZigyoushoCD;

            //発生日セット
            if (kijunYMD == null)
            {
                //基準日がnullの場合システム日付セット
                obic7TextDatetimeHasseiDate.Value = GetSystemDate();
            }
            else
            {
                //基準日をセット
                obic7TextDatetimeHasseiDate.Value = kijunYMD;
            }

            //事業所情報取得
            using (DataTable dtZig = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(obic7TextStringZigyoushoCD.Value, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, 0, 0, 0, ""))
            {
                if (dtZig == null || dtZig.Rows.Count == 0)
                {
                    //事業所情報が取得できない場合
                    obic7TextStringZigyoushoCD.Value = "";
                }
                else if (dtZig.Rows[0]["ZigyoushoName"] == DBNull.Value)
                {
                    //事業所名がnullの場合
                    obic7TextStringZigyoushoCD.Value = "";
                }
                else
                {
                    //本支店勘定科目マスタクラスより取得
                    using (DataTable dtHonsitenKanjou = WinMToolSearchCom.M0000MS_MA_HonsitenKanjou.SelectByKaiteiDate(obic7TextStringZigyoushoCD.Value, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, honshaZigyoushoSecurityFlag, ""))
                    {
                        if (dtHonsitenKanjou == null || dtHonsitenKanjou.Rows.Count == 0)
                        {
                            //本支店勘定科目が取得できない場合
                            obic7TextStringZigyoushoCD.Value = "";
                        }
                        else
                        {
                            //事業所情報取得
                            obic7LabelStringZigyoushoName.Value = ComATool.Function.AnyToString(dtZig.Rows[0]["ZigyoushoNameRyaku"]);
                            //事業所改定日
                            zigyoushoCDKaiteiDate = (DateTime)dtZig.Rows[0]["KaiteiDate"];
                            //セット残高日付
                            setZandakaDate = (DateTime)dtZig.Rows[0]["SetZandakaDate"];
                            if (dtZig.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                            {
                                //伝票締日
                                denpyouSimeDate = null;
                            }
                            else
                            {
                                //伝票締日
                                denpyouSimeDate = (DateTime)dtZig.Rows[0]["DenpyouSimeDate"];
                            }
                        }
                    }
                }
            }

            //発生日関連項目取得
            //総勘定科目コントロールマスタよりデータを取得
            using (DataTable dtKanControlM = WinMToolSearchCom.M0000MS_MA_KanjouControl.SelectByKaiteiDate((DateTime)obic7TextDatetimeHasseiDate.Value, ""))
            {
                //取得値有効チェック
                if ((dtKanControlM != null) && (dtKanControlM.Rows.Count != 0))
                {
                    //仮払消費税科目コード
                    kariBaraiZeiKamokuCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["KaribaraiZeiCD"]);
                    //仮受消費税科目コード
                    kariUkeZeiKamokuCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["KariukeZeiCD"]);
                    //諸口科目コード
                    shokutiCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["ShokutiCD"]);
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                    //リバースチャージ払科目コード
                    rcHaraiCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["RCHaraiCD"]);
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了
                }
            }

            //仮払消費税科目コードのチェック
            using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariBaraiZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, ""))
            {
                //取得値有効チェック
                if ((dtKanjouM != null) && (dtKanjouM.Rows.Count != 0))
                {
                    //仮払消費税科目コード改定日
                    kariBaraiZeiKamokuCDKaiteiDate = (DateTime?)dtKanjouM.Rows[0]["KaiteiDate"];
                    //仮払消費税科目コード貸借区分
                    kariBaraiZeiKamokuCDTaishakuKBN = ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]);
                }
            }

            //仮受消費税科目コードのチェック
            using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariUkeZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, ""))
            {
                //取得値有効チェック
                if ((dtKanjouM != null) && (dtKanjouM.Rows.Count != 0))
                {
                    //仮受消費税科目コード改定日
                    kariUkeZeiKamokuCDKaiteiDate = (DateTime?)dtKanjouM.Rows[0]["KaiteiDate"];
                    //仮受消費税科目コード貸借区分
                    kariUkeZeiKamokuCDTaishakuKBN = ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]);
                }
            }

            //月度期間マスタチェック
            using (DataTable dtGetudoM = WinMToolSearchCom.M0000MS_MA_GetudoKikan.SelectByKijunbi((DateTime)obic7TextDatetimeHasseiDate.Value, ""))
            {
                //取得値有効チェック
                if ((dtGetudoM != null) && (dtGetudoM.Rows.Count != 0))
                {
                    //決算期
                    kessanki = ComATool.Function.AnyToInt32(dtGetudoM.Rows[0]["Kessanki"]);
                    //月度番号
                    monthNO = ComATool.Function.AnyToInt32(dtGetudoM.Rows[0]["MonthNO"]);
                }
            }

            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //基準区分のセット
            this.obic7TextNumberKijunKBN.Value = kijunKbn;
            using (DataTable dtComCd = WinMToolSearchCom.M0000MS_CommonCode.SelectByKey(COMMON_CD_KIJUNKBN, ComATool.Function.AnyToString(kijunKbn), ""))
            {
                //取得値有効チェック
                if ((dtComCd != null) && (dtComCd.Rows.Count != 0))
                {
                    //決算期
                    this.obic7LabelStringKijunKBNName.Text = ComATool.Function.AnyToString(dtComCd.Rows[0]["CodeName"]);
                }
            }
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑

            //伝票区分取得
            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //using (DataTable dtDen = WinMToolSearchCom.M0000MS_MA_DenpyouKBN.SelectForSearch(denKBNSecurityPatternCD, 0, " AND CONVERT(int, DenpyouKBN) < 20 ", ""))
            //using (DataTable dtDen = WinMToolLogic.M0000MS_MA_DenpyouKBN.SelectByKijunKBN(denKBNSecurityPatternCD, 1, null, kijunKbn))
            using (WinMToolSearch.MA_DenpyouKBN denpyouSearch = new WinMToolSearch.MA_DenpyouKBN())
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
            {
                DataTable dtDen = denpyouSearch.SelectByKijunKBN(denKBNSecurityPatternCD, 1, null, kijunKbn);
                if (dtDen != null && dtDen.Rows.Count != 0)
                {
                    //伝票区分セット
                    obic7TextStringDenpyouKBN.Value = ComATool.Function.AnyToString(dtDen.Rows[0]["DenpyouKBN"]);
                    //伝票区分名セット
                    obic7LabelStringDenpyouKBNName.Value = ComATool.Function.AnyToString(dtDen.Rows[0]["DenpyouKBNName"]);
                    //決算フラグセット
                    kessanFlg = ComATool.Function.AnyToInt32(dtDen.Rows[0]["KessanFlag"]);
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //本仮伝フラグセット
                    honKaridenFlag = ComATool.Function.AnyToInt32(dtDen.Rows[0]["HonKaridenFlag"]);
                    //過年度遡及修正フラグセット
                    kanendoSokyuuShuuseiFlag = ComATool.Function.AnyToInt32(dtDen.Rows[0]["KanendoSokyuuShuuseiFlag"]);
                    if (dtDen.Rows[0]["SokyuuShoriDate"] == DBNull.Value)
                    {
                        //遡及年月日
                        sokyuuShoriDateDen = null;
                    }
                    else
                    {
                        //遡及年月日
                        sokyuuShoriDateDen = (DateTime)dtDen.Rows[0]["SokyuuShoriDate"];
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                }
            }

            //即伝発行区分セット
            obic7TextNumberSokudenHakkou.Value = sokudenFlag;

            //即伝発行区分名取得
            using (DataTable dtCom = WinMToolSearchCom.M0000MS_CommonCode.SelectByKey(1100, ComATool.Function.AnyToString(obic7TextNumberSokudenHakkou.Value), ""))
            {
                if (dtCom != null && dtCom.Rows.Count != 0)
                {
                    //即伝発行区分名セット
                    obic7LabelStringSokudenHakkouName.Value = ComATool.Function.AnyToString(dtCom.Rows[0]["CodeName"]);
                }
            }

            //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
            //仕訳パターン番号格納変数を初期化
            this.siwakePatternNO = "";
            //2008/11/10  変更  T.Nakano  終了
            // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
            //仕訳パターンタイムスタンプ格納変数を初期化
            this.siwakePatternTimestamp = null;
            //仕訳パターンユーザグループコード格納変数を初期化
            this.siwakePatternUserGroupCD = "";
            // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //基準別締管理マスタから伝票締日を取得する。
            this.GetKijunSimeKanri();
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
        }

        #endregion

        #region 基準別締管理マスタから伝票締日を取得する。
        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
        /// <summary>
        /// 基準別締管理マスタから伝票締日を取得する。
        /// </summary>
        private void GetKijunSimeKanri()
        {
            //コントロールM.[締管理区分]<>[0](事業所単位)の場合で、画面.[事業所コード]、画面.[基準区分]が入力されている場合
            //基準別締管理マスタから伝票締日を取得する。
            if (simeKanriKbn != 0)
            {
                if (!string.IsNullOrEmpty(obic7TextStringZigyoushoCD.Value) && !string.IsNullOrEmpty(this.obic7TextNumberKijunKBN.Text))
                {
                    using (DataTable dtKij = WinMToolSearchCom.M0000MS_MA_KijunSimeKanri.SelectByKey(this.obic7TextStringZigyoushoCD.Text, ComATool.Function.AnyToInt32(this.obic7TextNumberKijunKBN.Value), ""))
                    {
                        if (dtKij != null && dtKij.Rows.Count != 0)
                        {
                            if (dtKij.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                            {
                                //伝票締日
                                denpyouSimeDate = null;
                            }
                            else
                            {
                                //伝票締日
                                denpyouSimeDate = (DateTime)dtKij.Rows[0]["DenpyouSimeDate"];
                            }
                        }

                    }
                    if (this.hontenShuutyuuFlag == 1)
                    {
                        using (DataTable dtKij = WinMToolSearchCom.M0000MS_MA_KijunSimeKanri.SelectByKey(this.honshaZigyoushoCD, ComATool.Function.AnyToInt32(this.obic7TextNumberKijunKBN.Value), ""))
                        {
                            if (dtKij != null && dtKij.Rows.Count != 0)
                            {
                                if (dtKij.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                                {
                                    //伝票締日
                                    honshaZigyoushoDenpyouSimeDate = null;
                                }
                                else
                                {
                                    //伝票締日
                                    honshaZigyoushoDenpyouSimeDate = (DateTime)dtKij.Rows[0]["DenpyouSimeDate"];
                                }
                            }

                        }
                    }
                }
            }
        }
        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
        #endregion

        #region 画面入力可否制御

        /// <summary>
        /// 画面入力可否制御
        /// </summary>
        /// <param name="isEnabledHeader"></param>
        /// <param name="isEnabledDetail"></param>
        private void SwitchDisplay(bool isEnabledHeader, bool isEnabledDetail)
        {
            if (isEnabledHeader == true)
            {
                //呼出伝票番号
                obic7TextStringCalledDenpyouNO.Enabled = true;
                obic7ButtonWithLogicSearchCalledDenpyouNO.Enabled = true;
                //前回伝票番号
                obic7TextStringPrevDenpyouNO.Enabled = true;

                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                //if ((obic7ComboBoxMode.Text != MODE_DELETE && obic7ComboBoxMode.Text != MODE_SELECT) || isEnabledDetail == false)
                if ((obic7ComboBoxMode.Text != MODE_DELETE && obic7ComboBoxMode.Text != MODE_SELECT && obic7ComboBoxMode.Text != MODE_TENPU) || isEnabledDetail == false)
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                {
                    //事業所
                    obic7TextStringZigyoushoCD.Enabled = true;
                    obic7TextStringZigyoushoCD.ReadOnly = false;
                    obic7TextStringZigyoushoCD.TabStop = true;
                    obic7ButtonWithLogicSearchZigyoushoCD.Enabled = true;
                }
                else
                {
                    //削除モード、参照モードで明細が表示される場合は事業所は使用不可にする
                    //事業所
                    obic7TextStringZigyoushoCD.Enabled = true;
                    obic7TextStringZigyoushoCD.ReadOnly = true;
                    obic7TextStringZigyoushoCD.TabStop = false;
                    obic7ButtonWithLogicSearchZigyoushoCD.Enabled = false;
                }

                if (obic7ComboBoxMode.Text == MODE_INSERT || (obic7ComboBoxMode.Text == MODE_UPDATE && isEnabledDetail == true))
                {
                    //発生日
                    obic7TextDatetimeHasseiDate.Enabled = true;
                    obic7TextDatetimeHasseiDate.ReadOnly = false;
                    obic7TextDatetimeHasseiDate.TabStop = true;

                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //基準区分
                    obic7TextNumberKijunKBN.Enabled = true;
                    obic7TextNumberKijunKBN.ReadOnly = false;
                    obic7TextNumberKijunKBN.TabStop = true;
                    obic7ButtonWithLogicSearchKijunKBN.Enabled = true;
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                    //伝票区分
                    obic7TextStringDenpyouKBN.Enabled = true;
                    obic7TextStringDenpyouKBN.ReadOnly = false;
                    obic7TextStringDenpyouKBN.TabStop = true;
                    obic7ButtonWithLogicSearchDenpyouKBN.Enabled = true;

                    //伝票番号
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 2)
                    //|| (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN == 2))
                    if ((this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 2)
                    || (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN == 2))
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        obic7TextStringDenpyouNO.Enabled = true;
                        obic7TextStringDenpyouNO.ReadOnly = false;
                        obic7TextStringDenpyouNO.TabStop = true;
                    }
                    else
                    {
                        obic7TextStringDenpyouNO.Enabled = true;
                        obic7TextStringDenpyouNO.ReadOnly = true;
                        obic7TextStringDenpyouNO.TabStop = false;
                    }

                    //伝票摘要
                    obic7TextStringDenpyouTekiyou.Enabled = true;
                    obic7TextStringDenpyouTekiyou.ReadOnly = false;
                    obic7TextStringDenpyouTekiyou.TabStop = true;

                    obic7ButtonWithLogicSearchDenpyouTekiyou.Enabled = true;
                    //即伝発行
                    obic7TextNumberSokudenHakkou.Enabled = true;
                    obic7TextNumberSokudenHakkou.ReadOnly = false;
                    obic7TextNumberSokudenHakkou.TabStop = true;

                    obic7ButtonWithLogicSearchSokudenHakkou.Enabled = true;
                }
                else
                {
                    //発生日
                    obic7TextDatetimeHasseiDate.Enabled = true;
                    obic7TextDatetimeHasseiDate.ReadOnly = true;
                    obic7TextDatetimeHasseiDate.TabStop = false;

                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //基準区分
                    obic7TextNumberKijunKBN.Enabled = true;
                    obic7TextNumberKijunKBN.ReadOnly = true;
                    obic7TextNumberKijunKBN.TabStop = false;
                    obic7ButtonWithLogicSearchKijunKBN.Enabled = false;
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                    //伝票区分
                    obic7TextStringDenpyouKBN.Enabled = true;
                    obic7TextStringDenpyouKBN.ReadOnly = true;
                    obic7TextStringDenpyouKBN.TabStop = false;
                    obic7ButtonWithLogicSearchDenpyouKBN.Enabled = false;
                    //伝票番号
                    obic7TextStringDenpyouNO.Enabled = true;
                    obic7TextStringDenpyouNO.ReadOnly = true;
                    obic7TextStringDenpyouNO.TabStop = false;
                    //伝票摘要
                    obic7TextStringDenpyouTekiyou.Enabled = true;
                    obic7TextStringDenpyouTekiyou.ReadOnly = true;
                    obic7TextStringDenpyouTekiyou.TabStop = false;
                    obic7ButtonWithLogicSearchDenpyouTekiyou.Enabled = false;
                    //即伝発行
                    obic7TextNumberSokudenHakkou.Enabled = true;
                    obic7TextNumberSokudenHakkou.ReadOnly = true;
                    obic7TextNumberSokudenHakkou.TabStop = false;
                    obic7ButtonWithLogicSearchSokudenHakkou.Enabled = false;
                }

                //表示ボタン
                obic7ButtonWithLogicDisplay.Enabled = true;

                //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                if (isEnabledDetail == true)
                {
                    //電子証憑ボタン
                    obic7ButtonWithLogicDensiShouhyou.Enabled = true;
                }
                else
                {
                    //電子証憑ボタン
                    obic7ButtonWithLogicDensiShouhyou.Enabled = false;
                }
                //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了

                //処理モード
                obic7ComboBoxMode.Enabled = false;
            }
            else
            {
                //処理モード
                obic7ComboBoxMode.Enabled = true;
                obic7ComboBoxMode.Focus();
                //事業所
                obic7TextStringZigyoushoCD.Enabled = false;
                obic7ButtonWithLogicSearchZigyoushoCD.Enabled = false;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //基準区分
                obic7TextNumberKijunKBN.Enabled = false;
                obic7ButtonWithLogicSearchKijunKBN.Enabled = false;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                //呼出伝票番号
                obic7TextStringCalledDenpyouNO.Enabled = false;
                obic7ButtonWithLogicSearchCalledDenpyouNO.Enabled = false;
                //発生日
                obic7TextDatetimeHasseiDate.Enabled = false;
                //伝票区分
                obic7TextStringDenpyouKBN.Enabled = false;
                obic7ButtonWithLogicSearchDenpyouKBN.Enabled = false;
                //伝票番号
                obic7TextStringDenpyouNO.Enabled = false;
                //伝票摘要
                obic7TextStringDenpyouTekiyou.Enabled = false;
                obic7ButtonWithLogicSearchDenpyouTekiyou.Enabled = false;
                //即伝発行
                obic7TextNumberSokudenHakkou.Enabled = false;
                obic7ButtonWithLogicSearchSokudenHakkou.Enabled = false;

                //前回伝票番号
                obic7TextStringPrevDenpyouNO.Enabled = false;

                //表示ボタン
                obic7ButtonWithLogicDisplay.Enabled = false;

                //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                //電子証憑ボタン
                obic7ButtonWithLogicDensiShouhyou.Enabled = false;
                //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了
            }

            if (isEnabledDetail == false)
            {
                //ツールチップテキストの削除
                SetToolTip(2);
            }

            //明細部の制御
            obic7MultilineCheckGridDetail.Enabled = isEnabledDetail;
            obic7TextNumberTotalKariSougaku.Enabled = isEnabledDetail;
            obic7TextNumberTotalKasiSougaku.Enabled = isEnabledDetail;
            obic7TextNumberTotalKariKingaku.Enabled = isEnabledDetail;
            obic7TextNumberTotalKasiKingaku.Enabled = isEnabledDetail;
            obic7TextNumberTotalKariZeigaku.Enabled = isEnabledDetail;
            obic7TextNumberTotalKasiZeigaku.Enabled = isEnabledDetail;

            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            //if (obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_SELECT)
            if (obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_SELECT || obic7ComboBoxMode.Text == MODE_TENPU)
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
            {
                obic7MultilineCheckGridDetail.ReadOnly = true;
            }
            else
            {
                obic7MultilineCheckGridDetail.ReadOnly = false;
            }
        }

        #endregion

