        #region ヘッダ部にデータを表示

        /// <summary>
        /// ヘッダ部にデータを表示
        /// </summary>
        /// <param name="siwakeInfo">複数行コントロールに表示するデータ</param>
        private void SetDataToHeader(DataTable siwakeInfo)
        {
            //修正前情報
            if (obic7ComboBoxMode.Text != MODE_INSERT)
            {
                prevZigyoushoCD = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["ZigyoushoCD"]);
                prevSystemCategory = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["SystemCategory"]);
                prevKessanki = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["Kessanki"]);
                prevMonthNO = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["MonthNO"]);
                prevHasseiDate = (DateTime)siwakeInfo.Rows[0]["HasseiDate"];
