                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                prevHonKaridenFlag = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["HonKaridenFlag"]);
                prevkanendoSokyuuShuuseiFlag = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["KanendoSokyuuShuuseiFlag"]);
                if (siwakeInfo.Rows[0]["SokyuuShoriDate"] == DBNull.Value)
                {
                    prevsokyuuShoriDateDen = null;
                }
                else
                {
                    prevsokyuuShoriDateDen = (DateTime)siwakeInfo.Rows[0]["SokyuuShoriDate"];
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                prevKessanFlg = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["KessanFlag"]);
                systemDenpyouNO = ComATool.Function.AnyToDecimal(siwakeInfo.Rows[0]["SystemDenpyouNO"]);
                systemCategory = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["SystemCategory"]);
                subSystemSystemDenpyouNO = ComATool.Function.AnyToDecimal(siwakeInfo.Rows[0]["SubSystemDenpyouNO"]);
                subSystemShoriKBN = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["SubShoriKBN"]);
                subSystemDenpyouNO = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["SubDenpyouNO"]);
                shouninJoutaiKBN = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["ShouninStateKBN"]);
                if (siwakeInfo.Rows[0]["GuidAnken"] == DBNull.Value)
                {
                    ankenGuid = null;
                }
                else
                {
                    ankenGuid = (Guid)siwakeInfo.Rows[0]["GuidAnken"];
                }
                kihyouUserID = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["KihyouUserID"]);
            }


            //事業所情報
            obic7TextStringZigyoushoCD.Value = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["ZigyoushoCD"]);
            obic7LabelStringZigyoushoName.Text = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["ZigyoushoNameRyaku"]);
            zigyoushoCDKaiteiDate = (DateTime)siwakeInfo.Rows[0]["ZigyoushoKaiteiDate"];
            setZandakaDate = (DateTime)siwakeInfo.Rows[0]["SetZandakaDate"];
            if (siwakeInfo.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
            {
                //伝票締日
                denpyouSimeDate = null;
            }
            else
            {
                //伝票締日
                denpyouSimeDate = (DateTime)siwakeInfo.Rows[0]["DenpyouSimeDate"];
            }
            //本社事業所コード
            honshaZigyoushoCD = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["HonshaZigyoushoCD"]);
            //本社事業所セット残高日付
            honshaZigyoushoSetZandakaDate = (DateTime)siwakeInfo.Rows[0]["HonshaZigyoushoSetZandakaDate"];
            if (siwakeInfo.Rows[0]["HonshaZigyoushoDenpyouSimeDate"] == DBNull.Value)
            {
                //本社事業所伝票締日
                honshaZigyoushoDenpyouSimeDate = null;
            }
            else
            {
                //本社事業所伝票締日
                honshaZigyoushoDenpyouSimeDate = (DateTime)siwakeInfo.Rows[0]["HonshaZigyoushoDenpyouSimeDate"];
            }

            denpyouTypeKBN = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["denpyouTypeKBN"]);

            //発生日情報
            obic7TextDatetimeHasseiDate.Value = (DateTime)siwakeInfo.Rows[0]["HasseiDate"];
            kessanki = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["Kessanki"]);
            monthNO = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["MonthNO"]);
            //2012/06/15 M.Kobayashi 変更 開始 (M04758)修正モード呼出で発生日を変えずに新規行追加(行挿入も同様)したときに追加行の仮払消費税科目・仮受消費税科目が、発生日直近の科目でセットされない不具合改修
            //発生日情報に基づき、消費税科目の再取得を行う
            //総勘定科目コントロールマスタよりデータを取得
            using (DataTable dtKanControlM = WinMToolSearchCom.M0000MS_MA_KanjouControl.SelectByKaiteiDate((DateTime)obic7TextDatetimeHasseiDate.Value, ""))
            {
                //取得値有効チェック
                if ((dtKanControlM != null) && (dtKanControlM.Rows.Count != 0))
                {
                    //仮払消費税科目コード
                    kariBaraiZeiKamokuCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["KaribaraiZeiCD"]);
                    //仮受消費税科目コード
                    kariUkeZeiKamokuCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["KariukeZeiCD"]);
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                    //リバースチャージ払科目コード
                    rcHaraiCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["RCHaraiCD"]);
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了
                }
            }

            //仮払消費税科目コードのチェック
            using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariBaraiZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, ""))
            {
                //取得値有効チェック
                if ((dtKanjouM != null) && (dtKanjouM.Rows.Count != 0))
                {
                    //仮払消費税科目コード改定日
                    kariBaraiZeiKamokuCDKaiteiDate = (DateTime?)dtKanjouM.Rows[0]["KaiteiDate"];
                    //仮払消費税科目コード貸借区分
                    kariBaraiZeiKamokuCDTaishakuKBN = ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]);
                }
            }

            //仮受消費税科目コードのチェック
            using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariUkeZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, ""))
            {
                //取得値有効チェック
                if ((dtKanjouM != null) && (dtKanjouM.Rows.Count != 0))
                {
                    //仮受消費税科目コード改定日
                    kariUkeZeiKamokuCDKaiteiDate = (DateTime?)dtKanjouM.Rows[0]["KaiteiDate"];
                    //仮受消費税科目コード貸借区分
                    kariUkeZeiKamokuCDTaishakuKBN = ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]);
                }
            }
            //2012/06/15 M.Kobayashi 変更 終了 (M04758)修正モード呼出で発生日を変えずに新規行追加(行挿入も同様)したときに追加行の仮払消費税科目・仮受消費税科目が、発生日直近の科目でセットされない不具合改修

            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //基準区分
            obic7TextNumberKijunKBN.Text = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["KijunKBN"]);
            obic7LabelStringKijunKBNName.Value = String.Empty;
            if (!String.IsNullOrEmpty(obic7TextNumberKijunKBN.Text))
            {
                //基準区分取得
                using (DataTable dtDen = WinMToolSearchCom.M0000MS_CommonCode.SelectByKey(COMMON_CD_KIJUNKBN, this.obic7TextNumberKijunKBN.Text, ""))
                {
                    if (dtDen != null && dtDen.Rows.Count != 0)
                    {
                        //基準区分名セット
                        obic7LabelStringKijunKBNName.Value = ComATool.Function.AnyToString(dtDen.Rows[0]["CodeName"]);
                    }
                }
            }
            honKaridenFlag = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["HonKaridenFlag"]);
            kanendoSokyuuShuuseiFlag = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["KanendoSokyuuShuuseiFlag"]);
            if (siwakeInfo.Rows[0]["SokyuuShoriDate"] == DBNull.Value)
            {
                //遡及年月日
                sokyuuShoriDateDen = null;
            }
            else
            {
                //遡及年月日
                sokyuuShoriDateDen = (DateTime)siwakeInfo.Rows[0]["SokyuuShoriDate"];
            }
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑

            //伝票区分
            obic7TextStringDenpyouKBN.Value = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["DenpyouKBN"]);
            obic7LabelStringDenpyouKBNName.Value = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["DenpyouKBNName"]);
            kessanFlg = ComATool.Function.AnyToInt32(siwakeInfo.Rows[0]["KessanFlag"]);

            //伝票摘要
            if (kensakuTensouMode == 1 || kensakuTensouMode == 2)
            {
                obic7TextStringDenpyouTekiyou.Value = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["DenpyouNO"]);
            }
            else
            {
                obic7TextStringDenpyouTekiyou.Value = ComATool.Function.AnyToString(siwakeInfo.Rows[0]["DenpyouTekiyou"]);
            }
        }

