        #region ヘッダ部の未入力チェック
        /// <summary>
        /// ヘッダ部の未入力チェック
        /// </summary>
        /// <returns></returns>
        private bool CheckHeaderEmpty()
        {
            int errorFlg = 0;

            //エラープロバイダを解除
            ClearErrorProvider(1);

            //エラープロバイダー表示
            ComATool.Logic.Message message = new ComATool.Logic.Message();
            message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);

            //事業所コードが未入力の場合
            if ((String.IsNullOrEmpty(obic7TextStringZigyoushoCD.Value) == true))
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringZigyoushoCD, message.MessageSummary);
                errorFlg = 1;
            }

            //新規時か修正時の入力可能な場合に発生日が未入力の場合
            if ((obic7ComboBoxMode.Text == MODE_INSERT && String.IsNullOrEmpty(obic7TextDatetimeHasseiDate.Text) == true)
                || (obic7ComboBoxMode.Text == MODE_UPDATE && String.IsNullOrEmpty(obic7TextDatetimeHasseiDate.Text) == true && obic7MultilineCheckGridDetail.Enabled == true))
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextDatetimeHasseiDate, message.MessageSummary);
                if (errorFlg == 0)
                {
                    errorFlg = 2;
                }
            }
            //新規時に修正時の入力可能な場合に伝票区分が未入力の場合
            if ((obic7ComboBoxMode.Text == MODE_INSERT && String.IsNullOrEmpty(obic7TextStringDenpyouKBN.Value) == true)
                || (obic7ComboBoxMode.Text == MODE_UPDATE && String.IsNullOrEmpty(obic7TextStringDenpyouKBN.Text) == true && obic7MultilineCheckGridDetail.Enabled == true))
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringDenpyouKBN, message.MessageSummary);
                if (errorFlg == 0)
                {
                    errorFlg = 3;
                }
            }

            //伝票番号が未入力の場合
            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //if (String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) == true
            //    && ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 2)
            //      || (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN == 2)))
            if (String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) == true
                && ((this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 2)
                  || (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN == 2)))
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringDenpyouNO, message.MessageSummary);
                if (errorFlg == 0)
                {
                    errorFlg = 4;
                }
            }

            //新規以外で呼出伝票番号が未入力の場合
            if (obic7ComboBoxMode.Text != MODE_INSERT && (String.IsNullOrEmpty(obic7TextStringCalledDenpyouNO.Value) == true))
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringCalledDenpyouNO, message.MessageSummary);
                if (errorFlg == 0)
                {
                    errorFlg = 5;
                }
            }

            //新規時修正時の入力可能な場合に即伝発行が未入力の場合
            if ((obic7ComboBoxMode.Text == MODE_INSERT && String.IsNullOrEmpty(obic7TextNumberSokudenHakkou.Text) == true)
                || (obic7ComboBoxMode.Text == MODE_UPDATE && String.IsNullOrEmpty(obic7TextNumberSokudenHakkou.Text) == true && obic7MultilineCheckGridDetail.Enabled == true))
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextNumberSokudenHakkou, message.MessageSummary);
                if (errorFlg == 0)
                {
                    errorFlg = 6;
                }
            }

            //エラーがある場合
            if (errorFlg != 0)
            {
                //エラー表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00103", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                //フォーカス移動
                switch (errorFlg)
                {
                    //事業所
                    case 1:
                        obic7TextStringZigyoushoCD.Focus();
                        break;
                    //発生日
                    case 2:
                        obic7TextDatetimeHasseiDate.Focus();
                        break;
                    //伝票区分
                    case 3:
                        obic7TextStringDenpyouKBN.Focus();
                        break;
                    //伝票番号
                    case 4:
                        obic7TextStringDenpyouNO.Focus();
                        break;
                    //呼出伝票番号
                    case 5:
                        obic7TextStringCalledDenpyouNO.Focus();
                        break;
                    //即伝発行
                    case 6:
                        obic7TextNumberSokudenHakkou.Focus();
                        break;
                }
                return false;
            }

            return true;
        }
        #endregion

        #region ヘッダ部の項目チェック

        /// <summary>
        /// ヘッダ部の項目チェック
        /// </summary>
        /// <returns></returns>
        private bool CheckHeaderInput()
        {
            //事業所のチェック
            if (CheckZigyoushoCD(KBN_KOUMOKUCHK_HEAD) == false)
            {
                obic7TextStringZigyoushoCD.Focus();
                return false;
            }

            //新規時
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //発生日のチェック
                if (CheckHasseiDate(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextDatetimeHasseiDate.Focus();
                    return false;
                }

                //伝票区分のチェック
                if (CheckDenpyouKBN(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextStringDenpyouKBN.Focus();
                    return false;
                }

                if (obic7TextStringDenpyouNO.ReadOnly == false)
                {
                    //伝票番号のチェック
                    if (CheckDenpyouNO(KBN_KOUMOKUCHK_ALL) == false)
                    {
                        obic7TextStringDenpyouNO.Focus();
                        return false;
                    }
                }
            }

            //新規以外の時
            if (obic7ComboBoxMode.Text != MODE_INSERT)
            {
                //呼出伝票番号のチェック
                if (CheckCalledDenpyouNO(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextStringCalledDenpyouNO.Focus();
                    return false;
                }
            }

            //新規時
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //即伝発行のチェック
                if (CheckSokudenHakkou(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextNumberSokudenHakkou.Focus();
                    return false;
                }
            }

            return true;
        }

        #endregion

        #region 処理モードの処理

        private void CheckShoriMode()
        {
            //画面制御
            SwitchDisplay(true, false);

            if (String.IsNullOrEmpty(obic7TextStringZigyoushoCD.Value) == true)
            {
                //事業所が未設定なら事業所へフォーカス
                obic7TextStringZigyoushoCD.Focus();
            }
            else
            {
                if (obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    //新規時は発生日にフォーカスセット
                    obic7TextDatetimeHasseiDate.Focus();
                }
                else
                {
                    //修正、削除、参照時は呼出伝票番号にフォーカスセット
                    obic7TextStringCalledDenpyouNO.Focus();
                }
            }

            //ファンクションキャプション変更
            if (obic7ComboBoxMode.Text == MODE_DELETE)
            {
                //削除モードではF3のキャプションを「F3 削除」とする
                base.obic7ToolStripButtonWithLogicF3.Text = F3.DELETE_DATA;
            }
            else
            {
                //削除モード以外はF3のキャプションを「F3 行削除」とする
                base.obic7ToolStripButtonWithLogicF3.Text = F3.DELETE_ROW;
            }

            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            if (this.obic7ComboBoxMode.Text == MODE_TENPU)
            {
                //添付モードではF10のキャプションを「F10 添付登録」とする
                base.obic7ToolStripButtonWithLogicF10.Text = "F10 添付登録";

                //添付モードではWFの申請種別をBM1010：追加添付(仕訳伝票)にする
                this.wfExecuter = new WFExecuter("BM1010", "B");
            }
            else
            {
                //添付モード以外ではF10のキャプションを「F10 登録」とする
                base.obic7ToolStripButtonWithLogicF10.Text = F10.UPDATE;

                //添付モード以外はWFの申請種別をBM0010：仕訳伝票にする
                this.wfExecuter = new WFExecuter("BM0010", "B");
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
        }

        #endregion

        #region 事業所のチェック

        /// <summary>
        /// 事業所コードのチェック
        /// </summary>
        /// <param name="checkkbn">1:入力時、2:ALLチェック時</param>
        /// <returns></returns>
        private bool CheckZigyoushoCD(int checkkbn)
        {
            //変更のあった場合のみクリア
            if (obic7TextStringZigyoushoCD.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL || checkkbn == KBN_KOUMOKUCHK_HEAD)
            {
                //事業所関連項目のクリア
                //事業所改定日
                zigyoushoCDKaiteiDate = null;
                //セット残高日付
                setZandakaDate = null;
                //伝票締日
                denpyouSimeDate = null;
                //事業所名
                obic7LabelStringZigyoushoName.Value = "";
            }

            if (checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //事業所コードが未入力の場合
                if ((String.IsNullOrEmpty(obic7TextStringZigyoushoCD.Value) == true))
                {
                    //エラープロバイダー表示
                    ComATool.Logic.Message message = new ComATool.Logic.Message();
                    message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);
                    WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringZigyoushoCD, message.MessageSummary);
                    return false;
                }
            }

            //事業所コードが入力されていて、変更のあった場合のみチェックを行う
            if ((String.IsNullOrEmpty(obic7TextStringZigyoushoCD.Value) == false) &&
                (obic7TextStringZigyoushoCD.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL || checkkbn == KBN_KOUMOKUCHK_HEAD))
            {

                //事業所マスタよりデータを取得
                using (DataTable dtZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(obic7TextStringZigyoushoCD.Value, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, 0, 0, 0, ""))
                {
                    //取得値有効チェック
                    if ((dtZigyoushoM != null) && (dtZigyoushoM.Rows.Count != 0))
                    {
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00024", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //新規時もしくは修正、削除時のALLチェック時
                    if (obic7ComboBoxMode.Text == MODE_INSERT
                        || ((obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE) && checkkbn == KBN_KOUMOKUCHK_ALL)
                        )
                    {
                        //事業所マスタ.事業所名がNULLもしくは空文字の場合
                        if (String.IsNullOrEmpty(ComATool.Function.AnyToString(ComATool.Function.AnyToString(dtZigyoushoM.Rows[0]["ZigyoushoName"]))) == true)
                        {
                            //エラー表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00026", null, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            return false;

                        }
                    }

                    //事業所変更不可チェック
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (obic7ComboBoxMode.Text == MODE_UPDATE
                    //    && ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN != 2)
                    //|| (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN != 2))
                    //    && String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) ==false 
                    //    && prevZigyoushoCD != obic7TextStringZigyoushoCD.Value)
                    if (obic7ComboBoxMode.Text == MODE_UPDATE
                        && ((this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN != 2)
                    || (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN != 2))
                        && String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) == false
                        && prevZigyoushoCD != obic7TextStringZigyoushoCD.Value)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00163", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //本支店勘定科目マスタクラスより取得
                    using (DataTable dtHonsitenKanjou = WinMToolSearchCom.M0000MS_MA_HonsitenKanjou.SelectByKaiteiDate(obic7TextStringZigyoushoCD.Value, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, honshaZigyoushoSecurityFlag, ""))
                    {
                        if (dtHonsitenKanjou == null || dtHonsitenKanjou.Rows.Count == 0)
                        {
                            object[] obj = new object[1];
                            obj[0] = "";

                            //エラー表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00445", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return false;
                        }

                        //本社事業所コード
                        honshaZigyoushoCD = ComATool.Function.AnyToString(dtHonsitenKanjou.Rows[0]["HonshaZigyoushoCD"]);
                    }

                    // 本店集中する時のみ
                    if (hontenShuutyuuFlag == 1 && obic7TextStringZigyoushoCD.Value != honshaZigyoushoCD)
                    {
                        //事業所マスタよりデータを取得
                        //2008/05/14 変更 N.Sasaki 開始 本社事業所チェックはセキュリティを考慮しない
                        //                        using (DataTable dtHonshaZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(honshaZigyoushoCD, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, 0, 0, 0, ""))
                        using (DataTable dtHonshaZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(honshaZigyoushoCD, (DateTime)obic7TextDatetimeHasseiDate.Value, "", 0, 0, 0, ""))
                        //2008/05/14 変更 N.Sasaki 終了
                        {
                            //取得値有効チェック
                            if ((dtHonshaZigyoushoM != null) && (dtHonshaZigyoushoM.Rows.Count != 0))
                            {
                                //本社事業所セット残高日付
                                honshaZigyoushoSetZandakaDate = (DateTime)dtHonshaZigyoushoM.Rows[0]["SetZandakaDate"];
                                //本社事業所伝票締日
                                if (dtHonshaZigyoushoM.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                                {
                                    //伝票締日
                                    honshaZigyoushoDenpyouSimeDate = null;
                                }
                                else
                                {
                                    //伝票締日
                                    honshaZigyoushoDenpyouSimeDate = (DateTime)dtHonshaZigyoushoM.Rows[0]["DenpyouSimeDate"];
                                }
                            }
                            else
                            {
                                //エラー表示
                                object[] obj = new object[1];
                                obj[0] = "";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00453", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                return false;
                            }

                            //本社事業所の事業所名NULLチェック
                            if (dtHonshaZigyoushoM.Rows[0]["ZigyoushoName"] == DBNull.Value)
                            {
                                object[] obj = new object[1];
                                obj[0] = "";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00454", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                return false;
                            }
                        }
                    }

                    //事業所関連項目セット
                    //事業所略名
                    obic7LabelStringZigyoushoName.Value = ComATool.Function.AnyToString(dtZigyoushoM.Rows[0]["ZigyoushoNameRyaku"]);
                    //事業所改定日
                    zigyoushoCDKaiteiDate = (DateTime)dtZigyoushoM.Rows[0]["KaiteiDate"];
                    //セット残高日付
                    setZandakaDate = (DateTime)dtZigyoushoM.Rows[0]["SetZandakaDate"];
                    if (dtZigyoushoM.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                    {
                        //伝票締日
                        denpyouSimeDate = null;
                    }
                    else
                    {
                        //伝票締日
                        denpyouSimeDate = (DateTime)dtZigyoushoM.Rows[0]["DenpyouSimeDate"];
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //コントロールM.[締管理区分]<>[0](事業所単位)の場合、基準別締管理M.[伝票締日]をクリアする。
                    if (this.simeKanriKbn != 0)
                    {
                        this.denpyouSimeDate = null;
                        if (this.hontenShuutyuuFlag == 1)
                        {
                            this.honshaZigyoushoDenpyouSimeDate = null;
                        }
                        this.GetKijunSimeKanri();
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                    //明細が表示されている時
                    if (obic7MultilineCheckGridDetail.GetDisplayedData().Count != 0 && obic7MultilineCheckGridDetail.Enabled == true && checkkbn == 1)
                    {
                        if (this.zigyoushoBumonCheckKBN != 0)
                        {
                            RefreshSiwakeMeisai();
                        }
                    }

                }
            }
            return true;
        }

        #endregion

        #region 発生日のチェック

        /// <summary>
        /// 発生日のチェック
        /// </summary>
        /// <param name="checkkbn">1:入力時、2:ALLチェック時</param>
        /// <returns></returns>
        private bool CheckHasseiDate(int checkkbn)
        {
            if (checkkbn == 1)
            {

                //発生日が未入力の場合
                if ((String.IsNullOrEmpty(obic7TextDatetimeHasseiDate.Text) == true))
                {
                    //エラープロバイダー表示
                    ComATool.Logic.Message message = new ComATool.Logic.Message();
                    message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);
                    WinAToolUI.Obic7ErrorProvider.SetError(obic7TextDatetimeHasseiDate, message.MessageSummary);
                    return false;
                }
            }

            ////発生日が入力されていて、変更のあった場合のみチェックを行う
            if (String.IsNullOrEmpty(obic7TextDatetimeHasseiDate.Text) == false
                && (obic7TextDatetimeHasseiDate.IsChangedText == true || checkkbn == 2))
            {
                //事業所マスタよりデータを取得
                using (DataTable dtZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(obic7TextStringZigyoushoCD.Value, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, 0, 0, 0, ""))
                {
                    //取得値有効チェック
                    if ((dtZigyoushoM != null) && (dtZigyoushoM.Rows.Count != 0))
                    {
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00024", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //新規時もしくは修正、削除時のALLチェック時
                    if (obic7ComboBoxMode.Text == MODE_INSERT
                        || ((obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE) && checkkbn == KBN_KOUMOKUCHK_ALL)
                        )
                    {
                        //事業所マスタ.事業所名がNULLもしくは空文字の場合
                        if (String.IsNullOrEmpty(ComATool.Function.AnyToString(dtZigyoushoM.Rows[0]["ZigyoushoName"])) == true)
                        {
                            //エラー表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00026", null, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return false;
                        }
                    }

                    //事業所変更不可チェック
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (obic7ComboBoxMode.Text == MODE_UPDATE
                    //    && ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN != 2)
                    //|| (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN != 2))
                    //    && String.IsNullOrEmpty(obic7TextStringCalledDenpyouNO.Text) == false
                    //    && prevZigyoushoCD != obic7TextStringZigyoushoCD.Text)
                    if (obic7ComboBoxMode.Text == MODE_UPDATE
                        && ((this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN != 2)
                    || (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN != 2))
                        && String.IsNullOrEmpty(obic7TextStringCalledDenpyouNO.Text) == false
                        && prevZigyoushoCD != obic7TextStringZigyoushoCD.Text)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00163", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //本支店勘定科目マスタクラスより取得
                    using (DataTable dtHonsitenKanjou = WinMToolSearchCom.M0000MS_MA_HonsitenKanjou.SelectByKaiteiDate(obic7TextStringZigyoushoCD.Value, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, honshaZigyoushoSecurityFlag, ""))
                    {
                        if (dtHonsitenKanjou == null || dtHonsitenKanjou.Rows.Count == 0)
                        {
                            object[] obj = new object[1];
                            obj[0] = "";

                            //エラー表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00445", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return false;
                        }

                        //本社事業所コード
                        honshaZigyoushoCD = ComATool.Function.AnyToString(dtHonsitenKanjou.Rows[0]["HonshaZigyoushoCD"]);
                    }

                    if (hontenShuutyuuFlag == 1 && obic7TextStringZigyoushoCD.Value != honshaZigyoushoCD)
                    {
                        //事業所マスタよりデータを取得
                        //2008/05/14 変更 N.Sasaki 開始 本社事業所チェックはセキュリティを考慮しない
                        //                        using (DataTable dtHonshaZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(honshaZigyoushoCD, (DateTime)obic7TextDatetimeHasseiDate.Value, zigyoushoSecurityPatternCD, 0, 0, 0, ""))
                        using (DataTable dtHonshaZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(honshaZigyoushoCD, (DateTime)obic7TextDatetimeHasseiDate.Value, "", 0, 0, 0, ""))
                        //2008/05/14 変更 N.Sasaki 終了
                        {
                            //取得値有効チェック
                            if ((dtHonshaZigyoushoM != null) && (dtHonshaZigyoushoM.Rows.Count != 0))
                            {
                                //本社事業所セット残高日付
                                honshaZigyoushoSetZandakaDate = (DateTime)dtHonshaZigyoushoM.Rows[0]["SetZandakaDate"];
                                //本社事業所伝票締日
                                if (dtHonshaZigyoushoM.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                                {
                                    //伝票締日
                                    honshaZigyoushoDenpyouSimeDate = null;
                                }
                                else
                                {
                                    //伝票締日
                                    honshaZigyoushoDenpyouSimeDate = (DateTime)dtHonshaZigyoushoM.Rows[0]["DenpyouSimeDate"];
                                }
                            }
                            else
                            {
                                object[] obj = new object[1];
                                obj[0] = "";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00453", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                return false;
                            }

                            //本社事業所の事業所名NULLチェック
                            if (dtHonshaZigyoushoM.Rows[0]["ZigyoushoName"] == DBNull.Value)
                            {
                                object[] obj = new object[1];
                                obj[0] = "";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00454", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                return false;
                            }
                        }
                    }

                    //事業所関連項目セット
                    //事業所略名
                    obic7LabelStringZigyoushoName.Value = ComATool.Function.AnyToString(dtZigyoushoM.Rows[0]["ZigyoushoNameRyaku"]);
                    //事業所改定日
                    zigyoushoCDKaiteiDate = (DateTime?)dtZigyoushoM.Rows[0]["KaiteiDate"];
                    //セット残高日付
                    setZandakaDate = (DateTime?)dtZigyoushoM.Rows[0]["SetZandakaDate"];
                    if (dtZigyoushoM.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                    {
                        //伝票締日
                        denpyouSimeDate = null;
                    }
                    else
                    {
                        //伝票締日
                        denpyouSimeDate = (DateTime)dtZigyoushoM.Rows[0]["DenpyouSimeDate"];
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //コントロールM.[締管理区分]<>[0](事業所単位)の場合、基準別締管理M.[伝票締日]をクリアする。
                    if (this.simeKanriKbn != 0)
                    {
                        this.denpyouSimeDate = null;
                        this.GetKijunSimeKanri();
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                }

                //総勘定科目コントロールマスタ項目クリア
                //仮払消費税科目コード
                kariBaraiZeiKamokuCD = "";
                //仮払消費税科目コード改定日
                kariBaraiZeiKamokuCDKaiteiDate = null;
                //仮払消費税科目コード貸借区分
                kariBaraiZeiKamokuCDTaishakuKBN = null;
                //仮受消費税科目コード
                kariUkeZeiKamokuCD = "";
                //仮受消費税科目コード改定日
                kariUkeZeiKamokuCDKaiteiDate = null;
                //仮受消費税科目コード貸借区分
                kariUkeZeiKamokuCDTaishakuKBN = null;
                //諸口コード
                shokutiCD = "";
                // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                //リバースチャージ払科目コード
                rcHaraiCD = "";
                // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了


                //総勘定科目コントロールマスタよりデータを取得
                using (DataTable dtKanControlM = WinMToolSearchCom.M0000MS_MA_KanjouControl.SelectByKaiteiDate((DateTime)obic7TextDatetimeHasseiDate.Value, ""))
                {
                    //取得値有効チェック
                    if ((dtKanControlM != null) && (dtKanControlM.Rows.Count != 0))
                    {
                        //仮払消費税科目コード
                        kariBaraiZeiKamokuCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["KaribaraiZeiCD"]);
                        //仮受消費税科目コード
                        kariUkeZeiKamokuCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["KariukeZeiCD"]);
                        //諸口科目コード
                        shokutiCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["ShokutiCD"]);
                        // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                        //リバースチャージ払科目コード
                        rcHaraiCD = ComATool.Function.AnyToString(dtKanControlM.Rows[0]["RCHaraiCD"]);
                        // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了
                    }
                }

                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                DenpyouKBN = "";
                if (!string.IsNullOrEmpty(obic7TextStringDenpyouKBN.Value))
                {
                    DenpyouKBN = obic7TextStringDenpyouKBN.Value;
                }
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                //仮払消費税科目コードのチェック
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                //using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariBaraiZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, ""))
                using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariBaraiZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, "", DenpyouKBN))
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End
                {
                    //取得値有効チェック
                    if ((dtKanjouM != null) && (dtKanjouM.Rows.Count != 0))
                    {
                    }
                    else
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮払";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00165", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //総勘定科目名がNullか空文字の場合
                    if (String.IsNullOrEmpty(ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KanjouName"])) == true)
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮払";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00166", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //科目分類<>0(財務基本科目の場合)
                    if (ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["KamokuCategory"]) != 0)
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮払";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00167", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //科目区分<>0(一般科目の場合)
                    if (ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["KamokuKBN"]) != 0)
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮払";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00168", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //仮払消費税科目コード改定日
                    kariBaraiZeiKamokuCDKaiteiDate = (DateTime)dtKanjouM.Rows[0]["KaiteiDate"];
                    //仮払消費税科目コード貸借区分
                    kariBaraiZeiKamokuCDTaishakuKBN = ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]);
                }


                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                DenpyouKBN = "";
                if (!string.IsNullOrEmpty(obic7TextStringDenpyouKBN.Value))
                {
                    DenpyouKBN = obic7TextStringDenpyouKBN.Value;
                }
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                //仮受消費税科目コードのチェック
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                //using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariUkeZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, ""))
                using (DataTable dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(kariUkeZeiKamokuCD, (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, "", DenpyouKBN))
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End
                {
                    //取得値有効チェック
                    if ((dtKanjouM != null) && (dtKanjouM.Rows.Count != 0))
                    {
                    }
                    else
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮受";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00165", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //総勘定科目名がNullか空文字の場合
                    if (String.IsNullOrEmpty(ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KanjouName"])) == true)
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮受";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00166", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //科目分類<>0(財務基本科目の場合)
                    if (ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["KamokuCategory"]) != 0)
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮受";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00167", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //科目区分<>0(一般科目の場合)
                    if (ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["KamokuKBN"]) != 0)
                    {
                        object[] obj = new object[1];
                        obj[0] = "仮受";

                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00168", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }

                    //仮受消費税科目コード改定日
                    kariUkeZeiKamokuCDKaiteiDate = (DateTime)dtKanjouM.Rows[0]["KaiteiDate"];
                    //仮受消費税科目コード貸借区分
                    kariUkeZeiKamokuCDTaishakuKBN = ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]);
                }


                //明細が表示されている時
                if (obic7MultilineCheckGridDetail.GetDisplayedData().Count != 0 && obic7MultilineCheckGridDetail.Enabled == true && checkkbn == 1)
                {
                    //明細項目洗い換え処理
                    RefreshSiwakeMeisai();
                }

                //発生日 <= セット残高日付の場合
                if (obic7TextDatetimeHasseiDate.Value <= (DateTime)setZandakaDate)
                {
                    object[] obj = new object[1];
                    obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(setZandakaDate), "yyyy/MM/dd", false);

                    //エラー表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00171", obj, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    return false;

                }

                //月度期間マスタチェック
                using (DataTable dtGetudoM = WinMToolSearchCom.M0000MS_MA_GetudoKikan.SelectByKijunbi((DateTime)obic7TextDatetimeHasseiDate.Value, ""))
                {
                    //取得値有効チェック
                    if ((dtGetudoM != null) && (dtGetudoM.Rows.Count != 0))
                    {
                        //決算期
                        kessanki = ComATool.Function.AnyToInt32(dtGetudoM.Rows[0]["Kessanki"]);
                        //月度番号
                        monthNO = ComATool.Function.AnyToInt32(dtGetudoM.Rows[0]["MonthNO"]);
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00172", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                }

                if (hontenShuutyuuFlag == 1)
                {
                    //本社事業所セット残高日付チェック
                    if (obic7TextDatetimeHasseiDate.Value <= honshaZigyoushoSetZandakaDate)
                    {
                        object[] obj = new object[1];
                        obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(honshaZigyoushoSetZandakaDate), "yyyy/MM/dd", false);

                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00753", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                }
            }
            return true;
        }

        #endregion

        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
        #region 基準区分のチェック

        /// <summary>
        /// 基準区分のチェック
        /// </summary>
        /// <param name="checkkbn">1:入力時、2:ALLチェック時</param>
        /// <returns></returns>
        private bool CheckKijunKBN(int checkkbn)
        {
            if (obic7TextNumberKijunKBN.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL)
            {
                //基準区分クリア
                obic7LabelStringKijunKBNName.Text = "";
            }

            if (checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //基準区分が未入力の場合
                if ((String.IsNullOrEmpty(obic7TextNumberKijunKBN.Text) == true))
                {
                    //エラープロバイダー表示
                    ComATool.Logic.Message message = new ComATool.Logic.Message();
                    message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);
                    WinAToolUI.Obic7ErrorProvider.SetError(obic7TextNumberKijunKBN, message.MessageSummary);
                    return false;
                }
            }

            if (obic7TextNumberKijunKBN.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL)
            {
                //基準区分取得
                using (DataTable dtDen = WinMToolSearchCom.M0000MS_CommonCode.SelectByKey(COMMON_CD_KIJUNKBN, this.obic7TextNumberKijunKBN.Text, ""))
                {
                    if (dtDen != null && dtDen.Rows.Count != 0)
                    {
                        //基準区分名セット
                        obic7LabelStringKijunKBNName.Value = ComATool.Function.AnyToString(dtDen.Rows[0]["CodeName"]);
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01212", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                }

                this.obic7TextStringDenpyouKBN.Text = String.Empty;
                this.obic7LabelStringDenpyouKBNName.Text = String.Empty;
                this.kessanFlg = null;
                this.kanendoSokyuuShuuseiFlag = null;
                this.honKaridenFlag = null;
                this.sokyuuShoriDateDen = null;

                using (WinMToolSearch.MA_DenpyouKBN denpyouSerch = new WinMToolSearch.MA_DenpyouKBN())
                {
                    DataTable dtDen2 = denpyouSerch.SelectByKijunKBN(denKBNSecurityPatternCD, 1, null, ComATool.Function.AnyToInt32(this.obic7TextNumberKijunKBN.Value));
                    if (ComATool.Function.IsValidDataTable(dtDen2) && dtDen2.Rows.Count != 0)
                    {
                        this.obic7TextStringDenpyouKBN.Text = ComATool.Function.AnyToString(dtDen2.Rows[0]["DenpyouKBN"]);
                        this.obic7LabelStringDenpyouKBNName.Text = ComATool.Function.AnyToString(dtDen2.Rows[0]["DenpyouKBNName"]);
                        this.kessanFlg = ComATool.Function.AnyToInt32(dtDen2.Rows[0]["KessanFlag"]);
                        this.kanendoSokyuuShuuseiFlag = ComATool.Function.AnyToInt32(dtDen2.Rows[0]["KanendoSokyuuShuuseiFlag"]);
                        this.honKaridenFlag = ComATool.Function.AnyToInt32(dtDen2.Rows[0]["HonKaridenFlag"]);
                        if (dtDen2.Rows[0]["SokyuuShoriDate"] == DBNull.Value)
                        {
                            //遡及年月日
                            sokyuuShoriDateDen = null;
                        }
                        else
                        {
                            //遡及年月日
                            sokyuuShoriDateDen = (DateTime)dtDen2.Rows[0]["SokyuuShoriDate"];
                        }
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00084", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                }
                //コントロールM.[締管理区分]<>[0](事業所単位)の場合、基準別締管理M.[伝票締日]をクリアする。
                if (this.simeKanriKbn != 0)
                {
                    this.denpyouSimeDate = null;
                    if (this.hontenShuutyuuFlag == 1)
                    {
                        this.honshaZigyoushoDenpyouSimeDate = null;
                    }
                    this.GetKijunSimeKanri();

                    //明細の伝票締日の再セット
                    this.RefreshMeisaiDenpyouSimeDate();
                }

                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応
                //明細が表示されている時
                if (obic7MultilineCheckGridDetail.GetDisplayedData().Count != 0 && obic7MultilineCheckGridDetail.Enabled == true && checkkbn == 1)
                {
                    //明細項目洗い換え処理
                    RefreshSiwakeMeisai();

                }
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応
            }

            return true;
        }

        #endregion
        //　2010/08/16　変更　　　C.Okuno  (M04451)↑

        #region 伝票区分のチェック

        /// <summary>
        /// 
        /// </summary>
        /// <param name="checkkbn">1:入力時、2:ALLチェック時</param>
        /// <returns></returns>
        private bool CheckDenpyouKBN(int checkkbn)
        {
            if (obic7TextStringDenpyouKBN.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL)
            {
                //伝票区分クリア
                obic7LabelStringDenpyouKBNName.Text = "";
                //決算フラグクリア
                kessanFlg = null;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //本仮伝フラグ
                honKaridenFlag = null;
                //過年度遡及修正フラグ
                kanendoSokyuuShuuseiFlag = null;
                sokyuuShoriDateDen = null;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
            }

            if (checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //伝票区分が未入力の場合
                if ((String.IsNullOrEmpty(obic7TextStringDenpyouKBN.Value) == true))
                {
                    //エラープロバイダー表示
                    ComATool.Logic.Message message = new ComATool.Logic.Message();
                    message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);
                    WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringDenpyouKBN, message.MessageSummary);
                    return false;
                }
            }

            if (obic7TextStringDenpyouKBN.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL)
            {

                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                ////伝票区分が10～19以外の場合
                //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) > 19 || ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 10)
                //{
                //    //エラー表示
                //    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00690", null, null, GetType(),
                //                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                //                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                //    return false;
                //}
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                //伝票区分取得
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //using (DataTable dtDen = WinMToolSearchCom.M0000MS_MA_DenpyouKBN.SelectByKey(obic7TextStringDenpyouKBN.Value, denKBNSecurityPatternCD, 0, ""))
                using (DataTable dtDen = WinMToolSearchCom.M0000MS_MA_DenpyouKBN.SelectByKey(obic7TextStringDenpyouKBN.Value, denKBNSecurityPatternCD, 0, 0,
                                                                                             null, ComATool.Function.AnyToInt32(this.obic7TextNumberKijunKBN.Value), ""))
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                {
                    if (dtDen != null && dtDen.Rows.Count != 0)
                    {
                        //伝票区分名セット
                        obic7LabelStringDenpyouKBNName.Value = ComATool.Function.AnyToString(dtDen.Rows[0]["DenpyouKBNName"]);
                        //決算フラグセット
                        kessanFlg = ComATool.Function.AnyToInt32(dtDen.Rows[0]["KessanFlag"]);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        //本仮伝フラグセット
                        honKaridenFlag = ComATool.Function.AnyToInt32(dtDen.Rows[0]["HonKaridenFlag"]);
                        //過年度遡及修正フラグセット
                        kanendoSokyuuShuuseiFlag = ComATool.Function.AnyToInt32(dtDen.Rows[0]["KanendoSokyuuShuuseiFlag"]);
                        //遡及年月日
                        if (dtDen.Rows[0]["SokyuuShoriDate"] == DBNull.Value)
                        {
                            sokyuuShoriDateDen = null;
                        }
                        else
                        {
                            sokyuuShoriDateDen = (DateTime)dtDen.Rows[0]["SokyuuShoriDate"];
                        }
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00084", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //本伝票以外の場合
                if (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou)
                {
                    //エラー表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01218", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    return false;
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                //伝票番号使用制御
                if (checkkbn == KBN_KOUMOKUCHK_INPUT && (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE))
                {
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN != 2)
                    //    || (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN != 2))
                    if ((this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN != 2)
                        || (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN != 2))
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        obic7TextStringDenpyouNO.ReadOnly = true;
                        obic7TextStringDenpyouNO.TabStop = false;
                    }
                    else
                    {
                        obic7TextStringDenpyouNO.ReadOnly = false;
                        obic7TextStringDenpyouNO.TabStop = true;
                    }
                }
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応
                //明細が表示されている時
                if (obic7MultilineCheckGridDetail.GetDisplayedData().Count != 0 && obic7MultilineCheckGridDetail.Enabled == true && checkkbn == 1)
                {
                    //明細項目洗い換え処理
                    RefreshSiwakeMeisai();

                }
                //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応
            }

            return true;
        }

        #endregion

        #region 伝票番号のチェック

        /// <summary>
        /// 伝票番号のチェック
        /// </summary>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時</param>
        /// <returns></returns>
        private bool CheckDenpyouNO(int checkkbn)
        {
            //追加Where句
            string whereString = "";

            //伝票番号が未入力で、変更のあった場合未入力エラー
            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //if ((String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) == true) &&
            //    (obic7TextStringDenpyouNO.IsChangedText == true) &&
            //    ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 2)
            //        || (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN == 2))
            //    )
            if ((String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) == true) &&
                (obic7TextStringDenpyouNO.IsChangedText == true) &&
                ((honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 2)
                    || (honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN == 2))
                )
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
            {
                //エラープロバイダー表示
                ComATool.Logic.Message message = new ComATool.Logic.Message();
                message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);
                WinAToolUI.Obic7ErrorProvider.SetError(obic7TextStringDenpyouNO, message.MessageSummary);
                return false;
            }

            //伝票番号が入力されていて、変更のあった場合、チェックを行う
            if ((String.IsNullOrEmpty(obic7TextStringDenpyouNO.Value) == false) &&
                (obic7TextStringDenpyouNO.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL))
            {
                //(画面.伝票番号 < 20 かつ プライベート変数.伝票採番区分 = 2) もしくは (画面.伝票番号 >= 20 かつ プライベート変数.仮伝票採番区分 = 2)の場合
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //if ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 2)
                //    || (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN == 2))
                if ((honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 2)
                    || (honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN == 2))
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                {
                    //追加Where句作成
                    if (obic7ComboBoxMode.Text == MODE_INSERT)
                    {
                        //2009/02/09  変更　T.Nakano  開始　(M04159)伝票番号またはユーザIDに「'(シングルコーテーション)」を使用するとシステムエラーになる不具合を改修
                        //whereString = " WHERE SystemCategoryInitial = '" + ComATool.Function.Left(obic7TextStringDenpyouNO.Value, 1) + "' AND SystemCategory <> 10 ";
                        //  2015/08/20  修正   K.Yamashita     (28128-28231-28233)会計WG要望49期上期対応 開始
                        //whereString = " WHERE SystemCategoryInitial = " + ComATool.Function.SqlEscapeVarchar(ComATool.Function.Left(obic7TextStringDenpyouNO.Value, 1)) + " AND SystemCategory <> 10 ";
                        whereString = " WHERE SystemCategoryInitial = " + ComATool.Function.SqlEscapeVarchar(ComATool.Function.Left(obic7TextStringDenpyouNO.Value, 1)) + " AND (SystemCategory <> 10 AND SystemCategory <> 12) ";
                        //  2015/08/20  修正   K.Yamashita     (28128-28231-28233)会計WG要望49期上期対応 終了
                        //2009/02/09  変更　T.Nakano  終了
                    }
                    else
                    {
                        //2009/02/09  変更　T.Nakano  開始　(M04159)伝票番号またはユーザIDに「'(シングルコーテーション)」を使用するとシステムエラーになる不具合を改修
                        //whereString = " WHERE SystemCategoryInitial = '" + ComATool.Function.Left(obic7TextStringDenpyouNO.Value, 1) + "' AND SystemCategory <> " + ComATool.Function.AnyToString(prevSystemCategory);
                        whereString = " WHERE SystemCategoryInitial = " + ComATool.Function.SqlEscapeVarchar(ComATool.Function.Left(obic7TextStringDenpyouNO.Value, 1)) + " AND SystemCategory <> " + ComATool.Function.AnyToString(prevSystemCategory);
                        //2009/02/09  変更　T.Nakano  終了
                    }

                    //システム採番マスタ
                    using (DataTable dtSys = WinMToolSearchCom.M0000MS_MA_SystemSaiban.SelectByCustom(whereString))
                    {
                        if (dtSys != null && dtSys.Rows.Count != 0)
                        {
                            //データが取得できたらエラーメッセージ表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00173", null, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return false;
                        }
                    }
                }

                //仕訳伝票チェック
                int iRetCD = CheckSiwakeRead(KBN_DENNOCHK_TOROKU, obic7TextStringDenpyouNO.Value);
                if (iRetCD != 0)
                {
                    return false;
                }
            }

            return true;
        }

        #endregion

        #region 呼出伝票番号の脱出時の実処理
        /// <summary>
        /// 呼出伝票番号の脱出時の実処理
        /// </summary>
        /// <param name="checkkbn">1:呼出伝票番号脱出時 2:それ以外</param>
        /// <returns></returns>
        private bool ValidatingCalledDenpyouNO(int checkkbn)
        {
            // 2015/07/29  修正  A.Kitagawa  (28928)処理モード削除、照会時に事業所違いで同一伝票番号の呼び出しを行うことが出来ない不具合の修正。  開始
            ////削除、照会時に現在呼出伝票番号と同じ伝票番号が入力された場合は処理なし
            ////削除、照会時は伝票呼出時に呼出伝票番号から脱出しないので２度同じ伝票の呼出処理が実行されるのを抑制するために条件追加
            //if ((obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_SELECT) && prevZigyoushoCD == obic7TextStringZigyoushoCD.Value && prevCalledDenpyouNO == obic7TextStringCalledDenpyouNO.Value)
            //{
            //    return true;
            //}
            //削除、照会時に現在呼出伝票番号と同じ伝票番号が入力された場合は処理なし
            //削除、照会時は伝票呼出時に呼出伝票番号から脱出しないので２度同じ伝票の呼出処理が実行されるのを抑制するために条件追加
            if ((obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_SELECT) && prevCalledDenpyouNO == obic7TextStringCalledDenpyouNO.Value && checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                return true;
            }
            // 2015/07/29  修正  A.Kitagawa  (28928)処理モード削除、照会時に事業所違いで同一伝票番号の呼び出しを行うことが出来ない不具合の修正。  終了

            System.Windows.Forms.Cursor.Current = System.Windows.Forms.Cursors.WaitCursor;

            // ↓ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
            //呼出伝票番号チェック前にシステム伝票番号を退避
            preSystemDenpyouNO = systemDenpyouNO;
            // ↑ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正

            // 2024/11/26  修正  H.Kusano    (241607)【横展開(241099)】【本支店仕訳入力】元帳からのドリルダウン時に伝票締日以前の伝票に対して追加添付できない場合があります。開始↓
            //追加添付モードの場合、呼び出す伝票の事業所・締日でチェックを行う必要があるため取得しなおす。
            if (obic7ComboBoxMode.Text == MODE_TENPU && checkkbn != 1)
            {
                var zigyoushoCD = "";
                var hasseidate = new DateTime?();
                StringBuilder sb = new StringBuilder();

                sb.Append(" SELECT ");
                sb.Append("     ZigyoushoCD,HasseiDate  ");
                sb.Append(" FROM  M0000RR_MA_SiwakeMeisai ");
                sb.Append(" WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(kensakuSystemDenpyouNO) + " ");

                using (DataTable dt = businessDB.GetDataTable(sb.ToString()))
                {
                    if (ComATool.Function.IsValidDataTable(dt))
                    {
                        zigyoushoCD = ComATool.Function.AnyToString(dt.Rows[0]["ZigyoushoCD"]);
                        hasseidate = ComATool.Function.AnyToDateTime(dt.Rows[0]["HasseiDate"]);
                    }
                }

                //事業所情報取得
                using (DataTable dtZig = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(zigyoushoCD, (DateTime)hasseidate, zigyoushoSecurityPatternCD, 0, 0, 0, ""))
                {
                    if (dtZig.Rows[0]["DenpyouSimeDate"] == DBNull.Value)
                    {
                        //伝票締日
                        denpyouSimeDate = null;
                    }
                    else
                    {
                        //伝票締日
                        denpyouSimeDate = (DateTime)dtZig.Rows[0]["DenpyouSimeDate"];
                    }
                }
            }
            // 2024/11/26  修正  H.Kusano    (241607)【横展開(241099)】【本支店仕訳入力】元帳からのドリルダウン時に伝票締日以前の伝票に対して追加添付できない場合があります。終了↑

            //呼出伝票番号のチェック
            if (CheckCalledDenpyouNO(checkkbn) == false)
            {
                // ↓ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
                //呼出伝票番号を待避（エラー時も呼出伝票番号を退避する）
                prevCalledDenpyouNO = obic7TextStringCalledDenpyouNO.Value;
                // ↑ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
                return false;
            }

            // ↓ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
            int iRetCD;
            if (obic7MultilineCheckGridDetail.Enabled == true)
            {
                // ↓ 2011/12/05 変更 S.Harada (M04719)ドリルダウンで伝票訂正をする際に異常終了する不具合修正
                //if ((obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE) && prevCalledDenpyouNO != obic7TextStringCalledDenpyouNO.Value)
                if ((obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE) && prevCalledDenpyouNO != obic7TextStringCalledDenpyouNO.Value && isKidouModeFlg == false)
                // ↑ 2011/12/05 変更 S.Harada (M04719)ドリルダウンで伝票訂正をする際に異常終了する不具合修正
                {
                    isHaitaDelFlg = true;
                    //排他削除処理
                    iRetCD = HaitaSetData(KBN_HAITA_SAKUJO);
                    if (iRetCD != 0)
                    {
                        isHaitaDelFlg = false;
                        return false;
                    }
                }
                isHaitaDelFlg = false;
                // ↓ 2011/12/05 変更 S.Harada (M04719)ドリルダウンで伝票訂正をする際に異常終了する不具合修正
                isKidouModeFlg = false;
                // ↑ 2011/12/05 変更 S.Harada (M04719)ドリルダウンで伝票訂正をする際に異常終了する不具合修正
            }
            // ↑ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正

            //仕訳伝票呼出処理
            // ↓ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
            //int iRetCD;
            // ↑ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
            iRetCD = SiwakeRead();
            if (iRetCD != 0)
            {
                return false;
            }

            //画面制御
            SwitchDisplay(true, true);

            if (obic7ComboBoxMode.Text != MODE_INSERT)
            {
                //新規以外の場合、伝票番号にセット
                obic7TextStringDenpyouNO.Value = obic7TextStringCalledDenpyouNO.Value;
            }

            //フォーカスセット
            if (checkkbn == KBN_KOUMOKUCHK_INPUT && (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE) && enterKeyDownFlg == true)
            {
                //新規、修正時は発生日にフォーカスセット
                obic7TextDatetimeHasseiDate.Focus();
            }
            else if (checkkbn == KBN_KOUMOKUCHK_INPUT && (obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_SELECT) && enterKeyDownFlg == true)
            {
                //削除、照会は呼出伝票番号にフォーカスセット
                obic7TextStringCalledDenpyouNO.Focus();
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            else if (checkkbn == KBN_KOUMOKUCHK_INPUT && obic7ComboBoxMode.Text == MODE_TENPU && enterKeyDownFlg == true)
            {
                //添付は添付ボタンにフォーカスセット
                obic7ButtonWithLogicDensiShouhyou.Focus();
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            //削除モード時削除ボタンは明細が表示されている場合のみ使用可にする
            if (obic7ComboBoxMode.Text == MODE_DELETE && ActiveControl.Name == "obic7TextStringCalledDenpyouNO")
            {
                //削除モード
                base.SetFunctionButton(false, true, obic7MultilineCheckGridDetail.Enabled, false, true, false, false, false, false, false, false, true);
            }

            //呼出伝票番号を待避
            prevCalledDenpyouNO = obic7TextStringCalledDenpyouNO.Value;

            System.Windows.Forms.Cursor.Current = System.Windows.Forms.Cursors.Default;


            return true;
        }
        #endregion

        #region 呼出伝票番号のチェック
        /// <summary>
        /// 呼出伝票番号のチェック
        /// </summary>
        /// <param name="checkkbn">1:呼出伝票番号脱出時 2:それ以外</param>
        /// <returns></returns>
        private bool CheckCalledDenpyouNO(int checkkbn)
        {

            //呼出伝票番号が未入力でなくて、変更のあった場合
            if ((String.IsNullOrEmpty(obic7TextStringCalledDenpyouNO.Value) == false) &&
                (obic7TextStringCalledDenpyouNO.IsChangedText == true || checkkbn != 1))
            {
                //仕訳伝票チェック
                int iRetCD = CheckSiwakeRead(KBN_DENNOCHK_CALLED, obic7TextStringCalledDenpyouNO.Value);
                if (iRetCD != 0)
                {
                    return false;
                }
            }
            return true;
        }


        #endregion

        #region 伝票摘要の処理

        private void CheckDenpyouTekiyou()
        {
            Encoding sjisEnc = Encoding.GetEncoding("Shift_JIS");

            //伝票摘要が5バイト以下の場合
            if (sjisEnc.GetByteCount(obic7TextStringDenpyouTekiyou.Text) <= 5)
            {
                using (DataTable dtTek1M = WinMToolSearchCom.M0000MS_MA_Tekiyou1.SelectByCustom(" WHERE Tekiyou1CD = " + ComATool.Function.SqlEscapeVarchar(obic7TextStringDenpyouTekiyou.Text)))
                {
                    //取得値有効チェック
                    if ((dtTek1M != null) && (dtTek1M.Rows.Count != 0))
                    {
                        obic7TextStringDenpyouTekiyou.Value = ComATool.Function.AnyToString(dtTek1M.Rows[0]["Tekiyou1Name"]);
                        obic7TextStringDenpyouTekiyou.Focus();
                        //先頭にカーソル配置
                        obic7TextStringDenpyouTekiyou.Select(0, 0);
                        return;
                    }
                }
            }
            obic7ButtonWithLogicDisplay.Focus();
            //表示ボタンクリック時と同じ処理を行う。
            obic7ButtonWithLogicDisplay.PerformClick();
        }
        #endregion

        #region 即伝発行のチェック
        /// <summary>
        /// 即伝発行のチェック
        /// </summary>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時</param>
        /// <returns></returns>
        private bool CheckSokudenHakkou(int checkkbn)
        {
            if (obic7TextNumberSokudenHakkou.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL)
            {
                //即伝発行名クリア
                obic7LabelStringSokudenHakkouName.Text = "";

            }

            if (checkkbn == 1)
            {
                //即伝発行が未入力の場合
                if ((String.IsNullOrEmpty(obic7TextNumberSokudenHakkou.Text) == true))
                {
                    //エラープロバイダー表示
                    ComATool.Logic.Message message = new ComATool.Logic.Message();
                    message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);
                    WinAToolUI.Obic7ErrorProvider.SetError(obic7TextNumberSokudenHakkou, message.MessageSummary);
                    return false;
                }
            }

            //即伝発行が入力されていて、変更のあった場合のみチェックを行う
            if ((String.IsNullOrEmpty(obic7TextNumberSokudenHakkou.Text) == false) &&
                (obic7TextNumberSokudenHakkou.IsChangedText == true || checkkbn == KBN_KOUMOKUCHK_ALL))
            {
                //即伝発行データ取得
                using (DataTable dtCodeM = WinMToolSearchCom.M0000MS_CommonCode.SelectByKey(1100, ComATool.Function.AnyToString(obic7TextNumberSokudenHakkou.Value), ""))
                {
                    //取得値有効チェック
                    if ((dtCodeM != null) && (dtCodeM.Rows.Count != 0))
                    {
                        obic7LabelStringSokudenHakkouName.Text = ComATool.Function.AnyToString(dtCodeM.Rows[0]["CodeName"]);
                    }
                    else
                    {
                        //エラー表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00183", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                }
            }

            return true;

        }

        #endregion

        #region メモ関連処理
        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始

        #region メモ情報データの削除
        /// <summary>
        /// メモ情報データの削除
        /// </summary>
        /// <param name="memoTableName">メモ情報データテーブル名</param>
        /// <returns>実行結果</returns>
        private bool DeleteMemoData(string memoTableName)
        {
            bool result = true;

            StringBuilder sb = new StringBuilder();

            sb.AppendLine(" DELETE FROM " + memoTableName + " ");
            sb.AppendLine(" WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(this.systemDenpyouNO) + " ");

            int iRetCD = 0;
            iRetCD = SQLExecuteNonQuery(sb.ToString());
            if (iRetCD != 0)
            {
                return false;
            }

            return result;
        }
        #endregion

        #region 本支店メモ情報ワークのデータ行削除のSQL作成
        /// <summary>
        /// 本支店メモ情報ワークのデータ削除のSQL作成(行指定なし)
        /// </summary>
        /// <returns>クエリ</returns>
        private string MakeSQLDeleteMemoWorkTable()
        {
            return MakeSQLDeleteMemoWorkTable(null);
        }

        /// <summary>
        /// 本支店メモ情報ワークのデータ行削除のSQL作成
        /// </summary>
        /// <param name="rowno">行番号(nullの場合は行指定なし)</param>
        /// <returns>クエリ</returns>
        private string MakeSQLDeleteMemoWorkTable(int? rowno)
        {
            StringBuilder sb = new StringBuilder();

            sb.Append(" DELETE FROM ");
            sb.Append(HONSITENMEMOWKTBL);
            sb.Append(" WHERE OperationComputerName = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.Append(" AND   OperationUserID       = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.Append(" AND   OperationJobID        = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " ");
            if (rowno != null)
            {
                sb.Append(" AND   GyouNO                = " + ComATool.Function.SqlEscapeNumber(rowno) + " ");
            }

            return ComATool.Function.AnyToString(sb);
        }
        #endregion

        #region 本支店メモ情報ワークのデータ行削除の洗い換えのSQL作成
        /// <summary>
        /// 本支店メモ情報ワークのデータ行削除の洗い換えのSQL作成
        /// </summary>
        /// <param name="rowno">行番号</param>
        /// <returns>クエリ</returns>
        private string MakeSQLAraigaeMemoWorkTableGyou_Delete(int rowno)
        {
            StringBuilder sb = new StringBuilder();

            sb.Append(" UPDATE ");
            sb.Append(HONSITENMEMOWKTBL);
            sb.Append(" SET GyouNO = GyouNO - 1");
            sb.Append(" WHERE UpdateUserID          = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.Append(" AND   UpdateComputerName    = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.Append(" AND   UpdateJobID           = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            sb.Append(" AND   GyouNO                > " + ComATool.Function.SqlEscapeNumber(rowno) + " ");

            return ComATool.Function.AnyToString(sb);
        }
        #endregion

        #region 本支店メモ情報ワークのデータ登録のSQL作成
        /// <summary>
        /// 本支店メモ情報ワークのデータ登録のSQL作成
        /// </summary>
        /// <param name="insertedRow">対象行</param>
        /// <param name="isRowInserting">行挿入時かどうか true:行挿入 false:行更新</param>
        /// <returns>クエリ</returns>
        private string MakeSQLInsertMemoWorkTable(DataRow insertedRow, bool isRowInserting)
        {
            StringBuilder sb = new StringBuilder();

            sb.AppendLine(" INSERT INTO " + HONSITENMEMOWKTBL + " ");
            sb.AppendLine(" ( ");
            sb.AppendLine("  OperationComputerName ");
            sb.AppendLine(" ,OperationUserID ");
            sb.AppendLine(" ,OperationDatetime ");
            sb.AppendLine(" ,OperationJobID ");
            sb.AppendLine(" ,GyouNO ");
            sb.AppendLine(" ,KariRValue ");
            sb.AppendLine(" ,KariGValue ");
            sb.AppendLine(" ,KariBValue ");
            sb.AppendLine(" ,KariMemo ");
            sb.AppendLine(" ,KasiRValue ");
            sb.AppendLine(" ,KasiGValue ");
            sb.AppendLine(" ,KasiBValue ");
            sb.AppendLine(" ,KasiMemo ");
            sb.AppendLine(" ,CompanyNO ");
            sb.AppendLine(" ,UpdateDatetime ");
            sb.AppendLine(" ,UpdateCertificatedGuid ");
            sb.AppendLine(" ,UpdateJobID ");
            sb.AppendLine(" ,UpdateUserID ");
            sb.AppendLine(" ,UpdateComputerName ");
            sb.AppendLine(" ,UpdateComputerUserName ");
            sb.AppendLine(" ,UpdateComputerDomainName ");
            sb.AppendLine(" ) VALUES (                  ");
            /* OperationComputerName      */
            sb.AppendLine("  " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerName) + " ");
            /* OperationUserID            */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            /* OperationDatetime          */
            sb.AppendLine(" ,GETDATE() ");
            /* OperationJobID             */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            /* GyouNO                     */
            if (isRowInserting)
            {
                if (this.gyouSounyuuFlg)
                {
                    //行挿入
                    sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(this.sounyuuGyouNO) + " ");
                }
                else
                {
                    //新規行
                    sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(this.GetMaxRowNo() + 1) + " ");
                }
            }
            else
            {
                //行更新
                sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_GYOUNO]) + " ");
            }
            /* KariRValue                 */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_KARIMEMO_RVALUE]) + " ");
            /* KariGValue                 */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_KARIMEMO_GVALUE]) + " ");
            /* KariBValue                 */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_KARIMEMO_BVALUE]) + " ");
            /* KariMemo                   */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeVarchar(insertedRow[COL_KARIMEMO]) + " ");
            /* KasiRValue                 */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_KASIMEMO_RVALUE]) + " ");
            /* KasiGValue                 */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_KASIMEMO_GVALUE]) + " ");
            /* KasiBValue                 */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(insertedRow[COL_KASIMEMO_BVALUE]) + " ");
            /* KasiMemo                   */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeVarchar(insertedRow[COL_KASIMEMO]) + " ");
            /* CompanyNO                  */
            sb.AppendLine(" ," + ComATool.Function.SqlEscapeNumber(ComATool.Logic.CurrentUser.CompanyNO) + " ");
            /* UpdateDatetime             */
            sb.AppendLine(" ,GETDATE() ");
            /* UpdateCertificatedGuid     */
            sb.AppendLine("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.CertificatedGuid) + " ");
            /* UpdateJobID                */
            sb.AppendLine("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            /* UpdateUserID               */
            sb.AppendLine("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            /* UpdateComputerName         */
            sb.AppendLine("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerName) + " ");
            /* UpdateComputerUserName     */
            sb.AppendLine("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerUserName) + " ");
            /* UpdateComputerDomainName   */
            sb.AppendLine("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerDomainName) + " ");
            sb.AppendLine(" ) ");

            return ComATool.Function.AnyToString(sb);
        }
        #endregion

        #region 本支店メモ情報ワークのデータ行挿入時の洗い換えのSQL作成
        /// <summary>
        /// 本支店メモ情報ワークのデータ行挿入時の洗い換えのSQL作成
        /// </summary>
        /// <param name="rowno">行番号</param>
        /// <returns>クエリ</returns>
        private string MakeSQLAraigaeMemoWorkTableGyou_Insert(int rowno)
        {
            StringBuilder sb = new StringBuilder();

            sb.Append(" UPDATE ");
            sb.Append(HONSITENMEMOWKTBL);
            sb.Append(" SET GyouNO = GyouNO + 1");
            sb.Append(" WHERE UpdateUserID          =  " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.Append(" AND   UpdateComputerName    =  " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.Append(" AND   UpdateJobID           =  " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            sb.Append(" AND   GyouNO                >= " + ComATool.Function.SqlEscapeNumber(rowno) + " ");

            return ComATool.Function.AnyToString(sb);
        }
        #endregion

        #region 本支店メモ情報ワークのデータ更新のSQL作成
        /// <summary>
        /// 本支店メモ情報ワークのデータ更新のSQL作成
        /// </summary>
        /// <param name="e">イベント引数</param>
        /// <returns>クエリ</returns>
        private string MakeSQLUpdateMemoWorkTable(Obic7fx.Win.A0000.Tool.UI.Obic7MultilineCancelEventArgs e)
        {
            StringBuilder sb = new StringBuilder();

            //Delete
            sb.Append(this.MakeSQLDeleteMemoWorkTable(ComATool.Function.AnyToInt32(e.InsertedRow[COL_GYOUNO])));
            //Insert
            sb.Append(this.MakeSQLInsertMemoWorkTable(e.InsertedRow, false));

            return ComATool.Function.AnyToString(sb);
        }
        #endregion

        #region メモ情報を取得
        /// <summary>
        /// メモ情報を取得
        /// </summary>
        /// <param name="rowNo">行番号</param>
        private void GetMemoInfo(int rowNo)
        {
            Control ctrlAbstract = this.ActiveControl as Control;

            int taishakuKBN = 0;

            if (ctrlAbstract.Name == "obic7ButtonWithLogicKasiMemo")
            {
                taishakuKBN = 1; //貸方
            }
            else
            {
                taishakuKBN = 0; //借方
            }

            using (var dlgMemo = new Obic7fx.Win.M0000.Tool.Input.MA_Memo())
            {
                //貸借発生区分
                dlgMemo.TaishakuHasseiKBN = taishakuKBN;

                //貸方
                if (taishakuKBN == 1)
                {
                    //R値
                    dlgMemo.RValue = (int?)this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_RVALUE);
                    //G値
                    dlgMemo.GValue = (int?)this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_GVALUE);
                    //B値
                    dlgMemo.BValue = (int?)this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_BVALUE);
                    //メモ
                    dlgMemo.Memo = this.GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO);
                }
                //借方
                else
                {
                    //R値
                    dlgMemo.RValue = (int?)this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_RVALUE);
                    //G値
                    dlgMemo.GValue = (int?)this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_GVALUE);
                    //B値
                    dlgMemo.BValue = (int?)this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_BVALUE);
                    //メモ
                    dlgMemo.Memo = this.GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO);
                }
                //行番号
                dlgMemo.GyouNO = ComATool.Function.AnyToInt32(this.GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_GYOUNO));
                //画面行番号
                dlgMemo.DispGyouNO = ComATool.Function.AnyToInt32(this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, this.obic7LabelNumberGyou.Name).Text);
                //処理モード
                if (this.obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    dlgMemo.ShoriMode = 1;  //1:新規
                }
                else if (this.obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    dlgMemo.ShoriMode = 2;  //2:修正
                }
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                //else if (this.obic7ComboBoxMode.Text == MODE_DELETE || this.obic7ComboBoxMode.Text == MODE_SELECT)
                else if (this.obic7ComboBoxMode.Text == MODE_DELETE || this.obic7ComboBoxMode.Text == MODE_SELECT || this.obic7ComboBoxMode.Text == MODE_TENPU)
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                {
                    //照会の場合は更新処理を行わない
                    dlgMemo.ShoriMode = 3;  //3:削除
                }

                if (dlgMemo.ShowDialog() == DialogResult.OK)
                {
                    //借方
                    if (taishakuKBN == 0)
                    {
                        //転送モードが削除の場合
                        if (dlgMemo.TensouMode == 2)
                        {
                            //借方メモR値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_RVALUE, null);
                            //借方メモG値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_GVALUE, null);
                            //借方メモB値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_BVALUE, null);
                            //借方メモ
                            this.SetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO, string.Empty);
                            //借方メモボタンをデフォルトに戻す
                            this.SetMemoInfo(rowNo, KBN_TAISHAKU_KARIKATA, this.defaultButtonColor, string.Empty);
                        }
                        //転送モードが転記の場合
                        else if (dlgMemo.TensouMode == 1)
                        {
                            //借方メモR値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_RVALUE, dlgMemo.RValue);
                            //借方メモG値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_GVALUE, dlgMemo.GValue);
                            //借方メモB値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO_BVALUE, dlgMemo.BValue);
                            //借方メモ
                            this.SetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIMEMO, dlgMemo.Memo);
                            //借方メモボタンに情報をセットする
                            this.SetMemoInfo(rowNo, KBN_TAISHAKU_KARIKATA, Color.FromArgb((int)dlgMemo.RValue, (int)dlgMemo.GValue, (int)dlgMemo.BValue), dlgMemo.Memo);
                        }
                        else
                        {
                            //それ以外の場合は処理を行わない
                        }
                    }
                    //貸方
                    else
                    {
                        //転送モードが削除の場合
                        if (dlgMemo.TensouMode == 2)
                        {
                            //貸方メモR値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_RVALUE, null);
                            //貸方メモG値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_GVALUE, null);
                            //貸方メモB値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_BVALUE, null);
                            //貸方メモ
                            this.SetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO, string.Empty);
                            //貸方メモボタンをデフォルトに戻す
                            this.SetMemoInfo(rowNo, KBN_TAISHAKU_KASIKATA, this.defaultButtonColor, string.Empty);
                        }
                        //転送モードが転記の場合
                        else if (dlgMemo.TensouMode == 1)
                        {
                            //貸方メモR値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_RVALUE, dlgMemo.RValue);
                            //貸方メモG値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_GVALUE, dlgMemo.GValue);
                            //貸方メモB値
                            this.SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO_BVALUE, dlgMemo.BValue);
                            //貸方メモ
                            this.SetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIMEMO, dlgMemo.Memo);
                            //貸方メモボタンに情報をセットする
                            this.SetMemoInfo(rowNo, KBN_TAISHAKU_KASIKATA, Color.FromArgb((int)dlgMemo.RValue, (int)dlgMemo.GValue, (int)dlgMemo.BValue), dlgMemo.Memo);
                        }
                        else
                        {
                            //それ以外の場合は処理を行わない
                        }
                    }
                }
            }
        }
