        #region メモ情報をボタンにセット
        /// <summary>
        /// メモ情報をボタンにセットする
        /// </summary>
        /// <param name="rowNo">行番号</param>
        /// <param name="taishakuKBN">貸借区分(1:借方 2:貸方)</param>
        /// <param name="memoColor">色</param>
        /// <param name="memoNaiyou">内容</param>
        private void SetMemoInfo(int rowNo, int taishakuKBN, Color memoColor, string memoNaiyou)
        {
            //借方
            if (taishakuKBN == KBN_TAISHAKU_KARIKATA)
            {
                //色をセット
                this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, "obic7ButtonWithLogicKariMemo").BackColor = memoColor;
                //内容をツールチップにセット
                this.toolTip1.SetToolTip(this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, "obic7ButtonWithLogicKariMemo"), memoNaiyou);
            }
            //貸方
            else
            {
                //色をセット
                this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, "obic7ButtonWithLogicKasiMemo").BackColor = memoColor;
                //内容をツールチップにセット
                this.toolTip1.SetToolTip(this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, "obic7ButtonWithLogicKasiMemo"), memoNaiyou);
            }
        }
