        private int CheckSiwakeRead(int checkkbn, string denpyouNO)
        {
            using (SqlCommand sc = businessDB.NewSqlCommand())
            {
                sc.CommandType = CommandType.StoredProcedure;
                sc.CommandText = SIWAKE_MEISAI_CHECK;

                SqlParameter param1;
