                param27.Direction = ParameterDirection.Input;
                param27.Value = zigyoushoSecurityPatternCD;

                SqlParameter param28;
                param28 = sc.Parameters.Add("@p_HonsitenSecurityFlag", SqlDbType.TinyInt);
                param28.Direction = ParameterDirection.Input;
                param28.Value = honsitenSecurityFlag;

                // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                SqlParameter param29;
                param29 = sc.Parameters.Add("@p_BunsekiCD1NyuuryokuSeigyoFlg", SqlDbType.TinyInt);
                param29.Direction = ParameterDirection.Input;
