        #region 仕訳データの登録
        /// <summary>   
        /// 仕訳データの登録
        /// </summary>
        private int EntrySiwake()
        {
            using (SqlCommand sc = businessDB.NewSqlCommand())
            {
                sc.CommandType = CommandType.StoredProcedure;
                sc.CommandText = SIWAKE_MEISAI_ENTRY;

                SqlParameter param1;
                param1 = sc.Parameters.Add("@po_ErrorKBN", SqlDbType.Int);
                param1.Direction = ParameterDirection.Output;

                SqlParameter param2;
                param2 = sc.Parameters.Add("@po_ErrorCD1", SqlDbType.VarChar, 128);
                param2.Direction = ParameterDirection.Output;

                SqlParameter param3;
                param3 = sc.Parameters.Add("@po_ErrorCD2", SqlDbType.VarChar, 128);
                param3.Direction = ParameterDirection.Output;

                SqlParameter param4;
                param4 = sc.Parameters.Add("@po_ErrorProcName", SqlDbType.VarChar, 128);
                param4.Direction = ParameterDirection.Output;

                SqlParameter param5;
                param5 = sc.Parameters.Add("@po_ErrorSummary", SqlDbType.VarChar, 256);
                param5.Direction = ParameterDirection.Output;

                SqlParameter param6;
                param6 = sc.Parameters.Add("@po_ErrorDetail", SqlDbType.VarChar, 2560);
                param6.Direction = ParameterDirection.Output;

                SqlParameter param7;
                param7 = sc.Parameters.Add("@po_ErrorBtnKBN", SqlDbType.TinyInt);
                param7.Direction = ParameterDirection.Output;

                SqlParameter param8;
                param8 = sc.Parameters.Add("@po_ErrorBtnDefault", SqlDbType.TinyInt);
                param8.Direction = ParameterDirection.Output;

                SqlParameter param9;
                param9 = sc.Parameters.Add("@po_SystemDenpyouNO", SqlDbType.Decimal, 18);
                param9.Direction = ParameterDirection.InputOutput;

                if (obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    param9.Value = ConvertParamData(systemDenpyouNO);
                }
                else
                {
                    param9.Value = DBNull.Value;
                }

                SqlParameter param10;
                param10 = sc.Parameters.Add("@po_DenpyouNO", SqlDbType.VarChar, 12);
                param10.Direction = ParameterDirection.InputOutput;
                if (obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    param10.Value = obic7TextStringDenpyouNO.Value;
                }
                else
                {
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if ((ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN != 2)
                    //  || (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN != 2))
                    if ((this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN != 2)
                      || (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN != 2))
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        param10.Value = obic7TextStringCalledDenpyouNO.Value;
                    }
                    else
                    {
                        param10.Value = obic7TextStringDenpyouNO.Value;
                    }
                }

                SqlParameter param11;
                param11 = sc.Parameters.Add("@p_ShoriMode", SqlDbType.TinyInt);
                param11.Direction = ParameterDirection.Input;
                if (obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    //新規
                    param11.Value = 1;
                }
                else
                {
                    //修正
                    param11.Value = 2;
                }

                SqlParameter param12;
                param12 = sc.Parameters.Add("@p_DenpyouSaibanHouhou", SqlDbType.TinyInt);
                param12.Direction = ParameterDirection.Input;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20)
                if (this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou)
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                {
                    //伝票採番区分
                    param12.Value = ConvertParamData(denpyouSaibanKBN);
                }
                else
                {
                    //仮伝票採番区分
                    param12.Value = ConvertParamData(kariDenpyouSaibanKBN);
                }

                SqlParameter param13;
                param13 = sc.Parameters.Add("@p_DenpyouCountKeta", SqlDbType.TinyInt);
                param13.Direction = ParameterDirection.Input;
                param13.Value = ConvertParamData(denpyouNOKetasuu);

                SqlParameter param14;
                param14 = sc.Parameters.Add("@p_ZigyoushoCD", SqlDbType.VarChar, 6);
                param14.Direction = ParameterDirection.Input;
                param14.Value = obic7TextStringZigyoushoCD.Value;

                SqlParameter param15;
                param15 = sc.Parameters.Add("@p_HasseiDate", SqlDbType.DateTime);
                param15.Direction = ParameterDirection.Input;
                param15.Value = obic7TextDatetimeHasseiDate.Value;

                SqlParameter param16;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //param16 = sc.Parameters.Add("@p_DenpyouKBN", SqlDbType.VarChar, 2);
                param16 = sc.Parameters.Add("@p_DenpyouKBN", SqlDbType.VarChar, 3);
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                param16.Direction = ParameterDirection.Input;
                param16.Value = obic7TextStringDenpyouKBN.Value;

                SqlParameter param17;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //param17 = sc.Parameters.Add("@p_ShuuseimaeDenpyouKBN", SqlDbType.VarChar, 2);
                param17 = sc.Parameters.Add("@p_ShuuseimaeDenpyouKBN", SqlDbType.VarChar, 3);
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                param17.Direction = ParameterDirection.Input;
                param17.Value = ConvertParamData(prevDenpyouKBN);

                SqlParameter param26;
                param26 = sc.Parameters.Add("@p_BumonSecurityPatternCD", SqlDbType.VarChar, 4);
                param26.Direction = ParameterDirection.Input;
                param26.Value = bumonSecurityPatternCD;

                SqlParameter param27;
                param27 = sc.Parameters.Add("@p_KanjouSecurityPatternCD", SqlDbType.VarChar, 4);
                param27.Direction = ParameterDirection.Input;
                param27.Value = kanjouSecurityPatternCD;

                SqlParameter param28;
                param28 = sc.Parameters.Add("@p_ZigyoushoSecurityPatternCD", SqlDbType.VarChar, 4);
                param28.Direction = ParameterDirection.Input;
                param28.Value = zigyoushoSecurityPatternCD;


                SqlParameter param29;
                param29 = sc.Parameters.Add("@p_HonsitenSecurityFlag", SqlDbType.TinyInt);
                param29.Direction = ParameterDirection.Input;
                param29.Value = honsitenSecurityFlag;

                SqlParameter param18;
                param18 = sc.Parameters.Add("@p_UpdateDatetime", SqlDbType.DateTime);
                param18.Direction = ParameterDirection.Input;
                param18.Value = GetSystemDate();

                SqlParameter param19;
                param19 = sc.Parameters.Add("@p_UpdateCertificatedGuid", SqlDbType.UniqueIdentifier);
                param19.Direction = ParameterDirection.Input;
                param19.Value = ComATool.Logic.CurrentUser.CertificatedGuid;

                SqlParameter param20;
                param20 = sc.Parameters.Add("@p_UpdateJobID", SqlDbType.VarChar, 128);
                param20.Direction = ParameterDirection.Input;
                param20.Value = ComATool.Logic.CurrentUser.JobID;

                SqlParameter param21;
                param21 = sc.Parameters.Add("@p_UpdateUserID", SqlDbType.VarChar, 128);
                param21.Direction = ParameterDirection.Input;
                param21.Value = ComATool.Logic.CurrentUser.UserID;

                SqlParameter param22;
                param22 = sc.Parameters.Add("@p_UpdateComputerName", SqlDbType.VarChar, 128);
                param22.Direction = ParameterDirection.Input;
                param22.Value = ComATool.Logic.CurrentUser.ComputerName;

                SqlParameter param23;
                param23 = sc.Parameters.Add("@p_UpdateComputerUserName", SqlDbType.VarChar, 128);
                param23.Direction = ParameterDirection.Input;
                param23.Value = ComATool.Logic.CurrentUser.ComputerUserName;

                SqlParameter param24;
                param24 = sc.Parameters.Add("@p_UpdateComputerDomainName", SqlDbType.VarChar, 256);
                param24.Direction = ParameterDirection.Input;
                param24.Value = ComATool.Logic.CurrentUser.ComputerDomainName;

                SqlParameter param25;
                param25 = sc.Parameters.Add("RetVal", SqlDbType.Int);
                param25.Direction = ParameterDirection.ReturnValue;

                // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(残高更新)
                SqlParameter param30;
                param30 = sc.Parameters.Add("@p_BunsekibetuZandakaSiyouKBN", SqlDbType.TinyInt);
                param30.Direction = ParameterDirection.Input;
                param30.Value = ConvertParamData(bunsekibetuZandakaSiyouKBN);
                // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(残高更新)

                try
                {
                    sc.ExecuteNonQuery();
                }
                catch (SqlException ex)
                {
                    //【ストアドにて業務ロジック以外のエラー（システムエラー）発生時は、ここで例外を処理する。】
                    //メッセージ分類は「InternalError」、メッセージアイコンは「Error」とする。
                    //ロールバック、メッセージボックス表示処理は業務ロジックで行い、処理の中断のみ行う。
                    //アプリケーションは異常終了させない。
                    //注：この処理を行うのは、デッドロックの場合のみとする。

                    bool bDeadLockFlg = true;

                    //メッセージ詳細の組み立て
                    string[] objMsgDetail = new string[3];

                    //ストアド名
                    objMsgDetail[0] = ex.Procedure.ToString();
                    //エラーコード
                    objMsgDetail[1] = ex.Number.ToString();
                    //エラー内容
                    for (int i = 0; i < ex.Errors.Count; i++)
                    {
                        objMsgDetail[2] += ex.Errors[i].ToString();
                    }

                    //エラーがデッドロック以外の場合、フラグをfalseに設定する。
                    //ex.エラーコード = 1205 → デッドロック
                    //                = 2627 → キー重複
                    //                = 8134 → ゼロ除算
                    if (ex.Number != 1205)
                    {
                        bDeadLockFlg = false;
                    }

                    if (bDeadLockFlg == true)
                    {
                        //デッドロックの場合は、業務にてエラー処理を行う。

                        // ロールバック
                        businessDB.RollBackTransaction();

                        //メッセージボックス表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00119", null, objMsgDetail, GetType(),
                                                             WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                             WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return 99999;
                    }
                    else
                    {
                        //デッドロック以外のエラーはthrowして、共通クラスのエラー処理に委ねる。
                        throw;
                    }
                }

                //システムエラー発生時
                //（留意事項）エラー発生時、ストアドの「ERR_SHORI」ブロックで処理された結果のパラメータは、C＃側で参照することが出来ません。
                //            よってこの部分が処理されることはありませんが、明示的に共通部品の例外を発生させる例として記載しておきます。
                //【例外処理は、上記のcatch句内にて行います。】
                if (ComATool.Function.AnyToInt16(param1.Value) == 1)
                {
                    //業務にて想定の範囲外のエラーが発生した場合は、共通部品を使用して明示的に例外をスローし、呼び出し元にてCatchする。
                    //(例外スローによる上位処理(共通部品側処理)終了時、当JOBは強制終了される。)
                    throw new ComATool.Obic7Exception("想定外のエラーが発生しました。【詳細】ストアド名 = "
                                                       + param4.Value.ToString() + " エラー内容 = " + param6.Value.ToString());
                }

                //個別エラー発生時
                if (ComATool.Function.AnyToInt16(param1.Value) == 2)
                //業務にて想定の範囲内のエラーが発生した場合は、ストアドからの戻り値を取得して、メッセージボックスを表示する。
                {
                    // ロールバック
                    businessDB.RollBackTransaction();

                    ProcError(param2, param3, param4, param5, param6, param7, param8);

                    //2009/08/05 OBIC H.Sudo 変更 開始 (M04264)１行目の借方勘定科目にフォーカスセット
                    //１行目の借方勘定科目にフォーカスセット
                    SetFocusMeisaiCtl(KBN_KOUMOKUCHK_ALL, 0, COL_KARIKANJOUCD);
                    //2009/08/05 OBIC H.Sudo 変更 終了

                    return ComATool.Function.AnyToInt32(param3.Value);
                }


                obic7TextStringPrevDenpyouNO.Text = ComATool.Function.AnyToString(param10.Value);
                systemDenpyouNO = ComATool.Function.AnyToDecimal(param9.Value);
            }
            return 0;
        }

