        /// <summary>
        /// 仕訳ﾊﾟﾀｰﾝの登録
        /// </summary>
        /// <param name="siwakepatternno">仕訳ﾊﾟﾀｰﾝ番号</param>
        /// <param name="siwakepatternname">仕訳ﾊﾟﾀｰﾝ名</param>
        /// <param name="siwakepatterngroup">仕訳ﾊﾟﾀｰﾝグループ</param>
        /// <param name="commonpatternkbn">仕訳ﾊﾟﾀｰﾝの共通パターン区分</param>
        /// <param name="usergroupcd">仕訳ﾊﾟﾀｰﾝのユーザグループコード</param>
        /// <returns></returns>
        private int EntrySiwakePattern(string siwakepatternno, string siwakepatternname, string siwakepatterngroup, int commonpatternkbn, string usergroupcd)
        // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)
        {
            using (SqlCommand sc = businessDB.NewSqlCommand())
            {
                sc.CommandType = CommandType.StoredProcedure;
                sc.CommandText = SIWAKE_PATTERN_ENTRY;

                SqlParameter param1;
                param1 = sc.Parameters.Add("@po_ErrorKBN", SqlDbType.Int);
                param1.Direction = ParameterDirection.Output;

                SqlParameter param2;
                param2 = sc.Parameters.Add("@po_ErrorCD1", SqlDbType.VarChar, 128);
                param2.Direction = ParameterDirection.Output;

                SqlParameter param3;
                param3 = sc.Parameters.Add("@po_ErrorCD2", SqlDbType.VarChar, 128);
                param3.Direction = ParameterDirection.Output;

                SqlParameter param4;
                param4 = sc.Parameters.Add("@po_ErrorProcName", SqlDbType.VarChar, 128);
                param4.Direction = ParameterDirection.Output;

                SqlParameter param5;
                param5 = sc.Parameters.Add("@po_ErrorSummary", SqlDbType.VarChar, 256);
                param5.Direction = ParameterDirection.Output;

                SqlParameter param6;
                param6 = sc.Parameters.Add("@po_ErrorDetail", SqlDbType.VarChar, 2560);
                param6.Direction = ParameterDirection.Output;

                SqlParameter param7;
                param7 = sc.Parameters.Add("@po_ErrorBtnKBN", SqlDbType.TinyInt);
                param7.Direction = ParameterDirection.Output;

                SqlParameter param8;
                param8 = sc.Parameters.Add("@po_ErrorBtnDefault", SqlDbType.TinyInt);
                param8.Direction = ParameterDirection.Output;

                SqlParameter param9;
                param9 = sc.Parameters.Add("@p_UserGroupCD", SqlDbType.VarChar, 6);
                param9.Direction = ParameterDirection.Input;
                // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                //param9.Value = userGroupCD;
                param9.Value = usergroupcd; //登録するユーザグループコード
                // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

                SqlParameter param10;
                param10 = sc.Parameters.Add("@p_SiwakePatternNO", SqlDbType.VarChar, 12);
                param10.Direction = ParameterDirection.Input;
                param10.Value = siwakepatternno;

                SqlParameter param11;
                param11 = sc.Parameters.Add("@p_SiwakePatternName", SqlDbType.VarChar, 30);
                param11.Direction = ParameterDirection.Input;
                param11.Value = ConvertParamData(siwakepatternname);

                SqlParameter param12;
                param12 = sc.Parameters.Add("@p_SiwakePatternGroup", SqlDbType.VarChar, 20);
                param12.Direction = ParameterDirection.Input;
                param12.Value = ConvertParamData(siwakepatterngroup);

                SqlParameter param13;
                param13 = sc.Parameters.Add("@p_ZigyoushoCD", SqlDbType.VarChar, 6);
                param13.Direction = ParameterDirection.Input;
                param13.Value = obic7TextStringZigyoushoCD.Value;

                SqlParameter param14;
                param14 = sc.Parameters.Add("@p_DenpyouTekiyou", SqlDbType.VarChar, 60);
                param14.Direction = ParameterDirection.Input;
                param14.Value = ConvertParamData(obic7TextStringDenpyouTekiyou.Value);

                SqlParameter param15;
                param15 = sc.Parameters.Add("@p_UpdateDatetime", SqlDbType.DateTime);
                param15.Direction = ParameterDirection.Input;
                param15.Value = GetSystemDate();

                SqlParameter param16;
                param16 = sc.Parameters.Add("@p_UpdateCertificatedGuid", SqlDbType.UniqueIdentifier);
                param16.Direction = ParameterDirection.Input;
                param16.Value = ComATool.Logic.CurrentUser.CertificatedGuid;

                SqlParameter param17;
                param17 = sc.Parameters.Add("@p_UpdateJobID", SqlDbType.VarChar, 128);
                param17.Direction = ParameterDirection.Input;
                param17.Value = ComATool.Logic.CurrentUser.JobID;

                SqlParameter param18;
                param18 = sc.Parameters.Add("@p_UpdateUserID", SqlDbType.VarChar, 128);
                param18.Direction = ParameterDirection.Input;
                param18.Value = ComATool.Logic.CurrentUser.UserID;

                SqlParameter param19;
                param19 = sc.Parameters.Add("@p_UpdateComputerName", SqlDbType.VarChar, 128);
                param19.Direction = ParameterDirection.Input;
                param19.Value = ComATool.Logic.CurrentUser.ComputerName;

                SqlParameter param20;
                param20 = sc.Parameters.Add("@p_UpdateComputerUserName", SqlDbType.VarChar, 128);
                param20.Direction = ParameterDirection.Input;
                param20.Value = ComATool.Logic.CurrentUser.ComputerUserName;

                SqlParameter param21;
                param21 = sc.Parameters.Add("@p_UpdateComputerDomainName", SqlDbType.VarChar, 256);
                param21.Direction = ParameterDirection.Input;
                param21.Value = ComATool.Logic.CurrentUser.ComputerDomainName;

                SqlParameter param22;
                param22 = sc.Parameters.Add("RetVal", SqlDbType.Int);
                param22.Direction = ParameterDirection.ReturnValue;

                //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
                //仕訳パターン呼出時の仕訳パターン番号のタイムスタンプ
                SqlParameter param23;
                param23 = sc.Parameters.Add("@po_UpdateTimestamp", SqlDbType.Timestamp);
                param23.Direction = ParameterDirection.InputOutput;
                //2008/11/10  変更  T.Nakano  終了
                //一度も仕訳パターンが呼び出されていないとき
                if (this.siwakePatternTimestamp == null)
                {
                    param23.Value = DBNull.Value;
                }
                //呼び出されていれば、そのときの仕訳パターン番号のタイムスタンプ
                else
                {
                    param23.Value = this.siwakePatternTimestamp;
                }

                //仕訳パターン呼出時の仕訳パターン番号
                SqlParameter param24;
                param24 = sc.Parameters.Add("@p_MotoSiwakePatternNO", SqlDbType.VarChar, 12);
                param24.Direction = ParameterDirection.Input;
                //一度も仕訳パターンが呼び出されていないとき
                if (String.IsNullOrEmpty(this.siwakePatternNO))
                {
                    param24.Value = DBNull.Value;
                }
                //呼び出されていれば、そのときの仕訳パターン番号のタイムスタンプ
                else
                {
                    param24.Value = this.siwakePatternNO;
                }
                //2008/11/10  変更  T.Nakano  終了

                // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                //共通パターン区分
                SqlParameter param25;
                param25 = sc.Parameters.Add("@p_CommonPatternKBN", SqlDbType.TinyInt);
                param25.Direction = ParameterDirection.Input;
                param25.Value = commonpatternkbn;

                //仕訳パターン呼出時のユーザグループコード
                SqlParameter param26;
                param26 = sc.Parameters.Add("@p_MotoUserGroupCD", SqlDbType.VarChar, 6);
                param26.Direction = ParameterDirection.Input;
                //一度も仕訳パターンが呼び出されていないとき
                if (String.IsNullOrEmpty(this.siwakePatternUserGroupCD))
                {
                    param26.Value = DBNull.Value;
                }
                //呼び出されていれば、そのときのユーザグループコード
                else
                {
                    param26.Value = this.siwakePatternUserGroupCD;
                }
                // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

                try
                {
                    sc.ExecuteNonQuery();
                }
                catch (SqlException ex)
                {
                    //【ストアドにて業務ロジック以外のエラー（システムエラー）発生時は、ここで例外を処理する。】
                    //メッセージ分類は「InternalError」、メッセージアイコンは「Error」とする。
                    //ロールバック、メッセージボックス表示処理は業務ロジックで行い、処理の中断のみ行う。
                    //アプリケーションは異常終了させない。
                    //注：この処理を行うのは、デッドロックの場合のみとする。

                    bool bDeadLockFlg = true;

                    //メッセージ詳細の組み立て
                    string[] objMsgDetail = new string[3];

                    //ストアド名
                    objMsgDetail[0] = ex.Procedure.ToString();
                    //エラーコード
                    objMsgDetail[1] = ex.Number.ToString();
                    //エラー内容
                    for (int i = 0; i < ex.Errors.Count; i++)
                    {
                        objMsgDetail[2] += ex.Errors[i].ToString();
                    }

                    //エラーがデッドロック以外の場合、フラグをfalseに設定する。
                    //ex.エラーコード = 1205 → デッドロック
                    //                = 2627 → キー重複
                    //                = 8134 → ゼロ除算
                    if (ex.Number != 1205)
                    {
                        bDeadLockFlg = false;
                    }

                    if (bDeadLockFlg == true)
                    {
                        //デッドロックの場合は、業務にてエラー処理を行う。

                        // ロールバック
                        businessDB.RollBackTransaction();

                        //メッセージボックス表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00119", null, objMsgDetail, GetType(),
                                                             WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                             WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return 99999;
                    }
                    else
                    {
                        //デッドロック以外のエラーはthrowして、共通クラスのエラー処理に委ねる。
                        throw;
                    }
                }

                //システムエラー発生時
                //（留意事項）エラー発生時、ストアドの「ERR_SHORI」ブロックで処理された結果のパラメータは、C＃側で参照することが出来ません。
                //            よってこの部分が処理されることはありませんが、明示的に共通部品の例外を発生させる例として記載しておきます。
                //【例外処理は、上記のcatch句内にて行います。】
                if (ComATool.Function.AnyToInt16(param1.Value) == 1)
                {
                    //業務にて想定の範囲外のエラーが発生した場合は、共通部品を使用して明示的に例外をスローし、呼び出し元にてCatchする。
                    //(例外スローによる上位処理(共通部品側処理)終了時、当JOBは強制終了される。)
                    throw new ComATool.Obic7Exception("想定外のエラーが発生しました。【詳細】ストアド名 = "
                                                       + param4.Value.ToString() + " エラー内容 = " + param6.Value.ToString());
                }

                //個別エラー発生時
                if (ComATool.Function.AnyToInt16(param1.Value) == 2)
                //業務にて想定の範囲内のエラーが発生した場合は、ストアドからの戻り値を取得して、メッセージボックスを表示する。
                {
                    // ロールバック
                    businessDB.RollBackTransaction();

                    ProcError(param2, param3, param4, param5, param6, param7, param8);

                    return ComATool.Function.AnyToInt32(param3.Value);
                }

                //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
                //タイムスタンプを格納
                if (param23.Value != DBNull.Value)
                {
                    this.siwakePatternTimestamp = (byte[])param23.Value;
                }
                //2008/11/10  変更  T.Nakano  終了
            }
            return 0;
        }

