        #region 基準締管理マスタからの取得項目洗替（明細）
        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
        /// <summary>
        /// 事業所単位ではない場合、締日と本支店締日を基準締管理マスタから再取得
        /// </summary>
        private void RefreshMeisaiDenpyouSimeDate()
        {
            //仕訳画面データ取得
            DataView dataView = obic7MultilineCheckGridDetail.GetDisplayedData();

            for (int i = 0; i < dataView.Count; i++)
            {
                for (int taishakukbn = 1; taishakukbn <= 2; taishakukbn++)
                {
                    this.SetMeisaiDenpyouSimeDate(i, taishakukbn, KBN_KOUMOKUCHK_ALL);
                }
            }
        }
        /// <summary>
        /// 
        /// </summary>
        /// <param name="rowNo"></param>
        /// <param name="taishakukbn"></param>
        /// <param name="checkkbn"></param>
        private void SetMeisaiDenpyouSimeDate(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtKijunSimeM = null;
            DataTable dtHonshaKijunSimeM = null;

            //貸借名
            String taishakuName;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
            }
            else
            {
                taishakuName = "Kasi";
            }

            if (!String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")))
            {
                dtKijunSimeM = WinMToolSearchCom.M0000MS_MA_KijunSimeKanri.SelectByKey(
                               GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")
                               , (Int32)this.obic7TextNumberKijunKBN.Value
                               , "");

                dtHonshaKijunSimeM = WinMToolSearchCom.M0000MS_MA_KijunSimeKanri.SelectByKey(
                               GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD")
                               , (Int32)this.obic7TextNumberKijunKBN.Value
                               , "");

                //事業所伝票締日をセット
                SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoDenpyouSimeDate", null);
                if (dtKijunSimeM != null && dtKijunSimeM.Rows.Count != 0)
                {
                    SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoDenpyouSimeDate", ChangeDateTime(dtKijunSimeM.Rows[0]["DenpyouSimeDate"]));
                }
                SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoDenpyouSimeDate", null);
                if (dtHonshaKijunSimeM != null && dtHonshaKijunSimeM.Rows.Count != 0)
                {
                    if (hontenShuutyuuFlag == 1 && GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD") != GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD"))
                    {
                        //本社事業所伝票締日をセット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoDenpyouSimeDate", ChangeDateTime(dtHonshaKijunSimeM.Rows[0]["DenpyouSimeDate"]));
                    }
                }
            }
        }
        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
        #endregion

        #endregion

        #region ストアドエラー処理
        private void ProcError(SqlParameter errorCD1, SqlParameter errorCD2, SqlParameter errorProcName, SqlParameter errorSummary, SqlParameter errorDetail, SqlParameter errorBtnKBN, SqlParameter errorBtnDefault)
        {
            //メッセージ概要・メッセージ詳細がパラメータ形式の文言の場合、パラメータにセットする値を配列形式で指定。
            //ストアドからの戻り値を、垂直タブ文字をデリミタとして分割し、配列に格納する。
            string[] objErrSummary = null;
            string[] objErrDetail = null;

            if (String.IsNullOrEmpty(errorSummary.Value.ToString()) == false)
            {
                objErrSummary = errorSummary.Value.ToString().Split('\v');
            }

            if (String.IsNullOrEmpty(errorDetail.Value.ToString()) == false)
            {
                objErrDetail = errorDetail.Value.ToString().Split('\v');
            }

            //ストアドからの戻り値より、メッセージボックスに表示するボタン種類とデフォルトボタンを設定する。
            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons btnType;
            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton btnDefault;

            switch (ComATool.Function.AnyToInt16(errorBtnKBN.Value.ToString()))
            {
                case 0:
                    btnType = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK;
                    break;

                case 1:
                    btnType = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo;
                    break;

                case 2:
                    btnType = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNoCancel;
                    break;

                default:
                    btnType = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK;
                    break;
            }

            switch (ComATool.Function.AnyToInt16(errorBtnDefault.Value.ToString()))
            {
                case 0:
                    btnDefault = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1;
                    break;

                case 1:
                    btnDefault = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button2;
                    break;

                case 2:
                    btnDefault = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button3;
                    break;

                default:
                    btnDefault = WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1;
                    break;
            }

            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, errorCD1.Value.ToString(), errorCD2.Value.ToString(), objErrSummary, objErrDetail, GetType(),
                                                        btnType,
                                                        btnDefault);


        }

        #endregion

        #region 合計金額計算(全体)
        /// <summary>
        /// 合計金額再計算（全体）
        /// </summary>
        private void RecalcTotal()
        {
            //金額コントロールワーク
            //ワーク用
            DataView source;
            //金額合計ワーク
            Decimal karikingaku = 0;
            Decimal kasikingaku = 0;
            Decimal karizeigaku = 0;
            Decimal kasizeigaku = 0;

            source = obic7MultilineCheckGridDetail.GetDisplayedData();
            //全行計算
            for (int i = 0; i < source.Count; i++)
            {
                karikingaku += ComATool.Function.AnyToDecimal(source[i][COL_KARIKINGAKU]);
                kasikingaku += ComATool.Function.AnyToDecimal(source[i][COL_KASIKINGAKU]);
                karizeigaku += ComATool.Function.AnyToDecimal(source[i][COL_KARIZEIGAKU]);
                kasizeigaku += ComATool.Function.AnyToDecimal(source[i][COL_KASIZEIGAKU]);
            }
            //金額をセットする
            obic7TextNumberTotalKariKingaku.Value = karikingaku;
            obic7TextNumberTotalKasiKingaku.Value = kasikingaku;
            obic7TextNumberTotalKariZeigaku.Value = karizeigaku;
            obic7TextNumberTotalKasiZeigaku.Value = kasizeigaku;
            obic7TextNumberTotalKariSougaku.Value = karikingaku + karizeigaku;
            obic7TextNumberTotalKasiSougaku.Value = kasikingaku + kasizeigaku;
        }
        #endregion

        #region 合計金額計算(行変更時)

        /// <summary>
        /// 合計金額再計算(行変更時)
        /// </summary>
        /// <param name="prevkingaku">変更前金額</param>
        /// <param name="prevzeigaku">変更前税額</param>
        /// <param name="curkingaku">現在金額</param>
        /// <param name="curzeigaku">現在税額</param>
        /// <param name="taishakukbn">貸借区分 1:借方 2:貸方</param>
        private void RecalcTotalForRowChenge(decimal? prevkingaku, decimal? prevzeigaku, decimal? curkingaku, decimal? curzeigaku, int taishakukbn)
        {
            //借方
            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                //合計金額計算
                obic7TextNumberTotalKariKingaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariKingaku.Value) - ComATool.Function.AnyToDecimal(prevkingaku) + ComATool.Function.AnyToDecimal(curkingaku);
                //合計税額計算
                obic7TextNumberTotalKariZeigaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariZeigaku.Value) - ComATool.Function.AnyToDecimal(prevzeigaku) + ComATool.Function.AnyToDecimal(curzeigaku);
                //合計総額計算
                obic7TextNumberTotalKariSougaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariSougaku.Value) - (ComATool.Function.AnyToDecimal(prevkingaku) + ComATool.Function.AnyToDecimal(prevzeigaku)) + (ComATool.Function.AnyToDecimal(curkingaku) + ComATool.Function.AnyToDecimal(curzeigaku));
            }
            //貸方
            else
            {
                //合計金額計算
                obic7TextNumberTotalKasiKingaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiKingaku.Value) - ComATool.Function.AnyToDecimal(prevkingaku) + ComATool.Function.AnyToDecimal(curkingaku);
                //合計税額計算
                obic7TextNumberTotalKasiZeigaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiZeigaku.Value) - ComATool.Function.AnyToDecimal(prevzeigaku) + ComATool.Function.AnyToDecimal(curzeigaku);
                //合計総額計算
                obic7TextNumberTotalKasiSougaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiSougaku.Value) - (ComATool.Function.AnyToDecimal(prevkingaku) + ComATool.Function.AnyToDecimal(prevzeigaku)) + (ComATool.Function.AnyToDecimal(curkingaku) + ComATool.Function.AnyToDecimal(curzeigaku));
            }
        }
        #endregion

