        #region 最大行番号を取得処理
        /// <summary>
        /// 最大行番号を取得
        /// </summary>
        /// <returns>明細中の最大行番号</returns>
        private decimal GetMaxRowNo()
        {
            //最大行NO
            Decimal maxRowNO = 0;
            //ワーク用
            DataView source;
            //行番号未設定の場合のみ処理を行う
            source = obic7MultilineCheckGridDetail.GetDisplayedData();
            for (int i = 0; i < source.Count; i++)
            {
                if (String.IsNullOrEmpty(ComATool.Function.AnyToString(source[i]["GyouNO"])) == false)
                {
                    if (maxRowNO < ComATool.Function.AnyToDecimal(source[i]["GyouNO"]))
                    {
                        maxRowNO = ComATool.Function.AnyToDecimal(source[i]["GyouNO"]);
                    }
                }
            }
            return maxRowNO;
        }
        #endregion

        #region 合計金額より指定明細行の金額をマイナスする

        /// <summary>
        /// 合計金額より指定明細行の金額をマイナスする
        /// </summary>
        /// <param name="rowNo">マイナス対象行番号</param>
        private void MinusTotal(int rowNo)
        {
            //借方金額コントロールワーク
            WinAToolUI.Obic7TextNumber kariKingaku;
            //借方消費税コントロールワーク
            WinAToolUI.Obic7TextNumber kariZeigaku;
            //貸方金額コントロールワーク
            WinAToolUI.Obic7TextNumber kasiKingaku;
            //貸方消費税コントロールワーク
            WinAToolUI.Obic7TextNumber kasiZeigaku;

            //借方金額コントロール取得
            kariKingaku = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIKINGAKU) as WinAToolUI.Obic7TextNumber;
            if (kariKingaku != null)
            {
                //合計金額を再計算
                obic7TextNumberTotalKariKingaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariKingaku.Value) - ComATool.Function.AnyToDecimal(kariKingaku.Value);
            }
            //借方消費税コントロール取得
            kariZeigaku = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIZEIGAKU) as WinAToolUI.Obic7TextNumber;
            if (kariZeigaku != null)
            {
                //合計金額を再計算
                obic7TextNumberTotalKariZeigaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariZeigaku.Value) - ComATool.Function.AnyToDecimal(kariZeigaku.Value);
            }
            //貸方金額コントロール取得
            kasiKingaku = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIKINGAKU) as WinAToolUI.Obic7TextNumber;
            if (kasiKingaku != null)
            {
                //合計金額を再計算
                obic7TextNumberTotalKasiKingaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiKingaku.Value) - ComATool.Function.AnyToDecimal(kasiKingaku.Value);
            }
            //貸方消費税コントロール取得
            kasiZeigaku = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIZEIGAKU) as WinAToolUI.Obic7TextNumber;
            if (kasiZeigaku != null)
            {
                //合計金額を再計算
                obic7TextNumberTotalKasiZeigaku.Value = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiZeigaku.Value) - ComATool.Function.AnyToDecimal(kasiZeigaku.Value);
            }

            //借方合計総額をセット
            obic7TextNumberTotalKariSougaku.Value = obic7TextNumberTotalKariKingaku.Value + obic7TextNumberTotalKariZeigaku.Value;
            //貸方合計総額をセット
            obic7TextNumberTotalKasiSougaku.Value = obic7TextNumberTotalKasiKingaku.Value + obic7TextNumberTotalKasiZeigaku.Value;

        }

        #endregion

        #region 指定行以降の行番号の洗い換えを行う
        /// <summary>
        /// 指定行以降の行番号の洗い換えを行う 
        /// </summary>
        /// <param name="gyouNo">洗い換え開始行</param>
        /// <param name="shorikbn">処理区分 1: 行挿入時 2:行削除時</param>
        private void ResetRowNo(int gyouNo, int shorikbn)
        {
            //データビュー
            DataView displayData = obic7MultilineCheckGridDetail.GetDisplayedData();
            //明細コントロール最大行
            int maxRow = displayData.Count;
            if (shorikbn == 1)
            {
                //各行の行番号を再セットする
                for (int i = 0; i < maxRow; i++)
                {
                    if (ComATool.Function.AnyToInt32(displayData[i]["GyouNO"]) >= gyouNo)
                    {

                        //新規行でなければ番号を振りなおす
                        displayData[i]["GyouNO"] = ComATool.Function.AnyToInt32(displayData[i]["GyouNO"]) + 1;
                    }
                }
            }
            else
            {
                for (int i = 0; i < maxRow; i++)
                {
                    if (ComATool.Function.AnyToInt32(displayData[i]["GyouNO"]) > gyouNo)
                    {

                        //新規行でなければ番号を振りなおす
                        displayData[i]["GyouNO"] = ComATool.Function.AnyToInt32(displayData[i]["GyouNO"]) - 1;
                    }
                }
            }
        }
        #endregion

