        /// <param name="Kbn">1:ヘッダ部 2:明細部</param>
        private void ClearErrorProvider(int Kbn)
        {

            int meisaicnt = 0;

            if (Kbn == 1)
            {
                //ヘッダのエラープロバイダを解除
                WinAToolUI.Obic7ErrorProvider.Clear(obic7TextStringZigyoushoCD);
                WinAToolUI.Obic7ErrorProvider.Clear(obic7TextDatetimeHasseiDate);
                WinAToolUI.Obic7ErrorProvider.Clear(obic7TextStringDenpyouKBN);
