                //解除する行数を取得
                if (obic7MultilineCheckGridDetail.GetDisplayedData().Count < DSPLAY_ROW_COUNT)
                {
                    meisaicnt = obic7MultilineCheckGridDetail.GetDisplayedData().Count + 1;
