                    WinAToolUI.Obic7ErrorProvider.Clear(GetNumberColumn(i, COL_KARIZEIKOMIKBN));
                    WinAToolUI.Obic7ErrorProvider.Clear(GetNumberColumn(i, COL_KARIKINGAKU));
                    WinAToolUI.Obic7ErrorProvider.Clear(GetNumberColumn(i, COL_KARIZEIGAKU));
                    WinAToolUI.Obic7ErrorProvider.Clear(GetStringColumn(i, COL_KARIBUNSEKICD1));
