        #region 仕訳区分の取得
        /// <summary>
        /// 仕訳区分を取得する
        /// </summary>
        private bool GetSiwakeKBN()
        {

            //仕訳区分データを本支店仕訳入力画面明細ワークテーブルにセットし、そのデータを取得
            using (DataTable dtSiwake = GetSiwakeData())
            {

                if (dtSiwake == null)
                {
                    return false;
                }

                //仕訳画面データ取得
                DataView dvMeisai = obic7MultilineCheckGridDetail.GetDisplayedData();

                //データビュー取得
                DataView dvSiwake = dtSiwake.DefaultView;

                //行番号順にソート
                dvMeisai.Sort = "GyouNO";
                dvSiwake.Sort = "GyouNO";

                for (int i = 0; i < dvSiwake.Count; i++)
                {
                    //仕訳区分のセット
                    dvMeisai[i][COL_SIWAKEKBN] = dvSiwake[i][0];
                }

                dvSiwake.Dispose();
            }
            return true;
        }

