                        toolTip1.SetToolTip(this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKasiMemo"), GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO));
                    }
                    else
                    {
                        //ツールチップテキスト
                        toolTip1.SetToolTip(this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKasiMemo"), "");
                    }
                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
                }
                else
                {
                    return;
                }
            }
        }

