        #region 複写処理
        /// <summary>
        /// 指定明細行に１行上の行のデータを複写する
        /// </summary>
        /// <param name="hukushakbn">複写区分 0:全て 1:摘要のみ</param>
        private bool ExecHukusha(int hukushakbn)
        {
            DataView source;

            //１つ上の行番号
            int prevRowNO;
            WinAToolUI.Obic7TextAbstract textAbstract = null;
            //旧value
            textAbstract = PrevControl as WinAToolUI.Obic7TextAbstract;

            //１つ上の行の行番号セット

            if (String.IsNullOrEmpty(GetNumberColumn(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_GYOUNO).Text) == false)
            {
                //現在行が既存行の時
                prevRowNO = ComATool.Function.AnyToInt32(((WinATool.UI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_GYOUNO)).Value) - 1;
            }
            else
            {
                //現在行が新規行の時
                prevRowNO = ComATool.Function.AnyToInt32(GetMaxRowNo());
            }

            //先頭行の時(カレント行の行番号が1の時)
            if (prevRowNO <= 0)
            {
                //エラーメッセージ表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00238", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                return false;
            }

            source = obic7MultilineCheckGridDetail.GetDisplayedData();

            if (hukushakbn == KBN_HUKUSHA_TEKIYOU)
            {
                //摘要のみコピー
                GetStringColumn(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_MEISAITEKIYOU).Value = ComATool.Function.AnyToString(source.ToTable().Rows[prevRowNO - 1][COL_MEISAITEKIYOU]);
            }
            else
            {
                // 2013/09/04 修正 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                ////行番号以外全てコピー
                //for (int i = 0; i < COL_COUNT - 1; i++)
                //{
                //    if (i != COL_GYOUNO)
                //    {
                //        ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), i)).Text = ComATool.Function.AnyToString(source.ToTable().Rows[prevRowNO - 1][i]);
                //    }
                //}
                for (int i = 0; i < COL_COUNT - 1; i++)
                {
                    //行番号、メモ情報以外全てコピー
                    if (i != COL_GYOUNO
                        && i != COL_KARIMEMO_RVALUE && i != COL_KARIMEMO_GVALUE && i != COL_KARIMEMO_BVALUE && i != COL_KARIMEMO
                        && i != COL_KASIMEMO_RVALUE && i != COL_KASIMEMO_GVALUE && i != COL_KASIMEMO_BVALUE && i != COL_KASIMEMO)
                    {
                        ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), i)).Text = ComATool.Function.AnyToString(source.ToTable().Rows[prevRowNO - 1][i]);
                    }
                }
                // 2013/09/04 修正 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

                //コピー元の行番号
                int? gyouNo;
                //コピー元のBaseDataSetのシーケンス
                int internalSeq = 999;

                //コピー元の行番号取得(コピー先が追加行の場合は-1が取得される)
                gyouNo = ComATool.Function.AnyToInt32(((WinAToolUI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_GYOUNO)).Value) - 1;


                if (gyouNo == -1)
                {
                    //コピー先が追加行の場合は最大行番号取得
                    gyouNo = ComATool.Function.AnyToInt32(GetMaxRowNo());
                }

                //BaseDataSetのシーケンス取得
                for (int i = 0; i < obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows.Count; i++)
                {
                    if (ComATool.Function.AnyToInt32(obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows[i][COL_GYOUNO]) == gyouNo)
                    {
                        internalSeq = i;
                        break;
                    }
                }

                //待避配列コピー
                for (int n = COL_COUNT; n < COL_DATACOUNT; n++)
                {
                    //待避配列データから内部データにセット
                    tempActiveInputDataRow[n] = obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows[internalSeq][n];
                }

                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                //メモを使用する場合
                if (this.memoSiyouFlag == KBN_MEMOSIYOU_YES)
                {
                    //借方総勘定コードが空ではない場合
                    if (!string.IsNullOrEmpty(this.GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIKANJOUCD)))
                    {
                        //メモボタンを使用可
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), "obic7ButtonWithLogicKariMemo").Enabled = true;
                    }
                    else
                    {
                        //メモボタンを使用不可
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), "obic7ButtonWithLogicKariMemo").Enabled = false;
                    }

                    //貸方総勘定コードが空ではない場合
                    if (!string.IsNullOrEmpty(this.GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIKANJOUCD)))
                    {
                        //メモボタンを使用可
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), "obic7ButtonWithLogicKasiMemo").Enabled = true;
                    }
                    else
                    {
                        //メモボタンを使用不可
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), "obic7ButtonWithLogicKasiMemo").Enabled = false;
                    }
                }
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
            }

            return true;
        }
        #endregion

        #region 登録処理

        private bool Touroku()
        {
            //ストアドメソッド返り値
            int iRetCD;

            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            if (isFileTenpuUse)
            {
                #region WFエンジンに渡す項目が大幅に変わるため削除
                ////2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                ////電子証憑基盤から対象の電子証憑情報を取得する。(WFエンジン処理で使用するため)
                //this.wfExecuter.EvidenceGuid = null;
                //this.wfExecuter.Version = null;
                //DataTable evidenceGuidData = new DataTable();
                //SQLGetDataTable(MakeSQLEvidenceGuidData(), ref evidenceGuidData, false);
                //if (evidenceGuidData.Rows.Count != 0)
                //{
                //    if (!(string.IsNullOrEmpty(evidenceGuidData.Rows[0]["EvidenceGuid"].ToString())))
                //    {
                //        var evidenceGetParams = new List<Guid>();
                //        for (int i = 0; i < evidenceGuidData.Rows.Count; i++)
                //        {
                //            {
                //                evidenceGetParams.Add(ComATool.Function.AnyToGuid(evidenceGuidData.Rows[i]["EvidenceGuid"].ToString()).Value);
                //            };
                //        }
                //        DataTable Evidences = new DataTable();
                //        Evidences = WinEvidence.Evidence.GetEvidenceByGuid(evidenceGetParams);
                //        //電子証憑データを一時テーブルに更新し、[バージョン]を電子証憑ワークへ更新する。
                //        //「画面.[処理モード]=[修正] かつ コントロールM.[伝票採番区分]=[2](手入力) かつ 伝票番号が変更されている場合」は伝票番号の更新も行う。
                //        if (shokiGuids != null && (obic7ComboBoxMode.Text == MODE_UPDATE) && (denpyouSaibanKBN == 2)
                //             && (this.obic7TextStringCalledDenpyouNO.Text != obic7TextStringDenpyouNO.Text))
                //        {
                //            TaihiEvidencesDataUpdate(Evidences);
                //        }
                //        //それ以外
                //        else
                //        {
                //            TaihiEvidencesDataInsert(Evidences);
                //        }
                //        //該当システム伝票番号の「電子証憑ワーク.電子証憑Guid」「電子証憑ワーク.バージョン」をWFエンジンへ転送
                //        //電子証憑基盤から対象の電子証憑情報を取得し直す。(バージョン情報を取り直すため)
                //        DataTable newEvidenceGuidData = new DataTable();
                //        SQLGetDataTable(MakeSQLEvidenceGuidData(), ref newEvidenceGuidData, false);
                //        Guid[] wFEvidenceGuid = new Guid[newEvidenceGuidData.Rows.Count];
                //        int[] wFVersion = new int[newEvidenceGuidData.Rows.Count];
                //        for (int i = 0; i < newEvidenceGuidData.Rows.Count; i++)
                //        {
                //            {
                //                wFEvidenceGuid[i] = ComATool.Function.AnyToGuid(newEvidenceGuidData.Rows[i]["EvidenceGuid"].ToString()).Value;
                //                wFVersion[i] = Int32.Parse(newEvidenceGuidData.Rows[i]["EvidenceVersionNO"].ToString());
                //            };
                //        }
                //        if (isAvailableEvidence)
                //        {
                //            this.wfExecuter.EvidenceGuid = wFEvidenceGuid;
                //            this.wfExecuter.Version = wFVersion;
                //        }
                //    }
                //}
                //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了
                #endregion
                //電子証憑基盤から対象の電子証憑情報を取得する。(WFエンジン処理で使用するため)
                this.wfExecuter.EvidenceDatas = null;
                this.wfExecuter.OtherFileDatas = null;
                DataTable evidenceData = new DataTable();
                SQLGetDataTable(MakeSQLEvidenceWKForWF(), ref evidenceData, false);

                //最新のバージョンを取り直す
                var evidenceInfoList = new List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey>();

                for (int i = 0; i < evidenceData.Rows.Count; i++)
                {
                    var evidenceInfo = new Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey
                    {
                        EvidenceGuid = ComATool.Function.AnyToGuid(evidenceData.Rows[i]["EvidenceGuid"].ToString()).Value,
                        LinkNO = 0,
                        ShowOrder = ComATool.Function.AnyToInt32(evidenceData.Rows[i]["EvidenceShowOrder"].ToString()),
                        VersionNO = null,
                    };

                    evidenceInfoList.Add(evidenceInfo);
                }

                var lastEvidenceInfo = WinEvidence.Evidence.GetEvidenceList(evidenceInfoList, false, false);

                if (lastEvidenceInfo.Data.Rows.Count != 0)
                {
                    //電子証憑データを一時テーブルに更新し、[バージョン]を電子証憑ワークへ更新する。
                    //2022/08/18  修正   Y.Matuzawa     (206079)伝票採番方法が手入力で伝票修正時に伝票番号を修正した際に、ファイルデータが正しく更新されません 開始
                    ////「画面.[処理モード]=[修正] かつ コントロールM.[伝票採番区分]=[2](手入力) かつ 伝票番号が変更されている場合」は伝票番号の更新も行う。
                    //if ((obic7ComboBoxMode.Text == MODE_UPDATE) && (denpyouSaibanKBN == 2)
                    //     && (this.obic7TextStringCalledDenpyouNO.Text != obic7TextStringDenpyouNO.Text))
                    //{
                    //    TaihiEvidencesDataUpdate(lastEvidenceInfo.Data);
                    //}
                    //else
                    //{
                    //    TaihiEvidencesDataInsert(lastEvidenceInfo.Data);
                    //}
                    TaihiEvidencesDataInsert(lastEvidenceInfo.Data);
                    //2022/08/18  修正   Y.Matuzawa     (206079)伝票採番方法が手入力で伝票修正時に伝票番号を修正した際に、ファイルデータが正しく更新されません 終了
                }

                DataTable evidenceData_VerUp = new DataTable();
                SQLGetDataTable(MakeSQLEvidenceWKForWF(), ref evidenceData_VerUp, false);

                if (evidenceData_VerUp.Rows.Count != 0)
                {
                    var wfEvidenceList = new List<WFExecuter.EvidenceData>();
                    var wfOtherFileList = new List<WFExecuter.OtherFileData>();
                    for (int i = 0; i < evidenceData_VerUp.Rows.Count; i++)
                    {
                        if (byte.Parse(evidenceData_VerUp.Rows[i]["EvidenceType"].ToString()) == (byte)EvidenceType.Sonota)
                        {
                            var data = new WFExecuter.OtherFileData()
                            {
                                FileGuid = (Guid)evidenceData_VerUp.Rows[i]["EvidenceGuid"],
                                FileName = evidenceData_VerUp.Rows[i]["FileName"].ToString(),
                                FileUpdateDateTime = DateTime.Now,
                                Memo = evidenceData_VerUp.Rows[i]["Memo"].ToString()
                            };
                            wfOtherFileList.Add(data);
                        }
                        else
                        {
                            var data = new WFExecuter.EvidenceData()
                            {
                                EvidenceGuid = (Guid)evidenceData_VerUp.Rows[i]["EvidenceGuid"],
                                EvidenceType = byte.Parse(evidenceData_VerUp.Rows[i]["EvidenceType"].ToString()),
                                Version = int.Parse(evidenceData_VerUp.Rows[i]["VersionNO"].ToString())
                            };
                            wfEvidenceList.Add(data);
                        }
                    }

                    if (wfOtherFileList.Count > 0)
                    {
                        WFExecuter.OtherFileData[] newOtherFileParam = new WFExecuter.OtherFileData[wfOtherFileList.Count];
                        for (int i = 0; i < wfOtherFileList.Count; i++)
                        {
                            newOtherFileParam[i] = wfOtherFileList[i];
                        }
                        this.wfExecuter.OtherFileDatas = newOtherFileParam;
                    }
                    else
                    {
                        this.wfExecuter.OtherFileDatas = new WFExecuter.OtherFileData[0];
                    }
                    if (wfEvidenceList.Count > 0)
                    {
                        WFExecuter.EvidenceData[] newEvidenceParam = new WFExecuter.EvidenceData[wfEvidenceList.Count];
                        for (int i = 0; i < wfEvidenceList.Count; i++)
                        {
                            newEvidenceParam[i] = wfEvidenceList[i];
                        }
                        this.wfExecuter.EvidenceDatas = newEvidenceParam;
                    }
                    else
                    {
                        this.wfExecuter.EvidenceDatas = new WFExecuter.EvidenceData[0];
                    }
                }

            }
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

            #region ワークフロー用　変数
            //ワークフロー用////////////////////////////////////

            // out引数
            string systemCategory = null;//システム分類CD
            string customizeSEQ = null;//カスタマイズSEQ
            string messageCD1 = null;
            string messageCD2 = null;
            Guid sinAnkenGuid = new Guid("00000000-0000-0000-0000-000000000000");  //新案件Guid

            // in引数
            DateTime datetimeSinsei;//申請日時
            ComWToolEngineRegist.Joukenti[] joukenti = null;//条件値

            //申請日時の設定
            datetimeSinsei = GetSystemDate();

            //条件値の設定
            joukenti = new ComWToolEngineRegist.Joukenti[1];

            joukenti[0].NameJoukenItem = "金額";
            joukenti[0].typeData = ComWToolEngineCommon.DbColumnCdValue.TypeData.TypeNumber;
            joukenti[0].strVal = null;
            joukenti[0].numVal = (long)(obic7TextNumberTotalKariSougaku.Value);
            joukenti[0].datetimeVal = null;

            WFExecuter.ReturnValue checkReturn;

            ////////////////////////////////////////////////////////////////////////////
            #endregion

            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //新規モード
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //if (shouninKBN == 0 && ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20)
                if (shouninKBN == 0 && this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou)
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                {
                    #region ワークフロー用　チェック処理
                    //ワークフロー処理///////////////////////////////////////

                    //承認申請のチェック
                    checkReturn = this.wfExecuter.Check(out systemCategory, out customizeSEQ
                                            , out messageCD1, out messageCD2
                                            , joukenti
                                            , datetimeSinsei
                                            , null, out sinAnkenGuid
                                            , this.businessDB);


                    if (checkReturn == WFExecuter.ReturnValue.Unusual)
                    {
                        //正常でない場合
                        // メッセージボックスを表示
                        WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                    else if (checkReturn == WFExecuter.ReturnValue.Cancel)
                    {
                        return false;
                    }
                    ///////////////////////////////////////////////////////////
                    #endregion
                }
            }
            else
            {
                //修正モード
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //if (shouninKBN == 0 && ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20)
                if (shouninKBN == 0 && this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou)
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                {
                    #region ワークフロー用　チェック処理

                    //ワークフロー用///////////////////////////////////////////
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (ComATool.Function.AnyToInt32(prevDenpyouKBN) < 20)
                    if (prevHonKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //本伝→本伝の修正

                        //承認申請のチェック
                        checkReturn = this.wfExecuter.Check(out systemCategory, out customizeSEQ
                                               , out messageCD1, out messageCD2
                                               , joukenti
                                               , datetimeSinsei
                                               , this.ankenGuid, out sinAnkenGuid
                                               , this.businessDB);
                    }
                    else
                    {
                        //仮伝→本伝
                        //承認申請のチェック
                        checkReturn = this.wfExecuter.Check(out systemCategory, out customizeSEQ
                                                , out messageCD1, out messageCD2
                                                , joukenti
                                                , datetimeSinsei
                                                , null, out sinAnkenGuid
                                                , this.businessDB);
                    }

                    if (checkReturn == WFExecuter.ReturnValue.Unusual)
                    {
                        //正常でない場合
                        // メッセージボックスを表示
                        WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                    else if (checkReturn == WFExecuter.ReturnValue.Cancel)
                    {
                        return false;
                    }
                    ///////////////////////////////////////////////////////////
                    #endregion
                }
            }

            //本支店仕訳入力画面ヘッダワークテーブル削除
            SQLExecuteNonQueryMain(MakeSQLDeleteHeaderWorkTable());

            //本支店仕訳入力画面ヘッダワークテーブル登録
            SQLExecuteNonQueryMain(MakeSQLInsertHeaderWorkTable((Guid)sinAnkenGuid));

            //トランザクション開始
            businessDB.BeginTransaction();
            // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
            {
                fileDB.BeginTransaction();
            }
            // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

            try
            {
                //仕訳登録処理
                iRetCD = EntrySiwake();
                if (iRetCD != 0)
                {
                    return false;
                }
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                //bool motoKaridenFLG = false;
                if (isFileTenpuUse)
                {
                    if (obic7ComboBoxMode.Text == MODE_INSERT)
                    {
                        UpdateEvidenceWK();
                    }
                    //2022/08/18  追加   Y.Matuzawa     (206079)伝票採番方法が手入力で伝票修正時に伝票番号を修正した際に、ファイルデータが正しく更新されません 開始
                    else if ((obic7ComboBoxMode.Text == MODE_UPDATE) && (denpyouSaibanKBN == 2)
                                 && (this.obic7TextStringCalledDenpyouNO.Text != obic7TextStringDenpyouNO.Text))
                    {
                        UpdateEvidenceWK_UpdateDenpyouNO();
                    }
                    //2022/08/18  追加   Y.Matuzawa     (206079)伝票採番方法が手入力で伝票修正時に伝票番号を修正した際に、ファイルデータが正しく更新されません 終了

                    //証憑の実更新する前のデータを退避
                    var evidenceDataBeforeUpdate = Win.B0000.Tool.Logic.Evidence.Evidence.GetDenpyouWK(fileKidouGuid, false, false, false);

                    if (isAvailableEvidence)
                    {
                        //電子証憑基盤.電子証憑確定処理を用いて電子証憑基盤のデータを更新する
                        var result = WinEvidence.Evidence.EnterEvidence(fileKidouGuid, this.obic7TextStringPrevDenpyouNO.Text, "M", "M_ET", "M_Evi");
                        if (!result.IsValid)
                        {
                            var message = result.EvidenceKeyAndResultCollection.ToList();
                            var message1 = message[0].MessageCD1;
                            var message2 = message[0].MessageCD2;
                            //メッセージボックス表示
                            WinAToolLogic.UI.Obic7MessageBox.Show(result.DBCategory, CUSTOMIZESEQ, message1, message2, null, null, GetType()
                                                                , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK
                                                                , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            // トランザクションを閉じてReturnする。
                            businessDB.RollBackTransaction();
                            if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                            {
                                fileDB.RollBackTransaction();
                            }
                            return false;
                        }
                    }
                    if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                    {
                        //関連書類データを更新する
                        //オペレーション項目をキーにして電子証憑ワークの情報を取得する
                        DataTable otherFileData = null;
                        SQLGetDataTable(MakeSQLSelectOtherFileData(), ref otherFileData, false);

                        //FileDBで使用するために、電子証憑ワークの内容を一時テーブルに格納する
                        TaihiEvidenceData(otherFileData);

                        try
                        {
                            if (obic7ComboBoxMode.Text == MODE_UPDATE)
                            {
                                //接続先FileDBで削除を行う
                                fileDB.ExecuteNonQuery(MakeSQLDeleteFileByDenpyouNO());
                                fileDB.ExecuteNonQuery(MakeSQLDeleteFileSubByDenpyouNO());
                                fileDB.ExecuteNonQuery(MakeSQLDeleteAlreadyRegisteredFile(evidenceDataBeforeUpdate));
                            }

                            //接続先FileDBへ追加更新を行う
                            fileDB.ExecuteNonQuery(MakeSQLInsertFile());
                            fileDB.ExecuteNonQuery(MakeSQLInsertFileSub());
                        }
                        catch (Exception ex)
                        {
                            businessDB.RollBackTransaction();
                            fileDB.RollBackTransaction();
                            throw ex;
                        }
                        WinEvidence.Evidence.DeleteDenpyouWK(fileKidouGuid);
                    }
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
                    //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                    //電子証憑更新処理
                    //手入力で伝票番号が変更されているとき、電子証憑紐付データの削除を行う。
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    //電子証憑データとの関連を削除する。
                    //if (shokiGuids != null && (obic7ComboBoxMode.Text == MODE_UPDATE) && (denpyouSaibanKBN == 2)
                    //    && (this.obic7TextStringCalledDenpyouNO.Text != obic7TextStringDenpyouNO.Text))
                    //{
                    //    var taishouGuids = new List<Guid>();
                    //    foreach (var item in shokiGuids)
                    //    {
                    //        taishouGuids.Add(item);
                    //    }
                    //    if (taishouGuids.Count != 0)
                    //    {
                    //        WinEvidence.Evidence.DeleteEvidenceData(taishouGuids);
                    //    }
                    //}
                    if ((obic7ComboBoxMode.Text == MODE_UPDATE) && (denpyouSaibanKBN == 2)
                        && (this.obic7TextStringCalledDenpyouNO.Text != obic7TextStringDenpyouNO.Text) )
                    {
                        //2022/08/18  修正   Y.Matuzawa     (206079)伝票採番方法が手入力で伝票修正時に伝票番号を修正した際に、ファイルデータが正しく更新されません 開始
                        ////複数電子証憑データから、削除可能フラグ = true、かつデータ状態 = 未確定のもののみ抽出して更新する
                        ////データ状態：1:未確定、2:新規登録、3:修正、4:論理削除、5:何もしない、6:復活_未確定、7:復活、8:紐づけ_未確定、9:紐づけ
                        //var evidence = WinEvidence.Evidence.GetDenpyouWK(fileKidouGuid, false, false, false);
                        ////データ状態を「修正」、関連データを「修正後伝票番号」に修正する
                        //for (int i = 0; i < evidence.Rows.Count; i++)
                        //{
                        //    evidence.Rows[i]["State"] = 3;
                        //    evidence.Rows[i]["RelationData"] = this.obic7TextStringPrevDenpyouNO.Text;
                        //}
                        //WinEvidence.Evidence.RegisterEvidence(evidence, "M_ET", "M_Evi");

                        var evidenceInfoList = new List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey>();

                        //退避しておいた電子証憑データから、制度ファイル かつ 削除可能フラグ = trueのレコードのみ抽出する
                        //データ状態：1:未確定、2:新規登録、3:修正、4:論理削除、5:何もしない、6:復活_未確定、7:復活、8:紐づけ_未確定、9:紐づけ
                        for (int i = 0; i < evidenceDataBeforeUpdate.Rows.Count; i++)
                        {
                            if (evidenceDataBeforeUpdate.Rows[i]["IsDeletable"].ToString() == "True"
                                && (evidenceDataBeforeUpdate.Rows[i]["EvidenceType"].ToString() == "1" || evidenceDataBeforeUpdate.Rows[i]["EvidenceType"].ToString() == "2"))
                            {
                                var evidenceInfo = new Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey
                                {
                                    EvidenceGuid = ComATool.Function.AnyToGuid(evidenceDataBeforeUpdate.Rows[i]["EvidenceGuid"].ToString()).Value,
                                    LinkNO = 0,
                                    ShowOrder = 1,
                                    VersionNO = null,
                                };

                                evidenceInfoList.Add(evidenceInfo);
                            }
                        }

                        //最新の証憑テーブル情報を取得する
                        var evidenceDataAfterUpdate = WinEvidence.Evidence.GetEvidenceList(evidenceInfoList, false, false);

                        //複数電子証憑データから、削除されていないレコードのみ抽出して更新する
                        var updatableTaishou = evidenceDataAfterUpdate.Data.AsEnumerable().Where(x => x["IsDeleted"].ToString() != "True");

                        if (updatableTaishou.Count() > 0)
                        {
                            var updateTaishou = updatableTaishou.CopyToDataTable();

                            //データ状態を「修正」、関連データを「修正後伝票番号」に修正する
                            //データ状態：1:未確定、2:新規登録、3:修正、4:論理削除、5:何もしない、6:復活_未確定、7:復活、8:紐づけ_未確定、9:紐づけ
                            for (int i = 0; i < updateTaishou.Rows.Count; i++)
                            {
                                updateTaishou.Rows[i]["State"] = 3;
                                updateTaishou.Rows[i]["RelationData"] = this.obic7TextStringPrevDenpyouNO.Text;
                            }

                            //<会計共通>電子証憑基盤接続クラス.[電子証憑登録処理]を呼び出す。
                            WinEvidence.Evidence.RegisterEvidence(updateTaishou, "M_ET", "M_Evi");
                        }
                        //2022/08/18  修正   Y.Matuzawa     (206079)伝票採番方法が手入力で伝票修正時に伝票番号を修正した際に、ファイルデータが正しく更新されません 終了
                    }
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
                    //電子証憑紐付データに更新する。
                    //2020/10/26    K.Matsumoto     修正      【本支店仕訳入力】【横展開179201】デッドロック発生時に不要な申請が起票される場合があります。   ↓
                    //UpdateEvidenceRelation();
                    if (UpdateEvidenceRelation() != 0)
                    {
                        return false;
                    }
                    //2020/10/26    K.Matsumoto     修正      【本支店仕訳入力】【横展開179201】デッドロック発生時に不要な申請が起票される場合があります。   ↑
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    ////<会計共通>電子証憑基盤接続クラス.[電子証憑関連データ更新処理]を使用して、
                    ////電子証憑データに関連データ(伝票番号)を更新する。
                    //DataTable relationGuidData = new DataTable();
                    ////2020/10/26    K.Matsumoto     修正      【本支店仕訳入力】【横展開179201】デッドロック発生時に不要な申請が起票される場合があります。   ↓
                    ////SQLGetDataTable(MakeSQLEvidenceRelationData(), ref relationGuidData, false);
                    //if (!SQLGetDataTable(MakeSQLEvidenceRelationData(), ref relationGuidData, true))
                    //{
                    //    return false;
                    //}
                    ////2020/10/26    K.Matsumoto     修正      【本支店仕訳入力】【横展開179201】デッドロック発生時に不要な申請が起票される場合があります。   ↑
                    //if (relationGuidData.Rows.Count != 0)
                    //{
                    //    var evidenceGetParams = new List<Guid>();
                    //    for (int i = 0; i < relationGuidData.Rows.Count; i++)
                    //    {
                    //        {
                    //            evidenceGetParams.Add(ComATool.Function.AnyToGuid(relationGuidData.Rows[i]["EvidenceGuid"].ToString()).Value);
                    //        };
                    //    }
                    //    //<会計共通>電子証憑基盤接続クラス.[電子証憑関連データ更新処理]
                    //    WinEvidence.Evidence.UpdateEvidenceData(evidenceGetParams, obic7TextStringPrevDenpyouNO.Text);
                    //}
                }
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
                //伝票番号紐付処理
                //「画面.[処理モード]=[新規]の場合(①)」もしくは「画面.[処理モード]=[修正] かつ
                // コントロールM.[伝票採番区分]=[2](手入力) かつ 伝票番号が変更されている場合(②)」
                if ((obic7ComboBoxMode.Text == MODE_INSERT)
                    || ((obic7ComboBoxMode.Text == MODE_UPDATE) && (denpyouSaibanKBN == 2)
                         && (this.obic7TextStringCalledDenpyouNO.Text != obic7TextStringDenpyouNO.Text)))
                {
                    //共通処理「伝票番号紐付データ更新処理」
                    //2020/10/26    K.Matsumoto     修正      【本支店仕訳入力】【横展開179201】デッドロック発生時に不要な申請が起票される場合があります。   ↓
                    if (UpdateRelationData() != 0)
                    {
                        return false;
                    }
                    //2020/10/26    K.Matsumoto     修正      【本支店仕訳入力】【横展開179201】デッドロック発生時に不要な申請が起票される場合があります。   ↑
                }
                //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了

                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //if (shouninKBN == 0 && ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20)
                if (shouninKBN == 0 && this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou)
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                {
                    #region ワークフロー用　本処理

                    //ワークフロー用///////////////////////////////////////////
                    //RDFファイルクラスを作成
                    Obic7fx.Win.M0000.Report.MA_SiwakeDenpyouRDF.MA_SiwakeDenpyouRDF rptSiwakeRDF = new Obic7fx.Win.M0000.Report.MA_SiwakeDenpyouRDF.MA_SiwakeDenpyouRDF(businessDB, (Decimal)systemDenpyouNO, this.obic7TextStringPrevDenpyouNO.Text, 3);

                    // 2008/08/20 T.Ota 変更開始 WF登録処理の引数変更対応
                    //引数用配列を作成し、開発用予備項目をセット
                    string[] kaihatuYobi = new string[3];
                    kaihatuYobi[0] = RenketuString(this.obic7TextStringZigyoushoCD.Text, "：", this.obic7LabelStringZigyoushoName.Text);
                    kaihatuYobi[1] = RenketuString(this.obic7TextStringDenpyouKBN.Text, "：", this.obic7LabelStringDenpyouKBNName.Text);
                    kaihatuYobi[2] = this.obic7TextDatetimeHasseiDate.Text;
                    // 2008/08/20 T.Ota 変更終了

                    //承認申請実行
                    if (wfExecuter.Execute(out systemCategory, out customizeSEQ
                                     , out messageCD1, out messageCD2
                        // 2008/08/20 T.Ota 変更開始 WF登録処理の引数変更対応
                        ////2008/07/04 変更 K.Satou 開始 WF登録処理において、表示項目１の伝票番号と表示項目２の発生日を入れ替える
                        //             //, ComATool.Function.AnyToString(this.obic7TextStringPrevDenpyouNO.Text)
                        //             //, RenketuString(RenketuString(obic7TextDatetimeHasseiDate.Text, "、", obic7TextNumberTotalKariSougaku.Text),"、",obic7TextStringDenpyouTekiyou.Text)
                        //             , ComATool.Function.AnyToString(this.obic7TextDatetimeHasseiDate.Text)
                        //             , RenketuString(RenketuString(obic7TextStringPrevDenpyouNO.Text, "、", obic7TextNumberTotalKariSougaku.Text), "、", obic7TextStringDenpyouTekiyou.Text)  
                        ////2008/07/04 変更 K.Satou 終了 WF登録処理において、表示項目１の伝票番号と表示項目２の発生日を入れ替える
                                     , ComATool.Function.AnyToString(this.obic7TextStringPrevDenpyouNO.Text)
                                     , RenketuString(obic7TextNumberTotalKariSougaku.Text, "、", obic7TextStringDenpyouTekiyou.Text)
                        // 2008/08/20 T.Ota 変更終了
                                     , rptSiwakeRDF
                                     , null, ComWToolEngineRegist.TypePriority.Normal, null
                        // 2008/08/20 T.Ota 変更開始 WF登録処理の引数変更対応
                        //, null, null, null) != WFExecuter.ReturnValue.Normal)
                                     , null, null, null
                                     , null
                                     , kaihatuYobi) != WFExecuter.ReturnValue.Normal)
                    // 2008/08/20 T.Ota 変更終了
                    {
                        //申請失敗時
                        //更新を元に戻す
                        this.businessDB.RollBackTransaction();

                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                        if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                        {
                            fileDB.RollBackTransaction();
                        }
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

                        // メッセージボックスを表示
                        WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                        return false;
                    }
                    ///////////////////////////////////////////////////////////
                    #endregion
                }

                //コミット
                businessDB.CommitTransaction();
                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                {
                    fileDB.CommitTransaction();
                }
                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                if (obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    //修正時、排他削除処理
                    iRetCD = HaitaSetData(KBN_HAITA_SAKUJO);
                    if (iRetCD != 0)
                    {
                        return false;
                    }
                }
            }
            catch (Exception ex)
            {
                //ロールバック
                businessDB.RollBackTransaction();
                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                {
                    fileDB.RollBackTransaction();
                }
                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                throw ex;
            }

            return true;
        }
        #endregion

        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
        #region 追加添付処理
        private bool Touroku_TuikaTenpu()
        {
            //電子証憑基盤から対象の電子証憑情報を取得する。(WFエンジン処理で使用するため)
            this.wfExecuter.EvidenceDatas = null;
            this.wfExecuter.OtherFileDatas = null;

            //電子証憑データの取得
            DataTable evidenceGuidData = new DataTable();
            SQLGetDataTable(MakeSQLEvidenceWKForWF(), ref evidenceGuidData, false);

            if (evidenceGuidData.Rows.Count != 0)
            {
                if (!(string.IsNullOrEmpty(evidenceGuidData.Rows[0]["EvidenceGuid"].ToString())))
                {
                    var evidenceInfoList = new List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey>();

                    for (int i = 0; i < evidenceGuidData.Rows.Count; i++)
                    {
                        var evidenceInfo = new Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey
                        {
                            EvidenceGuid = ComATool.Function.AnyToGuid(evidenceGuidData.Rows[i]["EvidenceGuid"].ToString()).Value,
                            LinkNO = 0,
                            ShowOrder = ComATool.Function.AnyToInt32(evidenceGuidData.Rows[i]["EvidenceShowOrder"].ToString()),
                            VersionNO = null,
                        };

                        evidenceInfoList.Add(evidenceInfo);
                    }

                    //3-0-1.<会計共通>電子証憑基盤接続クラス.[電子証憑一覧取得処理]
                    var lastEvidenceInfo = WinEvidence.Evidence.GetEvidenceList(evidenceInfoList, false, false);

                    if (lastEvidenceInfo.Data.Rows.Count != 0)
                    {
                        //電子証憑WKのバージョンを更新する
                        TaihiEvidencesDataInsert(lastEvidenceInfo.Data);
                    }
                }
            }

            //電子証憑ワークから取得した情報をワークフロー処理クラスに渡す
            DataTable evidenceData_VerUp = new DataTable();
            SQLGetDataTable(MakeSQLEvidenceWKForWF(), ref evidenceData_VerUp, false);

            if (evidenceData_VerUp.Rows.Count != 0)
            {
                var wfEvidenceList = new List<WFExecuter.EvidenceData>();
                var wfOtherFileList = new List<WFExecuter.OtherFileData>();
                for (int i = 0; i < evidenceData_VerUp.Rows.Count; i++)
                {
                    if (byte.Parse(evidenceData_VerUp.Rows[i]["EvidenceType"].ToString()) == (byte)EvidenceType.Sonota)
                    {
                        var data = new WFExecuter.OtherFileData()
                        {
                            FileGuid = (Guid)evidenceData_VerUp.Rows[i]["EvidenceGuid"],
                            FileName = evidenceData_VerUp.Rows[i]["FileName"].ToString(),
                            FileUpdateDateTime = DateTime.Now,
                            Memo = evidenceData_VerUp.Rows[i]["Memo"].ToString()
                        };
                        //その他添付ファイル情報
                        wfOtherFileList.Add(data);
                    }
                    else
                    {
                        var data = new WFExecuter.EvidenceData()
                        {
                            EvidenceGuid = (Guid)evidenceData_VerUp.Rows[i]["EvidenceGuid"],
                            EvidenceType = byte.Parse(evidenceData_VerUp.Rows[i]["EvidenceType"].ToString()),
                            Version = int.Parse(evidenceData_VerUp.Rows[i]["VersionNO"].ToString())
                        };
                        //制度ファイル情報
                        wfEvidenceList.Add(data);
                    }
                }

                if (wfOtherFileList.Count > 0)
                {
                    WFExecuter.OtherFileData[] newOtherFileParam = new WFExecuter.OtherFileData[wfOtherFileList.Count];
                    for (int i = 0; i < wfOtherFileList.Count; i++)
                    {
                        newOtherFileParam[i] = wfOtherFileList[i];
                    }
                    this.wfExecuter.OtherFileDatas = newOtherFileParam;
                }
                else
                {
                    this.wfExecuter.OtherFileDatas = new WFExecuter.OtherFileData[0];
                }

                if (wfEvidenceList.Count > 0)
                {
                    WFExecuter.EvidenceData[] newEvidenceParam = new WFExecuter.EvidenceData[wfEvidenceList.Count];
                    for (int i = 0; i < wfEvidenceList.Count; i++)
                    {
                        newEvidenceParam[i] = wfEvidenceList[i];
                    }
                    this.wfExecuter.EvidenceDatas = newEvidenceParam;
                }
                else
                {
                    this.wfExecuter.EvidenceDatas = new WFExecuter.EvidenceData[0];
                }
            }


            #region ワークフロー用　変数
            ////ワークフロー用////////////////////////////////////

            // out引数
            string systemCategory = null;//システム分類CD
            string customizeSEQ = null;//カスタマイズSEQ
            string messageCD1 = null;
            string messageCD2 = null;
            Guid sinAnkenGuid = new Guid("00000000-0000-0000-0000-000000000000");  //新案件Guid

            // in引数
            DateTime datetimeSinsei;//申請日時
            ComWToolEngineRegist.Joukenti[] joukenti = null;//条件値

            //申請日時の設定
            datetimeSinsei = GetSystemDate();

            //条件値の設定
            joukenti = new ComWToolEngineRegist.Joukenti[1];

            joukenti[0].NameJoukenItem = "金額";
            joukenti[0].typeData = ComWToolEngineCommon.DbColumnCdValue.TypeData.TypeNumber;
            joukenti[0].strVal = null;
            joukenti[0].numVal = (long)(obic7TextNumberTotalKariSougaku.Value);
            joukenti[0].datetimeVal = null;

            WFExecuter.ReturnValue checkReturn;

            //現時点の添付枚数を退避
            var currentEvidenceCount = 0;
            var currentEvidenceData = businessDB.GetDataTable(MakeSQLSelectEvidence(systemDenpyouNO));
            if (ComATool.Function.IsValidDataTable(currentEvidenceData))
            {
                currentEvidenceCount = currentEvidenceData.Rows.Count;
            }

            //////////////////////////////////////////////////////////////////////////////
            #endregion

            if ((tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri))
            {
                //申請中案件の場合
                if (yobidasiTuikaTenpuAnkenGuid != null)
                {
                    if (currentEvidenceCount != 0)
                    {
                        //既に申請モード
                        #region ワークフロー用　チェック処理
                        //承認申請のチェック
                        checkReturn = this.wfExecuter.Check(out systemCategory, out customizeSEQ
                                                , out messageCD1, out messageCD2
                                                , joukenti
                                                , datetimeSinsei
                                                , yobidasiTuikaTenpuAnkenGuid, out sinAnkenGuid
                                                , this.businessDB);

                        if (checkReturn == WFExecuter.ReturnValue.Unusual)
                        {
                            //正常でない場合
                            // メッセージボックスを表示
                            WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                                WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return false;
                        }
                        else if (checkReturn == WFExecuter.ReturnValue.Cancel)
                        {
                            return false;
                        }
                        #endregion
                    }
                }
                //新規申請案件の場合
                else
                {
                    //新規申請モード
                    #region ワークフロー用　チェック処理
                    //承認申請のチェック
                    checkReturn = this.wfExecuter.Check(out systemCategory, out customizeSEQ
                                           , out messageCD1, out messageCD2
                                           , joukenti
                                           , datetimeSinsei
                                           , null, out sinAnkenGuid
                                           , this.businessDB);

                    if (checkReturn == WFExecuter.ReturnValue.Unusual)
                    {
                        //正常でない場合
                        // メッセージボックスを表示
                        WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                            WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return false;
                    }
                    else if (checkReturn == WFExecuter.ReturnValue.Cancel)
                    {
                        return false;
                    }
                    #endregion
                }

                //採番された案件Guidを退避
                tuikaTenpuAnkenGuid = (Guid)sinAnkenGuid;
            }

            //トランザクション開始
            businessDB.BeginTransaction();

            if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
            {
                fileDB.BeginTransaction();
            }

            try
            {
                //追加電子証憑枚数用の変数を宣言
                var tuikaTenpuCount = 0;

                var evidence = new DataTable();

                //電子証憑確定を行うと伝票WKが削除されるため、ABB_伝票WKの情報を退避しておく。
                evidence = WinEvidence.Evidence.GetDenpyouWK(fileKidouGuid, false, false, false);

                //電子証憑基盤.電子証憑確定処理を用いて電子証憑基盤のデータを更新する
                if (isAvailableEvidence)
                {
                    //電子証憑基盤のデータ(ABBのファイル3テーブル)を更新する。
                    var result = WinEvidence.Evidence.EnterEvidence(fileKidouGuid, obic7TextStringDenpyouNO.Text, "M", "M_ET", "M_Evi");
                    if (!result.IsValid)
                    {
                        var message = result.EvidenceKeyAndResultCollection.ToList();
                        var message1 = message[0].MessageCD1;
                        var message2 = message[0].MessageCD2;
                        //メッセージボックス表示
                        WinAToolLogic.UI.Obic7MessageBox.Show(result.DBCategory, CUSTOMIZESEQ, message1, message2, null, null, GetType()
                                                            , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK
                                                            , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                        // トランザクションを閉じてReturnする。
                        businessDB.RollBackTransaction();
                        if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                        {
                            fileDB.RollBackTransaction();
                        }
                        return false;
                    }
                }

                if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                {
                    //その他添付データを更新する
                    //オペレーション項目をキーにして電子証憑ワークの情報を取得する
                    DataTable otherFileData = null;
                    SQLGetDataTable(MakeSQLSelectOtherFileData(), ref otherFileData, false);

                    //FileDBで使用するために、電子証憑ワークの内容を一時テーブルに格納する
                    TaihiEvidenceData(otherFileData);

                    try
                    {
                        //接続先FileDBで削除を行う
                        fileDB.ExecuteNonQuery(MakeSQLDeleteFileByDenpyouNO());
                        fileDB.ExecuteNonQuery(MakeSQLDeleteFileSubByDenpyouNO());
                        fileDB.ExecuteNonQuery(MakeSQLDeleteAlreadyRegisteredFile(evidence));

                        //接続先FileDBへ追加更新を行う
                        fileDB.ExecuteNonQuery(MakeSQLInsertFile());
                        fileDB.ExecuteNonQuery(MakeSQLInsertFileSub());
                    }
                    catch (Exception ex)
                    {
                        fileDB.RollBackTransaction();
                        businessDB.RollBackTransaction();
                        throw ex;
                    }

                    //伝票WK削除
                    WinEvidence.Evidence.DeleteDenpyouWK(fileKidouGuid);
                }

                //追加電子証憑紐付データに更新する。
                if (UpdateEvidenceRelationAddition(evidence, out tuikaTenpuCount) != 0)
                {
                    return false;
                }

                if (tuikaTenpuSiyouKBN != (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri)
                {
                    //電子証憑紐付データに更新する。
                    if (UpdateEvidenceRelation_TuikaTenpu() != 0)
                    {
                        return false;
                    }
                }


                if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri)
                {
                    #region ワークフロー用　本処理
                    //RDFファイルクラスを作成
                    Obic7fx.Win.M0000.Report.MA_SiwakeDenpyouRDF.MA_SiwakeDenpyouRDF rptSiwakeRDF = new Obic7fx.Win.M0000.Report.MA_SiwakeDenpyouRDF.MA_SiwakeDenpyouRDF(businessDB, (Decimal)systemDenpyouNO, this.obic7TextStringDenpyouNO.Text, 1, "BM1010");

                    //引数用配列を作成し、開発用予備項目をセット
                    string[] kaihatuYobi = new string[3];
                    kaihatuYobi[0] = RenketuString(this.obic7TextStringZigyoushoCD.Text, "：", this.obic7LabelStringZigyoushoName.Text);
                    kaihatuYobi[1] = RenketuString(this.obic7TextStringDenpyouKBN.Text, "：", this.obic7LabelStringDenpyouKBNName.Text);
                    kaihatuYobi[2] = this.obic7TextDatetimeHasseiDate.Text;


                    //申請中案件があり、現在添付登録しようとしている枚数が0件なら破棄のみ実行
                    if (yobidasiTuikaTenpuAnkenGuid != null && currentEvidenceCount == 0)
                    {
                        //承認申請の破棄
                        if (this.wfExecuter.Destroy(out systemCategory, out customizeSEQ
                                                   , out messageCD1, out messageCD2
                                                   , (Guid)yobidasiTuikaTenpuAnkenGuid, null, businessDB) != WFExecuter.ReturnValue.Normal)
                        {
                            //ロールバック
                            businessDB.RollBackTransaction();

                            if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                            {
                                fileDB.RollBackTransaction();
                            }

                            // メッセージボックスを表示
                            WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                                WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return false;
                        }
                    }
                    else
                    {
                        //承認申請実行
                        if (wfExecuter.Execute(out systemCategory, out customizeSEQ
                                         , out messageCD1, out messageCD2
                                         , ComATool.Function.AnyToString(this.obic7TextStringDenpyouNO.Text)
                                         , "追加：" + tuikaTenpuCount.ToString() + "、" + obic7TextNumberTotalKariSougaku.Text + "、" + obic7TextStringDenpyouTekiyou.Text
                                         , rptSiwakeRDF
                                         , null, ComWToolEngineRegist.TypePriority.Normal, null
                                         , null, null, null
                                         , null
                                         , kaihatuYobi) != WFExecuter.ReturnValue.Normal)
                        {
                            //申請失敗時
                            //更新を元に戻す
                            this.businessDB.RollBackTransaction();

                            if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                            {
                                fileDB.RollBackTransaction();
                            }

                            // メッセージボックスを表示
                            WinATool.Logic.UI.Obic7MessageBox.Show(systemCategory, customizeSEQ, messageCD1, messageCD2, null, null, this.GetType(),
                                                WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            return false;
                        }
                    }
                    #endregion
                }

                //コミット
                businessDB.CommitTransaction();
                if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                {
                    fileDB.CommitTransaction();
                }

                int iRetCD2 = HaitaSetData(KBN_HAITA_SAKUJO);
                //排他削除処理
                if (iRetCD2 != 0)
                {
                    return false;
                }
            }
            catch (Exception ex)
            {
                //ロールバック
                businessDB.RollBackTransaction();

                if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                {
                    fileDB.RollBackTransaction();
                }

                throw ex;
            }

            return true;
        }
