        /// <param name="commonpatternkbn">仕訳ﾊﾟﾀｰﾝの共通パターン区分</param>
        /// <param name="usergroupcd">仕訳ﾊﾟﾀｰﾝのユーザグループコード</param>
        /// <returns></returns>
        private bool PatternTouroku(string siwakepatternno, string siwakepatternname, string siwakepatterngroup, int commonpatternkbn, string usergroupcd)
        // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)
        {
            //トランザクション開始
            businessDB.BeginTransaction();

            try
            {
                //仕訳ﾊﾟﾀｰﾝ登録処理
                int iRetCD;
                // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
