        #region 本支店仕訳入力画面ヘッダワークテーブルのデータ登録の文字列作成
        /// <summary>
        /// 本支店仕訳入力画面ヘッダワークのデータ登録の文字列作成
        /// </summary>
        /// <param name="AnkenGuid"></param>
        /// <returns></returns>
        private string MakeSQLInsertHeaderWorkTable(Guid AnkenGuid)
        {
            StringBuilder sb = new StringBuilder();

            sb.Append(" INSERT INTO  ");
            sb.Append(HEADERWKTBL);
            sb.Append(" ( ");
            sb.Append("     OperationComputerName");
            sb.Append("     , OperationUserID");
            sb.Append("     , OperationDatetime");
            sb.Append("     , OperationJobID");
            sb.Append("     , SystemDenpyouNO");
            sb.Append("     , DenpyouNO");
            sb.Append("     , ShoriDate");
            sb.Append("     , HasseiDate");
            sb.Append("     , DenpyouTypeKBN");
            sb.Append("     , SystemCategory");
            sb.Append("     , SubSystemDenpyouNO");
            sb.Append("     , SubShoriKBN");
            sb.Append("     , SubDenpyouNO");
            sb.Append("     , DenpyouKBN");
            sb.Append("     , ZigyoushoCD");
            sb.Append("     , ZigyoushoKaiteiDate");
            sb.Append("     , DenpyouTekiyou");
            sb.Append("     , DenpyouListInziZumiKBN");
            sb.Append("     , CheckListInziZumiKBN");
            sb.Append("     , GuidAnken");
            sb.Append("     , ShouninStateKBN");
            sb.Append("     , KihyouUserID");
            sb.Append("     , CurrentUserID");
            sb.Append("     , ShouninUserID");
            sb.Append("     , ShouninDate");
            sb.Append("     , DenpyouSanshouRank");
            sb.Append("     , CompanyNO");
            sb.Append("     , UpdateDatetime");
            sb.Append("     , UpdateCertificatedGuid");
            sb.Append("     , UpdateJobID");
            sb.Append("     , UpdateUserID");
            sb.Append("     , UpdateComputerName");
            sb.Append("     , UpdateComputerUserName");
            sb.Append("     , UpdateComputerDomainName");
            sb.Append(" ) VALUES ( ");
            sb.Append("      " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerName) + " ");
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            sb.Append("     ,GETDATE() ");
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //新規時
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(0) + " ");       //システム伝票番号
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar("0") + " ");    //伝票番号
            }
            else
            {
                //修正時
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + " "); //システム伝票番号
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(obic7TextStringCalledDenpyouNO.Value) + " ");   //伝票番号
            }
            sb.Append("     ,CONVERT(VARCHAR(10),GETDATE(),111) ");                                                                              //処理日
            sb.Append("     ," + ComATool.Function.SqlEscapeDatetime(obic7TextDatetimeHasseiDate.Value) + " ");         //発生日
            sb.Append("     ," + ComATool.Function.SqlEscapeNumber(3) + " ");                                           //伝票タイプ区分
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //新規時
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(10) + " ");                                      //システム分類
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(0) + " ");                                       //サブシステムシステム伝票番号
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar("0") + " ");                                    //サブシステム処理区分
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar("0") + " ");                                    //サブシステム伝票番号
            }
            else
            {
                //修正時
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(prevSystemCategory) + " ");                      //システム分類
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(subSystemSystemDenpyouNO) + " ");                //サブシステムシステム伝票番号
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(subSystemShoriKBN) + " ");                      //サブシステム処理区分
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(subSystemDenpyouNO) + " ");                     //サブシステム伝票番号
            }

            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(obic7TextStringDenpyouKBN.Value) + " ");            //伝票区分
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(obic7TextStringZigyoushoCD.Value) + " ");           //事業所コード
            sb.Append("     ," + ComATool.Function.SqlEscapeDatetime(zigyoushoCDKaiteiDate) + " ");                     //事業所コード改定日
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ConvertParamData(obic7TextStringDenpyouTekiyou.Value)) + " ");        //伝票摘要
            sb.Append("     ," + ComATool.Function.SqlEscapeNumber(0) + " ");                                           //仕訳伝票印字済区分
            sb.Append("     ," + ComATool.Function.SqlEscapeNumber(0) + " ");                                           //仕訳チェックリスト印字済区分
            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //if (shouninKBN == 1 || ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20)
            if (shouninKBN == 1 || this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou)
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
            {
                //承認要否区分 = 1
                sb.Append("     ,NULL  ");                                                                          //案件Guid
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(50) + " ");                                  //承認状態区分

            }
            else
            {
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(AnkenGuid) + " ");                           //案件Guid
                sb.Append("     ," + ComATool.Function.SqlEscapeNumber(10) + " ");                                  //承認状態区分
            }

            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");      //起票ユーザID
            }
            else
            {
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(kihyouUserID) + " ");                           //起票ユーザID
            }
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");          //現在ユーザID

            //　2010/08/16　変更　　　C.Okuno  (M04451)↓
            //if (shouninKBN == 1 || ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20)
            if (shouninKBN == 1 || this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou)
            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
            {
                //承認要否区分 = 1
                sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");      //承認ユーザID
                sb.Append("     ,CONVERT(VARCHAR(10),GETDATE(),111) ");                                                     //処理日
            }
            else
            {
                sb.Append("     ,NULL  ");                                                                              //承認ユーザID         
                sb.Append("     ,NULL  ");                                                                              //承認日
            }
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(denpyouSanshouRank) + " ");                         //伝票参照ランク
            sb.Append("     ," + ComATool.Function.SqlEscapeNumber(ComATool.Logic.CurrentUser.CompanyNO) + " ");
            sb.Append("     ,GETDATE() ");
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.CertificatedGuid) + " ");
            sb.Append("     ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
