        /// <summary>
        /// 電子証憑データ取得用SQL文の作成
        /// </summary>
        /// <returns></returns>
        private string MakeSQLEvidenceGuidData()
        {
            //SQL文編集用
            StringBuilder sb = new StringBuilder();

            sb.AppendLine("SELECT EvidenceGuid");
            sb.AppendLine("      ,EvidenceVersionNO");
            sb.AppendLine("FROM  " + DENSIWKTBL + " MESH");
            sb.AppendLine("WHERE MESH.OperationComputerName =" + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.AppendLine("AND   MESH.OperationUserID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.AppendLine("AND   MESH.OperationJobID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " ");
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                sb.AppendLine("AND   MESH.SystemDenpyouNO = 0  ");
            }
            else
            {
                sb.AppendLine("AND   MESH.SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + "  ");
            }
            sb.AppendLine("ORDER BY EvidenceShowOrder");

            return sb.ToString();
        }
        // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
        /// <summary>
        /// 電子証憑データ取得用SQL文の作成
        /// </summary>
        /// <returns></returns>
        private string MakeSQLEvidenceData(EvidenceType evidenceType)
        {
            //SQL文編集用
            StringBuilder sb = new StringBuilder();

            sb.AppendLine("SELECT SystemDenpyouNO   ");
            sb.AppendLine("      ,DenpyouNO         ");
            sb.AppendLine("      ,EvidenceGuid      ");
            sb.AppendLine("      ,EvidenceVersionNO ");
            sb.AppendLine("      ,EvidenceShowOrder ");
            sb.AppendLine("      ,HasseiSystemCategory ");
            sb.AppendLine("      ,EvidenceType      ");
            sb.AppendLine("      ,Data              ");
            sb.AppendLine("      ,FileName          ");
            sb.AppendLine("      ,Memo              ");
            sb.AppendLine("FROM  " + DENSIWKTBL + " MESH");
            sb.AppendLine("WHERE MESH.OperationComputerName =" + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.AppendLine("AND   MESH.OperationUserID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.AppendLine("AND   MESH.OperationJobID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " ");
            if (evidenceType == EvidenceType.Densi || evidenceType == EvidenceType.Scanner)
            {
                sb.AppendLine("AND   MESH.EvidenceType IN ( 1 , 2 ) ");
            }
            else if(evidenceType == EvidenceType.Sonota)
            {
                sb.AppendLine("AND   MESH.EvidenceType = 3 ");
            }
            sb.AppendLine("ORDER BY EvidenceShowOrder");

            return sb.ToString();
        }
