        #region 電子証憑データを一時テーブルに更新(伝票登録時)
        /// <summary>
        /// 電子証憑データを一時テーブルに更新(伝票登録時)
        /// </summary>
        /// <param name="evidences"></param>
        private void TaihiEvidencesDataInsert(DataTable evidences)
        {
            //列削除処理
            List<string> removeColumnName = new List<string>();
            foreach (DataColumn item in evidences.Columns)
            {
                if (item.ColumnName != "EvidenceGuid" && item.ColumnName != "VersionNO")
                {
                    removeColumnName.Add(item.ColumnName);
                }
            }
            foreach (var item in removeColumnName)
            {
                evidences.Columns.Remove(item);
            }

            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_Evidences') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_Evidences ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_Evidences ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("    [EvidenceGuid] [uniqueidentifier]  ");
            sbCreate.AppendLine("   ,[VersionNO] [int]  ");
            sbCreate.AppendLine(" ) ");
            SQLExecuteNonQuery(sbCreate.ToString());

            //明細データをバルクコピー
            using (SqlCommand cm = businessDB.NewSqlCommand())
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(businessDB.NewSqlCommand().Connection, SqlBulkCopyOptions.CheckConstraints, cm.Transaction))
            {
                //コピー先のテーブル名をセット
                bulkCopy.DestinationTableName = "#M0000WK_Evidences";
                //バルクコピー
                bulkCopy.WriteToServer(evidences);
            }

            //取得した電子証憑データを電子証憑Guidで結合して、[伝票番号][バージョン]を電子証憑ワークへ更新する。
            StringBuilder sbUpdate = new StringBuilder();
            sbUpdate.AppendLine(" UPDATE    " + DENSIWKTBL + "");
            sbUpdate.AppendLine(" SET       EvidenceVersionNO = EVID.VersionNO");
            sbUpdate.AppendLine(" FROM      " + DENSIWKTBL + " MESH");
            sbUpdate.AppendLine(" INNER JOIN #M0000WK_Evidences EVID");
            sbUpdate.AppendLine(" ON        EVID.EvidenceGuid = MESH.EvidenceGuid");
            SQLExecuteNonQuery(sbUpdate.ToString());

        }
        #endregion

        #region 電子証憑データを一時テーブルに更新(伝票登録時・伝票番号修正時)
        /// <summary>
        /// 電子証憑データを一時テーブルに更新(伝票登録時・伝票番号修正時)
        /// </summary>
        /// <param name="evidences"></param>
        private void TaihiEvidencesDataUpdate(DataTable evidences)
        {
            //列削除処理
            List<string> removeColumnName = new List<string>();
            foreach (DataColumn item in evidences.Columns)
            {
                if (item.ColumnName != "EvidenceGuid" && item.ColumnName != "VersionNO")
                {
                    removeColumnName.Add(item.ColumnName);
                }
            }
            foreach (var item in removeColumnName)
            {
                evidences.Columns.Remove(item);
            }

            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_Evidences') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_Evidences ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_Evidences ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("    [EvidenceGuid] [uniqueidentifier]  ");
            sbCreate.AppendLine("   ,[VersionNO] [int]  ");
            sbCreate.AppendLine(" ) ");
            SQLExecuteNonQuery(sbCreate.ToString());

            //明細データをバルクコピー
            using (SqlCommand cm = businessDB.NewSqlCommand())
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(businessDB.NewSqlCommand().Connection, SqlBulkCopyOptions.CheckConstraints, cm.Transaction))
            {
                //コピー先のテーブル名をセット
                bulkCopy.DestinationTableName = "#M0000WK_Evidences";
                //バルクコピー
                bulkCopy.WriteToServer(evidences);
            }

            //取得した電子証憑データを電子証憑Guidで結合して、[バージョン]を電子証憑ワークへ更新する。
            StringBuilder sbUpdate = new StringBuilder();
            sbUpdate.AppendLine(" UPDATE    " + DENSIWKTBL + "");
            sbUpdate.AppendLine(" SET       DenpyouNO = " + ComATool.Function.SqlEscapeVarchar(this.obic7TextStringDenpyouNO.Value) + "");
            sbUpdate.AppendLine("          ,EvidenceVersionNO = EVID.VersionNO");
            sbUpdate.AppendLine(" FROM      " + DENSIWKTBL + " MESH");
            sbUpdate.AppendLine(" INNER JOIN #M0000WK_Evidences EVID");
            sbUpdate.AppendLine(" ON        EVID.EvidenceGuid = MESH.EvidenceGuid");
            SQLExecuteNonQuery(sbUpdate.ToString());

        }
