        #region 伝票番号紐付データ更新処理
        private int UpdateRelationData()
        {
            using (SqlCommand sc = businessDB.NewSqlCommand())
            {
                sc.CommandType = CommandType.StoredProcedure;
                sc.CommandText = RELATION_UPDATE;
                //エラー区分
                SqlParameter param1;
                param1 = sc.Parameters.Add("@po_ErrorKBN", SqlDbType.Int);
                param1.Direction = ParameterDirection.Output;
                //エラーCD1
                SqlParameter param2;
                param2 = sc.Parameters.Add("@po_ErrorCD1", SqlDbType.VarChar, 128);
                param2.Direction = ParameterDirection.Output;
                //エラーCD2
                SqlParameter param3;
                param3 = sc.Parameters.Add("@po_ErrorCD2", SqlDbType.VarChar, 128);
                param3.Direction = ParameterDirection.Output;
                //変更区分
                SqlParameter param4;
                param4 = sc.Parameters.Add("@p_HenkouKBN", SqlDbType.Int);
                param4.Direction = ParameterDirection.Input;
                if (obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    param4.Value = 0;
                }
                else if (obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    param4.Value = 1;
                }
                else if (obic7ComboBoxMode.Text == MODE_DELETE)
                {
                    param4.Value = 2;
                }
                //システム伝票番号
                SqlParameter param5;
                param5 = sc.Parameters.Add("@p_SystemDenpyouNO", SqlDbType.Decimal, 18);
                param5.Direction = ParameterDirection.Input;
                param5.Value = ConvertParamData(systemDenpyouNO);
                //変更後伝票番号
                SqlParameter param6;
                param6 = sc.Parameters.Add("@p_AfterDenpyouNO", SqlDbType.VarChar, 12);
                param6.Direction = ParameterDirection.Input;
                if (obic7ComboBoxMode.Text == MODE_DELETE)
                {
                    param6.Value = DBNull.Value;
                }
                else
                {
                    param6.Value = this.obic7TextStringPrevDenpyouNO.Text;
                }
                //変更前伝票番号
                SqlParameter param7;
                param7 = sc.Parameters.Add("@p_BeforeDenpyouNO", SqlDbType.VarChar, 12);
                param7.Direction = ParameterDirection.Input;
                if (obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    param7.Value = DBNull.Value;
                }
                else if (obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE)
                {
                    param7.Value = this.obic7TextStringCalledDenpyouNO.Text;
                }
                //伝票タイプ区分
                SqlParameter param8;
                param8 = sc.Parameters.Add("@p_DenpyouKBN", SqlDbType.Int);
                param8.Direction = ParameterDirection.Input;
                if (denpyouTypeKBN == null)
                {
                    param8.Value = 3;
                }
                else
                {
                    param8.Value = denpyouTypeKBN;
                }
                //更新ジョブID
                SqlParameter param9;
                param9 = sc.Parameters.Add("@p_UpdateJobID", SqlDbType.VarChar, 128);
                param9.Direction = ParameterDirection.Input;
                param9.Value = ComATool.Logic.CurrentUser.JobID;
                //更新ユーザID
                SqlParameter param10;
                param10 = sc.Parameters.Add("@p_UpdateUserID", SqlDbType.VarChar, 128);
                param10.Direction = ParameterDirection.Input;
                param10.Value = ComATool.Logic.CurrentUser.UserID;
                //更新PC名
                SqlParameter param11;
                param11 = sc.Parameters.Add("@p_UpdateComputerName", SqlDbType.VarChar, 128);
                param11.Direction = ParameterDirection.Input;
                param11.Value = ComATool.Logic.CurrentUser.ComputerName;
                //更新日時
                SqlParameter param12;
                param12 = sc.Parameters.Add("@p_UpdateDatetime", SqlDbType.DateTime);
                param12.Direction = ParameterDirection.Input;
                param12.Value = ConvertParamData((DateTime)businessDB.ExecuteScalar("SELECT GETDATE()"));
                //更新認証済Guid
                SqlParameter param13;
                param13 = sc.Parameters.Add("@p_UpdateCertificatedGuid", SqlDbType.UniqueIdentifier);
                param13.Direction = ParameterDirection.Input;
                param13.Value = ComATool.Logic.CurrentUser.CertificatedGuid;
                //更新PCユーザ名
                SqlParameter param14;
                param14 = sc.Parameters.Add("@p_UpdateComputerUserName", SqlDbType.VarChar, 128);
                param14.Direction = ParameterDirection.Input;
                param14.Value = ComATool.Logic.CurrentUser.ComputerUserName;
                //更新PCドメイン名
                SqlParameter param15;
                param15 = sc.Parameters.Add("@p_UpdateComputerDomainName", SqlDbType.VarChar, 256);
                param15.Direction = ParameterDirection.Input;
                param15.Value = ComATool.Logic.CurrentUser.ComputerDomainName;
                //会社NO
                SqlParameter param16;
                param16 = sc.Parameters.Add("@p_CompanyNO", SqlDbType.Int);
                param16.Direction = ParameterDirection.Input;
                param16.Value = ComATool.Logic.CurrentUser.CompanyNO;

                //戻り値
                SqlParameter param17;
                param17 = sc.Parameters.Add("RetVal", SqlDbType.Int);
                param17.Direction = ParameterDirection.ReturnValue;

                try
                {
                    sc.ExecuteNonQuery();
                }
                #region エラー処理
                catch (SqlException ex)
                {
                    //【ストアドにて業務ロジック以外のエラー（システムエラー）発生時は、ここで例外を処理する。】
                    //メッセージ分類は「InternalError」、メッセージアイコンは「Error」とする。
                    //ロールバック、メッセージボックス表示処理は業務ロジックで行い、処理の中断のみ行う。
                    //アプリケーションは異常終了させない。
                    //注：この処理を行うのは、デッドロックの場合のみとする。

                    bool bDeadLockFlg = true;

                    //メッセージ詳細の組み立て
                    string[] objMsgDetail = new string[3];

                    //ストアド名
                    objMsgDetail[0] = ex.Procedure.ToString();
                    //エラーコード
                    objMsgDetail[1] = ex.Number.ToString();
                    //エラー内容
                    for (int i = 0; i < ex.Errors.Count; i++)
                    {
                        objMsgDetail[2] += ex.Errors[i].ToString();
                    }

                    //エラーがデッドロック以外の場合、フラグをfalseに設定する。
                    //ex.エラーコード = 1205 → デッドロック
                    //                = 2627 → キー重複
                    //                = 8134 → ゼロ除算
                    if (ex.Number != 1205)
                    {
                        bDeadLockFlg = false;
                    }

                    if (bDeadLockFlg == true)
                    {
                        //デッドロックの場合は、業務にてエラー処理を行う。

                        // ロールバック
                        this.businessDB.RollBackTransaction();

                        //メッセージボックス表示
                        WinAToolLogic.UI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00119", null, objMsgDetail, GetType()
                                                            , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK
                                                            , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return 99999;
                    }
                    else
                    {
                        //デッドロック以外のエラーはthrowして、共通クラスのエラー処理に委ねる。
                        throw;
                    }
                }

                //個別エラー発生時
                if (ComATool.Function.AnyToInt16(param1.Value) == 2)
                //業務にて想定の範囲内のエラーが発生した場合は、ストアドからの戻り値を取得して、メッセージボックスを表示する。
                {
                    // ロールバック
                    this.businessDB.RollBackTransaction();

                    return ComATool.Function.AnyToInt32(param3.Value);
                }
                #endregion
            }
            return 0;
        }
        #endregion
        //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了

        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
        #region 追加添付証憑の承認状態を取得する
        private Dictionary<Guid, byte> GetAddEvidenceShouninStateDic()
        {
            StringBuilder sb = new StringBuilder();

            sb.Append(" SELECT ");
            sb.Append("      RR.EvidenceGuid  ");
            sb.Append("    , RR.ShouninStateKBN  ");
            sb.Append(" FROM " + DENSIADDRRTBL + " RR ");
            sb.Append(" WHERE RR.SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + " ");

            var evidenceShouninStateData = businessDB.GetDataTable(sb.ToString());

            var EvidenceShouninStateDic = new Dictionary<Guid, byte>();

            //EvidenceGuidをキーにし、証憑ごとの承認状態区分を退避するためのDictionaryを作成
            if (ComATool.Function.IsValidDataTable(evidenceShouninStateData))
            {
                for (int i = 0; i < evidenceShouninStateData.Rows.Count; i++)
                {
                    EvidenceShouninStateDic.Add(ComATool.Function.AnyToGuid(evidenceShouninStateData.Rows[i]["EvidenceGuid"], new Guid("00000000-0000-0000-0000-000000000000"))
                                              , ComATool.Function.AnyToByte(evidenceShouninStateData.Rows[i]["ShouninStateKBN"])
                                              );
                }
            }

            return EvidenceShouninStateDic;
        }
        #endregion

        #region 追加添付証憑の案件Guidを取得する
        private Guid? GetAddEvidenceAnkenGuid()
        {
            StringBuilder sb = new StringBuilder();

            sb.AppendLine(" SELECT TOP 1 RR.GuidAnken AS GuidAnken ");
            sb.AppendLine(" FROM " + DENSIADDRRTBL + " RR ");
            sb.AppendLine(" WHERE RR.SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + " ");
            sb.AppendLine(" AND   RR.ShouninStateKBN <> 50 ");

            var evidenceAnkenGuid = businessDB.GetDataTable(sb.ToString());

            if (ComATool.Function.IsValidDataTable(evidenceAnkenGuid))
            {
                if (evidenceAnkenGuid.Rows[0]["GuidAnken"] != DBNull.Value)
                {
                    return (Guid)evidenceAnkenGuid.Rows[0]["GuidAnken"];
                }
            }

            return null;
        }
        #endregion

        #region 追加添付の承認区分が変更されているかのチェック
        /// <summary>
        /// 追加添付の承認区分が変更されているかのチェック
        /// </summary>
        /// <returns></returns>
        private bool CheckShouninStateKBNChanged_TuikaTenpu()
        {
            //現在の承認区分を取得
            var currentEvidenceShouninStateDic = GetAddEvidenceShouninStateDic();

            //呼び出し時の承認区分と現在の承認区分が変更されていればtrueを返す
            var isChange = !yobidasiEvidenceShouninStateDic.OrderBy((o) => o.Key).SequenceEqual(currentEvidenceShouninStateDic.OrderBy((o) => o.Key));

            //呼出時の承認状態区分と現在の承認状態区分を比較
            if (isChange)
            {
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00744", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                return isChange;
            }

            return isChange;
        }
        #endregion

        #region 追加添付対象の存在チェック
        /// <summary>
        /// 追加添付対象の存在チェック
        /// </summary>
        /// <returns></returns>
        private bool CheckExist_TuikaTenpu()
        {
            //現在添付されている証憑の枚数を退避
            var currentEvidenceData = businessDB.GetDataTable(MakeSQLSelectEvidence(systemDenpyouNO));
            if (!ComATool.Function.IsValidDataTable(currentEvidenceData))
            {
                //呼び出し時、現在ともに添付枚数が0件の場合エラー
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30458", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                return false;
            }

            return true;
        }
        #endregion

        #region 追加電子証憑紐付データ更新
        private int UpdateEvidenceRelationAddition(DataTable abbDenpyouWKData, out int tuikaTenpuCount)
        {
            StringBuilder sbDelete = new StringBuilder();
            tuikaTenpuCount = 0;

            if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri)
            {
                sbDelete.AppendLine("DELETE FROM " + DENSIADDRRTBL + "");
                sbDelete.AppendLine("WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + "");
                sbDelete.AppendLine("AND   GuidAnken IS NOT NULL ");
                sbDelete.AppendLine("AND   ShouninStateKBN <> 50 "); //50：完了 以外

                var retValue = SQLExecuteNonQuery(sbDelete.ToString());
                if (retValue != 0)
                {
                    return 99999;
                }
            }
            else if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru)
            {
                MakeAlreadyRegisteredEvidenceFileDeleteData(abbDenpyouWKData);

                sbDelete.AppendLine("DELETE MAIN FROM " + DENSIADDRRTBL + " AS MAIN ");
                sbDelete.AppendLine("INNER JOIN #M0000WK_DeleteAlreadyRegisteredEvidenceFile AS WK ");
                sbDelete.AppendLine("ON  MAIN.EvidenceGuid = WK.EvidenceGuid ");
                sbDelete.AppendLine("WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + "");

                var retValue = SQLExecuteNonQuery(sbDelete.ToString());
                if (retValue != 0)
                {
                    return 99999;
                }
            }

            StringBuilder sb = new StringBuilder();

            sb.AppendLine("INSERT INTO " + DENSIADDRRTBL + "");
            sb.AppendLine("           ([SystemDenpyouNO]");
            sb.AppendLine("           ,[DenpyouNO]");
            sb.AppendLine("           ,[SystemCategory]");
            sb.AppendLine("           ,[SystemCategoryEdaban]");
            sb.AppendLine("           ,[EvidenceGuid]");
            sb.AppendLine("           ,[EvidenceShowOrder]");
            sb.AppendLine("           ,[EvidenceType]");
            sb.AppendLine("           ,[GuidAnken]");
            sb.AppendLine("           ,[ShouninStateKBN]");
            sb.AppendLine("           ,[KihyouUserID]");
            sb.AppendLine("           ,[CurrentUserID]");
            sb.AppendLine("           ,[ShouninUserID]");
            sb.AppendLine("           ,[ShouninDate]");
            sb.AppendLine("           ,[CompanyNO]");
            sb.AppendLine("           ,[UpdateDatetime]");
            sb.AppendLine("           ,[UpdateCertificatedGuid]");
            sb.AppendLine("           ,[UpdateJobID]");
            sb.AppendLine("           ,[UpdateUserID]");
            sb.AppendLine("           ,[UpdateComputerName]");
            sb.AppendLine("           ,[UpdateComputerUserName]");
            sb.AppendLine("           ,[UpdateComputerDomainName]");
            sb.AppendLine("           )");
            sb.AppendLine("SELECT");
            sb.AppendLine("           WK.SystemDenpyouNO");
            sb.AppendLine("          ,WK.DenpyouNO");
            sb.AppendLine("          ,12");
            sb.AppendLine("          ,0");
            sb.AppendLine("          ,WK.EvidenceGuid");
            sb.AppendLine("          ,WK.EvidenceShowOrder");
            sb.AppendLine("          ,WK.EvidenceType");
            if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri)
            {
                sb.AppendLine("      ," + ComATool.Function.SqlEscapeVarchar(tuikaTenpuAnkenGuid) + " "); //案件Guid
                sb.AppendLine("      ,10"); //承認状態区分
            }
            else
            {
                sb.AppendLine("      ,NULL"); //案件Guid
                sb.AppendLine("      ,50"); //承認状態区分
            }
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " AS KihyouUserID");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " AS CurrentUserID");
            if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri)
            {
                sb.AppendLine("      ,NULL"); //承認ユーザID
                sb.AppendLine("      ,NULL"); //承認日
            }
            else
            {
                sb.AppendLine("      ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " AS ShouninUserID"); //承認ユーザID
                sb.AppendLine("      ,CONVERT(VARCHAR(10),GETDATE(),111) AS UpdateDatetime"); //承認日
            }
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeNumber(ComAToolLogic.CurrentUser.CompanyNO) + " AS CompanyNO");
            sb.AppendLine("          ,GETDATE() AS UpdateDatetime");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.CertificatedGuid) + " AS UpdateCertificatedGuid");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " AS UpdateJobID");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " AS UpdateUserID");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " AS UpdateComputerName");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerUserName) + " AS UpdateComputerUserName");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerDomainName) + " AS UpdateComputerDomainName");
            sb.AppendLine("FROM   " + DENSIWKTBL + " WK");
            sb.AppendLine("LEFT JOIN " + DENSIRRTBL + " EVRL");
            sb.AppendLine("ON     WK.SystemDenpyouNO = EVRL.SystemDenpyouNO ");
            sb.AppendLine("AND    WK.EvidenceGuid    = EVRL.EvidenceGuid ");
            sb.AppendLine("WHERE  WK.OperationComputerName =" + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.AppendLine("AND    WK.OperationUserID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.AppendLine("AND    WK.OperationJobID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " ");
            sb.AppendLine("AND    WK.EvidenceGuid IS NOT NULL ");
            sb.AppendLine("AND    EVRL.EvidenceGuid IS NULL ");

            //SQL実行
            try
            {
                tuikaTenpuCount = businessDB.ExecuteNonQuery(sb.ToString());
            }
            catch (SqlException ex)
            {
                //【ストアドにて業務ロジック以外のエラー(システムエラー)発生時は、ここで例外を処理する。】
                //メッセージ分類は「InternalError」、メッセージアイコンは「Error」とする。
                //ロールバック、メッセージボックス表示処理は業務ロジックで行い、処理の中断のみ行う。
                //アプリケーションは異常終了させない。
                //注：この処理を行うのは、デッドロックの場合のみとする。

                bool bDeadLockFlg = true;

                //エラーがデッドロック以外の場合、フラグをfalseに設定する。
                //ex.エラーコード = 1205 → デッドロック
                //                = 2627 → キー重複
                //                = 8134 → ゼロ除算
                if (ex.Number != 1205)
                {
                    bDeadLockFlg = false;
                }

                if (bDeadLockFlg == true)
                {
                    //デッドロックの場合は、業務にてエラー処理を行う。

                    //ロールバック
                    businessDB.RollBackTransaction();

                    //メッセージボックス表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00119", null, null, GetType(),
                                                         WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                         WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    return 99999; //②このメソッドの呼び出し元(DeleteDenpyouメソッド)で例外をcatchされる為、ここでreturnさせる。(上記①も参照)
                }
                else
                {
                    //デッドロック以外のエラーはthrowして、共通クラスのエラー処理に委ねる。
                    throw;
                }
            }
            return 0;
        }
        #endregion

        #region 電子証憑紐付データ更新(追加添付用)
        private int UpdateEvidenceRelation_TuikaTenpu()
        {
            StringBuilder sbDelete = new StringBuilder();

            if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru)
            {
                sbDelete.AppendLine("DELETE MAIN FROM " + DENSIRRTBL + " AS MAIN ");
                sbDelete.AppendLine("INNER JOIN #M0000WK_DeleteAlreadyRegisteredEvidenceFile AS WK ");
                sbDelete.AppendLine("ON  MAIN.EvidenceGuid = WK.EvidenceGuid ");
                sbDelete.AppendLine("WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + "");

                var retValue = SQLExecuteNonQuery(sbDelete.ToString());
                if (retValue != 0)
                {
                    return 99999;
                }
            }

            StringBuilder sb = new StringBuilder();

            sb.AppendLine("INSERT INTO " + DENSIRRTBL + "");
            sb.AppendLine("           ([SystemDenpyouNO]");
            sb.AppendLine("           ,[DenpyouNO]");
            sb.AppendLine("           ,[SystemCategory]");
            sb.AppendLine("           ,[SystemCategoryEdaban]");
            sb.AppendLine("           ,[EvidenceGuid]");
            sb.AppendLine("           ,[EvidenceShowOrder]");
            sb.AppendLine("           ,[CompanyNO]");
            sb.AppendLine("           ,[UpdateDatetime]");
            sb.AppendLine("           ,[UpdateCertificatedGuid]");
            sb.AppendLine("           ,[UpdateJobID]");
            sb.AppendLine("           ,[UpdateUserID]");
            sb.AppendLine("           ,[UpdateComputerName]");
            sb.AppendLine("           ,[UpdateComputerUserName]");
            sb.AppendLine("           ,[UpdateComputerDomainName]");
            sb.AppendLine("           ,[EvidenceType])");
            sb.AppendLine("SELECT");
            sb.AppendLine("       WK.SystemDenpyouNO");
            sb.AppendLine("      ,WK.DenpyouNO");
            sb.AppendLine("          ,12");
            sb.AppendLine("          ,0");
            sb.AppendLine("          ,WK.EvidenceGuid");
            sb.AppendLine("          ,WK.EvidenceShowOrder");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeNumber(ComAToolLogic.CurrentUser.CompanyNO) + " AS CompanyNO");
            sb.AppendLine("          ,GETDATE() AS UpdateDatetime");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.CertificatedGuid) + " AS UpdateCertificatedGuid");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " AS UpdateJobID");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " AS UpdateUserID");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " AS UpdateComputerName");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerUserName) + " AS UpdateComputerUserName");
            sb.AppendLine("          ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerDomainName) + " AS UpdateComputerDomainName");
            sb.AppendLine("          ,WK.EvidenceType");
            sb.AppendLine("FROM   " + DENSIWKTBL + " WK");
            sb.AppendLine("LEFT JOIN " + DENSIRRTBL + " EVRL");
            sb.AppendLine("ON     WK.SystemDenpyouNO = EVRL.SystemDenpyouNO ");
            sb.AppendLine("AND    WK.EvidenceGuid    = EVRL.EvidenceGuid ");
            sb.AppendLine("WHERE  WK.OperationComputerName =" + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.AppendLine("AND    WK.OperationUserID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.AppendLine("AND    WK.OperationJobID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " ");
            sb.AppendLine("AND    WK.EvidenceGuid IS NOT NULL ");
            sb.AppendLine("AND    EVRL.EvidenceGuid IS NULL ");

            var retValue2 = SQLExecuteNonQuery(sb.ToString());
            if (retValue2 != 0)
            {
                return 99999;
            }
            return 0;
        }
