        #region 修正モードで削除された証憑を一時ワークに格納
        /// <summary>
        /// 修正モードで削除された証憑を一時ワークに格納
        /// </summary>
        private void MakeAlreadyRegisteredEvidenceFileDeleteData(DataTable abbDenpyouWKData)
        {
            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_DeleteAlreadyRegisteredEvidenceFile') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_DeleteAlreadyRegisteredEvidenceFile ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_DeleteAlreadyRegisteredEvidenceFile ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   [EvidenceGuid]               [uniqueidentifier] NOT NULL     ");
            sbCreate.AppendLine(" ) ");
            sbCreate.AppendLine(" CREATE INDEX IX_#M0000WK_DeleteAlreadyRegisteredEvidenceFile ON [#M0000WK_DeleteAlreadyRegisteredEvidenceFile] ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   [EvidenceGuid]  ");
            sbCreate.AppendLine(" ) ");
            businessDB.ExecuteNonQuery(sbCreate.ToString());

            // ABBの伝票WKで論理削除のデータを取得
            var taishouData = abbDenpyouWKData.AsEnumerable().Where(x => x["State"].ToString() == "4");

            var taishouDataTable = new DataTable();
            taishouDataTable.Columns.Add("EvidenceGuid", typeof(Guid));

            foreach (var item in taishouData)
            {
                var row = taishouDataTable.NewRow();
                row["EvidenceGuid"] = item["EvidenceGuid"];
                taishouDataTable.Rows.Add(row);
            }

            if (taishouDataTable.Rows.Count == 0)
            {
                return;
            }

            //バルクコピー
            using (SqlCommand cm = businessDB.NewSqlCommand())
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(businessDB.NewSqlCommand().Connection, SqlBulkCopyOptions.CheckConstraints, cm.Transaction))
            {
                //コピー先のテーブル名をセット
                bulkCopy.DestinationTableName = "#M0000WK_DeleteAlreadyRegisteredEvidenceFile";
                //バルクコピー
                bulkCopy.WriteToServer(taishouDataTable);
            }
        }
        #endregion
