        /// <returns></returns>
        private void CreateCheckTaishouTable()
        {
            //対象データを格納する一時テーブルを作成


            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_MA_CheckTaishouDenpyouInfo') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_MA_CheckTaishouDenpyouInfo ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_MA_CheckTaishouDenpyouInfo ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   SystemDenpyouNO        decimal(18,0) NOT NULL ");
            sbCreate.AppendLine("  ,DenpyouNO              varchar(12) COLLATE Database_Default ");
            sbCreate.AppendLine("  ,TorihikisakiCD         varchar(10) COLLATE Database_Default ");
            sbCreate.AppendLine("  ,TorihikisakiKaiteiDate datetime       ");
            sbCreate.AppendLine("  ,ZeiKBN                 varchar(3)  COLLATE Database_Default ");
            sbCreate.AppendLine(" ) ");

            sbCreate.AppendLine(" CREATE NONCLUSTERED INDEX IDX_#M0000WK_MA_CheckTaishouDenpyouInfo_01 ON #M0000WK_MA_CheckTaishouDenpyouInfo ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   TorihikisakiCD ");
            sbCreate.AppendLine("  ,TorihikisakiKaiteiDate ");
            sbCreate.AppendLine(" ) ");

            sbCreate.AppendLine(" CREATE NONCLUSTERED INDEX IDX_#M0000WK_MA_CheckTaishouDenpyouInfo_02 ON #M0000WK_MA_CheckTaishouDenpyouInfo ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   ZeiKBN ");
            sbCreate.AppendLine(" ) ");

            SQLExecuteNonQuery(sbCreate.ToString());

            //借方項目を#チェック対象伝票格納WKにINSERTする。

            StringBuilder sbInsertKari = new StringBuilder();

            sbInsertKari.AppendLine("INSERT INTO #M0000WK_MA_CheckTaishouDenpyouInfo ");
            sbInsertKari.AppendLine("           ( ");
            sbInsertKari.AppendLine("            [SystemDenpyouNO]");
            sbInsertKari.AppendLine("           ,[DenpyouNO]");
            sbInsertKari.AppendLine("           ,[TorihikisakiCD]");
