            sbInsertKari.AppendLine("    AND    OperationUserID       = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            sbInsertKari.AppendLine("    AND    OperationJobID        = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");

            SQLExecuteNonQuery(sbInsertKari.ToString());

            //貸方項目を#チェック対象伝票格納WKにINSERTする。
            StringBuilder sbInsertKasi = new StringBuilder();

            sbInsertKasi.AppendLine("INSERT INTO #M0000WK_MA_CheckTaishouDenpyouInfo ");
            sbInsertKasi.AppendLine("           ( ");
            sbInsertKasi.AppendLine("            [SystemDenpyouNO]");
            sbInsertKasi.AppendLine("           ,[DenpyouNO]");
            sbInsertKasi.AppendLine("           ,[TorihikisakiCD]");
            sbInsertKasi.AppendLine("           ,[TorihikisakiKaiteiDate]");
            sbInsertKasi.AppendLine("           ,[ZeiKBN]");
            sbInsertKasi.AppendLine("           ) ");
            sbInsertKasi.AppendLine("     SELECT");
            sbInsertKasi.AppendLine("            1 ");
            sbInsertKasi.AppendLine("           ,1 ");
            sbInsertKasi.AppendLine("           ,KasiTorihikisakiCD ");
            sbInsertKasi.AppendLine("           ,KasiTorihikisakiKaiteiDate ");
            sbInsertKasi.AppendLine("           ,KasiZeiKBN ");
            sbInsertKasi.AppendLine("    FROM   " + DETAILWKTBL + " ");

            sbInsertKasi.AppendLine("    WHERE  1 = 1 ");
            sbInsertKasi.AppendLine("    AND    OperationComputerName = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerName) + " ");
            sbInsertKasi.AppendLine("    AND    OperationUserID       = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            sbInsertKasi.AppendLine("    AND    OperationJobID        = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");

