        /// <summary>
        /// ストアドプロシージャへの引数引渡しの際に使用
        /// 未入力項目は""ではなくDBNull.Valueをセットするようにする
        /// </summary>
        /// <param name="value"></param>
        /// <returns></returns>
        private object ConvertParamData(string value)
        {
            if (!(String.IsNullOrEmpty(value)))
            {
                return value;
            }
            else
            {
                return DBNull.Value;
            }
        }

        /// <summary>
        /// ストアドプロシージャへの引数引渡しの際に使用
        /// Nullは""ではなくDBNull.Valueをセットするようにする
        /// </summary>
        /// <param name="value"></param>
        /// <returns></returns>
        private object ConvertParamData(decimal? value)
        {
            if (value != null)
            {
                return value;
            }
            else
            {
                return DBNull.Value;
            }
        }

        /// <summary>
        /// ストアドプロシージャへの引数引渡しの際に使用
        /// 未入力項目はNULLではなくDBNull.Valueをセットするようにする
        /// </summary>
        /// <param name="value"></param>
        /// <returns></returns>
        private object ConvertParamData(DateTime? value)
        {
            if (ComATool.Function.IsDateTime(value))
            {
                return (DateTime)value;
            }
            else
            {
                return DBNull.Value;
            }
        }

