        #region  フォーカスのセット処理(総勘定科目～金額)
        /// <summary>
        /// フォーカスのセット処理(総勘定科目～金額)
        /// </summary>
        /// <param name="rowNo">行番号</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="stcontrolkbn">フォーカス開始コントロール 1:総勘定科目 2:補助科目 3:補助内訳科目 4:取引先 5:事業所 6:部門  7:消費税本体科目 </param>
        private void SetFocusFromKanjouToKingaku(int rowNo, int taishakukbn, int stcontrolkbn)
        {
            //貸借名
            string taishakuName;

            //エンター押下時以外は処理終了
            if (enterKeyDownFlg == false)
            {
                return;
            }

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
            }
            else
            {
                taishakuName = "Kasi";
            }

            //スタートが総勘定科目
            if (stcontrolkbn == 1)
            {
                //総勘定科目が未入力の場合
                if (String.IsNullOrEmpty(GetStringColumn(rowNo, taishakuName, "KanjouCD").Value) == true)
                {
                    if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                    {
                        //貸方総勘定科目にフォーカスセット
                        GetStringColumn(rowNo, COL_KASIKANJOUCD).Focus();
                    }
                    else
                    {
                        //明細摘要にフォーカスセット
                        GetStringColumn(rowNo, COL_MEISAITEKIYOU).Focus();
                    }
                    return;
                }
                //補助区分 <> 0の場合
                else if (ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "HojoKBN")) != 0)
                {
                    //補助科目にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "HojoCD").Focus();
                    return;
                }
            }

            //スタートが補助科目
            if (stcontrolkbn == 2)
            {
                //補助内訳区分 <> 0の場合
                if (ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "UtiwakeKBN")) != 0)
                {
                    //補助内訳コードにフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "UtiwakeCD").Focus();
                    return;
                }
            }

            //スタートが総勘定科目～補助内訳科目
            if (stcontrolkbn <= 3)
            {
                //取引先区分 <> 0の場合
                if (ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "TorihikisakiKBN")) != 0)
                {
                    //借方取引先にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "TorihikisakiCD").Focus();
                    return;
                }
            }


            //スタートが総勘定科目～取引先
            if (stcontrolkbn <= 4)
            {
                //事業所にフォーカスセット
                GetStringColumn(rowNo, taishakuName, "ZigyoushoCD").Focus();
                return;
            }

            //スタートが総勘定科目～事業所
            if (stcontrolkbn <= 5)
            {
                //部門区分 <> 0の場合
                if (ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "BumonKBN")) != 0)
                {
                    //部門にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "BumonCD").Focus();
                    return;
                }
            }

            //スタートが総勘定科目～部門
            if (stcontrolkbn <= 6)
            {

                //総勘定科目コードが仮払、仮受消費税コードの時
                if (GetStringColumn(rowNo, taishakuName, "KanjouCD").Value == kariBaraiZeiKamokuCD
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                    || GetStringColumn(rowNo, taishakuName, "KanjouCD").Value == rcHaraiCD
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了
                    || GetStringColumn(rowNo, taishakuName, "KanjouCD").Value == kariUkeZeiKamokuCD)
                {

                    //消費税本体科目コードにフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "ZeiHontaiCD").Focus();
                    return;
                }
            }

            //スタートが総勘定科目～消費税本体科目コード
            if (stcontrolkbn <= 7)
            {
                //税フォーカスフラグ = 1 の場合
                if (zeiFocusFlag == 1)
                {
                    //借方税区分にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "ZeiKBN").Focus();
                    return;
                }
                else
                {
                    //金額にフォーカスセット
                    GetNumberColumn(rowNo, taishakuName, "Kingaku").Focus();
                    return;
                }

            }
        }

        #endregion

        #region フォーカスのセット処理(金額～明細摘要)

        /// <summary>
        /// フォーカスのセット処理(金額～明細摘要)
        /// </summary>
        /// <param name="rowNo">行番号</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="stcontrolkbn">フォーカス開始コントロール 1:金額 1:消費税 2:分析コード1 3:分析コード2 4:分析コード3 6:資金コード</param>
        private void SetFocusFromKingakuToTekiyou(int rowNo, int taishakukbn, int stcontrolkbn)
        {
            //貸借名
            string taishakuName;

            //エンター押下時以外は処理終了
            if (enterKeyDownFlg == false)
            {
                return;
            }

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
            }
            else
            {
                taishakuName = "Kasi";
            }

            //スタートが金額,消費税
            if (stcontrolkbn == 1)
            {
                //分析フォーカスフラグ == 1
                if (bunsekiCDFocusFlag == 1)
                {
                    //分析チェック区分1 <> 6の場合
                    if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") != 6)
                    {
                        //分析コード1にフォーカスセット
                        GetStringColumn(rowNo, taishakuName, "BunsekiCD1").Focus();
                        return;
                    }
                }
                //2008/05/14 変更 N.Sasaki 開始 分析フォーカスフラグが0(移動しない)でも分析コードに必須か警告項目がある場合は移動する
                //                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 4
                //                    || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 5)
                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 4
                    || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 5
                    || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 2
                    || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 3
                    )
                //2008/05/14 変更 N.Sasaki 終了
                {
                    //分析コード1にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "BunsekiCD1").Focus();
                    return;
                }
                //2008/05/14 変更 N.Sasaki 開始 分析フォーカスフラグが0(移動しない)でも分析コードに必須か警告項目がある場合は移動する
                //                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 4
                //               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 5)
                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 4
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 5
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 2
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 3
                    )
                //2008/05/14 変更 N.Sasaki 終了
                {
                    //分析コード2にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "BunsekiCD2").Focus();
                    return;
                }
                //2008/05/14 変更 N.Sasaki 開始 分析フォーカスフラグが0(移動しない)でも分析コードに必須か警告項目がある場合は移動する
                //                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 4
                //               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 5)
                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 4
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 5
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 2
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 3
                    )
                //2008/05/14 変更 N.Sasaki 終了
                {
                    //分析コード3にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "BunsekiCD3").Focus();
                    return;
                }
                //2008/05/14 変更 N.Sasaki 開始 分析フォーカスフラグが0(移動しない)でも分析コードに必須か警告項目がある場合は移動する
                //                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") == 4
                //               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") == 5)
                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") == 4
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") == 5
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") == 2
               || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") == 3
                    )
                //2008/05/14 変更 N.Sasaki 終了
                {
                    //資金コードにフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "SikinCD").Focus();
                    return;
                }
                // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                else if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouProjectCheckKBN") == 4
                || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouProjectCheckKBN") == 5
                || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouProjectCheckKBN") == 2
                || GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouProjectCheckKBN") == 3
                )
                {
                    //プロジェクトコードにフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "ProjectCD").Focus();
                    return;
                }
                // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                else
                {
                    //借方の場合
                    if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                    {
                        //1:Nの仕訳の場合
                        if (CheckNSiwake(rowNo, 2) == true)
                        {
                            //明細摘要にフォーカスセット
                            (GetStringColumn(rowNo, COL_MEISAITEKIYOU)).Focus();
                            return;
                        }
                        else
                        {
                            //貸方総勘定科目コードにフォーカスセット
                            (GetStringColumn(rowNo, COL_KASIKANJOUCD)).Focus();
                            return;
                        }
                    }
                    //貸方の場合
                    else
                    {
                        //明細摘要にフォーカスセット
                        (GetStringColumn(rowNo, COL_MEISAITEKIYOU)).Focus();
                        return;
                    }
                }
            }

            //スタートが金額から分析コード1
            if (stcontrolkbn <= 2)
            {
                //分析チェック区分2 <> 6の場合
                if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") != 6)
                {
                    //分析コード2にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "BunsekiCD2").Focus();
                    return;
                }
            }

            //スタートが金額から分析コード2
            if (stcontrolkbn <= 3)
            {
                //分析チェック区分3 <> 6の場合
                if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") != 6)
                {
                    //分析コード3にフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "BunsekiCD3").Focus();
                    return;
                }
            }

            //スタートが金額から分析コード3
            if (stcontrolkbn <= 4)
            {
                //分析チェック資金コード <> 6 の場合
                if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouSikinCheckKBN") != 6)
                {
                    //資金コードにフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "SikinCD").Focus();
                    return;
                }
            }


            // 2013/05/15 修正 I.Nakagawa 開始 (GX)
            ////スタートが金額から資金コード
            //if (stcontrolkbn <= 6)
            //{
            //    //借方の場合
            //    if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            //    {
            //        //1:Nの仕訳の場合
            //        if (CheckNSiwake(rowNo,2) == true)
            //        {
            //            //明細摘要にフォーカスセット
            //            GetStringColumn(rowNo, COL_MEISAITEKIYOU).Focus();
            //            return;
            //        }
            //        else
            //        {
            //            //貸方総勘定科目コードにフォーカスセット
            //            GetStringColumn(rowNo, COL_KASIKANJOUCD).Focus();
            //            return;
            //        }
            //    }
            //    //貸方の場合
            //    else
            //    {
            //        //明細摘要にフォーカスセット
            //        GetStringColumn(rowNo, COL_MEISAITEKIYOU).Focus();
            //        return;
            //    }
            //}

            //スタートが金額から資金コード
            if (stcontrolkbn <= 6)
            {
                if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "KanjouProjectCheckKBN") != 6)
                {
                    //プロジェクトコードにフォーカスセット
                    GetStringColumn(rowNo, taishakuName, "ProjectCD").Focus();
                    return;
                }
            }

            //スタートが金額からプロジェクトコード
            if (stcontrolkbn <= 7)
            {
                //借方の場合
                if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                {
                    //1:Nの仕訳の場合
                    if (CheckNSiwake(rowNo, 2) == true)
                    {
                        //明細摘要にフォーカスセット
                        GetStringColumn(rowNo, COL_MEISAITEKIYOU).Focus();
                        return;
                    }
                    else
                    {
                        //貸方総勘定科目コードにフォーカスセット
                        GetStringColumn(rowNo, COL_KASIKANJOUCD).Focus();
                        return;
                    }
                }
                //貸方の場合
                else
                {
                    //明細摘要にフォーカスセット
                    GetStringColumn(rowNo, COL_MEISAITEKIYOU).Focus();
                    return;
                }
            }
            // 2013/05/15 修正 I.Nakagawa 終了 (GX)

            return;
        }

        #endregion

        #region 分析情報起動処理
        /// <summary>
        /// 分析情報起動処理
        /// </summary>
        private void BunsekiJouhou(int colNumber, bool errorFlg)
        {
            //貸借区分
            int taishakukbn = 0;

            //貸借区分セット
            if (colNumber < COL_KASIKANJOUCD)
            {
                taishakukbn = 1;
            }
            else
            {
                taishakukbn = 2;
            }

            switch (colNumber)
            {
                case COL_KARIBUNSEKICD1:
                case COL_KARIBUNSEKICD2:
                case COL_KARIBUNSEKICD3:
                case COL_KARIBUNSEKICD4:
                case COL_KARIBUNSEKICD5:
                case COL_KARISIKINCD:
                case COL_KARIPROJECTCD:
                    taishakukbn = 1;
                    break;
                case COL_KASIBUNSEKICD1:
                case COL_KASIBUNSEKICD2:
                case COL_KASIBUNSEKICD3:
                case COL_KASIBUNSEKICD4:
                case COL_KASIBUNSEKICD5:
                case COL_KASISIKINCD:
                case COL_KASIPROJECTCD:
                    taishakukbn = 2;
                    break;
            }

            WinAToolUI.Obic7TextAbstract textAbstract = null;

            //旧value
            textAbstract = PrevControl as WinAToolUI.Obic7TextAbstract;
            int rowNo = ComATool.Function.AnyToInt32(textAbstract.Parent.Tag);

            WinAToolUI.Obic7TextString bunsekicd1control;            //分析コード1
            WinAToolUI.Obic7TextString bunsekicd2control;            //分析コード2
            WinAToolUI.Obic7TextString bunsekicd3control;            //分析コード3
            WinAToolUI.Obic7TextString bunsekicd4control;            //分析コード4
            WinAToolUI.Obic7TextString bunsekicd5control;            //分析コード5
            WinAToolUI.Obic7TextString sikincdcontrol;               //資金コード
            WinAToolUI.Obic7TextString projectcdcontrol;             //プロジェクトコード
            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                //呼び出し元が借方の場合、借方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                bunsekicd1control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIBUNSEKICD1) as WinAToolUI.Obic7TextString;
                bunsekicd2control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIBUNSEKICD2) as WinAToolUI.Obic7TextString;
                bunsekicd3control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIBUNSEKICD3) as WinAToolUI.Obic7TextString;
                bunsekicd4control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIBUNSEKICD4) as WinAToolUI.Obic7TextString;
                bunsekicd5control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIBUNSEKICD5) as WinAToolUI.Obic7TextString;
                sikincdcontrol = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARISIKINCD) as WinAToolUI.Obic7TextString;
                projectcdcontrol = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIPROJECTCD) as WinAToolUI.Obic7TextString;
            }
            else
            {
                //呼び出し元が貸方の場合、貸方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                bunsekicd1control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIBUNSEKICD1) as WinAToolUI.Obic7TextString;
                bunsekicd2control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIBUNSEKICD2) as WinAToolUI.Obic7TextString;
                bunsekicd3control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIBUNSEKICD3) as WinAToolUI.Obic7TextString;
                bunsekicd4control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIBUNSEKICD4) as WinAToolUI.Obic7TextString;
                bunsekicd5control = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIBUNSEKICD5) as WinAToolUI.Obic7TextString;
                sikincdcontrol = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASISIKINCD) as WinAToolUI.Obic7TextString;
                projectcdcontrol = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIPROJECTCD) as WinAToolUI.Obic7TextString;
            }

            // 2013/09/09 追加 K.Morita GX対応(プロジェクト仕訳入力対応) ↓
            //個別管理オプションのチェック
            using (DataTable kobetuData = WinMTool.CompanyUsability.SelectByKey((int)ComAToolLogic.CurrentUser.CompanyNO, "M_Kobetu"))
            {
                if (ComATool.Function.IsValidDataTable(kobetuData) == true)
                {
                    //対象項目が分析コード,資金コードであれば分析コード検索ダイアログを表示する
                    using (Obic7fx.Win.M0000.Tool.Input.MD_BunsekiCD bunseki = new Obic7fx.Win.M0000.Tool.Input.MD_BunsekiCD())
                    {


                        if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                        {
                            //呼び出し元が借方の場合、借方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                            bunseki.KanjouCD = GetStringColumn(rowNo, COL_KARIKANJOUCD).Value;
                            bunseki.KanjouName = GetStringColumn(rowNo, COL_KARIKANJOUNAMERYAKU).Value;
                            bunseki.BunsekiCheckKBN1 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUBUNSEKICHECKKBN1));
                            bunseki.BunsekiCheckKBN2 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUBUNSEKICHECKKBN2));
                            bunseki.BunsekiCheckKBN3 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUBUNSEKICHECKKBN3));
                            bunseki.BunsekiCheckKBN4 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUBUNSEKICHECKKBN4));
                            bunseki.BunsekiCheckKBN5 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUBUNSEKICHECKKBN5));
                            bunseki.SikinCheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUSIKINCHECKKBN));
                            bunseki.ProjectCheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKANJOUPROJECTCHECKKBN));
                        }
                        else
                        {
                            //呼び出し元が貸方の場合、借方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                            bunseki.KanjouCD = GetStringColumn(rowNo, COL_KASIKANJOUCD).Value;
                            bunseki.KanjouName = GetStringColumn(rowNo, COL_KASIKANJOUNAMERYAKU).Value;
                            bunseki.BunsekiCheckKBN1 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUBUNSEKICHECKKBN1));
                            bunseki.BunsekiCheckKBN2 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUBUNSEKICHECKKBN2));
                            bunseki.BunsekiCheckKBN3 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUBUNSEKICHECKKBN3));
                            bunseki.BunsekiCheckKBN4 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUBUNSEKICHECKKBN4));
                            bunseki.BunsekiCheckKBN5 = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUBUNSEKICHECKKBN5));
                            bunseki.SikinCheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUSIKINCHECKKBN));
                            bunseki.ProjectCheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKANJOUPROJECTCHECKKBN));
                        }
                        if (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE)
                        {
                            bunseki.Mode = 0;
                        }
                        else
                        {
                            bunseki.Mode = 1;
                        }
                        bunseki.BunsekiCD1 = bunsekicd1control.Text;
                        bunseki.BunsekiCD2 = bunsekicd2control.Text;
                        bunseki.BunsekiCD3 = bunsekicd3control.Text;
                        bunseki.BunsekiCD4 = bunsekicd4control.Value;
                        bunseki.BunsekiCD5 = bunsekicd5control.Value;
                        bunseki.SikinCD = sikincdcontrol.Text;
                        bunseki.ProjectCD = projectcdcontrol.Text;
                        if (errorFlg == true)
                        {
                            //呼出元をセット
                            switch (colNumber)
                            {
                                case COL_KARIBUNSEKICD1:
                                case COL_KASIBUNSEKICD1:
                                    bunseki.YobidasiMoto = 1;
                                    break;
                                case COL_KARIBUNSEKICD2:
                                case COL_KASIBUNSEKICD2:
                                    bunseki.YobidasiMoto = 2;
                                    break;
                                case COL_KARIBUNSEKICD3:
                                case COL_KASIBUNSEKICD3:
                                    bunseki.YobidasiMoto = 3;
                                    break;
                                case COL_KARIBUNSEKICD4:
                                case COL_KASIBUNSEKICD4:
                                    bunseki.YobidasiMoto = 4;
                                    break;
                                case COL_KARIBUNSEKICD5:
                                case COL_KASIBUNSEKICD5:
                                    bunseki.YobidasiMoto = 5;
                                    break;
                                case COL_KARISIKINCD:
                                case COL_KASISIKINCD:
                                    bunseki.YobidasiMoto = 6;
                                    break;
                                case COL_KARIPROJECTCD:
                                case COL_KASIPROJECTCD:
                                    bunseki.YobidasiMoto = 7;
                                    break;
                            }
                        }

                        bunseki.TaishakuKBN = taishakukbn - 1;

                        // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                        bunseki.UserID = ComAToolLogic.CurrentUser.UserID;
                        bunseki.BunsekiCD1NyuuryokuSeigyoFlg = bunsekiCD1NyuuryokuSeigyoFlg;
                        bunseki.BunsekiCD2NyuuryokuSeigyoFlg = bunsekiCD2NyuuryokuSeigyoFlg;
                        bunseki.BunsekiCD3NyuuryokuSeigyoFlg = bunsekiCD3NyuuryokuSeigyoFlg;
                        bunseki.BunsekiCD4NyuuryokuSeigyoFlg = bunsekiCD4NyuuryokuSeigyoFlg;
                        bunseki.BunsekiCD5NyuuryokuSeigyoFlg = bunsekiCD5NyuuryokuSeigyoFlg;
                        bunseki.SikinCDNyuuryokuSeigyoFlg = sikinCDNyuuryokuSeigyoFlg;
                        bunseki.ProjectCDNyuuryokuSeigyoFlg = projectCDNyuuryokuSeigyoFlg;
                        // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)

                        if (bunseki.ShowDialog() == DialogResult.OK)
                        {
                            bunsekicd1control.Value = bunseki.BunsekiCD1;
                            bunsekicd2control.Value = bunseki.BunsekiCD2;
                            bunsekicd3control.Value = bunseki.BunsekiCD3;
                            bunsekicd4control.Value = bunseki.BunsekiCD4;
                            bunsekicd5control.Value = bunseki.BunsekiCD5;
                            sikincdcontrol.Value = bunseki.SikinCD;
                            projectcdcontrol.Value = bunseki.ProjectCD;

                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 1);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 2);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 3);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 6);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 4);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 5);
