        /// <summary>
        /// エラープロバイダ表示(明細行チェック用)
        /// </summary>
        /// <param name="checkkbn"></param>
        /// <param name="rowno"></param>
        /// <param name="column"></param>
        private void DispErrorProvider(int checkkbn, int rowno, int column)
        {
            WinAToolUI.Obic7TextAbstract textAbstract = null;

            //エラープロバイダー表示
            ComATool.Logic.Message message = new ComATool.Logic.Message();
            message.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00104", null, null);

            if (checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7MultilineCheckGridDetail.GetColumnObject(rowno, column), message.MessageSummary);
            }
            else
            {
                //アクティブコントロールセット
                textAbstract = ActiveControl as WinAToolUI.Obic7TextAbstract;

                //エラープロバイダー表示
                WinAToolUI.Obic7ErrorProvider.SetError(obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), column), message.MessageSummary);
            }
        }
        #endregion

        #region １：Ｎの仕訳かのチェック

        /// <summary>
        /// １：Ｎの仕訳かのチェック
        /// </summary>
        /// <param name="rowNo">行番号</param>
        /// <param name="stcontrolkbn">1: 明細摘要 2:明細摘要以外</param>
        /// <returns></returns>
        private bool CheckNSiwake(int rowNo, int stcontrolkbn)
        {
            //明細摘要のとき
            if (stcontrolkbn == 1)
            {
                //借方総合計金額と貸方総合計金額が同じ場合
                if (obic7TextNumberTotalKariSougaku.Value == obic7TextNumberTotalKasiSougaku.Value)
                {
                    //借方金額と貸方金額が入力済みの場合
                    if (String.IsNullOrEmpty(GetNumberColumn(rowNo, COL_KARIKINGAKU).Text) == false
                        && String.IsNullOrEmpty(GetNumberColumn(rowNo, COL_KASIKINGAKU).Text) == false
                        )
                    {
                        //借方金額と貸方金額が符号が同じ場合
                        if (System.Math.Sign(ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KARIKINGAKU).Value))
                            == System.Math.Sign(ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KASIKINGAKU).Value))
                            )
                        {
                            //借方金額の絶対値がと貸方金額の絶対値よりも大きい場合
                            if (System.Math.Abs(ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KARIKINGAKU).Value) + ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KARIZEIGAKU).Value))
                                > System.Math.Abs(ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KASIKINGAKU).Value) + ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KASIZEIGAKU).Value))
                                )
                            {
                                return true;
                            }
                        }
                        //借方金額と貸方金額が符号が異なる場合
                        else
                        {
                            //借方金額が貸方金額よりも大きい場合
                            if (GetNumberColumn(rowNo, COL_KARIKINGAKU).Value + ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KARIZEIGAKU).Value)
                                > GetNumberColumn(rowNo, COL_KASIKINGAKU).Value + ComATool.Function.AnyToDecimal(GetNumberColumn(rowNo, COL_KASIZEIGAKU).Value)
                                )
                            {
                                return true;
                            }
                        }
                    }
                }
                //借方総合計金額と貸方総合計金額が異なる場合
                else
                {
                    //借方金額と貸方金額が符号が同じ場合
                    if (System.Math.Sign(ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariSougaku.Value))
                        == System.Math.Sign(ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiSougaku.Value))
                        )
                    {
                        //借方金額の絶対値がと貸方金額の絶対値よりも大きい場合
                        if (System.Math.Abs(ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariSougaku.Value))
                            > System.Math.Abs(ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiSougaku.Value))
                        )
                        {
                            return true;
                        }
                    }
                    //借方金額と貸方金額が符号が異なる場合
                    else
                    {
                        //借方金額が貸方金額よりも大きい場合
                        if (obic7TextNumberTotalKariSougaku.Value
                            > obic7TextNumberTotalKasiSougaku.Value
                            )
                        {
                            return true;
                        }
                    }
                }
            }
            //明細摘要以外のとき
            else
            {
                //借方総合計金額と貸方総合計金額が同じ場合
                if (obic7TextNumberTotalKariSougaku.Value == obic7TextNumberTotalKasiSougaku.Value)
                {
                    //借方金額が入力済みでと貸方金額が未入力の場合
                    if (String.IsNullOrEmpty(GetNumberColumn(rowNo, COL_KARIKINGAKU).Text) == false
                        && String.IsNullOrEmpty(GetNumberColumn(rowNo, COL_KASIKINGAKU).Text) == true
                        )
                    {
                        return true;
                    }
                }
                //借方総合計金額の絶対値<貸方総合計金額の絶対値の場合
                else if (System.Math.Abs(ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariSougaku.Value)) < System.Math.Abs(ComATool.Function.AnyToDecimal(obic7TextNumberTotalKasiSougaku.Value)))
                {
                    return true;
                }
            }
            return false;
        }

        #endregion

        #region 総勘定科目コードのチェック

        /// <summary>
        /// 総勘定科目コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckKanjouCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtKanjouM = null;
            DataTable dtKariZeiKBNM = null;
            DataTable dtKasiZeiKBNM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //勘定科目コードカラム番号
            int kanjouColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                kanjouColumnNo = COL_KARIKANJOUCD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                kanjouColumnNo = COL_KASIKANJOUCD;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, kanjouColumnNo).IsChangedText;
                }

                if ((isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT))
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //総勘定科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouNameRyaku", "");
                        if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                        {

                            //補助科目コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoCD", "");
                            //補助科目名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoNameRyaku", "");
                            //補助内訳科目コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCD", "");
                            //補助内訳科目名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeNameRyaku", "");
                            //取引先コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCD", "");
                            //取引先名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiShanaiName", "");
                            //税区分
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN", "0");
                            if (CheckZeiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE) != KBN_CHECK_OK)
                            {
                                return KBN_CHECK_NG_CANCEL;
                            }
                            //税込区分
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", 0);
                            if (CheckZeikomiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE) != KBN_CHECK_OK)
                            {
                                return KBN_CHECK_NG_CANCEL;
                            }

                            //消費税本体科目コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCD", "");
                            //消費税本体科目名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiNameRyaku", "");
                        }
                        //隠し項目のクリア
                        //総勘定科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouName", "");
                        //総勘定科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKaiteiDate", null);
                        //貸借区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TaishakuKBN", null);
                        //取引先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKBN", null);
                        //補助区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoKBN", null);
                        //部門区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonKBN", null);
                        //分析チェック区分1
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1", null);
                        //分析チェック区分2
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN2", null);
                        //分析チェック区分3
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN3", null);
                        //分析チェック区分4
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN4", null);
                        //分析チェック区分5
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN5", null);
                        //資金チェック区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouSikinCheckKBN", null);
                        //プロジェクトチェック区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouProjectCheckKBN", null);
                        //科目リース会社区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiLeaseKaishaKBN", null);
                        //科目税務署区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiZeimushoKBN", null);
                        //科目仕入先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiiresakiKBN", null);
                        //科目支払先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiharaisakiKBN", null);
                        //科目得意先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTokuisakiKBN", null);
                        //科目回収先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiKaishuusakiKBN", null);
                        //科目取引先区分1
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN1", null);
                        //科目取引先区分2
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN2", null);
                        //科目取引先区分3
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN3", null);
                        //科目取引先区分4
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN4", null);
                        //科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKamokuCategory", null);
                        //科目分類
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKamokuKBN", null);
                        //借方税区分開始日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiKaisiDate", null);
                        //借方税区分廃止日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiHaisiDate", null);
                        //貸方税区分開始日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiKaisiDate", null);
                        //貸方税区分廃止日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiHaisiDate", null);
                        //借方消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKamokuKBN", null);
                        //貸方消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKamokuKBN", null);
                        //補助科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoName", "");
                        //補助科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HojoKaiteiDate", null);
                        //補助内訳区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKBN", null);
                        //補助内訳科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeName", "");
                        //補助内訳コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKaiteiDate", null);
                        //取引先コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKaiteiDate", null);
                        //借方消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKamokuKBN", null);
                        //貸方消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKamokuKBN", null);

                        if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                        {

                            //通常税率
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", null);
                            //端数処理
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", null);
                            //消費税計算区分
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", null);
                            //消費税科目区分
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", null);

                        }
                        //借方税区分
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBN", "");
                        //貸方税区分
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBN", "");
                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == true)
                    {
                        //部門クリア
                        if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                        {
                            //部門コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD", "");
                            //部門名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonNameRyaku", "");
                            //部門名(隠し項目)
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonName", "");
                            //部門コード改定日
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "BumonKaiteiDate", null);

                            //金額
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku", null);
                            //消費税額
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku", null);
                            //合計額の計算
                            RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);

                            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                            //メモR値
                            this.SetNumberColumnValue(checkkbn, rowNo, taishakuName, "MemoRValue", null);
                            //メモG値
                            this.SetNumberColumnValue(checkkbn, rowNo, taishakuName, "MemoGValue", null);
                            //メモB値
                            this.SetNumberColumnValue(checkkbn, rowNo, taishakuName, "MemoBValue", null);
                            //メモ
                            this.SetStringColumnValue(checkkbn, rowNo, taishakuName, "Memo", "");
                            //Allチェック以外の場合
                            if (checkkbn != KBN_KOUMOKUCHK_ALL)
                            {
                                //メモボタンをデフォルトに戻す
                                this.SetMemoInfo(rowNo, taishakukbn, this.defaultButtonColor, string.Empty);
                                //メモボタンを使用不可
                                this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, "obic7ButtonWithLogic" + taishakuName + "Memo").Enabled = false;
                            }
                            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
                        }

                        //処理なし
                        return KBN_CHECK_OK;
                    }

                    //総勘定科目マスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                        DenpyouKBN = "";
                        if (!string.IsNullOrEmpty(obic7TextStringDenpyouKBN.Value))
                        {
                            DenpyouKBN = obic7TextStringDenpyouKBN.Value;
                        }
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                        //マスタよりデータを取得
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                        //dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD"), (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, "");
                        dtKanjouM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD"), (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, "", DenpyouKBN);
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                        if (dtKanjouM.Rows.Count == 0)
                        {
                            //総勘定科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag", 1);
                        }
                        else
                        {
                            //総勘定科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag", 0);
                        }

                        //データがある場合
                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag") == 0)
                        {
                            //部門区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BumonKBN"]));
                        }

                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {

                        //科目変更時部門表示フラグにより、画面項目クリア
                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag") == 1 || henkouHyouziFlag == 0 || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonKBN") == 0)
                        {
                            //部門コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD", "");
                            //部門名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonNameRyaku", "");
                            //部門名(隠し項目)
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonName", "");
                            //部門コード改定日
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "BumonKaiteiDate", null);
                        }

                        //  2014/02/27  変更   T.Shiraishi    (ID:9498)部門別科目制御対応 開始↓
                        //会計共通コントロールM.[科目変更時部門表示フラグ] = [1](表示クリアしない)の場合、かつ
                        //会計共通コントロールM.[部門科目種別パターンチェック区分] = [2](する(エラー時更新不可) の場合
                        if (this.henkouHyouziFlag == 1 && this.bumonKamokuShubetuPatternCheckKBN == 2)
                        {
                            DateTime kijunDate = (DateTime)this.obic7TextDatetimeHasseiDate.Value;
                            string kanjouCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD");
                            string bumonCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD");

                            //部門科目種別パターンチェック
                            if (!WinMTool.M0000MS_MA_BumonKamokuShubetuPatternCheck.BumonKamokuShubetuPatternCheck(kijunDate, kanjouCD, bumonCD))
                            {
                                //結果 False:エラー の場合　使用できない部門の為クリアする
                                //部門コード
                                SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD", "");
                                //部門名
                                SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonNameRyaku", "");
                                //部門名(隠し項目)
                                SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonName", "");
                                //部門コード改定日
                                SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "BumonKaiteiDate", null);
                            }
                        }
                        //  2014/02/27  変更   T.Shiraishi    (ID:9498)部門別科目制御対応 終了↑
                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag") == 1)
                    {
                        //総勘定エラーFlgが１の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00186", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }

                        //↓2011/12/05 追加 OBIC M.Shinbo (M04631)税区分・税込区分が0,0にも関わらず、消費税額が登録されてしまう件 開始
                        //消費税額
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku", null);
                        //合計額の計算
                        RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);
                        //↑2011/12/05 追加 OBIC M.Shinbo (M04631) 終了

                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //総勘定エラーFlgが０でチェック区分が2以外のときデータセット

                        //総勘定科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouName", ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KanjouName"]));
                        //科目区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKamokuCategory", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["KamokuCategory"]));
                        //科目分類をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKamokuKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["KamokuKBN"]));

                    }

                    //総勘定科目名がNULL または ""の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouName")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00187", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }

                        //↓2011/12/05 追加 OBIC M.Shinbo (M04631)税区分・税込区分が0,0にも関わらず、消費税額が登録されてしまう件 開始
                        //消費税額
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku", null);
                        //合計額の計算
                        RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);
                        //↑2011/12/05 追加 OBIC M.Shinbo (M04631) 終了

                        return KBN_CHECK_NG_CANCEL;
                    }

                    //科目分類 <> 0(財務基本科目) の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKamokuCategory") != 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00188", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }

                        //↓2011/12/05 追加 OBIC M.Shinbo (M04631)税区分・税込区分が0,0にも関わらず、消費税額が登録されてしまう件 開始
                        //消費税額
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku", null);
                        //合計額の計算
                        RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);
                        //↑2011/12/05 追加 OBIC M.Shinbo (M04631) 終了

                        return KBN_CHECK_NG_CANCEL;
                    }

                    //科目区分 <> 0(一般科目) の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKamokuKBN") != 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00189", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }

                        //↓2011/12/05 追加 OBIC M.Shinbo (M04631)税区分・税込区分が0,0にも関わらず、消費税額が登録されてしまう件 開始
                        //消費税額
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku", null);
                        //合計額の計算
                        RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);
                        //↑2011/12/05 追加 OBIC M.Shinbo (M04631) 終了

                        return KBN_CHECK_NG_CANCEL;

                    }

                    //借方税区分データ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //税区分マスタよりデータを取得
                        dtKariZeiKBNM = WinMToolSearchCom.M0000MS_MA_ZeiKBN.SelectByKey(null, ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KariZeiKBN"]), "");

                        if (dtKariZeiKBNM.Rows.Count == 0)
                        {
                            //総勘定科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag", 2);
                        }
                        else
                        {
                            //総勘定科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag", 0);
                        }
                    }

                    //総勘定科目ErrorFlg = 2の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag") == 2)
                    {

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "借方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00191", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //借方税区分開始日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiKaisiDate", ChangeDateTime(dtKariZeiKBNM.Rows[0]["ZeiKaisiDate"]));
                        //借方税区分廃止日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiHaisiDate", ChangeDateTime(dtKariZeiKBNM.Rows[0]["ZeiHaisiDate"]));
                    }

                    //借方税区分開始日 > 発生日の場合
                    //2012/10/05 K.Morita 変更 ST (M04851)平成26年消費税改正対応
                    //AllCheck時補助初期セット税区分を使用する場合は、補助チェックでエラーを出す

                    //if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value)
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value
                        && !(checkkbn == KBN_KOUMOKUCHK_ALL && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoZeiKBNSiyouFLG") == 1))
                    //2012/10/05 K.Morita 変更 ED (M04851)平成26年消費税改正対応
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "借方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00192", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //借方税区分廃止日 <> null
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiHaisiDate") != null)
                    {
                        //借方税区分廃止日 < 発生日の場合
                        //2012/10/05 K.Morita 変更 ST (M04851)平成26年消費税改正対応
                        //AllCheck時補助初期セット税区分を使用する場合は、補助チェックでエラーを出す

                        //if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value)
                        if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value
                            && !(checkkbn == KBN_KOUMOKUCHK_ALL && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoZeiKBNSiyouFLG") == 1))
                        //2012/10/05 K.Morita 変更 ED (M04851)平成26年消費税改正対応
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = "借方";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00193", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //貸方税区分データ----------------
                        //税区分マスタよりデータを取得
                        dtKasiZeiKBNM = WinMToolSearchCom.M0000MS_MA_ZeiKBN.SelectByKey(null, ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KasiZeiKBN"]), "");

                        if (dtKasiZeiKBNM.Rows.Count == 0)
                        {
                            //総勘定科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag", 3);
                        }
                        else
                        {
                            //総勘定科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag", 0);
                        }
                    }

                    //総勘定科目ErrorFlg = 3の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouCDErrorFlag") == 3)
                    {

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "貸方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00191", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //貸方税区分開始日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiKaisiDate", ChangeDateTime(dtKasiZeiKBNM.Rows[0]["ZeiKaisiDate"]));
                        //貸方税区分廃止日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiHaisiDate", ChangeDateTime(dtKasiZeiKBNM.Rows[0]["ZeiHaisiDate"]));
                    }

                    //貸方税区分開始日 > 発生日の場合
                    //2012/10/05 K.Morita 変更 ST (M04851)平成26年消費税改正対応
                    //AllCheck時補助初期セット税区分を使用する場合は、補助チェックでエラーを出す

                    //if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value)
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value
                        && !(checkkbn == KBN_KOUMOKUCHK_ALL && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoZeiKBNSiyouFLG") == 1))
                    //2012/10/05 K.Morita 変更 ED (M04851)平成26年消費税改正対応
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "貸方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00192", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //貸方税区分廃止日 <> null
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiHaisiDate") != null)
                    {
                        //貸方税区分廃止日 < 発生日の場合
                        //2012/10/05 K.Morita 変更 ST (M04851)平成26年消費税改正対応
                        //AllCheck時補助初期セット税区分を使用する場合は、補助チェックでエラーを出す

                        //if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value)
                        if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value
                            && !(checkkbn == KBN_KOUMOKUCHK_ALL && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoZeiKBNSiyouFLG") == 1))
                        //2012/10/05 K.Morita 変更 ED (M04851)平成26年消費税改正対応
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = "貸方";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00193", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {

                        //総勘定科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouNameRyaku", ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KanjouNameRyaku"]));

                        //総勘定科目改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "KanjouKaiteiDate", (DateTime?)dtKanjouM.Rows[0]["KaiteiDate"]);
                        //貸借区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TaishakuKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TaishakuKBN"]));
                        //取引先区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["TorihikisakiKBN"]));
                        //補助区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HojoKBN"]));
                        //部門区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BumonKBN"]));
                        //借方税区分セット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKBN", ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KariZeiKBN"]));
                        //貸方税区分セット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKBN", ComATool.Function.AnyToString(dtKanjouM.Rows[0]["KasiZeiKBN"]));

                        //分析チェック区分1セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN1"]));
                        //分析チェック区分2セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN2", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN2"]));
                        //分析チェック区分3セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN3", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN3"]));
                        //分析チェック区分4セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN4", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN4"]));
                        //分析チェック区分5セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN5", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN5"]));
                        //資金チェック区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouSikinCheckKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["SikinCheckKBN"]));
                        //プロジェクトチェック区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouProjectCheckKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["ProjectCheckKBN"]));

                        //科目リース会社区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiLeaseKaishaKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiLeaseKaishaKBN"]));
                        //科目税務署区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiZeimushoKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiZeimushoKBN"]));
                        //科目仕入先区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiiresakiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiSiiresakiKBN"]));
                        //科目支払先区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiharaisakiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiSiharaisakiKBN"]));
                        //科目得意先区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTokuisakiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiTokuisakiKBN"]));
                        //科目回収先区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiKaishuusakiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiKaishuusakiKBN"]));
                        //科目取引先区分1セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN1", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiTorihikisakiKBN1"]));
                        //科目取引先区分2セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN2", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiTorihikisakiKBN2"]));
                        //科目取引先区分3セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN3", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiTorihikisakiKBN3"]));
                        //科目取引先区分4セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN4", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["HasseiTorihikisakiKBN4"]));

                        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                        //メモボタンを使用可
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(rowNo, "obic7ButtonWithLogic" + taishakuName + "Memo").Enabled = true;
                        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        //借方のみ
                        if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                        {

                            //通常税率セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", ComATool.Function.AnyToDecimal(dtKariZeiKBNM.Rows[0]["ZeiRate"]));
                            //端数処理セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["HasuuKBN"]));
                            //消費税計算区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKeisanKBN"]));
                            //消費税科目区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //借方消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        //貸方のみ
                        if (taishakukbn == KBN_TAISHAKU_KASIKATA)
                        {
                            //通常税率セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", ComATool.Function.AnyToDecimal(dtKasiZeiKBNM.Rows[0]["ZeiRate"]));
                            //端数処理セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["HasuuKBN"]));
                            //消費税計算区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKeisanKBN"]));
                            //消費税科目区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //貸方消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        //税区分をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN", ComATool.Function.AnyToString(dtKanjouM.Rows[0][RenketuString(taishakuName, "ZeiKBN")]));
                        CheckZeiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                        //税込区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0][RenketuString(taishakuName, "ZeikomiKBN")]));
                        CheckZeikomiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                        // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                        //初期表示分析コードのセット
                        //初期表示分析コード1
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN1"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN1"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD1")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD1", defaultBunsekiCD1);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 1);
                        }
                        //初期表示分析コード2
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN2"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN2"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD2")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD2", defaultBunsekiCD2);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 2);
                        }
                        //初期表示分析コード3
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN3"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN3"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD3")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD3", defaultBunsekiCD3);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 3);
                        }
                        //初期表示分析コード4
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN4"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN4"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD4")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD4", defaultBunsekiCD4);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 4);
                        }
                        //初期表示分析コード5
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN5"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["BunsekiCheckKBN5"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD5")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD5", defaultBunsekiCD5);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 5);
                        }
                        //初期表示資金コード
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["SikinCheckKBN"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["SikinCheckKBN"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinCD")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinCD", defaultSikinCD);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 6);
                        }
                        //初期表示プロジェクトコード
                        if ((ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["ProjectCheckKBN"]) == 4 || ComATool.Function.AnyToInt32(dtKanjouM.Rows[0]["ProjectCheckKBN"]) == 5)
                            && string.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectCD")))
                        {
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectCD", defaultProjectCD);
                            CheckBunsekiCD(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE, 7);
                        }
                        // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                    }
                }

                return KBN_CHECK_OK;
            }
            finally
            {
                //マスタデータを破棄する。
                if (dtKanjouM != null)
                {
                    dtKanjouM.Dispose();
                }
                if (dtKariZeiKBNM != null)
                {
                    dtKariZeiKBNM.Dispose();
                }
                if (dtKasiZeiKBNM != null)
                {
                    dtKasiZeiKBNM.Dispose();
                }
            }
        }

        #endregion

        #region 補助科目コードのチェック

        /// <summary>
        /// 補助科目コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckHojoCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtHojoM = null;
            //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
            DataTable dtKanjouM = null;
            DataTable dtKariZeiKBNM = null;
            DataTable dtKasiZeiKBNM = null;
            //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //補助科目コードカラム番号
            int hojoColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                hojoColumnNo = COL_KARIHOJOCD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                hojoColumnNo = COL_KASIHOJOCD;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, hojoColumnNo).IsChangedText;
                }

                if ((isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT))
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //補助科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoNameRyaku", "");

                        if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                        {
                            //補助内訳科目コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCD", "");
                            //補助内訳科目名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeNameRyaku", "");
                        }
                        //隠し項目のクリア
                        //補助科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoName", "");
                        //補助科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HojoKaiteiDate", null);
                        //補助内訳区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKBN", null);

                        if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                        {
                            //補助内訳科目名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeName", "");
                            //補助内訳コード改定日
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKaiteiDate", null);
                        }
                        //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
                        //補助科目初期セット税区分使用フラグ
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoZeiKBNSiyouFLG", null);
                        //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応

                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoCD")) == true)
                    {
                        //処理なし
                        return KBN_CHECK_OK;
                    }

                    //*以外の記号入力のチェック
                    if (WinMTool.InputCheck.CheckedForSymbol(GetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoCD")) == false)
                    {
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //総勘定科目コードが未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00194", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            //総勘定科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
