                        }
                    }
                    //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //補助科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoNameRyaku", ComATool.Function.AnyToString(dtHojoM.Rows[0]["HojoNameRyaku"]));
                        //補助科目改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HojoKaiteiDate", ChangeDateTime(dtHojoM.Rows[0]["KaiteiDate"]));
                        //補助内訳区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKBN", ComATool.Function.AnyToInt32(dtHojoM.Rows[0]["UtiwakeKBN"]));

                    }

                    //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        //借方のみ
                        if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                        {

                            //通常税率セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", ComATool.Function.AnyToDecimal(dtKariZeiKBNM.Rows[0]["ZeiRate"]));
                            //端数処理セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["HasuuKBN"]));
                            //消費税計算区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKeisanKBN"]));
                            //消費税科目区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //借方消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        //貸方のみ
                        if (taishakukbn == KBN_TAISHAKU_KASIKATA)
                        {
                            //通常税率セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", ComATool.Function.AnyToDecimal(dtKasiZeiKBNM.Rows[0]["ZeiRate"]));
                            //端数処理セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["HasuuKBN"]));
                            //消費税計算区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKeisanKBN"]));
                            //消費税科目区分セット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //貸方消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        if (!string.IsNullOrEmpty(ComATool.Function.AnyToString(dtHojoM.Rows[0]["ShokiSetKariZeiKBN"])))
                        {
                            //税区分をセット
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN", ComATool.Function.AnyToString(dtHojoM.Rows[0][RenketuString("ShokiSet", taishakuName, "ZeiKBN")]));
                            CheckZeiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                            //税込区分をセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", ComATool.Function.AnyToInt32(dtHojoM.Rows[0][RenketuString("ShokiSet", taishakuName, "ZeikomiKBN")]));
                            CheckZeikomiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                        }
                        else
                        {
                            //税区分をセット
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN", ComATool.Function.AnyToString(dtKanjouM.Rows[0][RenketuString(taishakuName, "ZeiKBN")]));
                            CheckZeiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                            //税込区分をセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", ComATool.Function.AnyToInt32(dtKanjouM.Rows[0][RenketuString(taishakuName, "ZeikomiKBN")]));
                            CheckZeikomiKBN(rowNo, taishakukbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                        }
                    }
                    //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応
                }

                return KBN_CHECK_OK;
            }
            finally
            {
                if (dtHojoM != null)
                {
                    //マスタデータを破棄する。
                    dtHojoM.Dispose();
                }
                //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
                if (dtKanjouM != null)
                {
                    dtKanjouM.Dispose();
                }
                if (dtKariZeiKBNM != null)
                {
                    dtKariZeiKBNM.Dispose();
                }
                if (dtKasiZeiKBNM != null)
                {
                    dtKasiZeiKBNM.Dispose();
                }
                //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応
            }
        }

        #endregion

        #region 補助内訳科目コードのチェック

        /// <summary>
        /// 補助内訳科目コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckUtiwakeCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtUtiwakeM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //補助内訳科目コードカラム番号
            int UtiwakeColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                UtiwakeColumnNo = COL_KARIUTIWAKECD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                UtiwakeColumnNo = COL_KASIUTIWAKECD;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, UtiwakeColumnNo).IsChangedText;
                }

                if ((isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT))
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //補助内訳科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeNameRyaku", "");

                        //隠し項目のクリア
                        //補助内訳科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeName", "");
                        //補助内訳コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKaiteiDate", null);

                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCD")) == true)
                    {
                        //処理なし
                        return KBN_CHECK_OK;
                    }

                    //*以外の記号のチェック
                    if (WinMTool.InputCheck.CheckedForSymbol(GetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCD")) == false)
                    {
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //総勘定科目コードが未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00194", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            //総勘定科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIKANJOUCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIKANJOUCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }

                    //補助コードが未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoCD")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00198", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                            //補助科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIHOJOCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIHOJOCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }


                    //補助内訳区分が0の時
                    if (ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKBN")) == 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00199", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                            //補助科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIHOJOCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIHOJOCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }

                    //補助内訳科目マスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //マスタよりデータを取得
                        dtUtiwakeM = WinMToolSearchCom.M0000MS_MA_Utiwake.SelectByKaiteiDate(
                            GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")
                            , GetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoCD")
                            , GetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCD")
                            , (DateTime)obic7TextDatetimeHasseiDate.Value
                            , 0
                            , 0
                            , ""
                            );

                        if (dtUtiwakeM.Rows.Count == 0)
                        {
                            //補助内訳科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCDErrorFlag", 1);
                        }
                        else
                        {
                            //補助内訳科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCDErrorFlag", 0);
                        }
                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCDErrorFlag") == 1)
                    {
                        //補助内訳科目エラーFlgが１の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00200", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //補助内訳科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeName", ComATool.Function.AnyToString(dtUtiwakeM.Rows[0]["UtiwakeName"]));
                    }

                    //補助内訳科目名がNULL または ""の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeName")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00201", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //補助内訳科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeNameRyaku", ComATool.Function.AnyToString(dtUtiwakeM.Rows[0]["UtiwakeNameRyaku"]));
                        //補助内訳科目改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKaiteiDate", (DateTime)dtUtiwakeM.Rows[0]["KaiteiDate"]);
                    }



                }

                return KBN_CHECK_OK;
            }
            finally
            {
                if (dtUtiwakeM != null)
                {
                    //マスタデータを破棄する。
                    dtUtiwakeM.Dispose();
                }
            }
        }

        #endregion

        #region 取引先コードのチェック

        /// <summary>
        /// 取引先コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckTorihikisakiCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtTorihikisakiM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //取引先コードカラム番号
            int torihikisakiColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                torihikisakiColumnNo = COL_KARITORIHIKISAKICD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                torihikisakiColumnNo = COL_KASITORIHIKISAKICD;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, torihikisakiColumnNo).IsChangedText;
                }

                if ((isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT))
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //取引先名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiShanaiName", "");

                        //隠し項目のクリア
                        //取引先コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKaiteiDate", null);
                        //取引先リース会社区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiLeaseKaishaKBN", null);
                        //取引先税務署区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiZeimushoKBN", null);
                        //取引先仕入先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiiresakiKBN", null);
                        //取引先支払先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiharaisakiKBN", null);
                        //取引先得意先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTokuisakiKBN", null);
                        //取引先回収先区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiKaishuusakiKBN", null);
                        //取引先取引先区分1
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN1", null);
                        //取引先取引先区分2
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN2", null);
                        //取引先取引先区分3
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN3", null);
                        //取引先取引先区分4
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN4", null);

                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCD")) == true)
                    {
                        //処理なし
                        return KBN_CHECK_OK;
                    }

                    //*以外の記号入力のチェック
                    if (WinMTool.InputCheck.CheckedForSymbol(GetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCD")) == false)
                    {
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //総勘定科目コードが未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00194", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                            //総勘定科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIKANJOUCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIKANJOUCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }

                    //取引先区分が0の時
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKBN") == 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00208", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            //総勘定科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIKANJOUCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIKANJOUCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }

                    //取引先マスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //マスタよりデータを取得
                        dtTorihikisakiM = WinPToolSearchCom.P0000MS_Torihikisaki.SelectByKaiteiDate(
                            GetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCD")
                            , (DateTime)obic7TextDatetimeHasseiDate.Value
                            , 0
                            , ""
                            );

                        if (dtTorihikisakiM.Rows.Count == 0)
                        {
                            //取引先エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCDErrorFlag", 1);
                        }
                        else
                        {
                            //取引先エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCDErrorFlag", 0);
                        }

                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCDErrorFlag") == 1)
                    {
                        //取引先エラーFlgが１の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00209", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //取引先リース会社区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiLeaseKaishaKBN", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["LeaseKaishaKBN"]));
                        //取引先税務署区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiZeimushoKBN", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["ZeimushoKBN"]));
                        //取引先仕入先区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiiresakiKBN", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiSiiresakiKBN"]));
                        //取引先支払先区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiharaisakiKBN", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiSiharaisakiKBN"]));
                        //取引先得意先区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTokuisakiKBN", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiTokuisakiKBN"]));
                        //取引先回収先区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiKaishuusakiKBN", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiKaishuusakiKBN"]));
                        //取引先取引先区分1をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN1", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiTorihikisakiKBN1"]));
                        //取引先取引先区分2をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN2", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiTorihikisakiKBN2"]));
                        //取引先取引先区分3をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN3", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiTorihikisakiKBN3"]));
                        //取引先取引先区分4をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN4", ComATool.Function.AnyToInt32(dtTorihikisakiM.Rows[0]["HasseiTorihikisakiKBN4"]));
                    }

                    //取引先パターンチェック <> 0 の場合
                    if (torihikisakiCheckKBN != 0)
                    {
                        if (torihikisakiCheckKBN == 2
                            &&
                            !((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiLeaseKaishaKBN") == 1
                                   && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiLeaseKaishaKBN") == 1
                                )
                                ||
                                 (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiZeimushoKBN") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiZeimushoKBN") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiiresakiKBN") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiiresakiKBN") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiharaisakiKBN") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiharaisakiKBN") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTokuisakiKBN") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTokuisakiKBN") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiKaishuusakiKBN") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiKaishuusakiKBN") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN1") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN1") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN2") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN2") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN3") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN3") == 1
                                )
                                ||
                                (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN4") == 1
                                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN4") == 1
                                )
                            )
                        )
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00211", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //取引先名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiShanaiName", ComATool.Function.AnyToString(dtTorihikisakiM.Rows[0]["TorihikisakiShanaiName"]));
                        //取引先改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKaiteiDate", ChangeDateTime(dtTorihikisakiM.Rows[0]["TorihikisakiKaiteiDate"]));
                    }

                }

                return KBN_CHECK_OK;
            }
            finally
            {
                if (dtTorihikisakiM != null)
                {
                    //マスタデータを破棄する。
                    dtTorihikisakiM.Dispose();
                }
            }
        }

        #endregion

        #region 事業所コードのチェック

        /// <summary>
        /// 事業所コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckMeisaiZigyoushoCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtZigyoushoM = null;
            DataTable dtHonSitenM = null;
            DataTable dtHonshaZigyoushoM = null;


            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //事業所コードカラム番号
            int ZigyoushoColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                ZigyoushoColumnNo = COL_KARIZIGYOUSHOCD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                ZigyoushoColumnNo = COL_KASIZIGYOUSHOCD;
            }

            //セキュリティパターン
            string securityPattern = "";

            //セキュリティパターンを設定
            if (honsitenSecurityFlag == 0)
            {
                //事業所セキュリティパターンコード
                securityPattern = zigyoushoSecurityPatternCD;
            }
            else
            {
                securityPattern = "";
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, ZigyoushoColumnNo).IsChangedText;
                }

                //検索戻り後でないか直接入力で値変化があるか、直接入力以外の場合
                if (isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT)
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //事業所名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoNameRyaku", "");

                        //隠し項目のクリア
                        //事業所名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoName", "");
                        //事業所コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoKaiteiDate", null);
                        //事業所セット残高日付
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoSetZandakaDate", null);
                        //事業所伝票締日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoDenpyouSimeDate", null);
                        //本社事業所コード
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD", "");
                        //本社事業所名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoName", "");
                        //本社事業所セット残高日付
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoSetZandakaDate", null);

                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")) == true)
                    {
                        //事業所部門パターンチェック区分 <> 0 で部門が既に入力済みの場合,事業所部門パターンチェック
                        if (zigyoushoBumonCheckKBN != 0 && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")) == false)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ALL)
                            {
                                //マスタよりデータを取得
                                using (DataTable dtZigBumonM = WinMToolSearchCom.M0000MS_MA_Bumon.SelectByKaiteiDate(
                                    GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")
                                    , (DateTime)obic7TextDatetimeHasseiDate.Value
                                    , bumonSecurityPatternCD
                                    , 0
                                    , 0
                                    , obic7TextStringZigyoushoCD.Value
                                    , 0
                                    , ""
                                    )
                                )
                                {
                                    if (dtZigBumonM.Rows.Count == 0)
                                    {
                                        //部門エラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 2);
                                    }
                                    else
                                    {
                                        //部門エラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 0);
                                    }
                                }
                            }
                        }

                        return KBN_CHECK_OK;
                    }

                    //事業所マスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //マスタよりデータを取得
                        dtZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(
                            GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")
                            , (DateTime)obic7TextDatetimeHasseiDate.Value
                            , securityPattern
                            , 0
                            , 0
                            , 0
                            , ""
                            );

                        if (dtZigyoushoM.Rows.Count == 0)
                        {
                            //事業所エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag", 1);
                        }
                        else
                        {
                            //事業所エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag", 0);
                        }
                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag") == 1)
                    {
                        //事業所エラーFlgが１の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00449", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //事業所名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoName", ComATool.Function.AnyToString(dtZigyoushoM.Rows[0]["ZigyoushoName"]));
                        //セット残高日付をセット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoSetZandakaDate", ChangeDateTime(dtZigyoushoM.Rows[0]["SetZandakaDate"]));
                    }

                    //事業所名がNULL または ""の場合
                    if (obic7ComboBoxMode.Text == MODE_INSERT
                        || ((obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE) && checkkbn == KBN_KOUMOKUCHK_ALL)
                        )
                    {
                        if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoName")) == true)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00450", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //本支店勘定科目マスタクラスより取得
                        dtHonSitenM = WinMToolSearchCom.M0000MS_MA_HonsitenKanjou.SelectByKaiteiDate(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD"), (DateTime)obic7TextDatetimeHasseiDate.Value, securityPattern, honshaZigyoushoSecurityFlag, "");
                        if (dtHonSitenM == null || dtHonSitenM.Rows.Count == 0)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;

                            //エラー表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00445", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            return KBN_CHECK_NG_CANCEL;
                        }

                        if (dtHonSitenM.Rows.Count == 0)
                        {
                            //事業所エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag", 2);
                        }
                        else
                        {
                            //事業所エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag", 0);
                        }
                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag") == 2)
                    {
                        //事業所エラーFlgが２の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00445", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //本社事業所コードをセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD", ComATool.Function.AnyToString(dtHonSitenM.Rows[0]["HonshaZigyoushoCD"]));
                    }


                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoSetZandakaDate") != null)
                    {
                        //セット残高日付チェック
                        if (obic7TextDatetimeHasseiDate.Value <= GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoSetZandakaDate"))
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoSetZandakaDate")), "yyyy/MM/dd", false);
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00452", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    //本支店集中制度適用フラグ = 1 かつ 借方事業所コード <> 本社事業所コードの場合
                    if (hontenShuutyuuFlag == 1 && GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD") != GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD"))
                    {

                        //事業所マスタデータ（本社事業所データ）----------------
                        if (checkkbn != KBN_KOUMOKUCHK_ALL)
                        {
                            //マスタよりデータを取得
                            dtHonshaZigyoushoM = WinMToolSearchCom.M0000MS_MA_Zigyousho.SelectByKaiteiDate(
                                GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD")
                                , (DateTime)obic7TextDatetimeHasseiDate.Value
                                //2008/05/14 追加 N.Sasaki 開始 本社事業所チェックはセキュリティを考慮しない
                                //                                , zigyoushoSecurityPatternCD
                                , ""
                                //2008/05/14 追加 N.Sasaki 終了
                                , 0
                                , 0
                                , 0
                                , ""
                                );

                            if (dtHonshaZigyoushoM.Rows.Count == 0)
                            {
                                //事業所エラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag", 3);
                            }
                            else
                            {
                                //事業所エラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag", 0);
                            }
                        }

                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCDErrorFlag") == 3)
                        {
                            //事業所エラーFlgが3の時はエラー

                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00453", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }

                        if (checkkbn != KBN_KOUMOKUCHK_ALL)
                        {
                            //本社事業所名をセット
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoName", ComATool.Function.AnyToString(dtHonshaZigyoushoM.Rows[0]["ZigyoushoName"]));
                            //本社セット残高日付をセット
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoSetZandakaDate", ChangeDateTime(dtHonshaZigyoushoM.Rows[0]["SetZandakaDate"]));
                        }


                        //本社事業所名がNULL または ""の場合
                        if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoName")) == true)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00454", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }

                        //本社事業所セット残高日付チェック
                        if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoSetZandakaDate") == null)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00455", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }

                        //本社事業所セット残高日付チェック
                        if (obic7TextDatetimeHasseiDate.Value <= GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoSetZandakaDate"))
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoSetZandakaDate")), "yyyy/MM/dd", false);
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00456", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //事業所名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoNameRyaku", ComATool.Function.AnyToString(dtZigyoushoM.Rows[0]["ZigyoushoNameRyaku"]));
                        //事業所改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoKaiteiDate", (DateTime)dtZigyoushoM.Rows[0]["KaiteiDate"]);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoDenpyouSimeDate", null);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        ////事業所伝票締日をセット
                        //SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoDenpyouSimeDate", ChangeDateTime(dtZigyoushoM.Rows[0]["DenpyouSimeDate"]));
                        //if (hontenShuutyuuFlag == 1 && GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD") != GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD"))
                        //{
                        //    //本社事業所伝票締日をセット
                        //    SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoDenpyouSimeDate", ChangeDateTime(dtHonshaZigyoushoM.Rows[0]["DenpyouSimeDate"]));
                        //}
                        //締管理区分＝０：事業所単位の場合
                        if (this.simeKanriKbn == 0)
                        {
                            //事業所伝票締日をセット
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoDenpyouSimeDate", ChangeDateTime(dtZigyoushoM.Rows[0]["DenpyouSimeDate"]));
                            if (hontenShuutyuuFlag == 1 && GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD") != GetStringColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoCD"))
                            {
                                //本社事業所伝票締日をセット
                                SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "HonshaZigyoushoDenpyouSimeDate", ChangeDateTime(dtHonshaZigyoushoM.Rows[0]["DenpyouSimeDate"]));
                            }
                        }
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    }

                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //事業所単位ではない場合、基準締管理マスタから取得
                    if (this.simeKanriKbn != 0)
                    {
                        this.SetMeisaiDenpyouSimeDate(rowNo, taishakukbn, checkkbn);
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑


                    //事業所部門パターンチェック区分 <> 0 で部門が既に入力済みの場合,事業所部門パターンチェック
                    if (zigyoushoBumonCheckKBN != 0 && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")) == false)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ALL)
                        {
                            //マスタよりデータを取得
                            using (DataTable dtZigBumonM = WinMToolSearchCom.M0000MS_MA_Bumon.SelectByKaiteiDate(
                                GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")
                                , (DateTime)obic7TextDatetimeHasseiDate.Value
                                , bumonSecurityPatternCD
                                , 0
                                , 0
                                , GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")
                                , 0
                                , ""
                                )
                            )
                            {
                                if (dtZigBumonM.Rows.Count == 0)
                                {
                                    //部門エラーFlgをセット
                                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 2);
                                }
                                else
                                {
                                    //部門エラーFlgをセット
                                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 0);
                                }
                            }
                        }
                    }
                }

                return KBN_CHECK_OK;

            }
            finally
            {
                //マスタデータを破棄する。
                if (dtZigyoushoM != null)
                {
                    dtZigyoushoM.Dispose();
                }
                if (dtHonSitenM != null)
                {
                    dtHonSitenM.Dispose();
                }
                if (dtHonshaZigyoushoM != null)
                {
                    dtHonshaZigyoushoM.Dispose();
                }
            }
        }


        #endregion

        #region 部門コードのチェック

        /// <summary>
        /// 部門コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckBumonCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtBumonM = null;
            DataTable dtZigBumonM = null;


            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //部門コードカラム番号
            int BumonColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                BumonColumnNo = COL_KARIBUMONCD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                BumonColumnNo = COL_KASIBUMONCD;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, BumonColumnNo).IsChangedText;
                }

                //検索戻り後でないか直接入力で値変化があるか、直接入力以外の場合
                if ((isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT))
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //部門名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonNameRyaku", "");

                        //隠し項目のクリア
                        //部門名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonName", "");
                        //部門コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "BumonKaiteiDate", null);

                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")) == true)
                    {
                        //処理なし
                        return KBN_CHECK_OK;
                    }

                    //*以外の記号のチェック
                    if (WinMTool.InputCheck.CheckedForSymbol(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")) == false)
                    {
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //総勘定科目コードが未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00194", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                            //総勘定科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIKANJOUCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIKANJOUCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }

                    //部門区分が0の時
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonKBN") == 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00202", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            //総勘定科目コードにフォーカスセット
                            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KARIKANJOUCD);
                            }
                            else
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, COL_KASIKANJOUCD);
                            }
                        }
                        return KBN_CHECK_NG_FOCUS;
                    }

                    //部門マスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //マスタよりデータを取得
                        dtBumonM = WinMToolSearchCom.M0000MS_MA_Bumon.SelectByKaiteiDate(
                            GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")
                            , (DateTime)obic7TextDatetimeHasseiDate.Value
                            , bumonSecurityPatternCD
                            , 0
                            , 0
                            , ""
                            , 0
                            , ""
                            );

                        if (dtBumonM.Rows.Count == 0)
                        {
                            //部門エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 1);
                        }
                        else
                        {
                            //部門エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 0);
                        }
                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag") == 1)
                    {
                        //部門エラーFlgが１の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00203", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //部門名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonName", ComATool.Function.AnyToString(dtBumonM.Rows[0]["BumonName"]));
                    }

                    //部門名がNULL または ""の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonName")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00204", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //事業所部門パターンチェック区分 = 2 の場合
                    if (zigyoushoBumonCheckKBN == 2)
                    {
                        //事業所部門パターンチェック用事業所
                        string taishoZigyoushoCD = "";

                        if (checkkbn != KBN_KOUMOKUCHK_ALL)
                        {
                            //事業所部門パターンチェック用事業所取得
                            if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")) == true)
                            {
                                taishoZigyoushoCD = obic7TextStringZigyoushoCD.Value;
                            }
                            else
                            {
                                taishoZigyoushoCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD");
                            }

                            //マスタよりデータを取得
                            dtZigBumonM = WinMToolSearchCom.M0000MS_MA_Bumon.SelectByZigBmn(
                                GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")
                                , (DateTime)obic7TextDatetimeHasseiDate.Value
                                , bumonSecurityPatternCD
                                , 0
                                , 0
                                , taishoZigyoushoCD
                                , 0
                                , ""
                                );

                            if (dtZigBumonM.Rows.Count == 0)
                            {
                                //部門エラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 2);
                            }
                            else
                            {
                                //部門エラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 0);
                            }
                        }

                        //部門ErrorFlg = 2 の場合
                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag") == 2)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00206", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    //  2014/02/27  変更   T.Shiraishi    (ID:9498)部門別科目制御対応 開始↓
                    //会計共通コントロールM.[部門科目種別パターンチェック区分] = [2](入力不可)の場合
                    if (this.bumonKamokuShubetuPatternCheckKBN == 2)
                    {

                        DateTime kijunDate = (DateTime)this.obic7TextDatetimeHasseiDate.Value;
                        string kanjouCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD");
                        string bumonCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD");
                        if (!WinMTool.M0000MS_MA_BumonKamokuShubetuPatternCheck.BumonKamokuShubetuPatternCheck(kijunDate, kanjouCD, bumonCD))
                        {
                            //部門エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 3);
                        }
                        else
                        {
                            //部門エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag", 0);
                        }

                        //部門ErrorFlg = 3 の場合
                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonCDErrorFlag") == 3)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30058", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }
                    //  2014/02/27  変更   T.Shiraishi    (ID:9498)部門別科目制御対応 終了↑

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //部門名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonNameRyaku", ComATool.Function.AnyToString(dtBumonM.Rows[0]["BumonNameRyaku"]));
                        //部門改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "BumonKaiteiDate", (DateTime)dtBumonM.Rows[0]["KaiteiDate"]);
                    }
                }

                return KBN_CHECK_OK;

            }
            finally
            {
                //マスタデータを破棄する。
                if (dtBumonM != null)
                {
                    dtBumonM.Dispose();
                }
                if (dtZigBumonM != null)
                {
                    dtZigBumonM.Dispose();
                }
            }
        }


        #endregion

        #region 消費税本体科目コードのチェック

        /// <summary>
        /// 消費税本体科目コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckZeiHontaiCD(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtZeiHontaiM = null;
            DataTable dtKariZeiKBNM = null;
            DataTable dtKasiZeiKBNM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //消費税本体科目コードカラム番号
            int ZeiHontaiColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                ZeiHontaiColumnNo = COL_KARIZEIHONTAICD;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                ZeiHontaiColumnNo = COL_KASIZEIHONTAICD;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, ZeiHontaiColumnNo).IsChangedText;
                }

                //値変化がある時
                if (isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT)
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //項目のクリア
                        //消費税本体科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiNameRyaku", "");
                        //隠し項目のクリア
                        //消費税本体科目名
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiName", "");
                        //消費税本体科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKaiteiDate", null);
                        //消費税本体科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKamokuCategory", null);
                        //消費税本体科目分類
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKamokuKBN", null);
                        //消費税本体科目借方税区分
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBN", "");
                        //消費税本体科目貸方税区分
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBN", "");
                        //消費税本体科目借方税区分開始日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiKaisiDate", null);
                        //消費税本体科目借方税区分廃止日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiHaisiDate", null);
                        //消費税本体科目貸方税区分開始日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiKaisiDate", null);
                        //消費税本体科目貸方税区分廃止日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiHaisiDate", null);
                        //消費税本体科目借方消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKamokuKBN", null);
                        //消費税本体科目貸方消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKamokuKBN", null);

                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCD")) == true)
                    {
                        //処理なし
                        return KBN_CHECK_OK;
                    }
                    int zeikomikbn = ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN"));

                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                    ////総勘定科目コードが仮払,仮受消費税コードではないかもしくは、税区分が0の場合
                    //if ((GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") != kariBaraiZeiKamokuCD && GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") != kariUkeZeiKamokuCD) || zeikomikbn == 0)
                    if ((GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") != kariBaraiZeiKamokuCD
                        && GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") != kariUkeZeiKamokuCD
                        && GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") != rcHaraiCD) || zeikomikbn == 0)
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00219", obj, obj, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //総勘定科目マスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                        DenpyouKBN = "";
                        if (!string.IsNullOrEmpty(obic7TextStringDenpyouKBN.Value))
                        {
                            DenpyouKBN = obic7TextStringDenpyouKBN.Value;
                        }
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                        //マスタよりデータを取得
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                        //dtZeiHontaiM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCD"), (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, "");
                        dtZeiHontaiM = WinMToolSearchCom.M0000MS_MA_Kanjou.SelectByKaiteiDate(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCD"), (DateTime)obic7TextDatetimeHasseiDate.Value, 0, 0, 0, 0, 0, 0, kanjouSecurityPatternCD, 0, 0, "", DenpyouKBN);
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                        if (dtZeiHontaiM.Rows.Count == 0)
                        {
                            //消費税本体科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag", 1);
                        }
                        else
                        {
                            //消費税本体科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag", 0);
                        }
                    }

                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag") == 1)
                    {
                        //消費税本体科目エラーFlgが１の時はエラー

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00220", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //消費税本体科目エラーFlgが０でチェック区分が2以外のときデータセット

                        //消費税本体科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiName", ComATool.Function.AnyToString(dtZeiHontaiM.Rows[0]["KanjouName"]));
                        //消費税本体科目区分をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKamokuCategory", ComATool.Function.AnyToInt32(dtZeiHontaiM.Rows[0]["KamokuCategory"]));
                        //消費税本体科目分類をセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKamokuKBN", ComATool.Function.AnyToInt32(dtZeiHontaiM.Rows[0]["KamokuKBN"]));

                    }

                    //消費税本体科目名がNULL または ""の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiName")) == true)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00221", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //消費税本体科目分類 <> 0(財務基本科目) の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKamokuCategory") != 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00222", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //消費税本体科目区分 <> 0(一般科目) の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKamokuKBN") != 0)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00223", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;

                    }

                    //借方税区分データ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //税区分マスタよりデータを取得
                        dtKariZeiKBNM = WinMToolSearchCom.M0000MS_MA_ZeiKBN.SelectByKey(null, ComATool.Function.AnyToString(dtZeiHontaiM.Rows[0]["KariZeiKBN"]), "");

                        if (dtKariZeiKBNM.Rows.Count == 0)
                        {
                            //消費税本体科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag", 2);
                        }
                        else
                        {
                            //消費税本体科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag", 0);
                        }
                    }

                    //消費税本体科目ErrorFlg = 2の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag") == 2)
                    {

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "借方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00225", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //消費税本体科目借方税区分開始日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiKaisiDate", ChangeDateTime(dtKariZeiKBNM.Rows[0]["ZeiKaisiDate"]));
                        //消費税本体科目借方税区分廃止日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiHaisiDate", ChangeDateTime(dtKariZeiKBNM.Rows[0]["ZeiHaisiDate"]));
                    }

                    //消費税本体科目借方税区分開始日 > 発生日の場合
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "借方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00226", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //消費税本体科目借方税区分廃止日 <> null
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiHaisiDate") != null)
                    {
                        //消費税本体科目借方税区分廃止日 < 発生日の場合
                        if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = "借方";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00227", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //消費税本体科目借方消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKariZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    //貸方税区分データ----------------
                    if (checkkbn != 2)
                    {
                        //税区分マスタよりデータを取得
                        dtKasiZeiKBNM = WinMToolSearchCom.M0000MS_MA_ZeiKBN.SelectByKey(null, ComATool.Function.AnyToString(dtZeiHontaiM.Rows[0]["KasiZeiKBN"]), "");

                        if (dtKasiZeiKBNM.Rows.Count == 0)
                        {
                            //消費税本体科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag", 3);
                        }
                        else
                        {
                            //消費税本体科目エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag", 0);
                        }
                    }

                    //消費税本体科目ErrorFlg = 3の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCDErrorFlag") == 3)
                    {

                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "貸方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00225", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //消費税本体科目貸方税区分開始日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiKaisiDate", ChangeDateTime(dtKasiZeiKBNM.Rows[0]["ZeiKaisiDate"]));
                        //消費税本体科目貸方税区分廃止日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiHaisiDate", ChangeDateTime(dtKasiZeiKBNM.Rows[0]["ZeiHaisiDate"]));
                    }

                    //消費税本体科目貸方税区分開始日 > 発生日の場合
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = "貸方";
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00226", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //消費税本体科目貸方税区分廃止日 <> null
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiHaisiDate") != null)
                    {
                        //消費税本体科目貸方税区分廃止日 < 発生日の場合
                        if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = "貸方";
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00227", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //消費税本体科目貸方消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKamokuKBN", ComATool.Function.AnyToInt32(dtKasiZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    //税区分の整合性チェックを行う
                    int zeiKBNError = WinMTool.MA_Common.CheckZeiKBN(
                          taishakukbn - 1
                        , zeiKBNNyuuryokuFlag
                        , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN"))
                        , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKamokuKBN"))
                        , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKamokuKBN"))
                        );

                    //税区分整合性エラーが１の場合
                    if (zeiKBNError == 1)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = taishakuJpnName;

                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00228", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //チェック区分が2以外のときデータセット
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //消費税本体科目名をセット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiNameRyaku", ComATool.Function.AnyToString(dtZeiHontaiM.Rows[0]["KanjouNameRyaku"]));
                        //消費税本体科目改定日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKaiteiDate", ChangeDateTime(dtZeiHontaiM.Rows[0]["KaiteiDate"]));
                        //消費税本体科目借方税区分セット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKariZeiKBN", ComATool.Function.AnyToString(dtZeiHontaiM.Rows[0]["KariZeiKBN"]));
                        //消費税本体科目貸方税区分セット
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiKasiZeiKBN", ComATool.Function.AnyToString(dtZeiHontaiM.Rows[0]["KasiZeiKBN"]));

                    }
                }

                return KBN_CHECK_OK;

            }
            finally
            {
                //マスタデータを破棄する。
                if (dtZeiHontaiM != null)
                {
                    dtZeiHontaiM.Dispose();
                }
                if (dtKariZeiKBNM != null)
                {
                    dtKariZeiKBNM.Dispose();
                }
                if (dtKasiZeiKBNM != null)
                {
                    dtKasiZeiKBNM.Dispose();
                }
            }

        }

        #endregion

        #region 税区分のチェック

        /// <summary>
        /// 税区分のチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時</param>
        /// <returns></returns>
        private int CheckZeiKBN(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtZeiKBNM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //税区分カラム番号
            int zeiKBNColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                zeiKBNColumnNo = COL_KARIZEIKBN;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                zeiKBNColumnNo = COL_KASIZEIKBN;
            }

            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, zeiKBNColumnNo).IsChangedText;
                }

                //値変化がある時
                if (isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT)
                {
                    //未入力の時
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN")) == true)
                    {
                        //"０"をセットする
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN", "0");
                    }

                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //隠し項目のクリア

                        //通常税率
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", null);
                        //端数処理
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", null);
                        //消費税計算区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", null);
                        //消費税科目区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", null);
                        //税区分開始日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiKaisiDate", null);
                        //税区分廃止日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiHaisiDate", null);
                        //消費税科目コード
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuCD", "");
                        //消費税科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKaiteiDate", null);
                        //消費税科目貸借区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiTaishakuKBN", null);

                    }

                    //税区分データ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //税区分マスタよりデータを取得
                        dtZeiKBNM = WinMToolSearchCom.M0000MS_MA_ZeiKBN.SelectByKey(
                            null
                            , GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN")
                            , "");

                        if (dtZeiKBNM.Rows.Count == 0)
                        {
                            //税区分エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNErrorFlag", 1);
                        }
                        else
                        {
                            //税区分エラーFlgをセット
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNErrorFlag", 0);
                        }
                    }

                    //税区分ErrorFlg = 1の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNErrorFlag") == 1)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {

                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00212", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //税区分開始日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiKaisiDate", ChangeDateTime(dtZeiKBNM.Rows[0]["ZeiKaisiDate"]));
                        //税区分廃止日セット
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiHaisiDate", ChangeDateTime(dtZeiKBNM.Rows[0]["ZeiHaisiDate"]));
                        //消費税科目区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN", ComATool.Function.AnyToInt32(dtZeiKBNM.Rows[0]["ZeiKamokuKBN"]));
                    }

                    //税区分開始日 > 発生日の場合
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiKaisiDate") > obic7TextDatetimeHasseiDate.Value)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00213", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    //税区分廃止日 <> null
                    if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiHaisiDate") != null)
                    {
                        //税区分廃止日 < 発生日の場合
                        if (GetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBNZeiHaisiDate") < obic7TextDatetimeHasseiDate.Value)
                        {
                            if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00214", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }

                    //税区分の整合性チェックを行う
                    int zeiKBNError = WinMTool.MA_Common.CheckZeiKBN(
                          taishakukbn - 1
                        , zeiKBNNyuuryokuFlag
                        , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN"))
                        , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKariZeiKamokuKBN"))
                        , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouKasiZeiKamokuKBN"))
                        );

                    //税区分整合性エラーが１の場合
                    if (zeiKBNError == 1)
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            //↓2012/11/09 変更 M.Kobayashi (M04851)平成26年消費税改正対応(税区分整合性チェックメッセージを修正)
                            //補助科目に初期セット税区分が設定されている場合
                            if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoZeiKBNSiyouFLG") == 1)
                            {
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01430", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            else
                            {
                                //↑2012/11/09 変更 M.Kobayashi (M04851)平成26年消費税改正対応(税区分整合性チェックメッセージを修正)
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00215", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                //↓2012/11/09 変更 M.Kobayashi (M04851)平成26年消費税改正対応(税区分整合性チェックメッセージを修正)
                            }
                            //↑2012/11/09 変更 M.Kobayashi (M04851)平成26年消費税改正対応(税区分整合性チェックメッセージを修正)
                        }
                        return KBN_CHECK_NG_CANCEL;
                    }

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //通常税率セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiRate", ComATool.Function.AnyToDecimal(dtZeiKBNM.Rows[0]["ZeiRate"]));
                        //端数処理セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "HasuuKBN", ComATool.Function.AnyToInt32(dtZeiKBNM.Rows[0]["HasuuKBN"]));
                        //消費税計算区分セット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN", ComATool.Function.AnyToInt32(dtZeiKBNM.Rows[0]["ZeiKeisanKBN"]));

                    }

                    //税込区分 = [3]税抜内訳(内税)、[4]税抜内訳(外税) かつ																													
                    //消費税計算区分 <> [0](計算しない) の場合																													
                    if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3 || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 4)
                        && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN") != 0)
                    {
                        //消費税科目区分 = 1 の場合
                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN") == 1)
                        {
                            //消費税科目コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuCD", kariUkeZeiKamokuCD);
                            //消費税科目コード改定日
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKaiteiDate", kariUkeZeiKamokuCDKaiteiDate);
                            //消費税科目貸借区分
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiTaishakuKBN", kariUkeZeiKamokuCDTaishakuKBN);
                        }

                        //消費税科目区分 = 2 の場合
                        if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN") == 2)
                        {
                            //消費税科目コード
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuCD", kariBaraiZeiKamokuCD);
                            //消費税科目コード改定日
                            SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKaiteiDate", kariBaraiZeiKamokuCDKaiteiDate);
                            //消費税科目貸借区分
                            SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiTaishakuKBN", kariBaraiZeiKamokuCDTaishakuKBN);
                        }
                    }
                }

                return KBN_CHECK_OK;
            }
            finally
            {
                if (dtZeiKBNM != null)
                {
                    //マスタデータを破棄する。
                    dtZeiKBNM.Dispose();
                }
            }
        }

        #endregion

        #region 税込区分のチェック

        /// <summary>
        /// 税込区分のチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckZeikomiKBN(int rowNo, int taishakukbn, int checkkbn)
        {
            DataTable dtZeikomiKBNM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
            }

            try
            {
                //ALLチェック時以外の時
                if (checkkbn != KBN_KOUMOKUCHK_ALL)
                {

                    //税込区分名をクリア
                    SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBNName", "");
                }

                //未入力の時
                if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == null)
                {
                    //"０"をセットする
                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", 0);
                }

                //借方税区分データ----------------
                if (checkkbn != KBN_KOUMOKUCHK_ALL)
                {
                    //税込区分マスタよりデータを取得
                    dtZeikomiKBNM = WinMToolSearchCom.M0000MS_CommonCode.SelectByKey(
                        400
                        , ComATool.Function.AnyToString(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN"))
                        , "");

                    if (dtZeikomiKBNM.Rows.Count == 0)
                    {
                        //税込区分エラーFlgをセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBNErrorFlag", 1);
                    }
                    else
                    {
                        //税込区分エラーFlgをセット
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBNErrorFlag", 0);
                    }
                }

                //税込区分ErrorFlg = 1の場合
                if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBNErrorFlag") == 1)
                {
                    if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                    {

                        object[] obj = new object[1];
                        obj[0] = taishakuJpnName;
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00216", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    }
                    return KBN_CHECK_NG_CANCEL;
                }

                // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                if ((GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") == rcHaraiCD)
                    && (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") != 0 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") != 1 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") != 2))
                {
                    if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                    {
                        object[] obj = new object[1];
                        obj[0] = taishakuJpnName;
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01448", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    }
                    return KBN_CHECK_NG_CANCEL;
                }
                // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了

                //税込区分の整合性チェックを行う
                int zeiKomiKBNError = WinMTool.MA_Common.CheckZeikomiKBN(
                    GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")
                    , GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN")
                    , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN"))
                    , ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN"))
                    , kariBaraiZeiKamokuCD
                    , kariUkeZeiKamokuCD
                    );

                //税込区分整合性エラーが１の場合
                if (zeiKomiKBNError == 1)
                {
                    if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                    {
                        object[] obj = new object[1];
                        obj[0] = taishakuJpnName;
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00217", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    }
                    return KBN_CHECK_NG_CANCEL;
                }

                //税込区分整合性エラーが２の場合
                if (zeiKomiKBNError == 2)
                {
                    if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                    {
                        object[] obj = new object[1];
                        obj[0] = taishakuJpnName;
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00218", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    }
                    return KBN_CHECK_NG_CANCEL;
                }

                if (checkkbn != KBN_KOUMOKUCHK_ALL)
                {
                    //税込区分名をセット
                    SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBNName", ComATool.Function.AnyToString(dtZeikomiKBNM.Rows[0]["CodeName"]));
                }

                //税込区分 = [3]税抜内訳(内税)、[4]税抜内訳(外税) かつ																													
                //消費税計算区分 <> [0](計算しない) の場合																													
                if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3 || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 4)
                    && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN") != 0)
                {

                    //消費税科目区分 = 1 の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN") == 1)
                    {
                        //消費税科目コード
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuCD", kariUkeZeiKamokuCD);
                        //消費税科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKaiteiDate", kariUkeZeiKamokuCDKaiteiDate);
                        //消費税科目貸借区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiTaishakuKBN", kariUkeZeiKamokuCDTaishakuKBN);

                    }

                    //消費税科目区分 = 2 の場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuKBN") == 2)
                    {
                        //消費税科目コード
                        SetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKamokuCD", kariBaraiZeiKamokuCD);
                        //消費税科目コード改定日
                        SetDatetimeColumnValue(checkkbn, rowNo, taishakuName, "ZeiKaiteiDate", kariBaraiZeiKamokuCDKaiteiDate);
                        //消費税科目貸借区分
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiTaishakuKBN", kariBaraiZeiKamokuCDTaishakuKBN);
                    }

                }
                return KBN_CHECK_OK;
            }
            finally
            {
                if (dtZeikomiKBNM != null)
                {
                    dtZeikomiKBNM.Dispose();
                }
            }
        }

        #endregion

        #region 金額のチェック

        /// <summary>
        /// 金額のチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckKingaku(int rowNo, int taishakukbn, int checkkbn)
        {
            //貸借名
            string taishakuName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //金額カラム番号
            int kingakuColumnNo;

            //2013/06/27 E.Sato ST GX対応(M00015:税込区分=4の時、金額を空白のままEnterすると貸借金額が合わなくなる)
            //未入力フラグ
            bool emptyFalg = false;
            //税込区分
            int zeikomiKBN = 0;
            //2013/06/27 E.Sato ED

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                kingakuColumnNo = COL_KARIKINGAKU;
            }
            else
            {
                taishakuName = "Kasi";
                kingakuColumnNo = COL_KASIKINGAKU;
            }

            if (checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //値変化プロパティ取得
                isChangedTextFlg = GetNumberColumn(rowNo, kingakuColumnNo).IsChangedText;
            }


            //未入力で総勘定科目が入力済みの場合
            if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku") == null && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == false && checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //合計の差額分を表示

                //借方の場合
                if (taishakukbn == KBN_TAISHAKU_KARIKATA)
                {
                    //0以外ならセット
                    if (obic7TextNumberTotalKasiSougaku.Value - (obic7TextNumberTotalKariSougaku.Value - (ComATool.Function.AnyToDecimal(prevKingaku) + ComATool.Function.AnyToDecimal(prevZeigaku))) != 0)
                    {
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku", obic7TextNumberTotalKasiSougaku.Value - (obic7TextNumberTotalKariSougaku.Value - (ComATool.Function.AnyToDecimal(prevKingaku) + ComATool.Function.AnyToDecimal(prevZeigaku))));
                    }
                }
                //貸方の場合
                else
                {
                    //0以外ならセット
                    if (obic7TextNumberTotalKariSougaku.Value - (obic7TextNumberTotalKasiSougaku.Value - (ComATool.Function.AnyToDecimal(prevKingaku) + ComATool.Function.AnyToDecimal(prevZeigaku))) != 0)
                    {
                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku", obic7TextNumberTotalKariSougaku.Value - (obic7TextNumberTotalKasiSougaku.Value - (ComATool.Function.AnyToDecimal(prevKingaku) + ComATool.Function.AnyToDecimal(prevZeigaku))));
                    }
                }
                isChangedTextFlg = true;

                //2013/06/27 E.Sato ST GX対応(M00015:税込区分=4の時、金額を空白のままEnterすると貸借金額が合わなくなる)
                //未入力フラグをセット
                emptyFalg = true;
                //2013/06/27 E.Sato ED
            }


            //値変化がある時(税込区分が3の場合は入力前金額 + 入力前消費税額 <> 現在表示金額の場合)
            if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") != 3 && isChangedTextFlg == true)
                || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3 && (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku") != prevKingaku + prevZeigaku))
            {
                //税込区分が3か4の場合
                if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3
                    || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 4
                    )
                {
                    //消費税計算を行う

                    //消費税計算用金額
                    decimal kingaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"));
                    //消費税計算用消費税額
                    decimal zeigaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"));

                    if (ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN")) == 3
                    || ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN")) == 4)
                    {
                        zeigaku = 0;
                    }

                    //2013/06/27 E.Sato ST GX対応(M00015:税込区分=4の時、金額を空白のままEnterすると貸借金額が合わなくなる)
                    //税込区分を取得
                    zeikomiKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN"));

                    //金額が未入力、かつ、税込区分が4：税抜内訳(外)の場合
                    if (emptyFalg == true && zeikomiKBN == 4)
                    {
                        //税込区分が3：税抜内訳(内)として計算を行う
                        this.SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", 3);
                    }
                    else
                    {
                        //上記以外は画面の税込区分で計算を行う
                    }
                    //2013/06/27 E.Sato ED

                    //消費税計算を行う
                    ShouhizeiKeisan(rowNo, taishakuName, kingaku, zeigaku);

                    //2013/06/27 E.Sato ST GX対応(M00015:税込区分=4の時、金額を空白のままEnterすると貸借金額が合わなくなる)
                    //金額が未入力、かつ、税込区分が4：税抜内訳(外)の場合
                    if (emptyFalg == true && zeikomiKBN == 4)
                    {
                        //税込区分を元に戻す
                        this.SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN", 4);
                    }
                    //2013/06/27 E.Sato ED
                }
            }
            else
            {
                //税込区分 = 3の場合
                if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3)
                {
                    //値変化がない場合は表示金額を元に戻す処理のみ
                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku", GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku") - prevZeigaku);
                }
            }

            //合計額の計算
            RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);

            //2009/08/05 OBIC H.Sudo 変更 開始  (M04264)貸借不一致で登録できてしまう不具合を改修
            //金額編集抑制用フラグを制御
            isKingakuEditing = false;
            //2009/08/05 OBIC H.Sudo 変更 終了

            return KBN_CHECK_OK;
        }


        #endregion

        #region 消費税額のチェック

        /// <summary>
        /// 消費税額のチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private int CheckZeigaku(int rowNo, int taishakukbn, int checkkbn)
        {
            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //消費税額カラム番号
            int zeigakuColumnNo;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                zeigakuColumnNo = COL_KARIZEIGAKU;
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                zeigakuColumnNo = COL_KASIZEIGAKU;
            }

            if (checkkbn == KBN_KOUMOKUCHK_INPUT)
            {
                //値変化プロパティ取得
                isChangedTextFlg = GetNumberColumn(rowNo, zeigakuColumnNo).IsChangedText;
            }

            //(消費税計算区分 = 0 もしくは 税込区分 = 0 or 1 or 2 もしくは 金額が未入力 ) かつ　消費税額が未入力でない場合
            if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeiKeisanKBN") == 0
                || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 0
                || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 1
                || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 2
                || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku") == null)
                && (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku") != null)
                )
            {
                object[] obj = new object[1];
                obj[0] = taishakuJpnName;
                //エラーメッセージを表示
                // 2008/08/20 T.Ota 変更開始 消費税チェックでエラーメッセージ表示時、メッセージ詳細に引数を渡す
                //WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00229", obj, null, GetType(),
                //                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                //                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00229", obj, obj, GetType(),
                                                     WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                     WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                // 2008/08/20 T.Ota 変更終了
                return KBN_CHECK_NG_CANCEL;

            }

            //税込区分 = 3の場合
            if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3)
            {
                //金額に(入力前の金額 + 入力前の消費税額) - 金額をセット
                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"
                    , prevKingaku + prevZeigaku - ComATool.Function.AnyToDecimal(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku")));
            }

            //税込区分 = 3 or 4 ので消費税額が未入力の場合
            if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 3
                || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 4)
                && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku") == null
                )
            {
                //消費税額に0をセット
                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku", 0);
            }

            //合計額の計算
            RecalcTotalForRowChenge(prevKingaku, prevZeigaku, GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Zeigaku"), taishakukbn);

            //2009/08/05 OBIC H.Sudo 変更 開始  (M04264)貸借不一致で登録できてしまう不具合を改修
            //金額編集抑制用フラグを制御
            isKingakuEditing = false;
            //2009/08/05 OBIC H.Sudo 変更 終了

            return KBN_CHECK_OK;
        }

        #endregion

        #region 分析コードのチェック

        /// <summary>
        /// 分析コードのチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="taishakukbn">貸借区分 1:借方2:貸方</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <param name="bunsekikbn">分析区分 1～5:分析コード1～5　6:資金コード 7:プロジェクトコード</param>
        /// <returns></returns>
        private int CheckBunsekiCD(int rowNo, int taishakukbn, int checkkbn, int bunsekikbn)
        {
            DataTable dtBunsekiM = null;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //値変化フラグ
            bool isChangedTextFlg = false;

            //分析コードカラム番号
            int BunsekiColumnNo = 0;
            //分析コード
            string bunsekiCD = "";
            //分析コードチェック区分
            int bunsekicheckKBN = 0;

            if (taishakukbn == KBN_TAISHAKU_KARIKATA)
            {
                taishakuName = "Kari";
                taishakuJpnName = "借方";
                switch (bunsekikbn)
                {
                    case 1:
                        BunsekiColumnNo = COL_KARIBUNSEKICD1;
                        break;
                    case 2:
                        BunsekiColumnNo = COL_KARIBUNSEKICD2;
                        break;
                    case 3:
                        BunsekiColumnNo = COL_KARIBUNSEKICD3;
                        break;
                    case 6:
                        BunsekiColumnNo = COL_KARISIKINCD;
                        break;
                    case 4:
                        BunsekiColumnNo = COL_KARIBUNSEKICD4;
                        break;
                    case 5:
                        BunsekiColumnNo = COL_KARIBUNSEKICD5;
                        break;
                    case 7:
                        BunsekiColumnNo = COL_KARIPROJECTCD;
                        break;
                    default:
                        BunsekiColumnNo = COL_KARIBUNSEKICD1;
                        break;
                }
            }
            else
            {
                taishakuName = "Kasi";
                taishakuJpnName = "貸方";
                switch (bunsekikbn)
                {
                    case 1:
                        BunsekiColumnNo = COL_KASIBUNSEKICD1;
                        break;
                    case 2:
                        BunsekiColumnNo = COL_KASIBUNSEKICD2;
                        break;
                    case 3:
                        BunsekiColumnNo = COL_KASIBUNSEKICD3;
                        break;
                    case 6:
                        BunsekiColumnNo = COL_KASISIKINCD;
                        break;
                    case 4:
                        BunsekiColumnNo = COL_KASIBUNSEKICD4;
                        break;
                    case 5:
                        BunsekiColumnNo = COL_KASIBUNSEKICD5;
                        break;
                    case 7:
                        BunsekiColumnNo = COL_KASIPROJECTCD;
                        break;
                    default:
                        BunsekiColumnNo = COL_KASIBUNSEKICD1;
                        break;
                }
            }
            //資金コードの場合
            if (bunsekikbn == 6)
            {
                bunsekicheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouSikinCheckKBN"));
                bunsekiCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinCD");
            }
            //プロジェクトコードの場合
            else if (bunsekikbn == 7)
            {
                bunsekicheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouProjectCheckKBN"));
                bunsekiCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectCD");
            }
            //分析コードの場合
            else
            {
                bunsekicheckKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("KanjouBunsekiCheckKBN", ComATool.Function.AnyToString(bunsekikbn))));
                bunsekiCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn)));
            }
            try
            {
                if (checkkbn == KBN_KOUMOKUCHK_INPUT)
                {
                    //値変化プロパティ取得
                    isChangedTextFlg = GetStringColumn(rowNo, BunsekiColumnNo).IsChangedText;
                }

                //値変化がある時
                if (isChangedTextFlg == true || checkkbn != KBN_KOUMOKUCHK_INPUT)
                {
                    //ALLチェック時以外の時
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //隠し項目のクリア
                        if (bunsekikbn == 6)
                        {
                            //資金コード名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinName", "");
                        }
                        // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                        else if (bunsekikbn == 7)
                        {
                            //プロジェクトコード名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectName", "");
                        }
                        // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                        else if (bunsekikbn == 1 || bunsekikbn == 2 || bunsekikbn == 3)
                        {
                            //分析コード名
                            SetStringColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiName", ComATool.Function.AnyToString(bunsekikbn)), "");
                        }

                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        if (bunsekikbn == 1 || bunsekikbn == 2 || bunsekikbn == 3 || bunsekikbn == 6)
                        {
                            //ツールチップテキスト
                            toolTip1.SetToolTip(GetStringColumn(rowNo, BunsekiColumnNo), "");
                        }
                    }

                    //未入力の時
                    if (String.IsNullOrEmpty(bunsekiCD) == true)
                    {
                        //処理なし
                        return KBN_CHECK_OK;
                    }

                    //分析チェック区分が 6 で 分析コードが入力されている時
                    if (bunsekicheckKBN == 6 && String.IsNullOrEmpty(bunsekiCD) == false)
                    {
                        if (bunsekikbn == 6)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00232", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        else if (bunsekikbn == 7)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00234", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        else
                        {
                            object[] obj = new object[2];
                            obj[0] = taishakuJpnName;
                            obj[1] = ComATool.Function.AnyToString(bunsekikbn);
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00230", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        return KBN_CHECK_NG_CANCEL;

                    }

                    //分析コードマスタデータ----------------
                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //マスタよりデータを取得
                        dtBunsekiM = WinMToolSearchCom.M0000MS_MA_BunsekiCD.SelectByKey(bunsekikbn, bunsekiCD, "");

                        if (dtBunsekiM.Rows.Count == 0)
                        {
                            //資金コードの場合
                            if (bunsekikbn == 6)
                            {
                                //資金コードエラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag", 1);
                            }
                            //プロジェクトコードの場合
                            else if (bunsekikbn == 7)
                            {
                                //プロジェクトコードエラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag", 1);
                            }
                            //分析コードの場合
                            else
                            {
                                //分析コードエラーFlgをセット
                                SetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag"), 1);
                            }
                        }
                        else
                        {
                            // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                            //入力制御フラグを取得
                            byte seigyoFlg = WinMTool.MA_Common.GetSeigyoSiyouFlg(bunsekikbn, bunsekiCD1NyuuryokuSeigyoFlg, bunsekiCD2NyuuryokuSeigyoFlg, bunsekiCD3NyuuryokuSeigyoFlg
                                                                                 , bunsekiCD4NyuuryokuSeigyoFlg, bunsekiCD5NyuuryokuSeigyoFlg, sikinCDNyuuryokuSeigyoFlg, projectCDNyuuryokuSeigyoFlg);
                            //マスタが存在するかつ、制御フラグがtrueの場合のみ以下のチェックを行う
                            if (seigyoFlg == 1)
                            {
                                //分析コードマスタデータ セキュリティを考慮
                                //マスタよりデータを取得(セキュリティを考慮)
                                dtBunsekiM = WinMToolSearchCom.M0000MS_MA_BunsekiCD.SelectByKey(bunsekikbn, bunsekiCD, "", ComAToolLogic.CurrentUser.UserID, seigyoFlg);

                                if (dtBunsekiM.Rows.Count == 0)
                                {
                                    //資金コードの場合
                                    if (bunsekikbn == 6)
                                    {
                                        //資金コードエラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag", 2);
                                    }
                                    //プロジェクトコードの場合
                                    else if (bunsekikbn == 7)
                                    {
                                        //プロジェクトコードエラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag", 2);
                                    }
                                    //分析コードの場合
                                    else
                                    {
                                        //分析コードエラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag"), 2);
                                    }
                                }
                                else
                                {
                                    //資金コードの場合
                                    if (bunsekikbn == 6)
                                    {
                                        //資金コードエラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag", 0);
                                    }
                                    //プロジェクトコードの場合
                                    else if (bunsekikbn == 7)
                                    {
                                        //プロジェクトコードエラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag", 0);
                                    }
                                    else
                                    {
                                        //分析コードエラーFlgをセット
                                        SetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag"), 0);
                                    }
                                }
                            }
                            else
                            {
                                // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                                //資金コードの場合
                                if (bunsekikbn == 6)
                                {
                                    //資金コードエラーFlgをセット
                                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag", 0);
                                }
                                //プロジェクトコードの場合
                                else if (bunsekikbn == 7)
                                {
                                    //プロジェクトコードエラーFlgをセット
                                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag", 0);
                                }
                                else
                                {
                                    //分析コードエラーFlgをセット
                                    SetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag"), 0);
                                }
                                // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                            }
                            // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                        }
                    }

                    // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                    if (checkkbn != KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                        //分析チェック区分 <> 0 or 2 or 4の場合
                        if (bunsekicheckKBN != 0 && bunsekicheckKBN != 2 && bunsekicheckKBN != 4)
                        {
                            if ((bunsekikbn == 6 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag") == 1)
                                || (bunsekikbn == 7 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag") == 1)
                                || (bunsekikbn != 6 && bunsekikbn != 7 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag")) == 1)
                            )
                            {
                                //分析コードエラーFlgが１の時はエラー
                                if (bunsekikbn == 6)
                                {
                                    object[] obj = new object[1];
                                    obj[0] = taishakuJpnName;
                                    //エラーメッセージを表示
                                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00233", obj, null, GetType(),
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                }
                                //プロジェクトコードの場合
                                else if (bunsekikbn == 7)
                                {
                                    object[] obj = new object[1];
                                    obj[0] = taishakuJpnName;
                                    //エラーメッセージを表示
                                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00235", obj, null, GetType(),
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                }
                                else
                                {

                                    object[] obj = new object[2];
                                    obj[0] = taishakuJpnName;
                                    obj[1] = ComATool.Function.AnyToString(bunsekikbn);
                                    //エラーメッセージを表示
                                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00231", obj, null, GetType(),
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                }
                                return KBN_CHECK_NG_CANCEL;
                            }
                        }

                        // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
                        if ((bunsekikbn == 6 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag") == 2)
                           || (bunsekikbn == 7 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag") == 2)
                           || (bunsekikbn != 6 && bunsekikbn != 7 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag")) == 2)
                           )
                        {
                            //分析コードエラーFlgが１の時はエラー
                            if (bunsekikbn == 6)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30206", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            //プロジェクトコードの場合
                            else if (bunsekikbn == 7)
                            {
                                object[] obj = new object[1];
                                obj[0] = taishakuJpnName;
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30207", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            else
                            {

                                object[] obj = new object[2];
                                obj[0] = taishakuJpnName;
                                obj[1] = ComATool.Function.AnyToString(bunsekikbn);
                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30205", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            }
                            return KBN_CHECK_NG_CANCEL;
                        }
                    }
                    // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)

                    if (checkkbn != KBN_KOUMOKUCHK_ALL)
                    {
                        //分析コードエラーFlgが０のときデータセット
                        if ((bunsekikbn == 6 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "SikinCDErrorFlag") == 0)
                            || (bunsekikbn == 7 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ProjectCDErrorFlag") == 0)
                            || (bunsekikbn != 6 && bunsekikbn != 7 && GetNumberColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiCD", ComATool.Function.AnyToString(bunsekikbn), "ErrorFlag")) == 0)
                        )
                        {

                            if (bunsekikbn == 6)
                            {
                                //資金コード名
                                SetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinName", ComATool.Function.AnyToString(dtBunsekiM.Rows[0]["BunsekiName"]));
                            }
                            // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                            else if (bunsekikbn == 7)
                            {
                                //プロジェクトコード名
                                SetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectName", ComATool.Function.AnyToString(dtBunsekiM.Rows[0]["BunsekiName"]));
                            }
                            // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                            else if (bunsekikbn == 1 || bunsekikbn == 2 || bunsekikbn == 3)
                            {
                                //分析コード名
                                SetStringColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiName", ComATool.Function.AnyToString(bunsekikbn)), ComATool.Function.AnyToString(dtBunsekiM.Rows[0]["BunsekiName"]));
                            }
                        }
                    }

                    if (checkkbn == KBN_KOUMOKUCHK_INPUT || checkkbn == KBN_KOUMOKUCHK_AFTERSETVALUE)
                    {
                        if (bunsekikbn == 6)
                        {
                            //資金コード ツールチップテキストにセット
                            toolTip1.SetToolTip(GetStringColumn(rowNo, BunsekiColumnNo), RenketuString(bunsekiCD, "：", GetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinName")));
                        }
                        // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                        else if (bunsekikbn == 7)
                        {
                            //プロジェクトコード ツールチップテキストにセット
                            toolTip1.SetToolTip(GetStringColumn(rowNo, BunsekiColumnNo), RenketuString(bunsekiCD, "：", GetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectName")));
                        }
                        // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                        else if (bunsekikbn == 1 || bunsekikbn == 2 || bunsekikbn == 3)
                        {
                            //分析コード ツールチップテキストにセット
                            toolTip1.SetToolTip(GetStringColumn(rowNo, BunsekiColumnNo), RenketuString(bunsekiCD, "：", GetStringColumnValue(checkkbn, rowNo, taishakuName, RenketuString("BunsekiName", ComATool.Function.AnyToString(bunsekikbn)))));
                        }

                    }

                }

                return KBN_CHECK_OK;

            }
            finally
            {
                //マスタデータを破棄する。
                if (dtBunsekiM != null)
                {
                    dtBunsekiM.Dispose();
                }
            }

        }

        #endregion

        #region 明細摘要のチェック

        /// <summary>
        /// 明細摘要のチェック
        /// </summary>
        /// <param name="rowNo">対象行NO</param>
        /// <param name="checkkbn">チェック区分 1:項目入力時 2:ALLチェック時 3:発生日更新時</param>
        /// <returns></returns>
        private bool CheckMeisaiTekiyou(int rowNo, int checkkbn)
        {

            Encoding sjisEnc = Encoding.GetEncoding("Shift_JIS");

            if (enterKeyDownFlg == true)
            {
                //伝票摘要が5バイト以下の場合
                if (sjisEnc.GetByteCount(GetStringColumnValue(checkkbn, rowNo, COL_MEISAITEKIYOU)) <= 5)
                {
                    using (DataTable dtTek1M = WinMToolSearchCom.M0000MS_MA_Tekiyou1.SelectByCustom(RenketuString(" WHERE Tekiyou1CD = ", ComATool.Function.SqlEscapeVarchar(GetStringColumnValue(checkkbn, rowNo, COL_MEISAITEKIYOU)))))
                    {
                        //取得値有効チェック
                        if ((dtTek1M != null) && (dtTek1M.Rows.Count != 0))
                        {
                            GetStringColumn(rowNo, COL_MEISAITEKIYOU).Value = ComATool.Function.AnyToString(dtTek1M.Rows[0]["Tekiyou1Name"]);
                            GetStringColumn(rowNo, COL_MEISAITEKIYOU).Focus();
                            //先頭にカーソル配置
                            GetStringColumn(rowNo, COL_MEISAITEKIYOU).Select(0, 0);
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        #endregion

        #region 消費税計算
        /// <summary>
        /// 消費税計算
        /// </summary>
        /// <param name="rowNo"></param>
        /// <param name="taishakuName"></param>
        /// <param name="kingaku"></param>
        /// <param name="zeigaku"></param>
        private void ShouhizeiKeisan(int rowNo, string taishakuName, decimal kingaku, decimal zeigaku)
        {
            //消費税計算用表示金額
            decimal dispkingaku = 0;

            //消費税計算を行う
            WinMTool.MA_Common.ZeiKeisan(
                GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeiKBN")
            , ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeiRate"))
            , ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "HasuuKBN"))
            , ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, RenketuString("Kanjou", taishakuName, "ZeiKamokuKBN")))
            , ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeiKeisanKBN"))
            , ComATool.Function.AnyToInt32(prevZeikomiKBN)
            , ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeikomiKBN"))
            , ref kingaku
            , ref zeigaku
            , ref dispkingaku
            );

            //計算後の金額をセット
            SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Kingaku", kingaku);

            if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeikomiKBN") == 0 ||
                GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeikomiKBN") == 1 ||
                GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "ZeikomiKBN") == 2)
            {
                SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Zeigaku", null);
            }
            else
            {
                //計算後の消費税額をセット
                SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Zeigaku", zeigaku);
            }
        }

        #endregion

        #region 明細行の入力チェック
        /// <summary>
        /// 明細行の入力チェック
        /// </summary>
        /// <param name="checkkbn">1:入力時、2:ALLチェック時</param>
        /// <param name="rowNo"></param>
        /// <returns>明細項目番号(借方分析情報画面起動時は500,貸方分析情報画面起動時は600,エラーなしは-1を返す)</returns>
        private int CheckMeisaiGyou(int checkkbn, int rowNo)
        {

            //入力チェックフラグ
            bool nyuuryokuCheckErrorFlg = true;
            int errorColumnNumber = -1;

            //貸借名
            string taishakuName;
            string taishakuJpnName;

            //2008/06/02 追加 N.Sasaki 開始
            string bunsekiKeikokuText = "";
            //2008/06/02 追加 N.Sasaki 終了

            //未入力チェック
            for (int i = 1; i <= 2; i++)
            {
                if (i == KBN_TAISHAKU_KARIKATA)
                {
                    taishakuName = "Kari";
                }
                else
                {
                    taishakuName = "Kasi";
                }

                //総勘定科目コードが未入力で金額が入力されている場合
                if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == true
                    && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku") != null
                    )
                {
                    if (nyuuryokuCheckErrorFlg != false)
                    {
                        //エラー項目番号取得
                        errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "KanjouCD"))).ColumnNumber;

                        nyuuryokuCheckErrorFlg = false;

                        if (checkkbn == KBN_KOUMOKUCHK_ALL)
                        {
                            SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                        }
                    }

                    //エラープロバイダ表示
                    DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "KanjouCD"))).ColumnNumber);

                }

                //総勘定科目が入力されている場合にチェック
                if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD")) == false)
                {
                    //補助科目コードが未入力で補助区分が0以外の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "HojoCD")) == true
                        && ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "HojoKBN")) != 0)
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "HojoCD"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "HojoCD"))).ColumnNumber);

                    }

                    //補助内訳科目コードが未入力で内訳区分が0以外の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeCD")) == true
                        && ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "UtiwakeKBN")) != 0)
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "UtiwakeCD"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "UtiwakeCD"))).ColumnNumber);
                    }

                    //取引先コードが未入力で取引先区分が0以外の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiCD")) == true
                        && ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiKBN")) != 0)
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "TorihikisakiCD"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

