                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "TorihikisakiCD"))).ColumnNumber);

                    }

                    //部門コードが未入力で部門区分が0以外の場合
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")) == true
                        && ComATool.Function.AnyToInt32(GetNumberColumnValue(checkkbn, rowNo, taishakuName, "BumonKBN")) != 0)
                    {
