                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BumonCD"))).ColumnNumber);

                    }

                    //税区分が未入力
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiKBN")) == true)
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ZeiKBN"))).ColumnNumber;

