                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ZeiKBN"))).ColumnNumber);
                    }

                    //税込区分が未入力
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == null)
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(NUMCTLNAME, taishakuName, "ZeikomiKBN"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(NUMCTLNAME, taishakuName, "ZeikomiKBN"))).ColumnNumber);

                    }

                    //消費税本体コードが未入力
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZeiHontaiCD")) == true
                        // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 開始
                        //&& ((GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") == kariBaraiZeiKamokuCD || GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") == kariUkeZeiKamokuCD) && (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 1 || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 2)))
                        && ((GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") == kariBaraiZeiKamokuCD || GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") == kariUkeZeiKamokuCD || GetStringColumnValue(checkkbn, rowNo, taishakuName, "KanjouCD") == rcHaraiCD)
                            && (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 1 || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "ZeikomiKBN") == 2)))
                    // 2015/05/20 R.Aoki 変更 (25192-25347-25725)リバースチャージ対応 終了
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ZeiHontaiCD"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ZeiHontaiCD"))).ColumnNumber);

                    }

                    //金額が未入力で総勘定科目コードが入力されている場合
                    if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "Kingaku") == null
                        )
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(NUMCTLNAME, taishakuName, "Kingaku"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(NUMCTLNAME, taishakuName, "Kingaku"))).ColumnNumber);
                    }

                    //分析コード1
                    if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 4
                        || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 5)
                        && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD1")) == true
                        )
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BunsekiCD1"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

