                    }
                    //分析コード2
                    if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 4
                        || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 5)
                        && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD2")) == true
                        )
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BunsekiCD2"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BunsekiCD2"))).ColumnNumber);
                    }
                    //分析コード3
                    if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 4
                        || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN3") == 5)
                        && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD3")) == true
                        )
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BunsekiCD3"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BunsekiCD3"))).ColumnNumber);
                    }
                    //資金コード
                    if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouSikinCheckKBN") == 4
                        || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouSikinCheckKBN") == 5)
                        && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinCD")) == true
                        )
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "SikinCD"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;

                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "SikinCD"))).ColumnNumber);
                    }
                    // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                    //プロジェクトコード
                    if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouProjectCheckKBN") == 4
                        || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouProjectCheckKBN") == 5)
                        && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectCD")) == true
                        )
                    {
                        if (nyuuryokuCheckErrorFlg != false)
                        {
                            //エラー項目番号取得
                            errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ProjectCD"))).ColumnNumber;

                            nyuuryokuCheckErrorFlg = false;
                            if (checkkbn == KBN_KOUMOKUCHK_ALL)
                            {
                                SetFocusMeisaiCtl(checkkbn, rowNo, errorColumnNumber);
                            }
                        }

                        //エラープロバイダ表示
                        DispErrorProvider(checkkbn, rowNo, ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ProjectCD"))).ColumnNumber);
                    }
                    // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                }
            }

            //未入力項目があった場合
            if (nyuuryokuCheckErrorFlg == false)
            {
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00103", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                return errorColumnNumber;
            }

            //未入力チェック(分析コード4,分析コード5)
            for (int i = 1; i <= 2; i++)
            {
                if (i == KBN_TAISHAKU_KARIKATA)
                {
                    taishakuName = "Kari";
                    taishakuJpnName = "借方";
                }
                else
                {
                    taishakuName = "Kasi";
                    taishakuJpnName = "貸方";
                }

                //借方総勘定科目M.分析チェック区分4 = 4(入力必須(ﾏｽﾀﾁｪｯｸ無)) or 5(入力必須(ﾏｽﾀﾁｪｯｸ有)) かつ、分析コード4が未入力の場合未入力(警告)
                if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN4") == 4
                    || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN4") == 5)
                    && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD4")) == true
                    )
                {
                    object[] obj = new object[1];
                    obj[0] = taishakuJpnName;
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00103", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    if (checkkbn == KBN_KOUMOKUCHK_ALL)
                    {
