                    )
                    {
                        if (checkkbn != KBN_KOUMOKUCHK_ARAIGAE)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00210", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }

                    }


                    if (torihikisakiCheckKBN == 2
                        &&
                        !((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiLeaseKaishaKBN") == 1
                               && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiLeaseKaishaKBN") == 1
                            )
                            ||
                             (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiZeimushoKBN") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiZeimushoKBN") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiiresakiKBN") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiiresakiKBN") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiSiharaisakiKBN") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiSiharaisakiKBN") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTokuisakiKBN") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTokuisakiKBN") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiKaishuusakiKBN") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiKaishuusakiKBN") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN1") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN1") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN2") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN2") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN3") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN3") == 1
                            )
                            ||
                            (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouHasseiTorihikisakiKBN4") == 1
                            && GetNumberColumnValue(checkkbn, rowNo, taishakuName, "TorihikisakiHasseiTorihikisakiKBN4") == 1
                            )
                        )
                    )
                    {

                        object[] obj = new object[1];
                        obj[0] = taishakuJpnName;
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00211", obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                        //エラー項目番号取得
                        return errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "TorihikisakiCD"))).ColumnNumber;
                    }
                }

                ////部門が入力済みの場合
                if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")) == false
                     && nyuuryokuCheckErrorFlg == true
                    )
                {
                    //事業所部門パターンチェック用事業所
                    string taishoZigyoushoCD = "";

                    //事業所部門パターンチェック用事業所取得
                    if (String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD")) == true)
                    {
                        taishoZigyoushoCD = obic7TextStringZigyoushoCD.Value;
                    }
                    else
                    {
                        taishoZigyoushoCD = GetStringColumnValue(checkkbn, rowNo, taishakuName, "ZigyoushoCD");
                    }

