                    using (DataTable dtZigBumonM = WinMToolSearchCom.M0000MS_MA_Bumon.SelectByZigBmn(
                                GetStringColumnValue(checkkbn, rowNo, taishakuName, "BumonCD")
                                , (DateTime)obic7TextDatetimeHasseiDate.Value
                                , bumonSecurityPatternCD
                                , 0
                                , 0
                                , taishoZigyoushoCD
                                , 0
                                , ""
                                )
                    )
                    {
                        //部門データがなくて事業所部門チェック区分が1の場合入力不可(警告)
                        if (dtZigBumonM.Rows.Count == 0 && zigyoushoBumonCheckKBN == 1)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;

                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00205", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        }
                        //部門データがなくて事業所部門チェック区分が2の場合入力不可(エラー
                        else if (dtZigBumonM.Rows.Count == 0 && zigyoushoBumonCheckKBN == 2)
                        {
                            object[] obj = new object[1];
                            obj[0] = taishakuJpnName;
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00206", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            //エラー項目番号取得
                            return errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BumonCD"))).ColumnNumber;

                        }
                    }
