                //借方総勘定科目M.分析チェック区分1 = 2(未入力警告表示(ﾏｽﾀﾁｪｯｸ無)) or 3(未入力警告表示(ﾏｽﾀﾁｪｯｸ有)) かつ、分析コード1が未入力の場合未入力(警告)
                if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 2
                    || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 3)
                    && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD1")) == true
                    //2008/06/02 削除 N.Sasaki 開始
                    ////2008/05/14 追加 N.Sasaki 開始 行挿入時は分析コードの警告チェックは行なわない
                    //                    && gyouSounyuuFlg == false
                    ////2008/05/14 追加 N.Sasaki 終了 
