                //if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN1") == 6
                //    && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD1")) == false
                //    )
                //{
                //    object[] obj = new object[1];
                //    obj[0] = taishakuJpnName;
                //    //エラーメッセージを表示
                //    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00185", obj, null, GetType(),
                //                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                //                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                //    //エラー項目番号取得
                //    return errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "BunsekiCD1"))).ColumnNumber;

                //}
                //2008/06/02 削除 N.Sasaki 終了

                //借方総勘定科目M.分析チェック区分2 = 2(未入力警告表示(ﾏｽﾀﾁｪｯｸ無)) or 3(未入力警告表示(ﾏｽﾀﾁｪｯｸ有)) かつ、分析コード2が未入力の場合未入力(警告)
                if ((GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 2
                    || GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouBunsekiCheckKBN2") == 3)
                    && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "BunsekiCD2")) == true
                    //2008/06/02 削除 N.Sasaki 開始
