                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                    //エラー項目番号取得
                    if (i == KBN_TAISHAKU_KARIKATA)
                    {
                        return COL_KARIBUNSEKICD5;
                    }
                    else
                    {
                        return COL_KASIBUNSEKICD5;
                    }
                }

                //借方総勘定科目M.資金チェック区分 = 6(入力不可) かつ、資金コードが入力の場合入力不可
                if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouSikinCheckKBN") == 6
                    && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "SikinCD")) == false
                    )
                {
                    object[] obj = new object[1];
                    obj[0] = taishakuJpnName;
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00185", obj, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    //エラー項目番号取得
                    return errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "SikinCD"))).ColumnNumber;
                }

                //借方総勘定科目M.プロジェクトチェック区分 = 6(入力不可) かつ、借方プロジェクトコードが入力の場合入力不可
                if (GetNumberColumnValue(checkkbn, rowNo, taishakuName, "KanjouProjectCheckKBN") == 6
                    && String.IsNullOrEmpty(GetStringColumnValue(checkkbn, rowNo, taishakuName, "ProjectCD")) == false
                    )
                {
                    object[] obj = new object[1];
                    obj[0] = taishakuJpnName;
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00185", obj, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                    // 2013/05/15 修正 I.Nakagawa 開始 (GX)
                    //if (i == KBN_TAISHAKU_KARIKATA)
                    //{
                    //    return COL_KARIPROJECTCD;
                    //}
                    //else
                    //{
                    //    return COL_KASIPROJECTCD;
                    //}
                    //エラー項目番号取得
                    return errorColumnNumber = ((WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(0, RenketuString(STRCTLNAME, taishakuName, "ProjectCD"))).ColumnNumber;
                    // 2013/05/15 修正 I.Nakagawa 終了 (GX)
                }
            }

            return -1;

        }

        #endregion

        #region 登録前チェック

        /// <summary>
        /// 登録前チェック
        /// </summary>
        /// <param name="checkkbn">1:伝票登録時 2:ﾊﾟﾀｰﾝ登録時</param>
        /// <returns></returns>
        private bool CheckAll(int checkkbn)
        {
            //  2016/02/02  追加 T.Sato  (36053)決算伝票締日がチェックされない場合がある  開始
            //財務コントロールマスタの情報を再取得
            GetZaimuControlMaster();
            //  2016/02/02  追加 T.Sato  (36053)決算伝票締日がチェックされない場合がある  終了

            if (checkkbn == 1)
            {
                //ヘッダの必須チェック
                if (CheckHeaderEmpty() == false)
                {
                    return false;
                }

                //事業所のチェック
                if (CheckZigyoushoCD(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextStringZigyoushoCD.Focus();
                    return false;
                }

                if (this.simeKanriKbn != 0)
                {
                    //明細の伝票締日の再セット
                    this.RefreshMeisaiDenpyouSimeDate();
                }

                //　2010/08/10　変更　　　C.Okuno  (M04451)↓
                if (this.prevkanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.Taishougai)
                {
                    //　2010/08/10　変更　　　C.Okuno  (M04451)↑
                    if (obic7ComboBoxMode.Text == MODE_UPDATE)
                    {
                        //修正前決算フラグ = 1 の場合
                        if (prevKessanFlg == 1)
                        {
                            if (kessanDenpyouSimeDate != null)
                            {
                                //修正前発生日 <= 決算伝票締日
                                if (prevHasseiDate <= kessanDenpyouSimeDate)
                                {
                                    object[] obj = new object[2];
                                    obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(kessanDenpyouSimeDate), "yyyy/MM/dd", false);
                                    obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(prevHasseiDate), "yyyy/MM/dd", false);

                                    //エラーメッセージを表示
                                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00663", obj, null, GetType(),
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                    obic7TextDatetimeHasseiDate.Focus();
                                    return false;
                                }
                            }
                        }

                        //修正前決算フラグ <> 1 の場合
                        //伝票締日チェック
                        if (prevKessanFlg != 1)
                        {
                            if (denpyouSimeDate != null)
                            {
                                //発生日 <= 伝票締日
                                if (prevHasseiDate <= denpyouSimeDate)
                                {
                                    object[] obj = new object[2];
                                    obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(denpyouSimeDate), "yyyy/MM/dd", false);
                                    obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(prevHasseiDate), "yyyy/MM/dd", false);

                                    //エラーメッセージを表示
                                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00664", obj, null, GetType(),
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                    obic7TextDatetimeHasseiDate.Focus();
                                    return false;
                                }
                            }
                        }

                        //修正前決算フラグ <> 1 の場合
                        //伝票締日チェック
                        if (prevKessanFlg != 1 && hontenShuutyuuFlag == 1)
                        {
                            if (honshaZigyoushoDenpyouSimeDate != null)
                            {
                                //発生日 <= 伝票締日
                                if (prevHasseiDate <= honshaZigyoushoDenpyouSimeDate)
                                {
                                    object[] obj = new object[2];
                                    obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(honshaZigyoushoDenpyouSimeDate), "yyyy/MM/dd", false);
                                    obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(prevHasseiDate), "yyyy/MM/dd", false);

                                    //エラーメッセージを表示
                                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00664", obj, null, GetType(),
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                    obic7TextDatetimeHasseiDate.Focus();
                                    return false;
                                }
                            }
                        }

                        //修正前決算フラグ <> 1 の場合
                        //伝票締日チェック
                        if (prevKessanFlg != 1)
                        {
                            //明細事業所伝票締日チェック
                            if (CheckZigyoushoDepyouSimeDate(3) == false)
                            {
                                return false;
                            }
                        }
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                }
                if (this.prevkanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.Taishou)
                {
                    if (kanendoSokyuuDenpyouSimeDate != null)
                    {
                        //修正前.伝票区分M.[遡及処理年月日] <= 決算伝票締日
                        if (prevsokyuuShoriDateDen <= kanendoSokyuuDenpyouSimeDate)
                        {
                            object[] obj = new object[2];
                            obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(kanendoSokyuuDenpyouSimeDate), "yyyy/MM/dd", false);
                            obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(prevsokyuuShoriDateDen), "yyyy/MM/dd", false);

                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01216", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            obic7TextDatetimeHasseiDate.Focus();
                            return false;
                        }
                    }
                }
                if (this.prevkanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.SokyuuSumi)
                {
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01262", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    //　2010/09/16　変更　　　C.Okuno  (M04451)↓
                    //this.obic7TextStringCalledDenpyouNO.Focus();
                    this.obic7TextStringDenpyouKBN.Focus();
                    //　2010/09/16　変更　　　C.Okuno  (M04451)↑

                    return false;
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                //発生日のチェック
                if (CheckHasseiDate(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextDatetimeHasseiDate.Focus();
                    return false;
                }

                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                if (this.kanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.Taishougai)
                {
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    //決算フラグ = 1 の場合
                    if (kessanFlg == 1)
                    {
                        if (kessanDenpyouSimeDate != null)
                        {
                            //発生日 <= 決算伝票締日
                            if (obic7TextDatetimeHasseiDate.Value <= kessanDenpyouSimeDate)
                            {
                                object[] obj = new object[2];
                                obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(kessanDenpyouSimeDate), "yyyy/MM/dd", false);
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);

                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00239", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                obic7TextDatetimeHasseiDate.Focus();
                                return false;
                            }
                        }
                    }

                    //伝票締日チェック
                    //決算フラグ <> 1(決算仕訳) の場合
                    if (kessanFlg != 1)
                    {
                        if (denpyouSimeDate != null)
                        {
                            //発生日 <= 伝票締日
                            if (obic7TextDatetimeHasseiDate.Value <= denpyouSimeDate)
                            {
                                object[] obj = new object[2];
                                obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(denpyouSimeDate), "yyyy/MM/dd", false);
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);

                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00240", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                obic7TextDatetimeHasseiDate.Focus();
                                return false;
                            }
                        }


                    }

                    //決算フラグ <> 1 の場合
                    //伝票締日チェック
                    if (kessanFlg != 1 && hontenShuutyuuFlag == 1)
                    {
                        if (honshaZigyoushoDenpyouSimeDate != null)
                        {
                            //発生日 <= 伝票締日
                            //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                            //if (prevHasseiDate <= honshaZigyoushoDenpyouSimeDate)
                            if (obic7TextDatetimeHasseiDate.Value <= honshaZigyoushoDenpyouSimeDate)
                            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                            {
                                object[] obj = new object[2];
                                obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(honshaZigyoushoDenpyouSimeDate), "yyyy/MM/dd", false);
                                //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                                //obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(prevHasseiDate), "yyyy/MM/dd", false);
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);
                                //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00240", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                obic7TextDatetimeHasseiDate.Focus();
                                return false;
                            }
                        }
                    }

                    //伝票締日チェック
                    //決算フラグ <> 1(決算仕訳) の場合
                    if (kessanFlg != 1)
                    {
                        //明細事業所伝票締日チェック
                        if (CheckZigyoushoDepyouSimeDate(1) == false)
                        {
                            return false;
                        }
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                }
                if (this.kanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.Taishou)
                {
                    if (kanendoSokyuuDenpyouSimeDate != null)
                    {
                        //伝票区分M.[遡及処理年月日] <= 決算伝票締日
                        if (this.sokyuuShoriDateDen <= kanendoSokyuuDenpyouSimeDate)
                        {
                            object[] obj = new object[2];
                            obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(kanendoSokyuuDenpyouSimeDate), "yyyy/MM/dd", false);
                            obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(this.sokyuuShoriDateDen), "yyyy/MM/dd", false);

                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01217", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            obic7TextDatetimeHasseiDate.Focus();
                            return false;
                        }
                    }
                }
                if (this.kanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.SokyuuSumi)
                {
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01263", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    //　2010/09/16　変更　　　C.Okuno  (M04451)↓
                    //this.obic7TextStringCalledDenpyouNO.Focus();
                    this.obic7TextStringDenpyouKBN.Focus();
                    //　2010/09/16　変更　　　C.Okuno  (M04451)↑

                    return false;
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                //修正の場合決算期チェック
                if (obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    //修正前伝票区分が本伝の時のみ
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (ComATool.Function.AnyToInt32(prevDenpyouKBN) < 20)
                    if (this.prevHonKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //伝票区分 < 20 かつ伝票採番区分 = 0かつ (修正前.[決算期] <>  画面.[発生日]の[決算期]の場合) もしくは、(修正前.[月度] <> 画面.[発生日]の[月度])の場合
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 0 &&
                        //    (prevKessanki != kessanki || prevMonthNO != monthNO))
                        if (this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 0 &&
                            (prevKessanki != kessanki || prevMonthNO != monthNO))
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        {
                            object[] obj = new object[2];
                            obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(prevHasseiDate), "yyyy/MM/dd", false);
                            obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);

                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00241", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            obic7TextDatetimeHasseiDate.Focus();
                            return false;
                        }

                        //伝票区分 < 20 かつ伝票採番区分 = 1かつ 修正前.[決算期] <  画面.[発生日]の[決算期]の場合
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 1 &&
                        //    prevKessanki < kessanki)
                        if (this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 1 &&
                            prevKessanki < kessanki)
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        {
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00242", null, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            obic7TextDatetimeHasseiDate.Focus();
                            return false;
                        }

                        //伝票区分 < 20 かつ伝票採番区分 = 1かつ 修正前.[決算期] >  画面.[発生日]の[決算期]の場合
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && denpyouSaibanKBN == 1 &&
                        //    prevKessanki > kessanki)
                        if (this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && denpyouSaibanKBN == 1 &&
                            prevKessanki > kessanki)
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        {
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00243", null, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                            obic7TextDatetimeHasseiDate.Focus();
                            return false;
                        }
                    }

                    //伝票区分 >= 20 かつ仮伝票採番区分 = 0かつ 修正前.[決算期] <  画面.[発生日]の[決算期]の場合
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN == 0 &&
                    //    prevKessanki < kessanki)
                    if (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN == 0 &&
                        prevKessanki < kessanki)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00242", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        obic7TextDatetimeHasseiDate.Focus();
                        return false;
                    }

                    //伝票区分 >= 20 かつ仮伝票採番区分 = 0かつ 修正前.[決算期] >  画面.[発生日]の[決算期]の場合
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20 && kariDenpyouSaibanKBN == 0 &&
                    //    prevKessanki > kessanki)
                    if (this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou && kariDenpyouSaibanKBN == 0 &&
                        prevKessanki > kessanki)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00243", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        obic7TextDatetimeHasseiDate.Focus();
                        return false;
                    }
                }

                //伝票区分の脱出処理
                if (CheckDenpyouKBN(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextStringDenpyouKBN.Focus();
                    return false;
                }

                //修正の場合,本伝票→仮伝票修正チェック
                if (obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                    //if (ComATool.Function.AnyToInt32(prevDenpyouKBN) < 20 && ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) >= 20)
                    if (this.prevHonKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && this.honKaridenFlag == (Int32)HonKaridenFlag.KariDenpyou)
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    {
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00244", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        obic7TextStringDenpyouKBN.Focus();
                        return false;
                    }
                }

                //伝票番号の脱出処理
                if (CheckDenpyouNO(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextStringDenpyouNO.Focus();
                    return false;
                }

            }
            else
            {
                //事業所のチェック
                if (CheckZigyoushoCD(KBN_KOUMOKUCHK_ALL) == false)
                {
                    obic7TextStringZigyoushoCD.Focus();
                    return false;
                }
            }

            //明細の各項目のチェック
            if (CheckAllMeisai(KBN_ALLCHK_REQUIRE) == false)
            {
                return false;
            }

            //明細数 = 0の場合
            if (obic7MultilineCheckGridDetail.GetDisplayedData().Count == 0)
            {
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00245", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                //新規行の借方勘定科目にフォーカスセット
                obic7MultilineCheckGridDetail.GetColumnObject(0, COL_KARIKANJOUCD).Focus();
                return false;
            }

            //画面.借方総勘定科目コードが未入力で、貸方総勘定科目コードが未入力の行がある場合
            if (CheckEmptyRow() == false)
            {
                return false;
            }

            //明細部の明細数 > プライベート変数.入力伝票行数の場合
            if (obic7MultilineCheckGridDetail.GetDisplayedData().Count > inputKanouGyouCount)
            {
                object[] obj = new object[1];
                obj[0] = inputKanouGyouCount;

                if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00247", obj, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button2) == DialogResult.No
                )
                {
                    //元の項目へフォーカスセット
                    PrevControl.Focus();
                    return false;
                }
            }

            //登録チェック時のみ行う
            if (checkkbn == 1)
            {

                //画面.借方金額総合計 <> 貸方金額総合計の場合
                if (obic7TextNumberTotalKariSougaku.Value != obic7TextNumberTotalKasiSougaku.Value)
                {
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00248", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    //１行目の借方勘定科目にフォーカスセット
                    //2008/05/14 変更 N.Sasaki 開始
                    //                    obic7MultilineCheckGridDetail.SelectSpecifyRow(0, COL_KARIKANJOUCD);
                    SetFocusMeisaiCtl(KBN_KOUMOKUCHK_ALL, 0, COL_KARIKANJOUCD);
                    //2008/05/14 変更 N.Sasaki 終了
                    return false;

                }
            }

            //借方金額総合計が14桁以上の場合
            if (obic7TextNumberTotalKariSougaku.Value > 9999999999999)
            {
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00249", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                //１行目の借方勘定科目にフォーカスセット
                //2008/05/14 変更 N.Sasaki 開始
                //                obic7MultilineCheckGridDetail.SelectSpecifyRow(0, COL_KARIKANJOUCD);
                SetFocusMeisaiCtl(KBN_KOUMOKUCHK_ALL, 0, COL_KARIKANJOUCD);
                //2008/05/14 変更 N.Sasaki 終了

                return false;
            }

            //登録チェック時のみ行う
            if (checkkbn == 1)
            {
                //貸借判断処理を行い、仕訳区分を取得する
                if (GetSiwakeKBN() == false)
                {
                    return false;
                }

                //仕訳区分 = 1 かつ 借方総勘定科目コードが諸口科目コードの明細行がある場合
                if (CheckShokutiInHukugou() == false)
                {
                    return false;
                }
            }

            //明細の各項目のチェック
            if (CheckAllMeisai(KBN_ALLCHK_KOKUMOKU) == false)
            {
                return false;
            }

            return true;
        }

        #endregion

        #region 明細項目のALLチェック

        /// <summary>
        /// 明細項目のALLチェック
        /// </summary>
        /// <param name="checkkbn">1:必須チェック 2:項目脱出時のチェック</param>
        /// <returns></returns>
        private bool CheckAllMeisai(int checkkbn)
        {
            //仕訳画面データ取得
            DataView dataView = obic7MultilineCheckGridDetail.GetDisplayedData();

            int errorNumber = -1;
            int errorKBN = 0;

            if (checkkbn == 1)
            {
                //明細のエラープロバイダを解除
                ClearErrorProvider(2);

                //項目の必須チェック
                for (int i = 0; i < dataView.Count; i++)
                {
                    errorNumber = CheckMeisaiGyou(KBN_KOUMOKUCHK_ALL, i);
                    if (errorNumber != -1)
                    {
                        switch (errorNumber)
                        {
                            case COL_KARIBUNSEKICD4:
                            case COL_KARIBUNSEKICD5:
                            // 2013/05/15 削除 I.Nakagawa 開始 (GX)
                            //case COL_KARIPROJECTCD:
                            // 2013/05/15 削除 I.Nakagawa 終了 (GX)
                            case COL_KASIBUNSEKICD4:
                            case COL_KASIBUNSEKICD5:
                                // 2013/05/15 削除 I.Nakagawa 開始 (GX)
                                //case COL_KASIPROJECTCD:
                                // 2013/05/15 削除 I.Nakagawa 終了 (GX)
                                //分析情報画面起動
                                BunsekiJouhou(errorNumber, true);
                                break;
                            default:
                                break;
                        }
                        return false;
                    }
                }
            }
            else
            {
                for (int i = 0; i < dataView.Count; i++)
                {
                    //項目脱出時の処理
                    for (int taishakukbn = 1; taishakukbn <= 2; taishakukbn++)
