        // 2022/10/13 追加 D.Koga (210060-211112-211117)【インボイス対応】開始
        #region 取引先税区分整合性チェック処理
        /// <summary>
        /// 取引先税区分整合性チェック処理
        /// </summary>
        /// <returns>実行結果
        /// 0    :正常
        /// 99999:デッドロック
        /// 他   :個別エラー(メッセージコード2を返却)</returns>
        /// </returns>
        private int CheckTorihikisakiZeiKBNSeigousei()
        {
            var dt = new DataTable();

            using (SqlCommand sc = businessDB.NewSqlCommand())
            {
                sc.CommandType = CommandType.StoredProcedure;
                sc.CommandText = TORIHIKISAKIZEIKBN_SEIGOUSEI_CHECK;

                SqlParameter param1;
                param1 = sc.Parameters.Add("@po_ErrorKBN", SqlDbType.Int);
                param1.Direction = ParameterDirection.Output;

                SqlParameter param2;
                param2 = sc.Parameters.Add("@po_ErrorCD1", SqlDbType.VarChar, 128);
                param2.Direction = ParameterDirection.Output;

                SqlParameter param3;
                param3 = sc.Parameters.Add("@po_ErrorCD2", SqlDbType.VarChar, 128);
                param3.Direction = ParameterDirection.Output;

                SqlParameter param4;
                param4 = sc.Parameters.Add("@po_ErrorProcName", SqlDbType.VarChar, 128);
                param4.Direction = ParameterDirection.Output;

                SqlParameter param5;
                param5 = sc.Parameters.Add("@po_ErrorSummary", SqlDbType.VarChar, 256);
                param5.Direction = ParameterDirection.Output;

                SqlParameter param6;
                param6 = sc.Parameters.Add("@po_ErrorDetail", SqlDbType.VarChar, 2560);
                param6.Direction = ParameterDirection.Output;

                SqlParameter param7;
                param7 = sc.Parameters.Add("@po_ErrorBtnKBN", SqlDbType.TinyInt);
                param7.Direction = ParameterDirection.Output;

                SqlParameter param8;
                param8 = sc.Parameters.Add("@po_ErrorBtnDefault", SqlDbType.TinyInt);
                param8.Direction = ParameterDirection.Output;

                SqlParameter param9;
                param9 = sc.Parameters.Add("@p_YobidasiMotoKBN", SqlDbType.TinyInt);
                param9.Direction = ParameterDirection.Input;
                param9.Value = 0; // 入力ジョブ

                SqlParameter param10;
                param10 = sc.Parameters.Add("@p_OperationComputerName", SqlDbType.VarChar, 128);
                param10.Direction = ParameterDirection.Input;
                param10.Value = ComATool.Logic.CurrentUser.ComputerName;

                SqlParameter param11;
                param11 = sc.Parameters.Add("@p_OperationUserID", SqlDbType.VarChar, 128);
                param11.Direction = ParameterDirection.Input;
                param11.Value = ComATool.Logic.CurrentUser.UserID;

                SqlParameter param12;
                param12 = sc.Parameters.Add("@p_OperationJobID", SqlDbType.VarChar, 128);
                param12.Direction = ParameterDirection.Input;
                param12.Value = ComATool.Logic.CurrentUser.JobID;

                SqlParameter param13;
                param13 = sc.Parameters.Add("@p_UpdateDatetime", SqlDbType.DateTime);
                param13.Direction = ParameterDirection.Input;
                param13.Value = GetSystemDate();

                SqlParameter param14;
                param14 = sc.Parameters.Add("@p_UpdateCertificatedGuid", SqlDbType.UniqueIdentifier);
                param14.Direction = ParameterDirection.Input;
                param14.Value = ComATool.Logic.CurrentUser.CertificatedGuid;

                SqlParameter param15;
                param15 = sc.Parameters.Add("@p_UpdateJobID", SqlDbType.VarChar, 128);
                param15.Direction = ParameterDirection.Input;
                param15.Value = ComATool.Logic.CurrentUser.JobID;

                SqlParameter param16;
                param16 = sc.Parameters.Add("@p_UpdateUserID", SqlDbType.VarChar, 128);
                param16.Direction = ParameterDirection.Input;
                param16.Value = ComATool.Logic.CurrentUser.UserID;

                SqlParameter param17;
                param17 = sc.Parameters.Add("@p_UpdateComputerName", SqlDbType.VarChar, 128);
                param17.Direction = ParameterDirection.Input;
                param17.Value = ComATool.Logic.CurrentUser.ComputerName;

                SqlParameter param18;
                param18 = sc.Parameters.Add("@p_UpdateComputerUserName", SqlDbType.VarChar, 128);
                param18.Direction = ParameterDirection.Input;
                param18.Value = ComATool.Logic.CurrentUser.ComputerUserName;

                SqlParameter param19;
                param19 = sc.Parameters.Add("@p_UpdateComputerDomainName", SqlDbType.VarChar, 196);
                param19.Direction = ParameterDirection.Input;
                param19.Value = ComATool.Logic.CurrentUser.ComputerDomainName;

                try
                {
                    // 4-0-1.#チェック対象伝票格納WKに仕訳の情報をINSERTする
                    CreateCheckTaishouTable();

                    // 4-0-2.共通処理.取引先税区分整合性チェックを呼び出す。
                    using (SqlDataAdapter sa = new SqlDataAdapter(sc))
                    {
                        sa.Fill(dt);
                    }
                }
                #region エラー処理
                catch (SqlException ex)
                {
                    //【ストアドにて業務ロジック以外のエラー（システムエラー）発生時は、ここで例外を処理する。】
                    //メッセージ分類は「InternalError」、メッセージアイコンは「Error」とする。
                    //ロールバック、メッセージボックス表示処理は業務ロジックで行い、処理の中断のみ行う。
                    //アプリケーションは異常終了させない。
                    //注：この処理を行うのは、デッドロックの場合のみとする。

                    bool bDeadLockFlg = true;

                    //メッセージ詳細の組み立て
                    string[] objMsgDetail = new string[3];

                    //ストアド名
                    objMsgDetail[0] = ex.Procedure.ToString();
                    //エラーコード
                    objMsgDetail[1] = ex.Number.ToString();
                    //エラー内容
                    for (int i = 0; i < ex.Errors.Count; i++)
                    {
                        objMsgDetail[2] += ex.Errors[i].ToString();
                    }

                    //エラーがデッドロック以外の場合、フラグをfalseに設定する。
                    //ex.エラーコード = 1205 → デッドロック
                    //                = 2627 → キー重複
                    //                = 8134 → ゼロ除算
                    if (ex.Number != 1205)
                    {
                        bDeadLockFlg = false;
                    }

                    if (bDeadLockFlg == true)
                    {
                        //デッドロックの場合は、業務にてエラー処理を行う。

                        // ロールバック
                        this.businessDB.RollBackTransaction();

                        //メッセージボックス表示
                        WinAToolLogic.UI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00119", null, objMsgDetail, GetType()
                                                            , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK
                                                            , WinAToolLogic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                        return 99999;
                    }
                    else
                    {
                        //デッドロック以外のエラーはthrowして、共通クラスのエラー処理に委ねる。
                        throw;
                    }
                }

                //システムエラー発生時
                //（留意事項）エラー発生時、ストアドの「ERR_SHORI」ブロックで処理された結果のパラメータは、C＃側で参照することが出来ませ  ん。
                //            よってこの部分が処理されることはありませんが、明示的に共通部品の例外を発生させる例として記載しておきます。
                //【例外処理は、上記のcatch句内にて行います。】
                if (ComATool.Function.AnyToInt16(param1.Value) == 1)
                {
                    //業務にて想定の範囲外のエラーが発生した場合は、共通部品を使用して明示的に例外をスローし、呼び出し元にてCatchする。
                    //(例外スローによる上位処理(共通部品側処理)終了時、当JOBは強制終了される。)
                    throw new ComATool.Obic7Exception("想定外のエラーが発生しました。【詳細】ストアド名 = "
                                                       + param4.Value.ToString() + " エラー内容 = " + param6.Value.ToString());
                }

                //個別エラー発生時
                if (ComATool.Function.AnyToInt16(param1.Value) == 2)
                //業務にて想定の範囲内のエラーが発生した場合は、ストアドからの戻り値を取得して、メッセージボックスを表示する。
                {
                    // ロールバック
                    this.businessDB.RollBackTransaction();

                    return ComATool.Function.AnyToInt32(param3.Value);
                }
                #endregion
            }
            // 4-0-3.4-0-2の結果.件数 > 0の場合、以下の警告メッセージを作成する。
            //変数.メッセージ詳細

            if (ComATool.Function.IsValidDataTable(dt))
            {
                ComAToolLogic.Message msg = new ComAToolLogic.Message();
                msg.GetMessage(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30416");
                messageDetail = msg.MessageSummary;
            }
            return 0;
        }
        #endregion
        // 2022/10/13 追加 D.Koga (210060-211112-211117)【インボイス対応】終了

        #region 未入力行のチェック

        /// <summary>
