        private bool CheckEmptyRow()
        {
            //仕訳画面データ取得
            DataView dataView = obic7MultilineCheckGridDetail.GetDisplayedData();

            //未入力行のチェック
            for (int i = 0; i < dataView.Count; i++)
            {
