                {
                    //借方総勘定科目にフォーカスセット
                    //2008/05/14 変更 N.Sasaki 開始
                    //                    obic7MultilineCheckGridDetail.SelectSpecifyRow(i, COL_KARIKANJOUCD);
                    SetFocusMeisaiCtl(KBN_KOUMOKUCHK_ALL, i, COL_KARIKANJOUCD);
                    //2008/05/14 変更 N.Sasaki 終了

                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00246", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    return false;
                }
            }

            return true;
        }

