        #region 明細事業所伝票締日チェック
        /// <summary>
        /// 明細事業所伝票締日チェック
        /// </summary>
        /// <param name="checkkbn">1:登録時画面発生日と比較 2:削除時画面発生日と比較 3:登録時修正前発生日と比較</param>
        /// <returns></returns>
        private bool CheckZigyoushoDepyouSimeDate(int checkkbn)
        {

            string messageCD = "";
            if (checkkbn == 1)
            {
                //登録チェック時
                messageCD = "00240";
            }
            else if (checkkbn == 2)
            {
                //削除チェック時
                messageCD = "00237";
            }
            else if (checkkbn == 3)
            {
                //登録チェック時
                messageCD = "00664";
            }
            DataView dataView = obic7MultilineCheckGridDetail.GetDisplayedData();

            DateTime? hasseiDate = null;

            if (checkkbn == 1 || checkkbn == 2)
            {
                hasseiDate = obic7TextDatetimeHasseiDate.Value;
            }
            else
            {
                hasseiDate = prevHasseiDate;
            }

            //フォーカスの戻り先
            Obic7fx.Win.A0000.Tool.UI.Obic7TextAbstract focusControl;

            if (checkkbn == 1 || checkkbn == 3)
            {
                focusControl = obic7TextDatetimeHasseiDate;
            }
            else
            {
                focusControl = obic7TextStringCalledDenpyouNO;
            }

            //明細事業所伝票締日のチェック
            for (int i = 0; i < dataView.Count; i++)
            {
                //借方事業所コードのチェック
                if (String.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIZIGYOUSHOCD)) == false)
                {
                    //借方事業所の伝票締日チェック
                    if (GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIZIGYOUSHODENPYOSIMEDATE) != null && hasseiDate <= GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIZIGYOUSHODENPYOSIMEDATE))
                    {
                        object[] obj = new object[2];
                        obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIZIGYOUSHODENPYOSIMEDATE)), "yyyy/MM/dd", false);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                        //obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);
                        obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(hasseiDate), "yyyy/MM/dd", false);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, messageCD, obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                        focusControl.Focus();

                        return false;
                    }

                    if (hontenShuutyuuFlag == 1)
                    {
                        //借方本社事業所の伝票締日チェック
                        if (GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIHONSHAZIGYOUSHODENPYOSIMEDATE) != null && hasseiDate <= GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIHONSHAZIGYOUSHODENPYOSIMEDATE))
                        {
                            object[] obj = new object[2];
                            obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KARIHONSHAZIGYOUSHODENPYOSIMEDATE)), "yyyy/MM/dd", false);
                            //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                            //obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);
                            obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(hasseiDate), "yyyy/MM/dd", false);
                            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, messageCD, obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


                            focusControl.Focus();
                            return false;
                        }
                    }
                }

                //貸方事業所コードのチェック
                if (String.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIZIGYOUSHOCD)) == false)
                {
                    //貸方事業所の伝票締日チェック
                    if (GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIZIGYOUSHODENPYOSIMEDATE) != null && hasseiDate <= GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIZIGYOUSHODENPYOSIMEDATE))
                    {

                        //呼出伝票番号にフォーカスセット
                        focusControl.Focus();
                        object[] obj = new object[2];
                        obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIZIGYOUSHODENPYOSIMEDATE)), "yyyy/MM/dd", false);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                        //obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);
                        obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(hasseiDate), "yyyy/MM/dd", false);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        //エラーメッセージを表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, messageCD, obj, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                        focusControl.Focus();
                        return false;
                    }

                    if (hontenShuutyuuFlag == 1)
                    {
                        //貸方本社事業所の伝票締日チェック
                        if (GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIHONSHAZIGYOUSHODENPYOSIMEDATE) != null && hasseiDate <= GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIHONSHAZIGYOUSHODENPYOSIMEDATE))
                        {
                            //呼出伝票番号にフォーカスセット
                            focusControl.Focus();
                            object[] obj = new object[2];
                            obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(GetDatetimeColumnValue(KBN_KOUMOKUCHK_ALL, i, COL_KASIHONSHAZIGYOUSHODENPYOSIMEDATE)), "yyyy/MM/dd", false);
                            //　2010/08/16　変更　　　C.Okuno  (M04451)↓ 不具合修正
                            //obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);
                            obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(hasseiDate), "yyyy/MM/dd", false);
                            //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, messageCD, obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            focusControl.Focus();
                            return false;
                        }
                    }
                }
            }

            return true;
        }

