        #region 仕訳伝票の承認区分が変更されているかのチェック


        /// <summary>
        /// 仕訳伝票の承認区分が変更されているかのチェック
        /// </summary>
        /// <returns></returns>
        private bool CheckShouninStateKBNChanged()
        {
            //承認状態区分
            int shouninStateKBN;
            StringBuilder sb = new StringBuilder();

            sb.Append(" SELECT ");
            sb.Append("     ShouninStateKBN  ");
            sb.Append(" FROM  M0000RR_MA_SiwakeMeisai ");
            sb.Append(" WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + " ");

            //現在の承認区分を取得
            shouninStateKBN = ComATool.Function.AnyToInt32(businessDB.ExecuteScalar(ComATool.Function.AnyToString(sb)));

            //呼出時の承認状態区分と現在の承認状態区分を比較
            if (shouninJoutaiKBN != shouninStateKBN)
            {
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00744", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                return false;
            }

            return true;
        }


