        #region 待避配列データにデータを洗い換えする

        /// <summary>
        /// 待避配列データにデータを洗い換えする
        /// </summary>
        /// <param name="dispRowNo"></param>
        private void RefreshTempActiveInputDataRow(int dispRowNo)
        {
            if (ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, dispRowNo, COL_GYOUNO)) == 0)
            {
                //新規行時、待避配列データ初期化
                tempActiveInputDataRow = obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].NewRow();
            }
            else
            {
                int seq = GetBaseDataInnerSeq(dispRowNo);

                for (int i = COL_COUNT; i < COL_DATACOUNT; i++)
                {
                    //既存行時、待避配列データに既存データをセット
                    tempActiveInputDataRow[i] = obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows[seq][i];
                }
            }
        }

        #endregion

        #region BaseDataSetの行Seqを取得する

        /// <summary>
        /// BaseDataSetの行Seqを取得する
        /// </summary>
        /// <param name="dispRowNo">画面上の現在行</param>
        /// <returns></returns>
        private int GetBaseDataInnerSeq(int dispRowNo)
        {
            for (int i = 0; i < obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows.Count; i++)
            {
                if (ComATool.Function.AnyToInt32(obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows[i][COL_GYOUNO]) == ComATool.Function.AnyToInt32(((WinAToolUI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(dispRowNo, COL_GYOUNO)).Value))
                {
                    return i;
                }
            }
            return -1;
        }

