        #region SQL文直接発行用メソッド

        #region ExecuteNonQuery呼び出し

        /// <summary>
        /// ExecuteNonQueryを実行
        /// </summary>
        /// <param name="strSQL"></param>
        private bool SQLExecuteNonQueryMain(string strSQL)
        {

            //トランザクション開始
            businessDB.BeginTransaction();

            try
            {
                int iRetCD;

                iRetCD = SQLExecuteNonQuery(strSQL);

                if (iRetCD != 0)
                {
                    return false; //①DeleteSiwakeMeisaiにてエラー発生時、共通クラスに例外をcatchされないように、ここでreturnする。(下記②も参照)
                }
            }
            catch (Exception ex)
            {
                //ロールバック
                businessDB.RollBackTransaction();

                //例外をスロー(上位処理のCatchへ)
                throw ex;
            }

            //コミット
            businessDB.CommitTransaction();

            return true;
        }
        #endregion

        #region ExecuteNonQuery実行

        /// <summary>
        /// ExecuteNonQuery実行
        /// </summary>
        /// <param name="strSQL"></param>
        /// <returns></returns>
        private int SQLExecuteNonQuery(string strSQL)
        {
            using (SqlCommand sc = businessDB.NewSqlCommand())
            {
                sc.CommandType = CommandType.Text;
                sc.CommandText = strSQL;

                //SQL実行
                try
                {
                    sc.ExecuteNonQuery();
                }
                catch (SqlException ex)
                {
                    //【ストアドにて業務ロジック以外のエラー(システムエラー)発生時は、ここで例外を処理する。】
                    //メッセージ分類は「InternalError」、メッセージアイコンは「Error」とする。
                    //ロールバック、メッセージボックス表示処理は業務ロジックで行い、処理の中断のみ行う。
                    //アプリケーションは異常終了させない。
                    //注：この処理を行うのは、デッドロックの場合のみとする。

                    bool bDeadLockFlg = true;

                    //エラーがデッドロック以外の場合、フラグをfalseに設定する。
                    //ex.エラーコード = 1205 → デッドロック
                    //                = 2627 → キー重複
                    //                = 8134 → ゼロ除算
                    if (ex.Number != 1205)
                    {
                        bDeadLockFlg = false;
                    }

                    if (bDeadLockFlg == true)
                    {
                        //デッドロックの場合は、業務にてエラー処理を行う。

                        //ロールバック
                        businessDB.RollBackTransaction();

                        //メッセージボックス表示
                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00119", null, null, GetType(),
                                                             WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                             WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                        return 99999; //②このメソッドの呼び出し元(DeleteDenpyouメソッド)で例外をcatchされる為、ここでreturnさせる。(上記①も参照)
                    }
                    else
                    {
                        //デッドロック以外のエラーはthrowして、共通クラスのエラー処理に委ねる。
                        throw;
                    }
                }

                return 0;
            }
        }

        #endregion

