        private void densiShouhyouShori()
        {
            //呼び出した伝票について、財務伝票情報クラスのインスタンスを生成する。
            var denpyouInfo = new WinMToolModel.MA_DenpyouInfo
            {
                SystemDenpyouNO = decimal.Parse(systemDenpyouNO.ToString()),
                DenpyouNO = ComATool.Function.AnyToString(this.obic7TextStringCalledDenpyouNO.Value),
                HasseiDate = DateTime.Parse(ComATool.Function.AnyToString(this.obic7TextDatetimeHasseiDate.Value)),
                DenpyouTypeKBN = byte.Parse(denpyouTypeKBN.Value.ToString()),
                ZigyoushoCD = ComATool.Function.AnyToString(this.obic7TextStringZigyoushoCD.Value)
            };
            //電子証憑関連クラスのインスタンスを生成する。
            var evidence = new WinMToolLogic.MA_Evidence
            {
                OperationComputerName = ComATool.Logic.CurrentUser.ComputerName,
                OperationUserID = ComATool.Logic.CurrentUser.UserID,
                OperationDatetime = DateTime.Now,
                OperationJobID = ComATool.Logic.CurrentUser.JobID,
            };

            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            //電子証憑関連クラス.[電子証憑呼出処理]を実行する。
            //evidence.DensiShouhyouYobidasi(denpyouInfo);
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            //evidence.DensiShouhyouYobidasi(denpyouInfo, (byte)sonotaTenpuFileRiyouFLG);
            if (obic7ComboBoxMode.Text == MODE_TENPU)
            {
                //添付モードの場合は追加電子証憑紐づけデータからも証憑情報を取得する
                evidence.DensiShouhyouYobidasi(denpyouInfo, (byte)sonotaTenpuFileRiyouFLG, true);
            }
            else
            {
                evidence.DensiShouhyouYobidasi(denpyouInfo, (byte)sonotaTenpuFileRiyouFLG, false);
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            ////呼出時点で紐付いている電子証憑の情報を保持しておく。(電子証憑登録・照会画面とのやりとりで使用)
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            DataTable tuikaTenpuEvidenceData = new DataTable();

            if (obic7ComboBoxMode.Text == MODE_TENPU)
            {
                //呼び出し伝票をキーに 承認が完了していない追加添付証憑リストを取得
                SQLGetDataTable(MakeSQLSELECTTuikaTenpuData(), ref tuikaTenpuEvidenceData, false);
                tuikaTenpuEvidenceData.PrimaryKey = new DataColumn[] { tuikaTenpuEvidenceData.Columns["EvidenceGuid"] };
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            //shokiGuids = evidence.ShokiGuid;
            //evidenceKensuu = evidence.Kensuu;
            DataTable evidenceData = new DataTable();
            SQLGetDataTable(MakeSQLEvidenceData(EvidenceType.Densi), ref evidenceData, false);
            DataTable otherFileData = new DataTable();
            SQLGetDataTable(MakeSQLEvidenceData(EvidenceType.Sonota), ref otherFileData, false);

            //電子証憑復元クラス作成
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            //var restoreClass = CreateRestoreEvidenceClass(evidenceData);
            var restoreClass = CreateRestoreEvidenceClass(evidenceData, tuikaTenpuEvidenceData);
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            //通常ファイルクラス作成
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            //var otherFileClass = CreateOtherFileClass(otherFileData);
            var otherFileClass = CreateOtherFileClass(otherFileData, tuikaTenpuEvidenceData);
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            //伝票WK削除
            WinEvidence.Evidence.DeleteDenpyouWK(fileKidouGuid);

            //電子証憑伝票WK作成
            WinEvidence.Evidence.CreateDenpyouWK(fileKidouGuid, restoreClass, otherFileClass);

            //画面.[電子証憑枚数]に電子証憑関連クラスで取得した電子証憑の枚数を表示する。
            //this.obic7LabelStringDensiShouhyou.Text = "電子証憑" + evidenceKensuu.ToString() + "枚";
            this.obic7LabelStringDensiShouhyou.Text = GetEvidenceMaisuu();
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            if (obic7ComboBoxMode.Text == MODE_TENPU)
            {
                //追加添付関係の変数初期化
                yobidasiTenpuCount = 0;
                tuikaTenpuAnkenGuid = null;

                //呼び出し時時点で追加添付されている証憑の承認状態区分を退避
                yobidasiEvidenceShouninStateDic = GetAddEvidenceShouninStateDic();

                //呼び出し時時点で追加添付されている証憑の案件Guidを退避
                yobidasiTuikaTenpuAnkenGuid = GetAddEvidenceAnkenGuid();

                //呼び出し時時点で添付されている証憑の枚数を退避
                var yobidasiEvidenceData = businessDB.GetDataTable(MakeSQLSelectEvidence(systemDenpyouNO));
                if (ComATool.Function.IsValidDataTable(yobidasiEvidenceData))
                {
                    yobidasiTenpuCount = yobidasiEvidenceData.Rows.Count;
                }
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
        }
