        /// <summary>
        /// 電子証憑ワーク削除
        /// </summary>
        /// <returns></returns>
        private void DeleteEvidenceWK()
        {
            //SQL文編集用
            StringBuilder sbdelete = new StringBuilder();

            sbdelete.AppendLine(" DELETE WKEV");
            sbdelete.AppendLine(" FROM " + DENSIWKTBL + " WKEV");
            sbdelete.AppendLine(" WHERE OperationComputerName = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerName) + " ");
            sbdelete.AppendLine(" AND   OperationUserID       = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            sbdelete.AppendLine(" AND   OperationJobID        = " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                sbdelete.AppendLine(" AND   SystemDenpyouNO       = 0 ");
            }
            else
            {
                sbdelete.AppendLine(" AND   SystemDenpyouNO       = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + " ");
            }

            SQLExecuteNonQuery(sbdelete.ToString());
        }

        private void TaihiUpdateData(DataTable taishouData)
        {
            //テーブル内容更新処理
            for (int i = 0; i < taishouData.Rows.Count; i++)
            {
                if (taishouData.Rows[i]["EvidenceType"].ToString() == "3")
                {
                    taishouData.Rows[i]["FileName"] = taishouData.Rows[i]["FileName"].ToString() + taishouData.Rows[i]["Extension"].ToString();
                }
            }

            //列削除処理
            List<string> removeColumnName = new List<string>();
            foreach (DataColumn item in taishouData.Columns)
            {
                if (item.ColumnName != "EvidenceGuid"
                    && item.ColumnName != "VersionNO"
                    && item.ColumnName != "ShowOrder"
                    && item.ColumnName != "EvidenceType"
                    && item.ColumnName != "FileImage"
                    && item.ColumnName != "FileName"
                    && item.ColumnName != "Bikou")
                {
                    removeColumnName.Add(item.ColumnName);
                }
            }
            foreach (var item in removeColumnName)
            {
                taishouData.Columns.Remove(item);
            }

            //対象データを格納する一時テーブルを作成
            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_Taishou') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_Taishou ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_Taishou ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   [EvidenceGuid]     [uniqueidentifier] ");
            sbCreate.AppendLine("  ,[VersionNO]        [int] ");
            sbCreate.AppendLine("  ,[ShowOrder]        [int] ");
            sbCreate.AppendLine("  ,[EvidenceType]     [tinyint] NOT NULL          ");
            sbCreate.AppendLine("  ,[FileImage]        [varbinary] (MAX) NULL      ");
            sbCreate.AppendLine("  ,[FileName]         [nvarchar] (256) NULL       ");
            sbCreate.AppendLine("  ,[Bikou]            [nvarchar] (2048) NULL      ");
            sbCreate.AppendLine(" ) ");
            SQLExecuteNonQuery(sbCreate.ToString());

            //対象データをバルクコピー
            using (SqlCommand cm = businessDB.NewSqlCommand())
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(businessDB.NewSqlCommand().Connection, SqlBulkCopyOptions.CheckConstraints, cm.Transaction))
            {
                // フィールド名のマッピング
                foreach (var column in taishouData.Columns)
                {
                    bulkCopy.ColumnMappings.Add(column.ToString(), column.ToString());
                }

                //コピー先のテーブル名をセット
                bulkCopy.DestinationTableName = "#M0000WK_Taishou";
                //バルクコピー
                bulkCopy.WriteToServer(taishouData);
            }
        }

        private void InsertEvidenceWK()
        {
            //システム伝票番号を処理用に変換
            decimal? sysDenpyouNO = systemDenpyouNO;
            if (sysDenpyouNO == null)
            {
                sysDenpyouNO = 0;
            }

            //電子証憑登録画面で登録された電子証憑データを更新する
            StringBuilder sb = new StringBuilder();

            sb.AppendLine("INSERT INTO " + DENSIWKTBL + " ");
            sb.AppendLine("           ([OperationComputerName]");
            sb.AppendLine("           ,[OperationUserID]");
            sb.AppendLine("           ,[OperationDatetime]");
            sb.AppendLine("           ,[OperationJobID]");
            sb.AppendLine("           ,[SystemDenpyouNO]");
            sb.AppendLine("           ,[DenpyouNO]");
            sb.AppendLine("           ,[EvidenceGuid]");
            sb.AppendLine("           ,[EvidenceVersionNO]");
            sb.AppendLine("           ,[EvidenceShowOrder]");
            sb.AppendLine("           ,[HasseiSystemCategory]");
            sb.AppendLine("           ,[HasseiSystemCategoryEdaban]");
            sb.AppendLine("           ,[HasseiDenpyouNO]");
            sb.AppendLine("           ,[EvidenceType]");
            sb.AppendLine("           ,[Data]");
            sb.AppendLine("           ,[FileName]");
            sb.AppendLine("           ,[Memo]");
            sb.AppendLine("           ,[CompanyNO]");
            sb.AppendLine("           ,[UpdateDatetime]");
            sb.AppendLine("           ,[UpdateCertificatedGuid]");
            sb.AppendLine("           ,[UpdateJobID]");
            sb.AppendLine("           ,[UpdateUserID]");
            sb.AppendLine("           ,[UpdateComputerName]");
            sb.AppendLine("           ,[UpdateComputerUserName]");
            sb.AppendLine("           ,[UpdateComputerDomainName])");
            sb.AppendLine("     SELECT");
            sb.AppendLine("            " + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.ComputerName) + " ");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.UserID) + " ");
            sb.AppendLine("           ,GETDATE() ");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComATool.Logic.CurrentUser.JobID) + " ");
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                sb.AppendLine("           ,0");
            }
            else
            {
                sb.AppendLine("           ," + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + "");
            }
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                sb.AppendLine("           ,'0'");
            }
            else
            {
                sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(this.obic7TextStringCalledDenpyouNO.Value) + "");
            }
            sb.AppendLine("           ,TEMP.EvidenceGuid");
            sb.AppendLine("           ,TEMP.VersionNO");
            sb.AppendLine("           ,TEMP.ShowOrder");
            sb.AppendLine("           ,12");
            sb.AppendLine("           ,0");
            sb.AppendLine("           ,'0'");
            sb.AppendLine("           ,TEMP.EvidenceType");
            sb.AppendLine("           ,CASE WHEN TEMP.EvidenceType = 3 THEN TEMP.FileImage");
            sb.AppendLine("                 ELSE NULL ");
            sb.AppendLine("                 END AS Data ");
            sb.AppendLine("           ,CASE WHEN TEMP.EvidenceType = 3 THEN TEMP.FileName");
            sb.AppendLine("                 ELSE NULL ");
            sb.AppendLine("                 END AS FileName ");
            sb.AppendLine("           ,CASE WHEN TEMP.EvidenceType = 3 THEN TEMP.Bikou");
            sb.AppendLine("                 ELSE NULL ");
            sb.AppendLine("                 END AS Memo ");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeNumber(ComAToolLogic.CurrentUser.CompanyNO) + " AS CompanyNO");
            sb.AppendLine("           ,GETDATE() AS UpdateDatetime");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.CertificatedGuid) + " AS UpdateCertificatedGuid");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " AS UpdateJobID");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " AS UpdateUserID");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " AS UpdateComputerName");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerUserName) + " AS UpdateComputerUserName");
            sb.AppendLine("           ," + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerDomainName) + " AS UpdateComputerDomainName");
