        #region 電子証憑データ取得用SQL文の作成（その他関連データ更新用）
        /// <summary>
        /// 電子証憑データ取得用SQL文の作成（その他関連データ更新用）
        /// </summary>
        /// <returns></returns>
        private string MakeSQLSelectOtherFileData()
        {
            //SQL文編集用
            StringBuilder sb = new StringBuilder();

            sb.AppendLine("SELECT ");
            sb.AppendLine("  SystemDenpyouNO ");
            sb.AppendLine(" ,DenpyouNO ");
            sb.AppendLine(" ,EvidenceGuid ");
            sb.AppendLine(" ,EvidenceVersionNO ");
            sb.AppendLine(" ,EvidenceShowOrder ");
            sb.AppendLine(" ,HasseiSystemCategory ");
            sb.AppendLine(" ,EvidenceType ");
            sb.AppendLine(" ,Data ");
            sb.AppendLine(" ,FileName ");
            sb.AppendLine(" ,Memo ");
            sb.AppendLine(" ,'' AS ContentType ");//コンテンツタイプは仕訳入力内で取得するため空白で取得
            sb.AppendLine("FROM  " + DENSIWKTBL + " WK");
            sb.AppendLine("WHERE WK.OperationComputerName =" + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.ComputerName) + " ");
            sb.AppendLine("AND   WK.OperationUserID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.UserID) + " ");
            sb.AppendLine("AND   WK.OperationJobID = " + ComATool.Function.SqlEscapeVarchar(ComAToolLogic.CurrentUser.JobID) + " ");
            sb.AppendLine("AND   WK.SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(systemDenpyouNO) + "  ");
            sb.AppendLine("AND   WK.EvidenceType = 3 "); //3：その他添付
            sb.AppendLine("AND   WK.HasseiSystemCategory IN ( 10 , 12 ) ");
            sb.AppendLine("ORDER BY EvidenceShowOrder");

            return sb.ToString();
        }
