        #region 電子証憑ワークをFileDBの一時テーブルに更新
        /// <summary>
        /// 電子証憑ワークをFileDBの一時テーブルに更新（伝票の削除・更新時どちらでも使用するメソッド）
        /// </summary>
        /// <param name="data"></param>
        private void TaihiEvidenceData(DataTable data)
        {
            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_Evidence') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_Evidence ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_Evidence ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   [SystemDenpyouNO]            [decimal] (18, 0) NOT NULL  ");
            sbCreate.AppendLine("  ,[DenpyouNO]                  [varchar] (12) NOT NULL     ");
            sbCreate.AppendLine("  ,[EvidenceGuid]               [uniqueidentifier] NULL     ");
            sbCreate.AppendLine("  ,[EvidenceVersionNO]          [int] NULL                  ");
            sbCreate.AppendLine("  ,[EvidenceShowOrder]          [smallint] NULL             ");
            sbCreate.AppendLine("  ,[HasseiSystemCategory]       [tinyint] NULL              ");
            sbCreate.AppendLine("  ,[EvidenceType]               [tinyint] NULL              ");
            sbCreate.AppendLine("  ,[Data]                       [varbinary] (MAX) NULL      ");
            sbCreate.AppendLine("  ,[FileName]                   [nvarchar] (255) NULL        ");
            sbCreate.AppendLine("  ,[Memo]                       [nvarchar] (2048) NULL        ");
            sbCreate.AppendLine("  ,[ContentType]                [varchar] (256) NULL        ");
            sbCreate.AppendLine(" ) ");
            fileDB.ExecuteNonQuery(sbCreate.ToString());

            //TODO 引数で渡ってきた電子証憑ワークデータのうち、fileNameから拡張子を取得しDataTableに格納する・Guidも格納する
            //コンテンツタイプを取得しDataTableに格納する
            for (int i = 0; i < data.Rows.Count; i++)
            {
                string extension = "";
                string contentType = null;
                string targetFileName = data.Rows[i]["FileName"].ToString();
                // ファイルの拡張子を取得
                if (targetFileName.LastIndexOf(".") > 0)
                {
                    // 入力したファイル名の拡張子を取得
                    extension = Obic7fx.Core.A0000.Tool.Function.Right(targetFileName, targetFileName.Length - targetFileName.LastIndexOf("."));
                    contentType = CoreATool.FileInformation.GetContentTypeByExtension(extension);
                    data.Rows[i]["ContentType"] = contentType;
                }
            }

            //明細データをバルクコピー
            using (SqlCommand cm = fileDB.NewSqlCommand())
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(fileDB.NewSqlCommand().Connection, SqlBulkCopyOptions.CheckConstraints, cm.Transaction))
            {
                //コピー先のテーブル名をセット
                bulkCopy.DestinationTableName = "#M0000WK_Evidence";


                //バルクコピー
                bulkCopy.WriteToServer(data);
            }
        }
