        #region 電子証憑復元クラス作成
        /// <summary>
        /// 電子証憑復元クラス作成
        /// </summary>
        /// <param name="evidenceData"></param>
        /// <returns></returns>
        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
        //private List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiRestoreEvidence> CreateRestoreEvidenceClass(DataTable evidenceData)
        private List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiRestoreEvidence> CreateRestoreEvidenceClass(DataTable evidenceData, DataTable tuikaTenpuEvidenceData)
        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
        {
            var restoreClass = new List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiRestoreEvidence>();
            byte hasseiSystemCategory = 0;
            if (evidenceData.Rows.Count > 0)
            {
                for (int i = 0; i < evidenceData.Rows.Count; i++)
                {
                    hasseiSystemCategory = byte.Parse(evidenceData.Rows[i]["HasseiSystemCategory"].ToString());
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    bool isReadOnlyFLG = false;
                    if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        var tuikaTenpuEvidence = tuikaTenpuEvidenceData.Select("EvidenceGuid = '" + evidenceData.Rows[i]["EvidenceGuid"].ToString() + "'");

                        //操作対象の電子証憑Guidが追加電子証憑紐付データに存在しない場合（添付モード以外で添付された証憑）
                        if (!tuikaTenpuEvidence.Any())
                        {
                            isReadOnlyFLG = true;
                        }
                        //操作対象の電子証憑Guidが追加電子証憑紐付データに存在する場合（添付モードで添付された証憑）
                        else
                        {
                            //追加添付された証憑が最終承認まで完了していれば読み取り専用扱いにする
                            if (!string.IsNullOrEmpty(tuikaTenpuEvidence[0]["GuidAnken"].ToString()) && tuikaTenpuEvidence[0]["ShouninStateKBN"].ToString() == "50")
                            {
                                isReadOnlyFLG = true;
                            }
                        }
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                    var data = new Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiRestoreEvidence()
                    {
                        EvidenceKey = new Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidenceKey()
                        {
                            EvidenceGuid = (Guid)evidenceData.Rows[i]["EvidenceGuid"],
                            LinkNO = 0,
                            ShowOrder = int.Parse(evidenceData.Rows[i]["EvidenceShowOrder"].ToString()),
                            VersionNO = string.IsNullOrEmpty(evidenceData.Rows[i]["EvidenceVersionNO"].ToString()) ? null : (int?)(int.Parse(evidenceData.Rows[i]["EvidenceVersionNO"].ToString()))
                        },
                        IsDeletable = hasseiSystemCategory == 12 ? true : false,
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                        //IsReadOnly = false,
                        IsReadOnly = isReadOnlyFLG,
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                        IsReadOnlyEvidenceType = true
                    };
                    restoreClass.Add(data);
                }
            }
            return restoreClass;
        }
