        /// <summary>
        /// 通常ファイルクラス作成
        /// </summary>
        /// <param name="otherFileData"></param>
        /// <returns></returns>
        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
        //private List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidence> CreateOtherFileClass(DataTable otherFileData)
        private List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidence> CreateOtherFileClass(DataTable otherFileData, DataTable tuikaTenpuEvidenceData)
        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
        {
            byte hasseiSystemCategory = 0;
            var evidenceClass = new List<Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidence>();
            var fileName = "";
            var extension = "";
            if (otherFileData.Rows.Count > 0)
            {
                for (int i = 0; i < otherFileData.Rows.Count; i++)
                {
                    hasseiSystemCategory = byte.Parse(otherFileData.Rows[i]["HasseiSystemCategory"].ToString());
                    // ファイル名と拡張子に分断
                    fileName = "";
                    extension = "";
                    var fullName = otherFileData.Rows[i]["FileName"].ToString();
                    if (fullName.LastIndexOf(".") > 0)
                    {
                        fileName = Obic7fx.Core.A0000.Tool.Function.Left(fullName, fullName.LastIndexOf("."));
                        extension = Obic7fx.Core.A0000.Tool.Function.Right(fullName, fullName.Length - fullName.LastIndexOf("."));
                    }

                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    bool isReadOnlyFLG = false;
                    if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        var tuikaTenpuEvidence = tuikaTenpuEvidenceData.Select("EvidenceGuid = '" + otherFileData.Rows[i]["EvidenceGuid"].ToString() + "'");

                        //操作対象の電子証憑Guidが追加電子証憑紐付データに存在しない場合（添付モード以外で添付された証憑）
                        if (!tuikaTenpuEvidence.Any())
                        {
                            isReadOnlyFLG = true;
                        }
                        //操作対象の電子証憑Guidが追加電子証憑紐付データに存在する場合（添付モードで添付された証憑）
                        else
                        {
                            //追加添付された証憑が最終承認まで完了していれば読み取り専用扱いにする
                            if (!string.IsNullOrEmpty(tuikaTenpuEvidence[0]["GuidAnken"].ToString()) && tuikaTenpuEvidence[0]["ShouninStateKBN"].ToString() == "50")
                            {
                                isReadOnlyFLG = true;
                            }
                        }
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

                    var data = new Obic7fx.Win.B0000.Tool.Logic.Evidence.Evidence.KaikeiEvidence()
                    {
                        EvidenceGuid = (Guid)otherFileData.Rows[i]["EvidenceGuid"],
                        FileName = fileName,
                        Extension = extension,
                        Bikou = otherFileData.Rows[i]["Memo"].ToString(),
                        FileImage = (byte[])otherFileData.Rows[i]["Data"],
                        ShowOrder = int.Parse(otherFileData.Rows[i]["EvidenceShowOrder"].ToString()),
                        LinkNO = 0,
                        IsDeletable = hasseiSystemCategory == 12 ? true : false,
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                        //IsReadOnly = false,
                        IsReadOnly = isReadOnlyFLG,
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                        IsReadOnlyEvidenceType = true
                    };
                    evidenceClass.Add(data);
                }
            }
            return evidenceClass;
        }
