        /// <summary>
        /// 修正モードで削除されたその他添付の証憑を削除
        /// </summary>
        /// <returns></returns>
        private string MakeSQLDeleteAlreadyRegisteredFile(DataTable abbDenpyouWKData)
        {
            MakeAlreadyRegisteredFileDeleteData(abbDenpyouWKData);

            StringBuilder sb = new StringBuilder();
            sb.AppendLine(" DELETE MAIN FROM " + FILE + " AS MAIN ");
            sb.AppendLine(" INNER JOIN #M0000WK_DeleteAlreadyRegisteredEvidence AS WK ");
            sb.AppendLine(" ON  MAIN.FileGuid = WK.EvidenceGuid ");
            sb.AppendLine(Environment.NewLine);
            sb.AppendLine(" DELETE MAIN FROM " + FILESUB + " AS MAIN ");
            sb.AppendLine(" INNER JOIN #M0000WK_DeleteAlreadyRegisteredEvidence AS WK ");
            sb.AppendLine(" ON  MAIN.EvidenceGuid = WK.EvidenceGuid ");

            return ComATool.Function.AnyToString(sb);
        }

        /// <summary>
        /// 修正モードで削除されたその他添付の証憑を一時ワークに格納
        /// </summary>
        private void MakeAlreadyRegisteredFileDeleteData(DataTable abbDenpyouWKData)
        {
            StringBuilder sbCreate = new StringBuilder();
            sbCreate.AppendLine(" IF EXISTS (SELECT * FROM tempdb.sys.objects WHERE object_id = OBJECT_ID('tempdb..#M0000WK_DeleteAlreadyRegisteredEvidence') AND type = N'U') ");
            sbCreate.AppendLine(" BEGIN ");
            sbCreate.AppendLine(" DROP TABLE #M0000WK_DeleteAlreadyRegisteredEvidence ");
            sbCreate.AppendLine(" END ");
            sbCreate.AppendLine(" CREATE TABLE #M0000WK_DeleteAlreadyRegisteredEvidence ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   [EvidenceGuid]               [uniqueidentifier] NOT NULL     ");
            sbCreate.AppendLine(" ) ");
            sbCreate.AppendLine(" CREATE INDEX IX_#M0000WK_DeleteAlreadyRegisteredEvidence ON [#M0000WK_DeleteAlreadyRegisteredEvidence] ");
            sbCreate.AppendLine(" ( ");
            sbCreate.AppendLine("   [EvidenceGuid]  ");
            sbCreate.AppendLine(" ) ");
            fileDB.ExecuteNonQuery(sbCreate.ToString());

            // ABBの伝票WKで論理削除でかつその他添付のファイルデータを取得
            var taishouData = abbDenpyouWKData.AsEnumerable().Where(x => x["State"].ToString() == "4" && (byte)x["EvidenceType"] == 3);

            var taishouDataTable = new DataTable();
            taishouDataTable.Columns.Add("EvidenceGuid", typeof(Guid));

            foreach (var item in taishouData)
            {
                var row = taishouDataTable.NewRow();
                row["EvidenceGuid"] = item["EvidenceGuid"];
                taishouDataTable.Rows.Add(row);
            }

            if (taishouDataTable.Rows.Count == 0)
            {
                return;
            }

            //バルクコピー
            using (SqlCommand cm = fileDB.NewSqlCommand())
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(fileDB.NewSqlCommand().Connection, SqlBulkCopyOptions.CheckConstraints, cm.Transaction))
            {
                //コピー先のテーブル名をセット
                bulkCopy.DestinationTableName = "#M0000WK_DeleteAlreadyRegisteredEvidence";
                //バルクコピー
                bulkCopy.WriteToServer(taishouDataTable);
            }
        }
