        #region 列削除処理
        private DataTable CutColumn(DataTable data, ClassType classType)
        {
            //列削除処理
            List<string> removeColumnName = new List<string>();
            foreach (DataColumn item in data.Columns)
            {
                if (classType == ClassType.EvidenceLinkInfo)
                {
                    if (item.ColumnName != "EvidenceGuid" && item.ColumnName != "VersionNO" && item.ColumnName != "ShowOrder" && item.ColumnName != "LinkNO" && item.ColumnName != "EvidenceType")
                    {
                        removeColumnName.Add(item.ColumnName);
                    }
                }
                else if (classType == ClassType.OtherData)
                {
                    if (item.ColumnName != "EvidenceGuid" && item.ColumnName != "ShowOrder" && item.ColumnName != "LinkNO" && item.ColumnName != "FileImage" && item.ColumnName != "Bikou")
                    {
                        removeColumnName.Add(item.ColumnName);
                    }
                }
            }
            foreach (var item in removeColumnName)
            {
                data.Columns.Remove(item);
            }
            return data;
        }
