        #region F2キー（伝票検索）の実処理
        /// <summary>
        /// F2キー（伝票検索）の実処理
        /// </summary>
        private void F2Action()
        {
            //伝票検索画面のインスタンスを作成
            using (WinMToolSearch.MA_SiwakeDenpyouNO siwakeDenpyouNO = new WinMToolSearch.MA_SiwakeDenpyouNO(ComAToolLogic.CurrentUser.JobID))
            {
                //プロパティセット

                //処理モード
                if (obic7ComboBoxMode.Text == MODE_INSERT)
                {
                    siwakeDenpyouNO.ShoriMode = 1;
                }
                else if (obic7ComboBoxMode.Text == MODE_UPDATE)
                {
                    siwakeDenpyouNO.ShoriMode = 2;
                }
                else if (obic7ComboBoxMode.Text == MODE_DELETE)
                {
                    siwakeDenpyouNO.ShoriMode = 3;
                }
                else if (obic7ComboBoxMode.Text == MODE_SELECT)
                {
                    siwakeDenpyouNO.ShoriMode = 4;
                }
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                else if (obic7ComboBoxMode.Text == MODE_TENPU)
                {
                    siwakeDenpyouNO.ShoriMode = 4;
                }
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                //伝票タイプ
                siwakeDenpyouNO.DenpyouType = 3;
                //事業所コード
                // 2008/08/08 T.Ota 変更開始 伝票番号検索起動時、事業所コードは入力値をそのまま渡す
                //siwakeDenpyouNO.ZigyoushoCD = obic7TextStringZigyoushoCD.Value;
                siwakeDenpyouNO.ZigyoushoCD = obic7TextStringZigyoushoCD.Text;
                // 2008/08/08 T.Ota 変更終了

                //基準日
                siwakeDenpyouNO.KijunDate = (DateTime)obic7TextDatetimeHasseiDate.Value;
                //伝票区分
                siwakeDenpyouNO.DenpyouKBN = obic7TextStringDenpyouKBN.Value;
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //基準区分
                siwakeDenpyouNO.KijunKBN = ComATool.Function.AnyToInt32(this.obic7TextNumberKijunKBN.Value);
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                //メモ使用フラグ
                siwakeDenpyouNO.MemoSiyouFlag = this.memoSiyouFlag;
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

                if (siwakeDenpyouNO.CheckExecute())
                {
                    //伝票検索画面をモーダル表示
                    siwakeDenpyouNO.ShowDialog();
                }

                //伝票番号が返ってきた場合
                if (String.IsNullOrEmpty(siwakeDenpyouNO.DenpyouNO) == false)
                {
                    // ↓ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正
                    if (obic7MultilineCheckGridDetail.Enabled == true)
                    {
                        if ((obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_DELETE) && siwakeDenpyouNO.DenpyouNO != prevCalledDenpyouNO)
                        {
                            isHaitaDelFlg = true;
                            preSystemDenpyouNO = systemDenpyouNO;
                            //排他削除処理
                            int iRetCD;
                            iRetCD = HaitaSetData(KBN_HAITA_SAKUJO);
                            if (iRetCD != 0)
                            {
                                isHaitaDelFlg = false;
                                return;
                            }
                        }
                        isHaitaDelFlg = false;
                    }
                    // ↑ 2011/06/23 変更 S.Harada (M04615)修正・削除処理の場合に呼出伝票番号を変更すると変更前伝票の受入状態区分が「サブシステム処理中」状態となる不具合修正

                    //伝票番号セット
                    obic7TextStringCalledDenpyouNO.Value = siwakeDenpyouNO.DenpyouNO;
                    //検索用システム伝票番号
                    kensakuSystemDenpyouNO = siwakeDenpyouNO.SystemDenpyouNO;
                    //転送モードセット
                    kensakuTensouMode = siwakeDenpyouNO.TransferMode;
                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                    //メモ複写フラグセット
                    this.memoHukushaFlag = siwakeDenpyouNO.MemoHukushaFlag;
                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

                    //伝票番号の確定処理
                    if (ValidatingCalledDenpyouNO(KBN_KOUMOKUCHK_AFTERSETVALUE) == false)
                    {
                        //転送モードリセット
                        kensakuTensouMode = null;
                        //検索用システム伝票番号リセット
                        kensakuSystemDenpyouNO = null;
                        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                        //メモ複写フラグリセット
                        this.memoHukushaFlag = 0;
                        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
                        return;
                    }

                    obic7TextStringCalledDenpyouNO.CausesValidation = false;

                    obic7TextStringHeadDummy.Focus();

                    obic7TextStringCalledDenpyouNO.CausesValidation = true;

                    //伝票番号再セット
                    obic7TextStringCalledDenpyouNO.Value = siwakeDenpyouNO.DenpyouNO;

                    //呼出伝票番号を待避
                    prevCalledDenpyouNO = obic7TextStringCalledDenpyouNO.Value;

                    if (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE)
                    {
                        //新規、修正時は発生日にフォーカスセット
                        obic7TextDatetimeHasseiDate.Focus();
                    }
                    else if (obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_SELECT)
                    {
                        //削除、照会は呼出伝票番号にフォーカスセット
                        obic7TextStringCalledDenpyouNO.Focus();
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    else if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        //添付モードの場合、電子証憑ボタンにフォーカス遷移・F10添付登録を使用可能にする
                        this.obic7ButtonWithLogicDensiShouhyou.Focus();
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

                    //転送モードリセット
                    kensakuTensouMode = null;
                    //検索用システム伝票番号リセット
                    kensakuSystemDenpyouNO = null;
                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                    //メモ複写フラグリセット
                    this.memoHukushaFlag = 0;
                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
                    //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                    //電子証憑関連処理
                    //[電子証憑OP導入フラグ]=true(導入済)の場合 かつ 画面.[処理モード]<>[新規]の場合 のみ処理を行う。
                    //※新規複写では電子証憑を複写しない為。
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    //if ((isAvailableEvidence == true) && (obic7ComboBoxMode.Text != MODE_INSERT))
                    if ((isFileTenpuUse== true) && (obic7ComboBoxMode.Text != MODE_INSERT))
                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
                    {
                        densiShouhyouShori();
                    }
                    //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了
                }
                else
                {
                    PrevControl.Focus();
                }
            }
        }
        #endregion

        #region F3キー（削除）の実処理
        /// <summary>
        /// F3キー（削除）の実処理
        /// </summary>
        private void F3Action()
        {
            //エラー有無
            //モードにより処理を分岐
            if (obic7ComboBoxMode.Text != MODE_DELETE)
            {
                if (obic7MultilineCheckGridDetail.IsNewRow() == false)
                {

                    //確認メッセージ
                    if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00109", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button2) == DialogResult.Yes
                        )
                    {
                        WinAToolUI.Obic7TextAbstract textAbstract = null;

                        //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 開始↓
                        if (ActiveControl.Name == "obic7ButtonWithLogicKariMemo")
                        {
                            obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KARIKANJOUCD).Focus();
                        }
                        if (ActiveControl.Name == "obic7ButtonWithLogicKasiMemo")
                        {
                            obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KASIKANJOUCD).Focus();
                        }
                        //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 終了↑

                        //旧value
                        textAbstract = PrevControl as WinAToolUI.Obic7TextAbstract;

                        WinAToolUI.Obic7TextAbstract textAbstractDummy = null;

                        //行番号取得
                        int rowNo = ComATool.Function.AnyToInt32(textAbstract.Parent.Tag);

                        //検証処理を起こさない
                        textAbstract.CausesValidation = false;

                        obic7MultilineCheckGridDetail.GetColumnObject(rowNo, "obic7TextStringDummy2").Focus();

                        textAbstract.CausesValidation = true;

                        textAbstractDummy = (WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, "obic7TextStringDummy2");

                        textAbstractDummy.CausesValidation = false;

                        //削除モード以外：行削除
                        obic7MultilineCheckGridDetail.RowDelete(PrevControl);

                        //ツールチップテキストをセット
                        SetToolTip(1);

                        //待避配列データを洗い換えする(削除後に行が変わるため)
                        RefreshTempActiveInputDataRow(rowNo);

                        textAbstract.Focus();
                        textAbstractDummy.CausesValidation = true;
                    }
                }
            }
            else
            {
                //2009/02/05  変更　T.Nakano  開始　(M04150)削除モード時、伝票番号を呼び出し後、呼出伝票番号を変更し、そのまま削除ボタンを押したときに変更前の伝票番号内容が削除される不具合を改修
                //該当項目の脱出処理を行う
                if (!this.Validate())
                {
                    return;
                }
                //2009/02/05  変更　T.Nakano  終了

                //  2016/02/02  追加 T.Sato  (36053)決算伝票締日がチェックされない場合がある  開始
                //財務コントロールマスタの情報を再取得
                GetZaimuControlMaster();
                //  2016/02/02  追加 T.Sato  (36053)決算伝票締日がチェックされない場合がある  終了

                //事業所のチェック
                if (CheckZigyoushoCD(KBN_KOUMOKUCHK_ALL) == false)
                {
                    this.obic7TextStringCalledDenpyouNO.Focus();
                    return;
                }

                //仕訳画面データ取得
                DataView dataView = obic7MultilineCheckGridDetail.GetDisplayedData();

                int errorKBN = 0;
                //明細事業所のチェック
                for (int i = 0; i < dataView.Count; i++)
                {
                    //項目脱出時の処理
                    for (int taishakukbn = 1; taishakukbn <= 2; taishakukbn++)
                    {
                        //事業所コードのチェック
                        errorKBN = CheckMeisaiZigyoushoCD(i, taishakukbn, KBN_KOUMOKUCHK_ALL);
                        if (errorKBN != KBN_CHECK_OK)
                        {
                            this.obic7TextStringCalledDenpyouNO.Focus();
                            return;
                        }
                    }
                }

                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                if (this.kanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.Taishougai)
                {
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                    //決算伝票締日チェック
                    //決算フラグ = 1(決算仕訳) の場合
                    if (kessanFlg == 1)
                    {
                        if (kessanDenpyouSimeDate != null)
                        {
                            //発生日 <= 決算伝票締日
                            if (obic7TextDatetimeHasseiDate.Value <= kessanDenpyouSimeDate)
                            {
                                object[] obj = new object[2];
                                obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(kessanDenpyouSimeDate), "yyyy/MM/dd", false);
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);

                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00236", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                this.obic7TextStringCalledDenpyouNO.Focus();
                                return;
                            }
                        }
                    }

                    //伝票締日チェック
                    //決算フラグ <> 1(決算仕訳) の場合
                    if (kessanFlg != 1)
                    {
                        if (denpyouSimeDate != null)
                        {

                            //発生日 <= 伝票締日
                            if (obic7TextDatetimeHasseiDate.Value <= denpyouSimeDate)
                            {
                                object[] obj = new object[2];
                                obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(denpyouSimeDate), "yyyy/MM/dd", false);
                                obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(obic7TextDatetimeHasseiDate.Value), "yyyy/MM/dd", false);

                                //エラーメッセージを表示
                                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00237", obj, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                this.obic7TextStringCalledDenpyouNO.Focus();
                                return;
                            }
                        }

                        //明細事業所伝票締日チェック
                        if (CheckZigyoushoDepyouSimeDate(2) == false)
                        {
                            return;
                        }
                    }
                    //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                }
                if (this.kanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.Taishou)
                {
                    if (kanendoSokyuuDenpyouSimeDate != null)
                    {
                        //伝票区分M.[遡及処理年月日] <= 過年度遡及伝票締日
                        if (this.sokyuuShoriDateDen <= kanendoSokyuuDenpyouSimeDate)
                        {
                            object[] obj = new object[2];
                            obj[0] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(kanendoSokyuuDenpyouSimeDate), "yyyy/MM/dd", false);
                            obj[1] = ComATool.Function.FormatDate(ComATool.Function.AnyToString(this.sokyuuShoriDateDen), "yyyy/MM/dd", false);

                            //エラーメッセージを表示
                            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01215", obj, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                            this.obic7TextStringCalledDenpyouNO.Focus();

                            return;
                        }
                    }
                }
                if (this.kanendoSokyuuShuuseiFlag == (Int32)KanendoSokyuuShuuseiFlag.SokyuuSumi)
                {
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01261", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    this.obic7TextStringCalledDenpyouNO.Focus();

                    return;
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑

                //削除モード:データ削除
                //確認メッセージ
                if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00111", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button2) == DialogResult.Yes
                    )
                {

                    //承認要否区分が必要の場合
                    if (shouninKBN == 0)
                    {
                        //承認状態区分変更チェック
                        if (CheckShouninStateKBNChanged() == false)
                        {
                            obic7TextStringCalledDenpyouNO.Focus();
                            return;
                        }
                    }

                    //Yesの場合削除を行う
                    //トランザクション
                    businessDB.BeginTransaction();
                    // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                    {
                        fileDB.BeginTransaction();
                    }
                    // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                    try
                    {
                        //データ削除
                        int iRetCD;
                        iRetCD = DeleteSiwake();
                        if (iRetCD != 0)
                        {
                            return;
                        }
                        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                        //メモ情報データ削除
                        if (!this.DeleteMemoData(MEMORRTBL))
                        {
                            return;
                        }
                        //連携メモ情報データ削除
                        if (!this.DeleteMemoData(RENKEIMEMORRTBL))
                        {
                            return;
                        }
                        //本支店メモ情報データ削除
                        if (!this.DeleteMemoData(HONSITENMEMORRTBL))
                        {
                            return;
                        }
                        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        //if (shouninKBN == 0 && ComATool.Function.AnyToInt32(obic7TextStringDenpyouKBN.Value) < 20 && ankenGuid != null)
                        if (shouninKBN == 0 && this.honKaridenFlag == (Int32)HonKaridenFlag.HonDenpyou && ankenGuid != null)
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        {
                            #region ワークフローの処理
                            // out引数
                            string messageCD1 = null;
                            string messageCD2 = null;

                            // in引数

                            Guid guidAnken;//案件Guid

                            //案件Guid
                            guidAnken = (Guid)ankenGuid;

                            //out引数
                            string systemCategoryForMsg = "";
                            string customizeSEQForMsg = "";

                            //承認申請の破棄
                            // 2008/08/20 T.Ota 変更開始 WF登録処理の引数変更対応
                            //if (this.wfExecuter.Destroy(out systemCategoryForMsg, out customizeSEQForMsg
                            //                           , out messageCD1, out messageCD2
                            //                           , guidAnken, null) != WFExecuter.ReturnValue.Normal)
                            if (this.wfExecuter.Destroy(out systemCategoryForMsg, out customizeSEQForMsg
                                              , out messageCD1, out messageCD2
                                                       , guidAnken, null, businessDB) != WFExecuter.ReturnValue.Normal)
                            // 2008/08/20 T.Ota 変更終了
                            {
                                //ロールバック
                                businessDB.RollBackTransaction();
                                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                                if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                                {
                                    fileDB.RollBackTransaction();
                                }
                                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                                // メッセージボックスを表示
                                WinATool.Logic.UI.Obic7MessageBox.Show(systemCategoryForMsg, customizeSEQForMsg, messageCD1, messageCD2, null, null, this.GetType(),
                                                    WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinATool.Logic.UI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                return;
                            }
                            #endregion
                        }

                        // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                        if (isAvailableEvidence)
                        {
                            //電子証憑基盤接続クラス.[電子証憑伝票WK取得処理]を使用して伝票WKの情報を取得する。
                            var denpyouWKData = WinEvidence.Evidence.GetDenpyouWK(fileKidouGuid, false, false, false);
                            var updateTaishou = new DataTable();
                            var updateCollection = denpyouWKData.AsEnumerable().Where(x => x["IsDeletable"].ToString() == "True" && byte.Parse(x["EvidenceType"].ToString()) != 3);
                            if (updateCollection.Count() > 0)
                            {
                                updateTaishou = updateCollection.CopyToDataTable();

                                //電子証憑基盤接続クラス.[電子証憑削除処理]を使用して電子証憑データとの関連を削除する。
                                WinEvidence.Evidence.DeleteEvidence(updateTaishou, "M_ET", "M_Evi");
                            }

                            WinEvidence.Evidence.DeleteDenpyouWK(fileKidouGuid);
                        }
                        if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                        {
                            //オペレーション項目をキーにして電子証憑ワークの情報を取得する
                            DataTable otherFileData = null;
                            SQLGetDataTable(MakeSQLSelectOtherFileData(), ref otherFileData, false);

                            //FileDBで使用するために、電子証憑ワークの内容を一時テーブルに格納する
                            TaihiEvidenceData(otherFileData);

                            //接続先FileDBへ削除更新を行う
                            fileDB.ExecuteNonQuery(MakeSQLDeleteFileByGuid());
                            fileDB.ExecuteNonQuery(MakeSQLDeleteFileSubByGuid());
                        }

                        //共通処理「伝票番号紐付データ更新処理」
                        UpdateRelationData();
                        //コントロールクリア
                        this.obic7LabelStringDensiShouhyou.Text = "";
                        if (isFileTenpuUse)
                        {
                            WinEvidence.Evidence.DeleteDenpyouWK(fileKidouGuid);
                        }
                        // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                        //コミット
                        businessDB.CommitTransaction();
                        // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                        if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                        {
                            fileDB.CommitTransaction();
                        }
                        // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                        //排他削除処理
                        iRetCD = HaitaSetData(KBN_HAITA_SAKUJO);
                        if (iRetCD != 0)
                        {
                            return;
                        }
                    }
                    catch (Exception ex)
                    {
                        //ロールバック
                        businessDB.RollBackTransaction();
                        // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                        if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
                        {
                            fileDB.RollBackTransaction();
                        }
                        // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                        throw ex;
                    }

                    //削除終了メッセージ表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00153", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    //前回伝票番号をセット
                    obic7TextStringPrevDenpyouNO.Value = obic7TextStringCalledDenpyouNO.Value;

                    //一旦事業所コードにフォーカスセット
                    obic7TextStringZigyoushoCD.Focus();

                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                    //本支店メモ情報ワーク削除
                    SQLExecuteNonQueryMain(MakeSQLDeleteMemoWorkTable());
                    // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

                    // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    ////2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                    ////<会計共通>電子証憑基盤接続クラス.[電子証憑関連データ削除処理]を使用して、
                    ////電子証憑データとの関連を削除する。
                    //if (shokiGuids != null)
                    //{
                    //    var taishouGuids = new List<Guid>();
                    //    foreach (var item in shokiGuids)
                    //    {
                    //        taishouGuids.Add(item);
                    //    }
                    //    if (taishouGuids.Count != 0)
                    //    {
                    //        WinEvidence.Evidence.DeleteEvidenceData(taishouGuids);

                    //        //電子証憑ワークテーブルの削除
                    //        SQLExecuteNonQueryMain(MakeSQLDeleteDensiShouhyouWorkTable());
                    //    }
                    //}
                    ////共通処理「伝票番号紐付データ更新処理」
                    //UpdateRelationData();
                    ////コントロールクリア
                    //this.obic7LabelStringDensiShouhyou.Text = "";
                    ////2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了
                    // 2022/02/07 削除 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                    // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                    //電子証憑ワークテーブルの削除
                    SQLExecuteNonQueryMain(MakeSQLDeleteDensiShouhyouWorkTable());
                    // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

                    //画面コントロールの有効無効を切り替える
                    SwitchDisplay(true, false);

                    //項目のクリアを行う
                    ClearControl(false, false, false, true, true, false, false, true);

                    //呼出伝票番号にフォーカスセット
                    obic7TextStringCalledDenpyouNO.Focus();

                }
            }
        }
        #endregion

        #region F4キー（検索）の実処理
        /// <summary>
        /// F4キー（検索）の実処理
        /// </summary>
        private void F4Action()
        {
            //検索実行の有無
            bool isNotSearch = false;
            //コントロール判定用-テキストボックス
            WinAToolUI.Obic7TextAbstract textAbstract = null;
            //コントロール判定用-コンボボックス
            WinAToolUI.Obic7ComboBox comboBox = null;
            //旧value
            textAbstract = PrevControl as WinAToolUI.Obic7TextAbstract;
            //貸借判断用区分
            int taishakuKbn = 0;

            if (textAbstract != null)
            {
                if (textAbstract.Name == "obic7TextStringZigyoushoCD")
                {
                    //対象項目が事業所CDであれば事業所検索ダイアログを表示する
                    using (WinMToolSearch.MA_HonsitenZigyoushoCD honsitenzigyousho = new WinMToolSearch.MA_HonsitenZigyoushoCD())
                    {
                        //基準日
                        honsitenzigyousho.KijunDate = (DateTime)obic7TextDatetimeHasseiDate.Value;
                        //セキュリティパターンコード
                        honsitenzigyousho.SecurityPatternCD = zigyoushoSecurityPatternCD;
                        //本支店事業所セキュリティフラグ
                        honsitenzigyousho.HonshaZigyoushoSecurityFLG = honshaZigyoushoSecurityFlag;
                        //名称NULL非表示区分
                        if (obic7ComboBoxMode.Text == MODE_INSERT)
                        {
                            honsitenzigyousho.NameNullKubun = 1;
                        }
                        else
                        {
                            honsitenzigyousho.NameNullKubun = 0;
                        }
                        textAbstract.AttachedSearchDialog = honsitenzigyousho;

                        if (textAbstract.ShowDialog() == DialogResult.OK)
                        {
                            //次項目へ遷移
                            SelectNextInputControl(true);
                        }
                        else
                        {
                            //OK以外であれば元の項目へフォーカスを戻す
                            isNotSearch = true;
                        }
                    }
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                else if (textAbstract.Name == "obic7TextNumberKijunKBN")
                {
                    //対象項目が基準区分であれば任意コード検索ダイアログを表示する
                    using (WinMToolSearch.MA_CodeDialog code = new WinMToolSearch.MA_CodeDialog())
                    {
                        code.Shubetu = COMMON_CD_KIJUNKBN;
                        textAbstract.AttachedSearchDialog = code;

                        if (textAbstract.ShowDialog() == DialogResult.OK)
                        {
                            //次項目へ遷移
                            SelectNextInputControl(true);
                        }
                        else
                        {
                            isNotSearch = true;
                        }
                    }
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                else if (textAbstract.Name == "obic7TextStringDenpyouKBN")
                {
                    //対象項目が伝票区分であれば伝票区分検索ダイアログを表示する
                    using (WinMToolSearch.MA_DenpyouKBN denpyoukbn = new WinMToolSearch.MA_DenpyouKBN())
                    {
                        denpyoukbn.SecurityPatternCD = denKBNSecurityPatternCD;
                        denpyoukbn.AllSumKubun = 0;
                        denpyoukbn.KaridenHondenKBN = 1;
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                        denpyoukbn.KijunKBN = ComATool.Function.AnyToInt32(this.obic7TextNumberKijunKBN.Value);
                        //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                        textAbstract.AttachedSearchDialog = denpyoukbn;

                        if (textAbstract.ShowDialog() == DialogResult.OK)
                        {
                            //次項目へ遷移
                            SelectNextInputControl(true);
                        }
                        else
                        {
                            //OK以外であれば元の項目へフォーカスを戻す
                            isNotSearch = true;
                        }
                    }
                }
                else if (textAbstract.Name == "obic7TextStringDenpyouTekiyou")
                {
                    //対象項目が伝票摘要であれば伝票摘要検索ダイアログを表示する
                    using (WinMToolSearch.MA_Tekiyou tekiyou = new WinMToolSearch.MA_Tekiyou())
                    {
                        textAbstract.AttachedSearchDialog = tekiyou;

                        if (textAbstract.ShowDialog() == DialogResult.OK)
                        {
                            //2009/02/23 修正 OBIC H.Sudo 開始 (M04171) 伝票摘要検索後、フォーカスを伝票摘要にとどまらせるように変更
                            ////次項目へ遷移
                            //SelectNextInputControl(true);
                            //先頭にカーソル配置
                            textAbstract.Select(0, 0);
                            //2009/02/23 修正 OBIC H.Sudo 終了
                        }
                        else
                        {
                            //OK以外であれば元の項目へフォーカスを戻す
                            isNotSearch = true;
                        }
                    }
                }
                else if (textAbstract.Name == "obic7TextStringCalledDenpyouNO")
                {
                    F2Action();
                }
                else if (textAbstract.Name == "obic7TextNumberSokudenHakkou")
                {
                    //対象項目が即伝発行であれば任意コード検索ダイアログを表示する
                    using (WinMToolSearch.MA_CodeDialog code = new WinMToolSearch.MA_CodeDialog())
                    {
                        code.Shubetu = 1100;
                        textAbstract.AttachedSearchDialog = code;

                        if (textAbstract.ShowDialog() == DialogResult.OK)
                        {
                            //2009/02/24 追加 OBIC H.Sudo 開始 (M04171)即伝発行にて検索ボタンOK時、表示ボタン押下時と同じ処理を行うよう変更
                            ////次項目へ遷移
                            //SelectNextInputControl(true);
                            this.obic7ButtonWithLogicDisplay.PerformClick();
                            //2009/02/24 追加 OBIC H.Sudo 終了
                        }
                        else
                        {
                            //OK以外であれば元の項目へフォーカスを戻す
                            isNotSearch = true;
                        }
                    }
                }
                else if (textAbstract.Name == "obic7TextStringKariKanjouCD"
                    || textAbstract.Name == "obic7TextStringKariHojoCD"
                    || textAbstract.Name == "obic7TextStringKariUtiwakeCD"
                    || textAbstract.Name == "obic7TextStringKariBumonCD"
                    || textAbstract.Name == "obic7TextStringKariTorihikisakiCD"
                    || textAbstract.Name == "obic7TextStringKasiKanjouCD"
                    || textAbstract.Name == "obic7TextStringKasiHojoCD"
                    || textAbstract.Name == "obic7TextStringKasiUtiwakeCD"
                    || textAbstract.Name == "obic7TextStringKasiBumonCD"
                    || textAbstract.Name == "obic7TextStringKasiTorihikisakiCD"
                    )
                {
                    //対象項目が勘定科目CD,補助科目CD,補助内訳科目CD,部門CD,取引先CDであれば総合科目検索ダイアログを表示する
                    using (WinMToolSearch.MA_NyuuryokuKamokuSougou kamoku = new WinMToolSearch.MA_NyuuryokuKamokuSougou(ComATool.Logic.CurrentUser.JobID))
                    {
                        WinAToolUI.Obic7TextString kanjoucontrol;            //勘定科目コントロール
                        WinAToolUI.Obic7TextString hojocontrol;              //補助科目コントロール
                        WinAToolUI.Obic7TextString utiwakecontrol;           //補助内訳科目コントロール
                        WinAToolUI.Obic7TextString bumoncontrol;             //部門コントロール
                        WinAToolUI.Obic7TextString torihikisakicontrol;      //取引先コントロール
                        WinAToolUI.Obic7TextString zigyoushocontrol;         //事業所コントロール
                        WinAToolUI.Obic7TextString zeikbncontrol;            //税区分コントロール
                        WinAToolUI.Obic7TextNumber zeikomikbncontrol;        //税込区分コントロール


                        if (textAbstract.Name == "obic7TextStringKariKanjouCD"
                            || textAbstract.Name == "obic7TextStringKariHojoCD"
                            || textAbstract.Name == "obic7TextStringKariUtiwakeCD"
                            || textAbstract.Name == "obic7TextStringKariBumonCD"
                            || textAbstract.Name == "obic7TextStringKariTorihikisakiCD"
                            )
                        {
                            taishakuKbn = KBN_TAISHAKU_KARIKATA;

                            //呼び出し元が借方の場合、借方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                            kanjoucontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIKANJOUCD) as WinAToolUI.Obic7TextString;
                            hojocontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIHOJOCD) as WinAToolUI.Obic7TextString;
                            utiwakecontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIUTIWAKECD) as WinAToolUI.Obic7TextString;
                            bumoncontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIBUMONCD) as WinAToolUI.Obic7TextString;
                            torihikisakicontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARITORIHIKISAKICD) as WinAToolUI.Obic7TextString;
                            if (String.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIZIGYOUSHOCD)) == false)
                            {
                                zigyoushocontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIZIGYOUSHOCD) as WinAToolUI.Obic7TextString;
                            }
                            else
                            {
                                zigyoushocontrol = obic7TextStringZigyoushoCD;
                            }
                            zeikbncontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIZEIKBN) as WinAToolUI.Obic7TextString;
                            zeikomikbncontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIZEIKOMIKBN) as WinAToolUI.Obic7TextNumber;
                        }
                        else
                        {
                            taishakuKbn = KBN_TAISHAKU_KASIKATA;

                            //呼び出し元が貸方の場合、貸方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                            kanjoucontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIKANJOUCD) as WinAToolUI.Obic7TextString;
                            hojocontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIHOJOCD) as WinAToolUI.Obic7TextString;
                            utiwakecontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIUTIWAKECD) as WinAToolUI.Obic7TextString;
                            bumoncontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIBUMONCD) as WinAToolUI.Obic7TextString;
                            torihikisakicontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASITORIHIKISAKICD) as WinAToolUI.Obic7TextString;
                            if (String.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIZIGYOUSHOCD)) == false)
                            {
                                zigyoushocontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIZIGYOUSHOCD) as WinAToolUI.Obic7TextString;
                            }
                            else
                            {
                                zigyoushocontrol = obic7TextStringZigyoushoCD;
                            }
                            zeikbncontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIZEIKBN) as WinAToolUI.Obic7TextString;
                            zeikomikbncontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIZEIKOMIKBN) as WinAToolUI.Obic7TextNumber;
                        }

                        //プロパティセット
                        //事業所コード
                        kamoku.ZigyoushoCD = zigyoushocontrol.Value;
                        //基準日
                        kamoku.KijunDate = (DateTime)obic7TextDatetimeHasseiDate.Value;
                        //総勘定科目コード
                        kamoku.KanjouCD = kanjoucontrol.Text;
                        //補助科目コード
                        kamoku.HojoCD = hojocontrol.Text;
                        //内訳科目コード
                        kamoku.UtiwakeCD = utiwakecontrol.Text;
                        //部門コード
                        kamoku.BumonCD = bumoncontrol.Text;
                        //取引先コード
                        kamoku.TorihikisakiCD = torihikisakicontrol.Text;
                        //税区分
                        kamoku.ZeiKBN = zeikbncontrol.Value;
                        if (zeikomikbncontrol.Value != null)
                        {
                            //税込区分
                            kamoku.ZeikomiKBN = ComATool.Function.AnyToInt32(zeikomikbncontrol.Value);
                        }

                        //総勘定科目セキュリティパターンコード
                        kamoku.KanjouSecurityPatternCD = kanjouSecurityPatternCD;
                        //部門セキュリティパターンコード
                        kamoku.BumonSecurityPatternCD = bumonSecurityPatternCD;
                        //表示制御区分1(表示制御)
                        kamoku.HyouziKBN1 = 0;
                        //表示制御区分2(貸借)
                        kamoku.HyouziKBN2 = taishakuKbn - 1;
                        //表示制御区分3(科目分類)
                        kamoku.HyouziKBN3 = 1;
                        //表示制御区分4(科目区分)
                        kamoku.HyouziKBN4 = 1;

                        //呼出元項目
                        if (textAbstract.Name == "obic7TextStringKariKanjouCD" || textAbstract.Name == "obic7TextStringKasiKanjouCD")
                        {
                            kamoku.YobidasiMoto = 1;
                        }
                        else if (textAbstract.Name == "obic7TextStringKariHojoCD" || textAbstract.Name == "obic7TextStringKasiHojoCD")
                        {
                            kamoku.YobidasiMoto = 2;
                        }
                        else if (textAbstract.Name == "obic7TextStringKariUtiwakeCD" || textAbstract.Name == "obic7TextStringKasiUtiwakeCD")
                        {
                            kamoku.YobidasiMoto = 3;
                        }
                        else if (textAbstract.Name == "obic7TextStringKariBumonCD" || textAbstract.Name == "obic7TextStringKasiBumonCD")
                        {
                            kamoku.YobidasiMoto = 4;
                        }
                        else if (textAbstract.Name == "obic7TextStringKariTorihikisakiCD" || textAbstract.Name == "obic7TextStringKasiTorihikisakiCD")
                        {
                            kamoku.YobidasiMoto = 5;
                        }

                        //名称NULL非表示区分
                        kamoku.NullNameKBN = 1;
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 Start
                        kamoku.DenpyouKBN = obic7TextStringDenpyouKBN.Value;
                        //  2010/12/13  変更   Y.Tamashima    (M04451)使用科目制御対応 End

                        //  2014/02/27  変更   T.Shiraishi    (ID:9498)部門別科目制御対応 開始↓
                        kamoku.BumonKamokuShubetuPatternSiyouFlag = true;
                        //  2014/02/27  変更   T.Shiraishi    (ID:9498)部門別科目制御対応 終了↑

                        //行番号
                        int rowNo = ComATool.Function.AnyToInt32(textAbstract.Parent.Tag);
                        //税区分待避
                        string tempZeiKBN = zeikbncontrol.Value;
                        //税込区分待避
                        int tempZeikomiKBN = ComATool.Function.AnyToInt32(zeikomikbncontrol.Value);

                        if (kamoku.CheckExecute())
                        {
                            if (kamoku.ShowDialog() == DialogResult.OK)
                            {
                                enterKeyDownFlg = false;

                                string strValue = "";

                                //総勘定科目
                                if (textAbstract.Name == "obic7TextStringKariKanjouCD" || textAbstract.Name == "obic7TextStringKasiKanjouCD")
                                {
                                    strValue = kanjoucontrol.Value;
                                }
                                //補助科目
                                if (textAbstract.Name == "obic7TextStringKariHojoCD" || textAbstract.Name == "obic7TextStringKasiHojoCD")
                                {
                                    strValue = hojocontrol.Value;
                                }
                                //内訳科目                                    
                                if (textAbstract.Name == "obic7TextStringKariUtiwakeCD" || textAbstract.Name == "obic7TextStringKasiUtiwakeCD")
                                {
                                    strValue = utiwakecontrol.Value;
                                }
                                //部門
                                if (textAbstract.Name == "obic7TextStringKariBumonCD" || textAbstract.Name == "obic7TextStringKasiBumonCD")
                                {
                                    strValue = bumoncontrol.Value;
                                }
                                //取引先
                                if (textAbstract.Name == "obic7TextStringKariTorihikisakiCD" || textAbstract.Name == "obic7TextStringKasiTorihikisakiCD")
                                {
                                    strValue = torihikisakicontrol.Value;
                                }


                                //総勘定科目
                                kanjoucontrol.Value = kamoku.KanjouCD;

                                if ((textAbstract.Name == "obic7TextStringKariKanjouCD" || textAbstract.Name == "obic7TextStringKasiKanjouCD") && strValue != kamoku.KanjouCD)
                                {
                                    //消費税計算抑制のためフラグを立てる
                                    kensakuFlg = true;
                                    Validate();
                                    kensakuFlg = false;
                                }
                                else
                                {
                                    CheckKanjouCD(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                                }

                                //補助科目
                                if (string.IsNullOrEmpty(kamoku.HojoCD) == false)
                                {
                                    hojocontrol.Value = kamoku.HojoCD;
                                }

                                if ((textAbstract.Name == "obic7TextStringKariHojoCD" || textAbstract.Name == "obic7TextStringKasiHojoCD") && strValue != kamoku.HojoCD)
                                {
                                    //2012/10/05 K.Morita 変更 ST (M04851)平成26年消費税改正対応
                                    //Validate();
                                    //消費税計算抑制のためフラグを立てる
                                    kensakuFlg = true;
                                    Validate();
                                    kensakuFlg = false;
                                    //2012/10/05 K.Morita 変更 ED (M04851)平成26年消費税改正対応
                                }
                                else
                                {
                                    //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
                                    hojocontrol.CommitOldText();
                                    //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応
                                    CheckHojoCD(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                                }

                                //内訳科目                                    
                                if (string.IsNullOrEmpty(kamoku.UtiwakeCD) == false)
                                {
                                    utiwakecontrol.Value = kamoku.UtiwakeCD;
                                }

                                if ((textAbstract.Name == "obic7TextStringKariUtiwakeCD" || textAbstract.Name == "obic7TextStringKasiUtiwakeCD") && strValue != kamoku.UtiwakeCD)
                                {
                                    Validate();
                                }
                                else
                                {
                                    CheckUtiwakeCD(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                                }

                                //部門
                                if (string.IsNullOrEmpty(kamoku.BumonCD) == false)
                                {
                                    bumoncontrol.Value = kamoku.BumonCD;
                                }

                                if ((textAbstract.Name == "obic7TextStringKariBumonCD" || textAbstract.Name == "obic7TextStringKasiBumonCD") && strValue != kamoku.BumonCD)
                                {
                                    Validate();
                                }
                                else
                                {
                                    CheckBumonCD(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                                }

                                //取引先
                                if (string.IsNullOrEmpty(kamoku.TorihikisakiCD) == false)
                                {
                                    torihikisakicontrol.Value = kamoku.TorihikisakiCD;
                                }

                                if ((textAbstract.Name == "obic7TextStringKariTorihikisakiCD" || textAbstract.Name == "obic7TextStringKasiTorihikisakiCD") && strValue != kamoku.TorihikisakiCD)
                                {
                                    Validate();
                                }
                                else
                                {
                                    CheckTorihikisakiCD(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);
                                }

                                //税区分
                                zeikbncontrol.Value = kamoku.ZeiKBN;
                                CheckZeiKBN(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);

                                //税込区分
                                zeikomikbncontrol.Value = kamoku.ZeikomiKBN;
                                CheckZeikomiKBN(rowNo, taishakuKbn, KBN_KOUMOKUCHK_AFTERSETVALUE);


                                //貸借区分名
                                string taishakuName = "";
                                if (taishakuKbn == KBN_TAISHAKU_KARIKATA)
                                {
                                    taishakuName = "Kari";
                                }
                                else
                                {
                                    taishakuName = "Kasi";
                                }

                                //消費税計算を行う
                                if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Kingaku") != null && (tempZeiKBN != kamoku.ZeiKBN || tempZeikomiKBN != kamoku.ZeikomiKBN))
                                {
                                    //入力前金額退避
                                    decimal? maeKingaku = GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Kingaku");
                                    //入力前消費税額退避
                                    decimal? maeZeigaku = GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Zeigaku");
                                    //消費税計算用金額
                                    decimal kingaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Kingaku"));
                                    //消費税計算用消費税額
                                    decimal zeigaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Zeigaku"));
                                    //消費税計算
                                    ShouhizeiKeisan(rowNo, taishakuName, kingaku, zeigaku);
                                    //合計額の計算
                                    RecalcTotalForRowChenge(maeKingaku, maeZeigaku, GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Kingaku"), GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, taishakuName, "Zeigaku"), taishakuKbn);
                                }
                            }
                            else
                            {
                                //OK以外であれば元の項目へフォーカスを戻す
                                isNotSearch = true;
                            }
                        }
                    }
                }
                else if (textAbstract.Name == "obic7TextStringKariZigyoushoCD"
                || textAbstract.Name == "obic7TextStringKasiZigyoushoCD")
                {
                    //対象項目が事業所CDであれば本支店事業所検索ダイアログを表示する
                    using (WinMToolSearch.MA_HonsitenZigyoushoCD honsitenZigyousho = new WinMToolSearch.MA_HonsitenZigyoushoCD())
                    {
                        WinAToolUI.Obic7TextString zigyoushocontrol;            //事業所コントロール

                        if (textAbstract.Name == "obic7TextStringKariZigyoushoCD")
                        {
                            taishakuKbn = KBN_TAISHAKU_KARIKATA;

                            //呼び出し元が借方の場合、借方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                            zigyoushocontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIZIGYOUSHOCD) as WinAToolUI.Obic7TextString;
                        }
                        else
                        {
                            taishakuKbn = KBN_TAISHAKU_KASIKATA;

                            //呼び出し元が貸方の場合、貸方のコントロールセット(textAbstract.Parent.Tagは行番号を保持している)
                            zigyoushocontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIZIGYOUSHOCD) as WinAToolUI.Obic7TextString;
                        }


                        //基準日
                        honsitenZigyousho.KijunDate = (DateTime)obic7TextDatetimeHasseiDate.Value;
