                                // 検索呼び出し
                                if (projectSearch.CheckExecute())
                                {
                                    if (projectSearch.ShowDialog() == DialogResult.OK)
                                    {
                                        //戻り値セット
                                        textAbstract.Text = projectSearch.ProjectCD;

                                        enterKeyDownFlg = true;

                                        //次項目へ遷移
                                        SelectNextInputControl(true);
                                    }
                                    else
                                    {
                                        // OK以外であれば元の項目へフォーカスを戻す
                                        isNotSearch = true;
                                    }

                                }
