                            {
                                bunsekicdcontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIPROJECTCD) as WinAToolUI.Obic7TextString;
                            }
                            else if (textAbstract.Name == "obic7TextStringKasiProjectCD")
                            {
                                bunsekicdcontrol = obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KASIPROJECTCD) as WinAToolUI.Obic7TextString;
                            }
                            bunsekiCDKBN = 7;

