        #region F5キー（取消）の実処理
        /// <summary>
        /// F5キー（取消）の実処理
        /// </summary>
        private void F5Action()
        {

            WinAToolUI.Obic7TextAbstract textAbstract = null;

            //ヘッダ部にフォーカスがある場合
            if (obic7MultilineCheckGridDetail.HasControl(ActiveControl) == false)
            {
                if (ActiveControl == obic7TextNumberTotalKariKingaku
                    || ActiveControl == obic7TextNumberTotalKariZeigaku
                    || ActiveControl == obic7TextNumberTotalKariSougaku
                    || ActiveControl == obic7TextNumberTotalKasiKingaku
                    || ActiveControl == obic7TextNumberTotalKasiZeigaku
                    || ActiveControl == obic7TextNumberTotalKasiSougaku
                    )
                {
                    //新規,修正の場合
                    if (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE)
                    {
                        //確認メッセージ
                        if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00113", null, null, GetType(),
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1) == DialogResult.No
                            )
                        {
                            //元の項目へフォーカスセット
                            PrevControl.Focus();
                            return;
                        }

                        //新規の場合
                        if (obic7ComboBoxMode.Text == MODE_INSERT)
                        {

                            //発生日にフォーカスセット
                            obic7TextDatetimeHasseiDate.Focus();
                        }
                        else
                        {
                            //呼出伝票番号にフォーカスセット
                            obic7TextStringCalledDenpyouNO.Focus();
                        }

                    }
                    else
                    {
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                        if (obic7ComboBoxMode.Text == MODE_TENPU)
                        {
                            //確認メッセージ
                            if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00113", null, null, GetType(),
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1) == DialogResult.No
                                )
                            {
                                //元の項目へフォーカスセット
                                PrevControl.Focus();
                                return;
                            }
                        }
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                        ////削除時の場合
                        //if (obic7ComboBoxMode.Text == MODE_DELETE)
                        //削除・添付時の場合
                        if (obic7ComboBoxMode.Text == MODE_DELETE || obic7ComboBoxMode.Text == MODE_TENPU)
