        #region F6キー（行挿入）の実処理
        /// <summary>
        /// F6キー（行挿入）の実処理
        /// </summary>
        private void F6Action()
        {
            WinAToolUI.Obic7TextAbstract textAbstract = null;

            //明細行にフォーカスがある場合
            if (obic7MultilineCheckGridDetail.HasControl(ActiveControl))
            {
                //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 開始↓
                if (ActiveControl.Name == "obic7ButtonWithLogicKariMemo")
                {
                    obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KARIKANJOUCD).Focus();
                }
                if (ActiveControl.Name == "obic7ButtonWithLogicKasiMemo")
                {
                    obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KASIKANJOUCD).Focus();
                }
                //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 終了↑

                //旧value
                textAbstract = PrevControl as WinAToolUI.Obic7TextAbstract;

                //新規行以外の場合
                if (String.IsNullOrEmpty(((WinATool.UI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_GYOUNO)).Text) == false)
                {
                    //行挿入フラグをtrueに
                    gyouSounyuuFlg = true;

                    //挿入行番号取得
                    sounyuuGyouNO = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_GYOUNO));

                    //現在行が既存行の時に行挿入
                    if (obic7MultilineCheckGridDetail.RowAdd(ActiveControl) == false)
                    {
                        return;
                    }

                    obic7MultilineCheckGridDetail.CanScrollChecking();

                    obic7MultilineCheckGridDetail.GetDisplayedData().Table.DefaultView.Sort = "GyouNO";

                    //明細上のコントロールであればヘッダの先頭項目にフォーカスを戻すのみ
                    obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(textAbstract.Parent.Tag), COL_KARIKANJOUCD).Focus();

                    //ツールチップテキストをセット
                    SetToolTip(1);

                    //  2013/06/28  変更   T.Shiraishi    GX対応(M00017:明細行に行番号表示) 開始↓
                    //描画処理(行挿入時、ScrollAfterイベント発生時には行番号が未だ振られていない為、ここで再度描画する。)
                    this.DrawRowNumberColumn(this.obic7MultilineCheckGridDetail, this.obic7TextNumberGyouNO.ColumnNumber, this.obic7LabelNumberGyou.Name);
                    //  2013/06/28  変更   T.Shiraishi    GX対応(M00017:明細行に行番号表示) 終了↑

                }
                else
                {
                    //エラーメッセージ表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00597", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                }
            }
        }

        //  2013/06/28  変更   T.Shiraishi    GX対応(M00017:明細行に行番号表示) 開始↓
        #region 通し行番号列の描画処理
        /// <summary>
        /// 通し行番号列の描画処理
        /// </summary>
        /// <remarks>「伝票行番号」は数値でユニークな値を持つ行であればＯＫ</remarks>
        /// <param name="tgtGrid">対象となるマルチラインコントロール</param>
        /// <param name="denpyouGyoNoColumnNumber">「伝票行番号」を持つColumnNumber(this.obic7LabelNumberGyouNO.ColumnNumber)</param>
        /// <param name="drawGyoNoControlName">通し行番号を描画する対象のラベル名</param>
        private void DrawRowNumberColumn(WinAToolUI.Obic7MultilineCheckGrid tgtGrid, Int32 denpyouGyoNoColumnNumber, String drawGyoNoControlName)
        {
            Int32 dispRowIndex = 0;

            //バインドデータが存在する場合は一番上に表示されている行の「伝票行番号」を取得します
            if (tgtGrid.GetDisplayedData().Count != 0)
            {
                //表示中の一番上の行の「伝票行NO」を取得
                Int32 dispGyouNo = ComATool.Function.AnyToInt32(tgtGrid.GetColumnObject(0, denpyouGyoNoColumnNumber).Text);

                //「伝票行NO」を持つ行がバインドデータの何行目にあるかを特定
                DataTable baseTable = tgtGrid.GetDisplayedData().ToTable();

                for (int i = 0; i < baseTable.Rows.Count; i++)
                {
                    if (ComATool.Function.AnyToInt32(baseTable.Rows[i][denpyouGyoNoColumnNumber]) == dispGyouNo)
                    {
                        dispRowIndex = i;
                        break;
                    }
                }
            }

            Int32 rowNum = dispRowIndex;

            //Max行数
            Int32 maxGyouNO = tgtGrid.GetDisplayedData().Count;
            //新規行を追加しないモードの場合は描画範囲を狭めます
            if (tgtGrid.AllowAddNewRow == false)
            {
                maxGyouNO = maxGyouNO - 1;
            }

            //１行目のラベルコントロールへ行番号を表示
            tgtGrid.GetMultilineUnrelatedObject(0, drawGyoNoControlName).Text = (++rowNum).ToString();
            //２行目以降の行番号をラベルコントロールへ行番号を表示
            for (int i = 1; i < tgtGrid.MaxRowNumber; i++)
            {
                if (maxGyouNO < rowNum)
                {
                    break;
                }
                else
                {
                    tgtGrid.GetMultilineUnrelatedObject(i, drawGyoNoControlName).Text = (++rowNum).ToString();
                }
            }

        }
        #endregion
        //  2013/06/28  変更   T.Shiraishi    GX対応(M00017:明細行に行番号表示) 終了↑


        #endregion

