        #region F8キー（行複写）の実処理
        /// <summary>
        /// F8キー（行複写）の実処理
        /// </summary>
        private void F8Action()
        {

            //ここまで

            WinAToolUI.Obic7TextAbstract textAbstract = null;
            //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 開始↓
            if (ActiveControl.Name == "obic7ButtonWithLogicKariMemo")
            {
                obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KARIKANJOUCD).Focus();
            }
            if (ActiveControl.Name == "obic7ButtonWithLogicKasiMemo")
            {
                obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KASIKANJOUCD).Focus();
            }
            //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 終了↑
            //旧value
            textAbstract = PrevControl as WinAToolUI.Obic7TextAbstract;

            WinAToolUI.Obic7TextAbstract textAbstractDummy = null;

            //行番号取得
            int rowNo = ComATool.Function.AnyToInt32(textAbstract.Parent.Tag);

            //入力前金額退避
            decimal? maeKariKingaku = GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kari", "Kingaku");
            //入力前消費税額退避
            decimal? maeKariZeigaku = GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kari", "Zeigaku");
            //入力前金額退避
            decimal? maeKasiKingaku = GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kasi", "Kingaku");
            //入力前消費税額退避
            decimal? maeKasiZeigaku = GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kasi", "Zeigaku");

            //検証処理を起こさない
            textAbstract.CausesValidation = false;

            obic7MultilineCheckGridDetail.GetColumnObject(rowNo, "obic7TextStringDummy2").Focus();

            textAbstract.CausesValidation = true;

            textAbstractDummy = (WinAToolUI.Obic7TextAbstract)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, "obic7TextStringDummy2");

            textAbstractDummy.CausesValidation = false;

            //複写処理
            if (ExecHukusha(0) == true)
            {
                //合計額の計算(借方)
                RecalcTotalForRowChenge(maeKariKingaku, maeKariZeigaku, GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kari", "Kingaku"), GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kari", "Zeigaku"), KBN_TAISHAKU_KARIKATA);

                //合計額の計算(貸方)
                RecalcTotalForRowChenge(maeKasiKingaku, maeKasiZeigaku, GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kasi", "Kingaku"), GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kasi", "Zeigaku"), KBN_TAISHAKU_KASIKATA);

                //ツールチップテキストをセット
                SetActiveRowToolTip(1, rowNo);
            }

            textAbstract.Focus();
            textAbstractDummy.CausesValidation = true;

        }
        #endregion

        #region F9キー（分析情報）の実処理
        /// <summary>
        /// F9キー（分析情報）の実処理
        /// </summary>
        private void F9Action()
        {
            //2008/06/02 追加 N.Sasaki 開始

            //起動元が総勘定科目の場合は起動前に脱出処理を行なう。
            if (PrevControl.Name == "obic7TextStringKariKanjouCD" || PrevControl.Name == "obic7TextStringKasiKanjouCD")
            {
                if (Validate() == false)
                {
                    return;
                }
            }
            //2008/06/02 追加 N.Sasaki 終了

            //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 開始↓
            if (ActiveControl.Name == "obic7ButtonWithLogicKariMemo")
            {
                obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KARIKANJOUCD).Focus();
            }
            if (ActiveControl.Name == "obic7ButtonWithLogicKasiMemo")
            {
                obic7MultilineCheckGridDetail.GetColumnObject(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_KASIKANJOUCD).Focus();
            }
            //  2014/11/07  変更   T.Shiraishi    (ID:15784)登録時に意図しない行順で更新される場合がある 終了↑

            //分析情報画面起動
            BunsekiJouhou(((Obic7fx.Win.A0000.Tool.UI.Obic7TextAbstract)PrevControl).ColumnNumber, false);
        }
        #endregion

        #region F10キー（登録）の実処理
        /// <summary>
        /// F10キー（登録）の実処理
        /// </summary>
        private void F10Action()
        {
            //現在フォーカスのあるコントロールの検証を行う
            //① 現在のコントロールが複数行コントロールの支配化のコントロールであるかどうかのチェック
            //　 今回は複数行コントロールが1つ配置されただけの画面だが、ほかにコントロールが配置されていた場合
            //   そちらにフォーカスがあたっている場合も処理が実行されてしまいます。
            //   不必要な処理が走ってしまうのを防ぐためにHasControlメソッドで確認を行います。
            if (this.obic7MultilineCheckGridDetail.HasControl(this.ActiveControl))
            {
                //② 現在入力中の内容にエラーがないかどうかをチェックします。
                //   CanScrollChecking()は内部でValidatingイベントを発生させます。
                //   そのため、検証処理・登録処理を行うことができます。
                //   検証でエラーがある場合はCanScrollChecking()はfalseを返します。
                if (!this.obic7MultilineCheckGridDetail.CanScrollChecking())
                {
                    return;
                }
            }
            else
            {
                //脱出処理
                if (Validate() == false)
                {
                    return;
                }
            }

            //登録前Allチェック
            if (CheckAll(1) == false)
            {
                return;
            }

            // 2022/10/13 追加 D.Koga (210060-211112-211117)【インボイス対応】開始
            messageDetail = "";
            CheckTorihikisakiZeiKBNSeigousei();

            if (!String.IsNullOrEmpty(messageDetail))
            {
                var detail = new String[]{messageDetail};

                if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30417", null, detail, GetType(),
                                                  WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                  WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button2) == DialogResult.No
                   )
                {
                    //元の項目へフォーカスセット
                    PrevControl.Focus();
                    return;
                }
            }
            else
            {
                // 2022/10/13 追加 D.Koga (210060-211112-211117)【インボイス対応】終了
                //確認メッセージ
                if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00112", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1) == DialogResult.No
                    )
                {
                    //元の項目へフォーカスセット
                    PrevControl.Focus();
                    return;
                }

                // 2022/10/13 追加 D.Koga (210060-211112-211117)【インボイス対応】開始
            }
            // 2022/10/13 追加 D.Koga (210060-211112-211117)【インボイス対応】終了

            //修正時、承認要否区分が必要の場合
            if (shouninKBN == 0 && obic7ComboBoxMode.Text == MODE_UPDATE)
            {
                //承認状態区分変更チェック
                if (CheckShouninStateKBNChanged() == false)
                {
                    obic7TextStringCalledDenpyouNO.Focus();
                    return;
                }
            }

            //登録処理
            if (Touroku() == false)
            {
                //元の項目へフォーカスセット
                PrevControl.Focus();
                return;
            }

            //登録終了メッセージ表示
            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00251", null, null, GetType(),
                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);


            //事業所コードに一旦フォーカスセット
            obic7TextStringZigyoushoCD.Focus();

            //画面コントロールの有効無効を切り替える
            SwitchDisplay(true, false);

            //クリア前に即伝用に待避
            decimal? sokudenSystemDenpyouNo = systemDenpyouNO;

            //項目のクリアを行う
            ClearControl(false, false, false, true, true, false, false, true);

            // 2014/11/26 K.Morita 追加 (17048) ↓
            //登録後貸借の片方しかない行にフォーカスがあると、MultiLineのUpdateが走りM0000_MA_MemoWorkに無駄な行がInsertされてしまう。
            //そのためここでメモ情報ワークを削除する。
            SQLExecuteNonQueryMain(MakeSQLDeleteMemoWorkTable());
            // 2014/11/26 K.Morita 追加 (17048) ↑

            //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
            //電子証憑ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteDensiShouhyouWorkTable());
            //コントロールクリア
            this.obic7LabelStringDensiShouhyou.Text = "";
            //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了

            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //新規時、発生日にフォーカスセット
                obic7TextDatetimeHasseiDate.Focus();
            }
            else
            {
                //呼出伝票番号にフォーカスセット
                obic7TextStringCalledDenpyouNO.Focus();
            }

            //即伝発行の処理
            if (this.obic7TextNumberSokudenHakkou.Value == 1)
            {
                using (Obic7fx.Win.M0000.Print.MA_SiwakeDenpyouMiddle.MA_SiwakeDenpyouMiddle siwakeMiddle = new Obic7fx.Win.M0000.Print.MA_SiwakeDenpyouMiddle.MA_SiwakeDenpyouMiddle(ComATool.Logic.CurrentUser.JobID))
                {
                    siwakeMiddle.ZigyoushoCD = this.obic7TextStringZigyoushoCD.Value;
                    siwakeMiddle.SystemDenpyouNO = ComATool.Function.AnyToInt32(sokudenSystemDenpyouNo);
                    siwakeMiddle.KidouMode = 1;
                    siwakeMiddle.DenpyouKBN = this.obic7TextStringDenpyouKBN.Value;
                    siwakeMiddle.DenpyouType = 3;
                    siwakeMiddle.DenpyouNO = this.obic7TextStringPrevDenpyouNO.Value;

                    siwakeMiddle.InsatuShori_SokudenHakkou();
                }

            }

        }
        #endregion

        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
        #region F10キー（追加添付）の実処理
        /// <summary>
        /// F10キー（追加添付）の実処理
        /// </summary>
        private void F10Action_Tenpu()
        {
            //現在フォーカスのあるコントロールの検証を行う
            //① 現在のコントロールが複数行コントロールの支配化のコントロールであるかどうかのチェック
            //　 今回は複数行コントロールが1つ配置されただけの画面だが、ほかにコントロールが配置されていた場合
            //   そちらにフォーカスがあたっている場合も処理が実行されてしまいます。
            //   不必要な処理が走ってしまうのを防ぐためにHasControlメソッドで確認を行います。
            if (this.obic7MultilineCheckGridDetail.HasControl(this.ActiveControl))
            {
                //② 現在入力中の内容にエラーがないかどうかをチェックします。
                //   CanScrollChecking()は内部でValidatingイベントを発生させます。
                //   そのため、検証処理・登録処理を行うことができます。
                //   検証でエラーがある場合はCanScrollChecking()はfalseを返します。
                if (!this.obic7MultilineCheckGridDetail.CanScrollChecking())
                {
                    return;
                }
            }
            else
            {
                //脱出処理
                if (Validate() == false)
                {
                    return;
                }
            }

            //確認メッセージ
            if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00112", null, null, GetType(),
                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1) == DialogResult.No
                )
            {
                //元の項目へフォーカスセット
                PrevControl.Focus();
                return;
            }

            if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Suru_ShouninAri)
            {
                //承認状態区分変更チェック
                if (CheckShouninStateKBNChanged_TuikaTenpu() == true)
                {
                    obic7TextStringCalledDenpyouNO.Focus();
                    return;
                }
            }

            //呼び出し時の添付枚数が0件の場合、そこから更新対象が増えたかチェック
            if (yobidasiTenpuCount == 0)
            {
                if (CheckExist_TuikaTenpu() == false)
                {
                    obic7TextStringCalledDenpyouNO.Focus();
                    return;
                }
            }

            //登録処理
            if (Touroku_TuikaTenpu() == false)
            {
                //元の項目へフォーカスセット
                PrevControl.Focus();
                return;
            }

            //登録終了メッセージ表示
            WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00251", null, null, GetType(),
                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

            //一旦事業所コードにフォーカスセット
            obic7TextStringZigyoushoCD.Focus();

            //画面コントロールの有効無効を切り替える
            SwitchDisplay(true, false);

            //前回伝票番号に値をセット
            this.obic7TextStringPrevDenpyouNO.Text = this.obic7TextStringDenpyouNO.Text;

            //項目のクリアを行う
            ClearControl(false, false, false, true, true, false, false, true);

            //本支店仕訳入力画面明細ワークテーブル削除
            SQLExecuteNonQueryMain(MakeSQLDeleteMeisaiWorkTable());

            //登録後貸借の片方しかない行にフォーカスがあると、MultiLineのUpdateが走りM0000_MA_MemoWorkに無駄な行がInsertされてしまう。
            //そのためここで本支店メモ情報ワークを削除する。
            SQLExecuteNonQueryMain(MakeSQLDeleteMemoWorkTable());

            //電子証憑ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteDensiShouhyouWorkTable());

            //コントロールクリア
            this.obic7LabelStringDensiShouhyou.Text = "";

            //呼出伝票番号にフォーカスセット
            obic7TextStringCalledDenpyouNO.Focus();

            this.Refresh();
        }
        #endregion
        // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

        #region F11キー（パターン）の実処理
        /// <summary>
        /// F11キー（パターン）の実処理
        /// </summary>
        private void F11Action()
        {
            //会計共通メッセージ画面
            using (WinMTool.MA_CommonMessage commes = new WinMTool.MA_CommonMessage())
            {
                //プロパティのセット
                commes.ShoriMode = 1;
                if (obic7MultilineCheckGridDetail.HasControl(PrevControl) == true)
                {
                    commes.Button1SiyouFLG = 1;
                    commes.Button2SiyouFLG = 0;
                }
                else
                {
                    commes.Button1SiyouFLG = 0;
                    commes.Button2SiyouFLG = 1;
                }

                commes.ShowDialog();

                //転送モード = １ の場合
                if (commes.ReturnMode == 1)
                {
                    //仕訳パターン番号検索
                    using (WinMToolSearch.MA_SiwakePatternNO searchptn = new WinMToolSearch.MA_SiwakePatternNO(ComATool.Logic.CurrentUser.JobID))
                    {
                        //プロパティのセット
                        searchptn.KijunDate = (DateTime)obic7TextDatetimeHasseiDate.Value;
                        searchptn.ZigyoushoCD = obic7TextStringZigyoushoCD.Value;
                        searchptn.ZigyoushoSecurityPatternCD = zigyoushoSecurityPatternCD;
                        // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                        searchptn.UseOtherUserGroupPatternFlag = 1; //1:使用する
                        // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

                        if (searchptn.CheckExecute())
                        {
                            searchptn.ShowDialog();

                            //仕訳ﾊﾟﾀｰﾝ番号がある場合
                            if (String.IsNullOrEmpty(searchptn.SiwakePatternNO) == false)
                            {
                                int iRetCD;

                                //ﾊﾟﾀｰﾝチェック
                                // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                                //iRetCD = CheckPatternRead(searchptn.SiwakePatternNO);
                                iRetCD = CheckPatternRead(searchptn.SiwakePatternNO, searchptn.UserGroupCD);
                                // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)
                                if (iRetCD != 0)
                                {
                                    return;
                                }

                                //画面にセット
                                // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                                //iRetCD = PatternRead(searchptn.SiwakePatternNO);
                                iRetCD = PatternRead(searchptn.SiwakePatternNO, searchptn.UserGroupCD);
                                // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)
                                if (iRetCD != 0)
                                {
                                    return;
                                }

                                SwitchDisplay(true, true);
                                //合計計算
                                RecalcTotal();

                                //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
                                //戻り値[仕訳パターン番号]、[更新タイムスタンプ]を変数に退避
                                this.siwakePatternNO = searchptn.SiwakePatternNO;
                                //2008/11/10  変更  T.Nakano  終了
                                // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                                this.siwakePatternUserGroupCD = searchptn.UserGroupCD;
                                // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

                                obic7TextDatetimeHasseiDate.Focus();
                            }
                        }
                    }
                }
                //転送モード = ２ の場合
                else if (commes.ReturnMode == 2)
                {
                    if (!this.obic7MultilineCheckGridDetail.CanScrollChecking())
                    {
                        return;
                    }

                    //登録前Allチェック
                    if (CheckAll(2) == false)
                    {
                        PrevControl.Focus();
                        return;
                    }

                    //仕訳パターン追加画面
                    using (WinMTool.Input.MA_SiwakePattern inoputptn = new WinMTool.Input.MA_SiwakePattern(ComATool.Logic.CurrentUser.JobID))
                    {
                        //プロパティのセット
                        inoputptn.KijunDate = (DateTime)obic7TextDatetimeHasseiDate.Value;
                        inoputptn.ZigyoushoCD = obic7TextStringZigyoushoCD.Value;
                        inoputptn.ZigyoushoSecurityPatternCD = zigyoushoSecurityPatternCD;

                        //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
                        //戻り値[仕訳パターン番号]をセット
                        inoputptn.SiwakePatternNO = this.siwakePatternNO;
                        inoputptn.UpdateTimestamp = this.siwakePatternTimestamp;
                        //2008/11/10  変更  T.Nakano  終了
                        // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                        inoputptn.UserGroupCD = this.siwakePatternUserGroupCD;   //追加画面の初期表示制御に使用
                        // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

                        if (inoputptn.CheckExecute())
                        {
                            inoputptn.ShowDialog();

                            //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
                            if (inoputptn.DialogResult == DialogResult.OK)
                            //2008/11/10  変更  T.Nakano  終了
                            {

                                //仕訳ﾊﾟﾀｰﾝ番号がある場合
                                if (String.IsNullOrEmpty(inoputptn.SiwakePatternNO) == false)
                                {
                                    //仕訳ﾊﾟﾀｰﾝの登録
                                    // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                                    //if (PatternTouroku(inoputptn.SiwakePatternNO, inoputptn.SiwakePatternName, inoputptn.SiwakePatternGroup) == false)
                                    if (PatternTouroku(inoputptn.SiwakePatternNO, inoputptn.SiwakePatternName, inoputptn.SiwakePatternGroup, inoputptn.CommonPatternKBN, inoputptn.UserGroupCD) == false)
                                    // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)
                                    {
                                        //元の項目へフォーカスセット
                                        PrevControl.Focus();
                                    }
                                    else
                                    {
                                        //2008/11/10  変更  T.Nakano  開始　(M4076)呼びだしたパターン、もしくは登録したパターンが明細に表示されている状態で再度仕訳パターン登録を呼びだすと、保持したパターン番号を自動表示する
                                        //戻り値[仕訳パターン番号]
                                        this.siwakePatternNO = inoputptn.SiwakePatternNO;
                                        //2008/11/10  変更  T.Nakano  終了
                                        // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                                        this.siwakePatternUserGroupCD = inoputptn.UserGroupCD;
                                        // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)

                                        //エラー表示
                                        WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00252", null, null, GetType(),
                                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                            WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                                    }
                                }
                            }
                            // 2013/08/21 修正 Y.Katsumata 開始↓ GX対応(M00019:共通仕訳パターンの実装)
                            //「F12:閉じる」で戻ってきた場合
                            else
                            {
                                //自ユーザグループ作成分のパターンを呼び出して削除した場合
                                //(呼出パターングループ＝自ユーザグループ かつ 仕訳パターン番号がクリアされている 場合)
                                if ((this.siwakePatternUserGroupCD == userGroupCD) && string.IsNullOrEmpty(inoputptn.SiwakePatternNO))
                                {
                                    //呼び出しているパターンの変数をクリアする
                                    //(パターン呼出無しの状態にするため、受渡し項目はパターン追加画面でクリアされている)

                                    //戻り値[仕訳パターン番号]
                                    this.siwakePatternNO = inoputptn.SiwakePatternNO;
                                    //戻り値[ユーザグループコード]
                                    this.siwakePatternUserGroupCD = inoputptn.UserGroupCD;
                                    //タイムスタンプ
                                    this.siwakePatternTimestamp = null;
                                }
                            }
                            // 2013/08/21 修正 Y.Katsumata 終了↑ GX対応(M00019:共通仕訳パターンの実装)
                        }
                    }
                }

                PrevControl.Focus();
                return;
            }
        }
