        #region フォーム上でのキーダウンイベント
        /// <summary>
        /// フォーム上でのキーダウンイベント
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void MA_HonsitenSiwake_KeyDown(object sender, KeyEventArgs e)
        {
            if ((e.Alt == false) && (e.Shift == false) && (e.Control == false) && (e.KeyCode == Keys.Enter))
            {
                if (this.ActiveControl == obic7ComboBoxMode)
                {
                    //処理モードの処理
                    // 2008/08/06 T.Ota 変更開始 Tab移動でも処理モードから移動できるようにする
                    //CheckShoriMode();
                    base.SelectNextInputControl(true);
                    // 2008/08/06 T.Ota 変更終了
                }
                //呼出伝票
                else if (ActiveControl.Name == "obic7TextStringCalledDenpyouNO")
                {
                    //エンターフラグをtrueに
                    enterKeyDownFlg = true;
                    base.SelectNextInputControl(true);
                }
                //伝票摘要
                else if (ActiveControl.Name == "obic7TextStringDenpyouTekiyou")
                {
                    //伝票摘要の処理
                    CheckDenpyouTekiyou();
                }
                //2009/02/23 追加 OBIC H.Sudo 開始 (M04171)即伝発行にてEnterを押下時、表示ボタン押下時と同じ処理を行うよう変更
                //即伝発行
                else if (ActiveControl.Name == "obic7TextNumberSokudenHakkou")
                {
                    //表示ボタンクリック時と同じ処理を行う。
                    obic7ButtonWithLogicDisplay.PerformClick();
                }
                //2009/02/23 追加 OBIC H.Sudo 終了                
                //　2010/08/16　変更　　　C.Okuno  (M04451)↓
                //発生日
                else if (ActiveControl.Name == "obic7TextDatetimeHasseiDate")
                {
                    //Enter時は伝票区分へ、Tab時は次項目へフォーカスを移動する。
                    this.obic7TextStringDenpyouKBN.Focus();
                }
                //　2010/08/16　変更　　　C.Okuno  (M04451)↑
                else if (obic7MultilineCheckGridDetail.HasControl(ActiveControl) == false)
                {
                    base.SelectNextInputControl(true);
                }
                else if (obic7MultilineCheckGridDetail.HasControl(ActiveControl) == true)
                {
                    //エンターフラグをtrueに
                    enterKeyDownFlg = true;

                    //明細摘要
                    if (ActiveControl.Name == "obic7TextStringMeisaiTekiyou")
                    {
                        //1対N仕訳によるフォーカス判断用フラグをtrueに
                        nSiwakeFocusFlg = true;

                        //１：N仕訳かどうかのチェック
                        if (CheckNSiwake(ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), 1) == true)
                        {
                            //貸方総勘定科目にフォーカスセット
                            nSiwakeFocusKoumoku = true;
                        }
                        else
                        {
                            //借方総勘定科目にフォーカスセット
                            nSiwakeFocusKoumoku = false;
                        }

                        //既存行の場合
                        if (String.IsNullOrEmpty(ComATool.Function.AnyToString(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag), COL_GYOUNO))) == false)
                        {
                            //次行の内部的な行番号取得
                            int internalNo = ComATool.Function.AnyToInt32(ActiveControl.Parent.Tag);

                            if (internalNo <= 4)
                            {
                                internalNo = internalNo + 1;
                            }
                            else
                            {
                                internalNo = 5;
                            }

                            //１対N仕訳フォーカスのために次行のダミー項目に一旦フォーカスをセットさせるためTabStopをtrueに
                            obic7MultilineCheckGridDetail.GetColumnObject(internalNo, "obic7TextStringDummy").TabStop = true;
                        }

                        //複数行コントロールの最終項目ではフォーカス移動処理は行わない
                        if (!obic7MultilineCheckGridDetail.IsMultilineLastItem(ActiveControl))
                        {

                            base.SelectNextInputControl(true);
                        }
                    }
                    else
                    {
                        base.SelectNextInputControl(true);
                    }
                }
            }

            if (e.Control == true && e.KeyCode == Keys.Enter)
            {
                if (ActiveControl.Name == "obic7TextStringMeisaiTekiyou")
                {
                    e.SuppressKeyPress = true;
                }
            }

        }

        #endregion

        #region フォームロード時の処理

        /// <summary>
        /// フォームロード時の処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void MA_HonsitenSiwake_Load(object sender, EventArgs e)
        {
            //DBアクセスクラス（ステートフル）のインスタンスを作成
            businessDB = new WinAToolLogic.DBAccess(SYSTEMCATEGORYCD, CUSTOMIZESEQ, ComAToolLogic.DBAccess.Obic7DBAccessDBCategory.Business);

            //トリガーを無効に設定
            businessDB.IsNotUseTrigger = true;

            //本支店仕訳入力画面明細ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteMeisaiWorkTable());

            //貸借判断ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteTaishakuWorkTable());

            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //本支店メモ情報ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteMemoWorkTable());

            //会計共通ユーザグループ設定マスタクラス]より、メモ使用フラグを取得する
            GetKaikeiUserGroupSetteiMaster();
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

            //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
            //伝票NO特定ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteDenNOTokuteiWorkTable());

            //電子証憑ワークテーブルの削除
            SQLExecuteNonQueryMain(MakeSQLDeleteDensiShouhyouWorkTable());

            //電子証憑OP導入フラグの取得
            //[指定した契約の存在チェック]より、導入済みかどうかを取得する。
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            SQLExecuteNonQueryMain(MakeSQLDeleteShouhyouShutokuTaishouWorkTable());
            //isAvailableEvidence = WinAToolLogicUI.LicenseManager.CheckProduct("M_Evi");
            if (!WinAToolLogicUI.LicenseManager.CheckProduct("M_ET") && !WinAToolLogicUI.LicenseManager.CheckProduct("M_Evi"))
            {
                isAvailableEvidence = false;
            }
            else
            {
                isAvailableEvidence = true;
            }
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
            //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了

            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            //添付ファイル用起動Guidの取得
            fileKidouGuid = Guid.NewGuid();
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

            //ログインユーザIDより、セキュリティ情報を取得する
            GetSecurity();

            // ↓ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)
            //ログインユーザIDより、分析コード入力制御情報を取得する
            GetBunsekiCDNyuuryokuSeigyo();
            //ログインユーザIDより、分析コード初期セット情報を取得する
            GetBunsekiCDShokiSet();
            // ↑ 2016/10/17 M.Tamura INS [47349]分析コード機能強化対応(入力制御)

            //マルチラインコントロールを実体化
            SetMultiLineControl();

            //明細コントロール表示内容初期化
            //表示を初期化する
            obic7MultilineCheckGridDetail.BaseDataSet = GetBlankDataSet();

            //待避配列データを初期化
            tempActiveInputDataRow = obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].NewRow();

            //ユーザーのユーザグループコード取得
            GetUserGroupCD();

            //会計コントロールマスタ,コントロールマスタの情報を取得
            //  2016/02/02  修正 T.Sato  (36053)決算伝票締日がチェックされない場合がある  開始
            //GetControlMaster();
            GetKaikeiControlMaster();
            GetZaimuControlMaster();
            //  2016/02/02  修正 T.Sato  (36053)決算伝票締日がチェックされない場合がある  終了

            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            if (sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
            {
                //DBアクセスクラス（ステートフル）(FileDB)のインスタンスを作成
                fileDB = new WinAToolLogic.DBAccess(SYSTEMCATEGORYCD, CUSTOMIZESEQ, ComAToolLogic.DBAccess.Obic7DBAccessDBCategory.Business);
            }
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
            //初期表示セット
            SetDefDisplay();

            //ワークフロークラスの初期化
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            //this.wfExecuter = new WFExecuter("BM0010", "B");
            if (_kidouMode == 3)
            {
                this.wfExecuter = new WFExecuter("BM1010", "B");
            }
            else
            {
                this.wfExecuter = new WFExecuter("BM0010", "B");
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了

            //修正モードで起動した時
            if (_kidouMode == 1)
            {
                obic7ComboBoxMode.Text = MODE_UPDATE;

                //検索用システム伝票番号
                kensakuSystemDenpyouNO = _systemDenpyouNO;

                //キー、ヘッダ使用可に設定しておく
                SwitchDisplay(true, true);

                StringBuilder sb = new StringBuilder();

                sb.Append(" SELECT ");
                sb.Append("     DenpyouNO  ");
                sb.Append(" FROM  M0000RR_MA_SiwakeMeisai ");
                sb.Append(" WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(kensakuSystemDenpyouNO) + " ");

                obic7TextStringCalledDenpyouNO.Value = ComATool.Function.AnyToString(businessDB.ExecuteScalar(ComATool.Function.AnyToString(sb)));

                //転送モードセット
                kensakuTensouMode = 0;

                // ↓ 2011/12/05 変更 S.Harada (M04719)ドリルダウンで伝票訂正をする際に異常終了する不具合修正
                isKidouModeFlg = true;
                // ↑ 2011/12/05 変更 S.Harada (M04719)ドリルダウンで伝票訂正をする際に異常終了する不具合修正
            }
            // 2017/01/19 修正 H.Fukuda (52221-52242-52243) 【WG機能改善(50期4Q)】【伝票照会から入力画面新規モード起動】 ↓
            //流用新規モードで起動した時
            else if (_kidouMode == 2)
            {
                //画面.[処理モード] = [新規]とする。
                obic7ComboBoxMode.Text = MODE_INSERT;

                //キー、ヘッダ使用可に設定しておく
                SwitchDisplay(true, true);

                StringBuilder sb = new StringBuilder();

                //検索用システム伝票番号
                kensakuSystemDenpyouNO = _systemDenpyouNO;

                sb.Append(" SELECT ");
                sb.Append("     DenpyouNO  ");
                sb.Append(" FROM  M0000RR_MA_SiwakeMeisai ");
                sb.Append(" WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(kensakuSystemDenpyouNO) + " ");

                obic7TextStringCalledDenpyouNO.Value = ComATool.Function.AnyToString(businessDB.ExecuteScalar(ComATool.Function.AnyToString(sb)));

                //転送モードセット
                kensakuTensouMode = 0;

                isKidouModeFlg = true;
            }
            // 2017/01/19 修正 H.Fukuda (52221-52242-52243) 【WG機能改善(50期4Q)】【伝票照会から入力画面新規モード起動】 ↑
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            else if (_kidouMode == 3)
            {
                //画面.[処理モード] = [添付]とする。
                obic7ComboBoxMode.Text = MODE_TENPU;

                //キー、ヘッダ使用可に設定しておく
                SwitchDisplay(true, true);

                StringBuilder sb = new StringBuilder();

                //検索用システム伝票番号
                kensakuSystemDenpyouNO = _systemDenpyouNO;

                sb.Append(" SELECT ");
                sb.Append("     DenpyouNO  ");
                sb.Append(" FROM  M0000RR_MA_SiwakeMeisai ");
                sb.Append(" WHERE SystemDenpyouNO = " + ComATool.Function.SqlEscapeNumber(kensakuSystemDenpyouNO) + " ");

                obic7TextStringCalledDenpyouNO.Value = ComATool.Function.AnyToString(businessDB.ExecuteScalar(ComATool.Function.AnyToString(sb)));

                //転送モードセット
                kensakuTensouMode = 0;
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
            else
            {
                //キー、ヘッダ使用不可に設定
                SwitchDisplay(false, false);
            }

            //2023/08/31 修正 S.Mito (226830)ファイル添付制御マスタが全て使用不可の場合に添付を行うと登録した伝票を呼び出せない場合があります 開始
            if (isAvailableEvidence)
            {
                var fileTenpControlInfo = WinEvidence.Evidence.GetAttachFileControlInfo("M_ET", "M_Evi");
                if (!fileTenpControlInfo.Data.IsAvailableErectronicEvidence && !fileTenpControlInfo.Data.IsAvailableScannedEvidence && !fileTenpControlInfo.Data.IsAvailableCommonFile)
                {
                    isAvailableEvidence = false;
                    sonotaTenpuFileRiyouFLG = (int)TenpuFileRiyouFLG.Misiyou;
                }
            }
            //2023/08/31 修正 S.Mito (226830)ファイル添付制御マスタが全て使用不可の場合に添付を行うと登録した伝票を呼び出せない場合があります 終了
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            ////2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
            ////電子証憑関連の画面制御を行う。
            ////[電子証憑OP導入フラグ] = false(未導入)のとき、画面.[電子証憑ボタン]、画面.[電子証憑枚数ラベル]を非表示にする。
            //if (isAvailableEvidence == false)
            //{
            //    this.obic7LabelStringDensiShouhyou.Visible = false;
            //    this.obic7ButtonWithLogicDensiShouhyou.Visible = false;
            //}
            //else
            //{
            //    this.obic7LabelStringDensiShouhyou.Visible = true;
            //    this.obic7ButtonWithLogicDensiShouhyou.Visible = true;
            //}
            ////2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了
            //[電子証憑OP導入フラグ] = true(導入)または添付ファイル利用フラグ = 1:使用するのとき、画面.[電子証憑ボタン]、画面.[電子証憑枚数ラベル]を表示にする。
            if (isAvailableEvidence || sonotaTenpuFileRiyouFLG == (int)TenpuFileRiyouFLG.Siyou)
            {
                isFileTenpuUse = true;
            }
            else
            {
                this.obic7LabelStringDensiShouhyou.Visible = false;
                this.obic7ButtonWithLogicDensiShouhyou.Visible = false;
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                //ファイル添付機能フラグOFFの場合は添付モードを使えないようにする
                obic7ComboBoxMode.Items.Remove(MODE_TENPU);
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
            }
            // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了

            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            if (tuikaTenpuSiyouKBN == (byte)TuikaTenpuSiyouKBN.Sinai)
            {
                obic7ComboBoxMode.Items.Remove(MODE_TENPU);
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
        }

