        #region フォーム初回表示時の処理

        /// <summary>
        /// フォーム初回表示時の処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void MA_HonsitenSiwake_Shown(object sender, EventArgs e)
        {
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //メモボタンのデフォルト色を退避
            this.defaultButtonColor = this.obic7ButtonWithLogicKariMemo.BackColor;
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

            if (_kidouMode == 1)
            {
                //2008/09/30  変更  T.Nakano  開始　(M4058)処理モード=「修正」で呼び出したときに、
                //　　　　　　　　　　　　　　　　　該当伝票番号が仕訳明細に存在しない場合の起動と終了時の処理を追加
                if (String.IsNullOrEmpty(this.obic7TextStringCalledDenpyouNO.Value))
                {
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01008", null, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    this.obic7MultilineCheckGridDetail.Enabled = false;
                    this.Close();
                    return;
                }
                //2008/09/30  変更  T.Nakano  終了

                // 2024/02/20 修正 K.Imoto (232654)【本支店仕訳入力】【横展開232290】照会から修正モードで起動した時、添付されているファイルが閲覧できません。開始
                //画面クローズ時に電子証憑関連処理を行わないようにする為のフラグを宣言
                bool closeflg = false;
                // 2024/02/20 修正 K.Imoto (232654)【本支店仕訳入力】【横展開232290】照会から修正モードで起動した時、添付されているファイルが閲覧できません。終了

                //伝票呼出失敗時は画面終了
                if (ValidatingCalledDenpyouNO(KBN_KOUMOKUCHK_AFTERSETVALUE) == false)
                {
                    //2008/06/19 追加 N.Sasaki 開始
                    obic7MultilineCheckGridDetail.Enabled = false;
                    //2008/06/19 追加 N.Sasaki 終了
                    this.Close();
                    // 2024/02/20 修正 K.Imoto (232654)【本支店仕訳入力】【横展開232290】照会から修正モードで起動した時、添付されているファイルが閲覧できません。開始
                    //画面クローズ時に電子証憑関連処理を行わないようにする為のフラグをたてる
                    closeflg = true;
                    // 2024/02/20 修正 K.Imoto (232654)【本支店仕訳入力】【横展開232290】照会から修正モードで起動した時、添付されているファイルが閲覧できません。終了
                }

                // 2024/02/20 修正 K.Imoto (232654)【本支店仕訳入力】【横展開232290】照会から修正モードで起動した時、添付されているファイルが閲覧できません。開始
                //電子証憑関連処理
                if ((isFileTenpuUse == true) && (obic7ComboBoxMode.Text != MODE_INSERT) && (!closeflg))
                {
                    densiShouhyouShori();
                }
                // 2024/02/20 修正 K.Imoto (232654)【本支店仕訳入力】【横展開232290】照会から修正モードで起動した時、添付されているファイルが閲覧できません。終了

                //転送モードリセット
                kensakuTensouMode = null;
                //検索用システム伝票番号リセット
                kensakuSystemDenpyouNO = null;

                //フォーカスを処理モードにセット
                obic7TextDatetimeHasseiDate.Focus();

                // 2013/07/17 追加 M.Shinbo GX対応(M00001:ドリルダウン時にフォーカスセット) 開始
                //表示データの件数
                int dataCount = this.obic7MultilineCheckGridDetail.GetDisplayedData().Count;

                //起動引数.[画面上の先頭行番号]が設定されている場合、その行番号を画面上に表示するマルチラインの先頭行とする
                if (this._topGyouNO != null)
                {
                    //まず画面上の先頭行番号にフォーカスをセットさせる
                    for (int rowNO = 0; rowNO < dataCount; rowNO++)
                    {
                        if (this.obic7MultilineCheckGridDetail.GetDisplayedData().Table.Rows[rowNO][COL_GYOUNO].ToString() == this._topGyouNO.ToString())
                        {
                            this.obic7MultilineCheckGridDetail.SelectSpecifyRow(rowNO, COL_KARIKANJOUCD);
                            break;
                        }
                    }
                    //起動引数.[行番号]が設定されている場合、その行番号の借方総勘定科目コードにフォーカスをセットする
                    if (this._gyouNO != null)
                    {
                        //画面表示上の行番号
                        int focusRowNO = (int)this._gyouNO - (int)this._topGyouNO;

                        //該当行番号にフォーカスをセットさせる
                        this.obic7MultilineCheckGridDetail.GetColumnObject(focusRowNO, COL_KARIKANJOUCD).Focus();
                    }
                }
                //起動引数.[画面上の先頭行番号]が設定されていない、かつ起動引数.[行番号]が設定されている場合、
                //起動引数.[行番号]の総勘定科目コードにフォーカスをセットする
                else if (this._gyouNO != null)
                {
                    for (int rowNO = 0; rowNO < this.obic7MultilineCheckGridDetail.GetDisplayedData().Count; rowNO++)
                    {
                        if (this.obic7MultilineCheckGridDetail.GetDisplayedData().Table.Rows[rowNO][COL_GYOUNO].ToString() == this._gyouNO.ToString())
                        {
                            this.obic7MultilineCheckGridDetail.SelectSpecifyRow(rowNO, COL_KARIKANJOUCD);
                            break;
                        }
                    }
                }
                // 2013/07/17 追加 M.Shinbo GX対応(M00001:ドリルダウン時にフォーカスセット) 終了
            }

            // 2017/01/19 修正 H.Fukuda (52221-52242-52243) 【WG機能改善(50期4Q)】【伝票照会から入力画面新規モード起動】 ↓
            //流用新規モードで起動した時
            else if (_kidouMode == 2)
            {
                //該当伝票番号が仕訳明細に存在しない場合の起動と終了時の処理を追加
                if (String.IsNullOrEmpty(this.obic7TextStringCalledDenpyouNO.Value))
                {
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01008", null, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    this.obic7MultilineCheckGridDetail.Enabled = false;
                    this.Close();
                    return;
                }

                //伝票呼出失敗時は画面終了
                if (ValidatingCalledDenpyouNO(KBN_KOUMOKUCHK_AFTERSETVALUE) == false)
                {
                    obic7MultilineCheckGridDetail.Enabled = false;
                    this.Close();
                }

                //転送モードリセット
                kensakuTensouMode = null;
                //検索用システム伝票番号リセット
                kensakuSystemDenpyouNO = null;


                //フォーカスを処理モードにセット
                obic7TextDatetimeHasseiDate.Focus();

                //表示データの件数
                int dataCount = this.obic7MultilineCheckGridDetail.GetDisplayedData().Count;

                //起動引数.[画面上の先頭行番号]が設定されている場合、その行番号を画面上に表示するマルチラインの先頭行とする
                if (this._topGyouNO != null)
                {
                    //まず画面上の先頭行番号にフォーカスをセットさせる
                    for (int rowNO = 0; rowNO < dataCount; rowNO++)
                    {
                        if (this.obic7MultilineCheckGridDetail.GetDisplayedData().Table.Rows[rowNO][COL_GYOUNO].ToString() == this._topGyouNO.ToString())
                        {
                            this.obic7MultilineCheckGridDetail.SelectSpecifyRow(rowNO, COL_KARIKANJOUCD);
                            break;
                        }
                    }
                    //起動引数.[行番号]が設定されている場合、その行番号の借方総勘定科目コードにフォーカスをセットする
                    if (this._gyouNO != null)
                    {
                        //画面表示上の行番号
                        int focusRowNO = (int)this._gyouNO - (int)this._topGyouNO;

                        //該当行番号にフォーカスをセットさせる
                        this.obic7MultilineCheckGridDetail.GetColumnObject(focusRowNO, COL_KARIKANJOUCD).Focus();
                    }
                }
                //起動引数.[画面上の先頭行番号]が設定されていない、かつ起動引数.[行番号]が設定されている場合、
                //起動引数.[行番号]の総勘定科目コードにフォーカスをセットする
                else if (this._gyouNO != null)
                {
                    for (int rowNO = 0; rowNO < this.obic7MultilineCheckGridDetail.GetDisplayedData().Count; rowNO++)
                    {
                        if (this.obic7MultilineCheckGridDetail.GetDisplayedData().Table.Rows[rowNO][COL_GYOUNO].ToString() == this._gyouNO.ToString())
                        {
                            this.obic7MultilineCheckGridDetail.SelectSpecifyRow(rowNO, COL_KARIKANJOUCD);
                            break;
                        }
                    }
                }
            }
            // 2017/01/19 修正 H.Fukuda (52221-52242-52243) 【WG機能改善(50期4Q)】【伝票照会から入力画面新規モード起動】 ↑

            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            else if (_kidouMode == 3)
            {
                //呼び出したときに、該当伝票番号が仕訳明細に存在しない場合の起動と終了時の処理を追加
                if (String.IsNullOrEmpty(this.obic7TextStringCalledDenpyouNO.Value))
                {
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "01008", null, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    this.obic7MultilineCheckGridDetail.Enabled = false;
                    this.Close();
                    return;
                }

                //画面クローズ時に電子証憑関連処理を行わないようにする為のフラグを宣言
                bool closeflg = false;

                if (!isFileTenpuUse)
                {
                    //エラーメッセージを表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30459", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                    obic7MultilineCheckGridDetail.Enabled = false;
                    //画面クローズ時に電子証憑関連処理を行わないようにする為のフラグをたてる
                    closeflg = true;
                    this.Close();
                    return;
                }

                //伝票呼出失敗時は画面終了
                if (ValidatingCalledDenpyouNO(KBN_KOUMOKUCHK_AFTERSETVALUE) == false)
                {
                    obic7MultilineCheckGridDetail.Enabled = false;
                    this.Close();

                    //画面クローズ時に電子証憑関連処理を行わないようにする為のフラグをたてる
                    closeflg = true;
                }

                //電子証憑関連処理
                //[電子証憑OP導入フラグ]=true(導入済)の場合 かつ 画面クローズ時以外 のみ処理を行う。
                if (isFileTenpuUse == true && !closeflg)
                {
                    densiShouhyouShori();
                }

                //転送モードリセット
                kensakuTensouMode = null;
                //検索用システム伝票番号リセット
                kensakuSystemDenpyouNO = null;

                //表示データの件数
                int dataCount = this.obic7MultilineCheckGridDetail.GetDisplayedData().Count;

                //起動引数.[画面上の先頭行番号]が設定されている場合、その行番号を画面上に表示するマルチラインの先頭行とする
                if (this._topGyouNO != null)
                {
                    //まず画面上の先頭行番号にフォーカスをセットさせる
                    for (int rowNO = 0; rowNO < dataCount; rowNO++)
                    {
                        if (this.obic7MultilineCheckGridDetail.GetDisplayedData().Table.Rows[rowNO][COL_GYOUNO].ToString() == this._topGyouNO.ToString())
                        {
                            this.obic7MultilineCheckGridDetail.SelectSpecifyRow(rowNO, COL_KARIKANJOUCD);
                            break;
                        }
                    }
                }

                //添付モード時の制御を行う
                base.obic7ToolStripButtonWithLogicF10.Text = "F10 添付登録";

                //フォーカスを添付ボタンにセット
                this.obic7ButtonWithLogicDensiShouhyou.Focus();
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
            else
            {
                //フォーカスを処理モードにセット
                obic7ComboBoxMode.Focus();
            }
        }
