        #region フォームを閉じる際の処理
        /// <summary>
        /// フォームを閉じる際の処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void MA_HonsitenSiwake_FormClosing(object sender, FormClosingEventArgs e)
        {
            if (e.Cancel != true)
            {
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                ////新規・修正モードで入力途中であれば確認メッセージを表示する
                //if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
                //新規・修正・添付モードで入力途中であれば確認メッセージを表示する
                if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE) || (obic7ComboBoxMode.Text == MODE_TENPU))
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                {
                    if ((obic7ComboBoxMode.Enabled == false && obic7MultilineCheckGridDetail.GetDisplayedData().Count != 0))
                    {
                        if (WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "00110", null, null, GetType(),
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.YesNo,
                                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button2) != DialogResult.Yes)
                        {
                            //Yes以外であれば終了処理を中断する
                            e.Cancel = true;
                            return;
                        }
                    }
                }

                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                //修正、削除時、呼出伝票がある場合
                //if (((obic7ComboBoxMode.Text == MODE_DELETE) || (obic7ComboBoxMode.Text == MODE_UPDATE)) && obic7MultilineCheckGridDetail.Enabled == true)
                //修正、削除、添付時、呼出伝票がある場合
                if (((obic7ComboBoxMode.Text == MODE_DELETE) || (obic7ComboBoxMode.Text == MODE_UPDATE) || (obic7ComboBoxMode.Text == MODE_TENPU)) && obic7MultilineCheckGridDetail.Enabled == true)
                // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                {
                    //排他削除
                    int iRetCD;
                    iRetCD = HaitaSetData(KBN_HAITA_SAKUJO);
                    if (iRetCD != 0)
                    {
                        e.Cancel = true;
                        return;
                    }
                }

                // 2017/04/12 変更 K.Fujita (54275-59277)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
                //伝票NO特定ワークテーブルの削除
                SQLExecuteNonQueryMain(MakeSQLDeleteDenNOTokuteiWorkTable());
                //電子証憑ワークテーブルの削除
                SQLExecuteNonQueryMain(MakeSQLDeleteDensiShouhyouWorkTable());
                // 2017/04/12 変更 K.Fujita (54275-59277)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  終了
                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                SQLExecuteNonQueryMain(MakeSQLDeleteShouhyouShutokuTaishouWorkTable());
                //伝票WK削除
                WinEvidence.Evidence.DeleteDenpyouWK(fileKidouGuid);
                // 2022/02/07 追加 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
            }
        }
        #endregion

