        private void obic7TextStringZigyoushoCD_Enter(object sender, EventArgs e)
        {
            //ファンクションボタン切替
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                //新規モード
                base.SetFunctionButton(false, true, false, true, true, false, false, false, false, obic7MultilineCheckGridDetail.Enabled, true, true);
            }
            else if (obic7ComboBoxMode.Text == MODE_UPDATE)
            {
                //修正モード
                base.SetFunctionButton(false, true, false, true, true, false, false, false, false, obic7MultilineCheckGridDetail.Enabled, obic7MultilineCheckGridDetail.Enabled, true);
            }
            else if (obic7ComboBoxMode.Text == MODE_DELETE)
            {
                if (obic7TextStringZigyoushoCD.ReadOnly == true)
                {
                    //削除モード
                    base.SetFunctionButton(false, true, obic7MultilineCheckGridDetail.Enabled, false, true, false, false, false, false, false, false, true);
                }
                else
                {
                    //削除モード
                    base.SetFunctionButton(false, true, obic7MultilineCheckGridDetail.Enabled, true, true, false, false, false, false, false, false, true);
                }
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            else if (obic7ComboBoxMode.Text == MODE_TENPU)
            {
                if (obic7TextStringZigyoushoCD.ReadOnly == true)
                {
