                    base.SetFunctionButton(false, true, false, false, true, false, false, false, false, obic7MultilineCheckGridDetail.Enabled, false, true);
                }
                else
                {
                    //添付モード
                    base.SetFunctionButton(false, true, false, true, true, false, false, false, false, obic7MultilineCheckGridDetail.Enabled, false, true);
                }
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
            else
            {
                if (obic7TextStringZigyoushoCD.ReadOnly == true)
                {
                    //照会モード
                    base.SetFunctionButton(false, true, false, false, true, false, false, false, false, false, false, true);
                }
                else
                {
                    //照会モード
                    base.SetFunctionButton(false, true, false, true, true, false, false, false, false, false, false, true);
                }

            }
