        /// <summary>
        /// 発生日フォーカス取得時の処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void obic7TextDatetimeHasseiDate_Enter(object sender, EventArgs e)
        {
            //ファンクションボタン切替
            if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
            {
                //新規モード
                base.SetFunctionButton(false, true, false, false, true, false, false, false, false, obic7MultilineCheckGridDetail.Enabled, true, true);
            }
            else if (obic7ComboBoxMode.Text == MODE_UPDATE)
            {
                //修正モード
                base.SetFunctionButton(false, true, false, false, true, false, false, false, false, obic7MultilineCheckGridDetail.Enabled, obic7MultilineCheckGridDetail.Enabled, true);
            }
            else if (obic7ComboBoxMode.Text == MODE_DELETE)
            {
                //削除モード
                base.SetFunctionButton(false, true, obic7MultilineCheckGridDetail.Enabled, false, true, false, false, false, false, false, false, true);
            }
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            else if (obic7ComboBoxMode.Text == MODE_TENPU)
