        #region 明細行イベント

        #region 行単位チェック
        /// <summary>
        /// 行単位チェック
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo"></param>
        /// <param name="reservedFocus"></param>
        private void obic7MultilineCheckGridDetail_RowValidating(object sender, WinATool.UI.Obic7MultilineCancelEventArgs e, int rowNo, ref Control reservedFocus)
        {

            int errorNumber = -1;

            //読取専用時は処理なし
            if (obic7MultilineCheckGridDetail.ReadOnly == true)
            {
                return;
            }

            //取消押下時は処理なし
            if (torikesiFlg == true)
            {
                return;
            }

            //2008/06/02 追加 N.Sasaki 開始
            //行挿入時はチェックなし
            if (gyouSounyuuFlg == true)
            {
                return;
            }
            //2008/06/02 追加 N.Sasaki 終了

            //明細のエラープロバイダを解除
            ClearErrorProvider(2);

            //明細行の入力チェック
            errorNumber = CheckMeisaiGyou(KBN_KOUMOKUCHK_INPUT, rowNo);
            if (errorNumber != -1)
            {
                switch (errorNumber)
                {
                    case COL_KARIBUNSEKICD4:
                    case COL_KARIBUNSEKICD5:
                    // 2013/05/15 削除 I.Nakagawa 開始 (GX)
                    //case COL_KARIPROJECTCD:
                    // 2013/05/15 削除 I.Nakagawa 終了 (GX)
                    case COL_KASIBUNSEKICD4:
                    case COL_KASIBUNSEKICD5:
                        // 2013/05/15 削除 I.Nakagawa 開始 (GX)
                        //case COL_KASIPROJECTCD:
                        // 2013/05/15 削除 I.Nakagawa 終了 (GX)
                        reservedFocus = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_MEISAITEKIYOU);
                        //分析情報画面起動
                        BunsekiJouhou(errorNumber, true);
                        break;
                    default:
                        reservedFocus = obic7MultilineCheckGridDetail.GetColumnObject(rowNo, errorNumber);
                        break;
                }
                e.Cancel = true;
                return;
            }
        }

        #endregion

        #region カラム単位チェック

        /// <summary>
        /// カラム単位チェック
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo"></param>
        /// <param name="columnNo"></param>
        private void obic7MultilineCheckGridDetail_ColumnItemValidating(object sender, CancelEventArgs e, int rowNo, int columnNo)
        {
            //エラー区分
            int errorKBN = 0;

            //読取専用時は処理なし
            if (obic7MultilineCheckGridDetail.ReadOnly == true)
            {
                return;
            }

