                            ShouhizeiKeisan(rowNo, "Kasi", kingaku, zeigaku);
                            //合計額の計算
                            RecalcTotalForRowChenge(maeKingaku, maeZeigaku, GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kasi", "Kingaku"), GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, "Kasi", "Zeigaku"), KBN_TAISHAKU_KASIKATA);
                        }

                        break;
                    case COL_KASIZEIHONTAICD:
                        //貸方消費税本体コード
                        if (CheckZeiHontaiCD(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKanjouToKingaku(rowNo, KBN_TAISHAKU_KASIKATA, 7);
                        break;
                    case COL_KASIKINGAKU:
                        //貸方金額
                        if (CheckKingaku(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 1);

                        break;
                    case COL_KASIZEIGAKU:
                        //貸方税額
                        if (CheckZeigaku(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }

                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 1);
                        break;
                    case COL_KASIBUNSEKICD1:
                        //貸方分析コード1
                        if (CheckBunsekiCD(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT, 1) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 2);
                        break;
                    case COL_KASIBUNSEKICD2:
                        //貸方分析コード2
                        if (CheckBunsekiCD(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT, 2) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 3);
                        break;
                    case COL_KASIBUNSEKICD3:
                        //貸方分析コード3
                        if (CheckBunsekiCD(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT, 3) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 4);
                        break;
                    case COL_KASISIKINCD:
                        //貸方資金コード
                        if (CheckBunsekiCD(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT, 6) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 6);
                        break;
                    // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                    case COL_KASIPROJECTCD:
                        //貸方プロジェクトコード
                        if (CheckBunsekiCD(rowNo, KBN_TAISHAKU_KASIKATA, KBN_KOUMOKUCHK_INPUT, 7) == KBN_CHECK_NG_CANCEL)
                        {
                            e.Cancel = true;
                            break;
                        }
                        //項目入力時フォーカスのセットを行う
                        SetFocusFromKingakuToTekiyou(rowNo, KBN_TAISHAKU_KASIKATA, 7);
                        break;
                    // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                    case COL_MEISAITEKIYOU:
                        //明細摘要
                        CheckMeisaiTekiyou(rowNo, KBN_KOUMOKUCHK_INPUT);
                        break;
                    default:
                        break;
                }
            }

            //エンターフラグリセット
            enterKeyDownFlg = false;

            return;
        }

        #endregion

        #region 行挿入時のイベント
        /// <summary>
        /// 行挿入時のイベント
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo"></param>
        private void obic7MultilineCheckGridDetail_RowInserting(object sender, WinAToolUI.Obic7MultilineCancelEventArgs e, int rowNo)
        {

            //行挿入時の場合
            if (gyouSounyuuFlg == true)
            {
                //待避配列データ初期化
                tempActiveInputDataRow = obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].NewRow();

                //ワークの行番号インクリメント処理
                SQLExecuteNonQueryMain(MakeSQLInsertAraigaeWKSiwakeMeisaiGyou(sounyuuGyouNO));

                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                //本支店メモ情報ワークの行番号インクリメント処理
                SQLExecuteNonQueryMain(MakeSQLAraigaeMemoWorkTableGyou_Insert(sounyuuGyouNO));
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
            }
            else
            {
                for (int i = COL_COUNT; i < COL_DATACOUNT; i++)
                {
                    //更新項目に待避配列データをセット
                    e.InsertedRow[i] = tempActiveInputDataRow[i];
                }
            }

            //挿入処理
            SQLExecuteNonQueryMain(MakeSQLInsertMeisaiWorkTable(e.InsertedRow));

            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //本支店メモ情報ワーク挿入処理
            SQLExecuteNonQueryMain(MakeSQLInsertMemoWorkTable(e.InsertedRow, true));
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

            //行挿入時の場合
            if (gyouSounyuuFlg == true)
            {
                //挿入以降の行番号の洗い換えを行う
                ResetRowNo(sounyuuGyouNO, 1);

                SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_GYOUNO, sounyuuGyouNO);
            }
            //行追加の場合
            else
            {
                //最大行をセット
                GetNumberColumn(rowNo, COL_GYOUNO).Value = GetMaxRowNo() + 1;
            }

            //現在行を前回行として待避
            prevGyouNO = ComATool.Function.AnyToInt32(GetNumberColumn(rowNo, COL_GYOUNO).Value);

        }

        #endregion

        #region 行挿入後のイベント
        /// <summary>
        /// 行挿入後のイベント
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="args"></param>
        /// <param name="rowNo"></param>
        private void obic7MultilineCheckGridDetail_RowInserted(object sender, WinAToolUI.Obic7MultilineEventArgs args, int rowNo)
        {
            if (gyouSounyuuFlg == false)
            {
                int seq = GetBaseDataInnerSeq(rowNo);

                for (int i = COL_COUNT; i < COL_DATACOUNT; i++)
                {
                    //待避配列データから内部データにセット
                    obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows[seq][i] = tempActiveInputDataRow[i];
                }

                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                //メモ使用フラグ = 1(使用する) の場合
                if (this.memoSiyouFlag == KBN_MEMOSIYOU_YES)
                {
                    for (int i = 0; i < DSPLAY_ROW_COUNT; i++)
                    {
                        //メモ色
                        int kariRValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO_RVALUE));
                        int kariGValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO_GVALUE));
                        int kariBValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO_BVALUE));
                        int kasiRValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO_RVALUE));
                        int kasiGValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO_GVALUE));
                        int kasiBValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO_BVALUE));
                        //メモ有無(メモ色RGBがすべて0でなければメモ登録済みとする)
                        bool hasKariMemo = (kariRValue != 0) && (kariGValue != 0) && (kariBValue != 0);
                        bool hasKasiMemo = (kasiRValue != 0) && (kasiGValue != 0) && (kasiBValue != 0);

                        //明細部の全行に対してメモ情報の使用可否制御を行う

                        //画面.[借方総勘定科目コード]が入力されている場合
                        if (!string.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIKANJOUCD)))
                        {
                            //画面.[借方メモ情報]ボタンを使用可能とする
                            this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKariMemo").Enabled = true;
                            //メモがあればメモ情報をボタンにセットする
                            if (hasKariMemo)
                            {
                                this.SetMemoInfo(i, KBN_TAISHAKU_KARIKATA, Color.FromArgb(kariRValue, kariGValue, kariBValue)
                                                , ComATool.Function.AnyToString(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO)));
                            }
                            else
                            {
                                this.SetMemoInfo(i, KBN_TAISHAKU_KARIKATA, this.defaultButtonColor, string.Empty);
                            }
                        }
                        else
                        {
                            //画面.[借方メモ情報]ボタンを使用不可とする
                            this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKariMemo").Enabled = false;
                            this.SetMemoInfo(i, KBN_TAISHAKU_KARIKATA, this.defaultButtonColor, string.Empty);
                        }
                        //画面.[貸方総勘定科目コード]が入力されている場合
                        if (!string.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIKANJOUCD)))
                        {
                            //画面.[貸方メモ情報]ボタンを使用可能とする
                            this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKasiMemo").Enabled = true;
                            //メモがあればメモ情報をボタンにセットする
                            if (hasKasiMemo)
                            {
                                this.SetMemoInfo(i, KBN_TAISHAKU_KASIKATA, Color.FromArgb(kasiRValue, kasiGValue, kasiBValue)
                                                , ComATool.Function.AnyToString(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO)));
                            }
                            else
                            {
                                this.SetMemoInfo(i, KBN_TAISHAKU_KASIKATA, this.defaultButtonColor, string.Empty);
                            }
                        }
                        else
                        {
                            //画面.[貸方メモ情報]ボタンを使用不可とする
                            this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKasiMemo").Enabled = false;
                            this.SetMemoInfo(i, KBN_TAISHAKU_KASIKATA, this.defaultButtonColor, string.Empty);
                        }
                    }
                }
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
            }
            else
            {
                //行挿入フラグリセット
                gyouSounyuuFlg = false;

                //追加行の借方総勘定科目にフォーカスセット
                obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KARIKANJOUCD).Focus();
            }
        }
        #endregion

        #region 行更新時のイベント

        /// <summary>
        /// 行更新時のイベント
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo"></param>
        private void obic7MultilineCheckGridDetail_RowUpdating(object sender, WinAToolUI.Obic7MultilineCancelEventArgs e, int rowNo)
        {
            int seq = GetBaseDataInnerSeq(rowNo);

            if (seq != -1)
            {
                for (int n = COL_COUNT; n < COL_DATACOUNT; n++)
                {
                    //待避配列データから内部データにセット
                    obic7MultilineCheckGridDetail.BaseDataSet.Tables[0].Rows[seq][n] = tempActiveInputDataRow[n];
                }
            }

            for (int i = COL_COUNT; i < COL_DATACOUNT; i++)
            {
                //更新項目に待避配列データをセット
                e.InsertedRow[i] = tempActiveInputDataRow[i];
            }

            //更新処理
            SQLExecuteNonQueryMain(MakeSQLUpdateMeisaiWorkTable(e));

            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //本支店メモ情報ワーク更新処理
            SQLExecuteNonQueryMain(MakeSQLUpdateMemoWorkTable(e));
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
        }

        #endregion

        #region 行削除時のイベント
        /// <summary>
        /// 行削除時のイベント
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo"></param>
        private void obic7MultilineCheckGridDetail_RowDeleting(object sender, WinAToolUI.Obic7MultilineCancelEventArgs e, int rowNo)
        {
            //削除行番号取得
            int gyouNo = ComATool.Function.AnyToInt32(GetNumberColumn(rowNo, COL_GYOUNO).Value);

            //ワークデータ行削除
            SQLExecuteNonQueryMain(MakeSQLDeleteMeisaiWorkTableGyou(gyouNo));

            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //本支店メモ情報ワークデータ行削除
            SQLExecuteNonQueryMain(MakeSQLDeleteMemoWorkTable(gyouNo));
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

            //ワークの削除行以降の行番号の洗い換えを行う
            SQLExecuteNonQueryMain(MakeSQLDeleteAraigaeWKSiwakeMeisaiGyou(gyouNo));

            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            //本支店メモ情報ワークの削除行以降の行番号の洗い換えを行う
            SQLExecuteNonQueryMain(MakeSQLAraigaeMemoWorkTableGyou_Delete(gyouNo));
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

            //確認メッセージでYesを選択した場合
            //削除行の金額を合計よりマイナス
            MinusTotal(rowNo);
            //削除行以降の行番号の洗い換えを行う
            ResetRowNo(gyouNo, 2);
        }

        #endregion

        #region 明細コントロール内のコントロールがフォーカスを取得した際の処理

        /// <summary>
        /// 明細コントロール内のコントロールがフォーカスを取得した際の処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo"></param>
        /// <param name="columnNo"></param>
        private void obic7MultilineCheckGridDetail_ColumnItemEnter(object sender, EventArgs e, int rowNo, int columnNo)
        {
            //行変更時
            if (prevGyouNO != ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_GYOUNO)))
            {
                //待避配列データを洗い換えする
                RefreshTempActiveInputDataRow(rowNo);

                //ツールチップテキスト設定
                SetToolTip(1);

                //ツールチップテキスト設定
                SetActiveRowToolTip(1, rowNo);
            }

            //現在行を前回行として待避
            prevGyouNO = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_GYOUNO));

            //コントロールに応じて処理を分岐
            switch (((Control)sender).Name)
            {
                //1対N仕訳判断によるフォーカス振り分け用ダミー項目
                case "obic7TextStringDummy":
                    if (obic7MultilineCheckGridDetail.ReadOnly == true)
                    {
                        //借方総勘定科目にフォーカスセット
                        GetStringColumn(rowNo, COL_KARIKANJOUCD).Focus();
                    }
                    else
                    {
                        //1対N仕訳によるフォーカス判断用処理
                        if (nSiwakeFocusFlg == true)
                        {
                            nSiwakeFocusFlg = false;

                            if (nSiwakeFocusKoumoku == true)
                            {
                                //貸方総勘定科目にフォーカスセット
                                GetStringColumn(rowNo, COL_KASIKANJOUCD).Focus();
                            }
                            else
                            {
                                //借方総勘定科目にフォーカスセット
                                GetStringColumn(rowNo, COL_KARIKANJOUCD).Focus();
                            }
                        }
                        else
                        {
                            //借方総勘定科目にフォーカスセット
                            GetStringColumn(rowNo, COL_KARIKANJOUCD).Focus();
                        }
                    }
                    //ダミー項目のTabStopをfalseに
                    ((Control)sender).TabStop = false;
                    break;
                //借方総勘定科目CD
                case "obic7TextStringKariKanjouCD":
                //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
                //借方補助科目CD
                case "obic7TextStringKariHojoCD":
                    //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応
                    //入力前金額退避
                    prevKingaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIKINGAKU));
                    //入力前消費税額退避
                    prevZeigaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIZEIGAKU));
                    //入力前税込区分額退避
                    prevZeikomiKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KARIZEIKOMIKBN));
                    //ファンクションボタン切替
                    if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
                    {
                        //新規･修正モード
                        //2008/05/14 変更 N.Sasaki 開始 分析情報画面起動可能に変更
                        //                        base.SetFunctionButton(false, false, true, true, true, true, true, true, false, true, true, true);
                        base.SetFunctionButton(false, false, true, true, true, true, true, true, true, true, true, true);
                        //2008/05/14 変更 N.Sasaki 終了
                    }
                    else if (obic7ComboBoxMode.Text == MODE_DELETE)
                    {
                        //削除モード
                        //2008/05/14 変更 N.Sasaki 開始 分析情報画面起動可能に変更
                        //                        base.SetFunctionButton(false, false, true, false, true, false, false, false, false, false, false, true);
                        base.SetFunctionButton(false, false, true, false, true, false, false, false, true, false, false, true);
                        //2008/05/14 変更 N.Sasaki 終了
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    else if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        //添付モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, true, true, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                    else
                    {
                        //照会モード
                        //2008/05/14 変更 N.Sasaki 開始 分析情報画面起動可能に変更
                        //                        base.SetFunctionButton(false, false, false, false, true, false, false, false, false, false, false, true);
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, true, false, false, true);
                        //2008/05/14 変更 N.Sasaki 終了
                    }
                    break;
                //貸方総勘定科目CD
                case "obic7TextStringKasiKanjouCD":
                //2012/10/05 K.Morita 追加 ST (M04851)平成26年消費税改正対応
                //借方補助科目CD
                case "obic7TextStringKasiHojoCD":
                    //2012/10/05 K.Morita 追加 ED (M04851)平成26年消費税改正対応
                    //入力前金額退避
                    prevKingaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKINGAKU));
                    //入力前消費税額退避
                    prevZeigaku = ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIZEIGAKU));
                    //入力前税込区分額退避
                    prevZeikomiKBN = ComATool.Function.AnyToInt32(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIZEIKOMIKBN));
                    //ファンクションボタン切替
                    if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
                    {
                        //新規･修正モード
                        //2008/05/14 変更 N.Sasaki 開始 分析情報画面起動可能に変更
                        //                        base.SetFunctionButton(false, false, true, true, true, true, true, true, false, true, true, true);
                        base.SetFunctionButton(false, false, true, true, true, true, true, true, true, true, true, true);
                        //2008/05/14 変更 N.Sasaki 終了
                    }
                    else if (obic7ComboBoxMode.Text == MODE_DELETE)
                    {
                        //削除モード
                        //2008/05/14 変更 N.Sasaki 開始 分析情報画面起動可能に変更
                        //                        base.SetFunctionButton(false, false, true, false, true, false, false, false, false, false, false, true);
                        base.SetFunctionButton(false, false, true, false, true, false, false, false, true, false, false, true);
                        //2008/05/14 変更 N.Sasaki 終了
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
