                        if (GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIZEIKOMIKBN) == 3 && GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKINGAKU) != null)
                        {
                            if (ComATool.Function.AnyToDecimal(obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIKINGAKU).Text) <= ((WinATool.UI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIKINGAKU)).MaxValue
                                && ComATool.Function.AnyToDecimal(obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIKINGAKU).Text) >= ((WinATool.UI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIKINGAKU)).MinValue
                                && ComATool.Function.AnyToDecimal(obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIZEIGAKU).Text) <= ((WinATool.UI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIZEIGAKU)).MaxValue
                                && ComATool.Function.AnyToDecimal(obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIZEIGAKU).Text) >= ((WinATool.UI.Obic7TextNumber)obic7MultilineCheckGridDetail.GetColumnObject(rowNo, COL_KASIZEIGAKU)).MinValue
                                )
                            {
                                SetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKINGAKU,
                                    ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIKINGAKU)) +
                                    ComATool.Function.AnyToDecimal(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, rowNo, COL_KASIZEIGAKU)));
                            }
                        }
                        //2009/08/05 OBIC H.Sudo 変更 開始  (M04264)貸借不一致で登録できてしまう不具合を改修
                        isKingakuEditing = true;
                        //2009/08/05 OBIC H.Sudo 変更 終了

                    }

                    break;
                //明細摘要
                case "obic7TextStringMeisaiTekiyou":
                    //ファンクションボタン切替
                    if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
                    {
                        //新規･修正モード
                        base.SetFunctionButton(false, false, true, true, true, true, true, true, false, true, true, true);
                    }
                    else if (obic7ComboBoxMode.Text == MODE_DELETE)
                    {
                        //削除モード
                        base.SetFunctionButton(false, false, true, false, true, false, false, false, false, false, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    else if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        //添付モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, false, true, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                    else
                    {
                        //照会モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, false, false, false, true);
                    }
                    break;
                //貸方分析CD1
                case "obic7TextStringKasiBunsekiCD1":
                //貸方分析CD2
                case "obic7TextStringKasiBunsekiCD2":
                //貸方分析CD3
                case "obic7TextStringKasiBunsekiCD3":
                //貸方資金CD
                case "obic7TextStringKasiSikinCD":
                // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                //貸方プロジェクトCD
                case "obic7TextStringKasiProjectCD":
                // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                //借方分析CD1
                case "obic7TextStringKariBunsekiCD1":
                //借方分析CD2
                case "obic7TextStringKariBunsekiCD2":
                //借方分析CD3
                case "obic7TextStringKariBunsekiCD3":
                //借方資金CD
                case "obic7TextStringKariSikinCD":
                // 2013/05/15 追加 I.Nakagawa 開始 (GX)
                //借方プロジェクトCD
                case "obic7TextStringKariProjectCD":
                    // 2013/05/15 追加 I.Nakagawa 終了 (GX)
                    //ファンクションボタン切替
                    if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
                    {
                        //新規･修正モード
                        base.SetFunctionButton(false, false, true, true, true, true, true, true, true, true, true, true);
                    }
                    else if (obic7ComboBoxMode.Text == MODE_DELETE)
                    {
                        //削除モード
                        base.SetFunctionButton(false, false, true, false, true, false, false, false, true, false, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    else if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        //添付モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, true, true, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                    else
                    {
                        //照会モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, true, false, false, true);
                    }
                    break;
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
                //メモボタン
                case "obic7ButtonWithLogicKariMemo":
                case "obic7ButtonWithLogicKasiMemo":
                    //ファンクションボタン切替
                    if ((obic7ComboBoxMode.Text == MODE_INSERT) || (obic7ComboBoxMode.Text == MODE_UPDATE))
                    {
                        //新規･修正モード
                        base.SetFunctionButton(false, false, true, false, true, true, true, true, true, true, true, true);
                    }
                    else if (obic7ComboBoxMode.Text == MODE_DELETE)
                    {
                        //削除モード
                        base.SetFunctionButton(false, false, true, false, true, false, false, false, true, false, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
                    else if (obic7ComboBoxMode.Text == MODE_TENPU)
                    {
                        //添付モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, true, true, false, true);
                    }
                    // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
                    else
                    {
                        //照会モード
                        base.SetFunctionButton(false, false, false, false, true, false, false, false, true, false, false, true);
                    }
                    break;
                // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
            }

        }

