        #region 明細内ボタンクリック処理
        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
        /// <summary>
        /// 明細内のボタンをクリックしたときの処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        /// <param name="rowNo">コントロールの行NO</param>
        private void obic7MultilineCheckGridDetail_ColumnButtonClick(object sender, EventArgs e, int rowNo)
        {
            switch (((Control)sender).Name)
            {
                case "obic7ButtonWithLogicKariMemo":
                case "obic7ButtonWithLogicKasiMemo":
                    this.GetMemoInfo(rowNo);
                    break;
                default:
                    break;
            }
        }
        // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了
        #endregion

        #region 明細コントロール内スクロール移動後の処理
        /// <summary>
        /// 明細コントロール内スクロール移動後の処理
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void obic7MultilineCheckGridDetail_MoveScrollAfter(object sender, EventArgs e)
        {
            //フォーカスが明細外の場合はここでツールチップを再表示する
            if (obic7MultilineCheckGridDetail.HasControl(ActiveControl) == false)
            {
                SetToolTip(1);
            }

            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 開始
            for (int i = 0; i < DSPLAY_ROW_COUNT; i++)
            {
                //メモ使用フラグ = 1(使用する) の場合
                if (this.memoSiyouFlag == KBN_MEMOSIYOU_YES)
                {
                    //メモ色
                    int kariRValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO_RVALUE));
                    int kariGValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO_GVALUE));
                    int kariBValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO_BVALUE));
                    int kasiRValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO_RVALUE));
                    int kasiGValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO_GVALUE));
                    int kasiBValue = ComATool.Function.AnyToInt16(GetNumberColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO_BVALUE));
                    //メモ有無(メモ色RGBがすべて0でなければメモ登録済みとする)
                    bool hasKariMemo = (kariRValue != 0) && (kariGValue != 0) && (kariBValue != 0);
                    bool hasKasiMemo = (kasiRValue != 0) && (kasiGValue != 0) && (kasiBValue != 0);

                    //明細部の全行に対してメモ情報の使用可否制御を行う

                    //画面.[借方総勘定科目コード]が入力されている場合
                    if (!string.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIKANJOUCD)))
                    {
                        //画面.[借方メモ情報]ボタンを使用可能とする
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKariMemo").Enabled = true;
                        //メモがあればメモ情報をボタンにセットする
                        if (hasKariMemo)
                        {
                            this.SetMemoInfo(i, KBN_TAISHAKU_KARIKATA, Color.FromArgb(kariRValue, kariGValue, kariBValue)
                                            , ComATool.Function.AnyToString(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KARIMEMO)));
                        }
                        else
                        {
                            this.SetMemoInfo(i, KBN_TAISHAKU_KARIKATA, this.defaultButtonColor, string.Empty);
                        }
                    }
                    else
                    {
                        //画面.[借方メモ情報]ボタンを使用不可とする
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKariMemo").Enabled = false;
                        this.SetMemoInfo(i, KBN_TAISHAKU_KARIKATA, this.defaultButtonColor, string.Empty);
                    }
                    //画面.[貸方総勘定科目コード]が入力されている場合
                    if (!string.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIKANJOUCD)))
                    {
                        //画面.[貸方メモ情報]ボタンを使用可能とする
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKasiMemo").Enabled = true;
                        //メモがあればメモ情報をボタンにセットする
                        if (hasKasiMemo)
                        {
                            this.SetMemoInfo(i, KBN_TAISHAKU_KASIKATA, Color.FromArgb(kasiRValue, kasiGValue, kasiBValue)
                                            , ComATool.Function.AnyToString(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, i, COL_KASIMEMO)));
                        }
                        else
                        {
                            this.SetMemoInfo(i, KBN_TAISHAKU_KASIKATA, this.defaultButtonColor, string.Empty);
                        }
                    }
                    else
                    {
                        //画面.[貸方メモ情報]ボタンを使用不可とする
                        this.obic7MultilineCheckGridDetail.GetMultilineUnrelatedObject(i, "obic7ButtonWithLogicKasiMemo").Enabled = false;
                        this.SetMemoInfo(i, KBN_TAISHAKU_KASIKATA, this.defaultButtonColor, string.Empty);
                    }
                }
            }
            // 2013/09/04 追加 M.Shinbo GX対応(M00020:メモ機能の実装) 終了

            //  2013/06/28  変更   T.Shiraishi    GX対応(M00017:明細行に行番号表示) 開始↓
            this.SuspendLayout();

            //描画処理
            this.DrawRowNumberColumn(this.obic7MultilineCheckGridDetail, this.obic7TextNumberGyouNO.ColumnNumber, this.obic7LabelNumberGyou.Name);

            this.ResumeLayout();
            //  2013/06/28  変更   T.Shiraishi    GX対応(M00017:明細行に行番号表示) 終了↑

        }
        #endregion

        #region 明細コントロールフォーカス喪失時
        /// <summary>
        /// 明細コントロールフォーカス喪失時
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void obic7MultilineCheckGridDetail_Leave(object sender, CancelEventArgs e)
        {
            //前回行番号リセット
            prevGyouNO = -1;

            //2009/08/05 OBIC H.Sudo 変更 開始  (M04264)貸借不一致で登録できてしまう不具合を改修
            //金額編集抑制用フラグを制御
            isKingakuEditing = false;
            //2009/08/05 OBIC H.Sudo 変更 終了
        }
        #endregion

        //2017/04/14 変更 K.Fujita (54275-59278)【スキャナ保存要件緩和対応】電子証憑ボタンの追加  開始
        #region 電子証憑ボタン押下時
        /// <summary>
        /// 電子証憑ボタン押下時
        /// </summary>
        /// <param name="sender"></param>
        /// <param name="e"></param>
        private void obic7ButtonDensiShouhyou_Click(object sender, EventArgs e)
        {
            //明細の借方・貸方ともに未入力の場合、エラーとする。
            if (obic7MultilineCheckGridDetail.GetDisplayedData().Count == 0)
            {
                //エラーメッセージを表示
                WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30274", null, null, GetType(),
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                    WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);
                //借方総勘定科目にフォーカスセット
                obic7MultilineCheckGridDetail.GetColumnObject(0, COL_KARIKANJOUCD).Focus(); ;

                return;
            }

            // 2022/07/27  追加   Y.Matuzawa  (205476)【電子証憑対応】その他添付の利用設定のずれをエラーとする ↓
            //電子証憑OP導入フラグ = true(導入済)の場合、その他添付ファイルの利用設定が会計マスタと証憑基盤マスタでずれている場合、エラーとする
            if (isAvailableEvidence)
            {
                var fileControlInfo = WinEvidence.Evidence.GetAttachFileControlInfo("M_ET", "M_Evi");
                //ファイル添付制御マスタに該当ジョブのレコードがない状態でこのメソッドが呼ばれることはないため、Dataがnullのときの考慮はしない
                if ((fileControlInfo.Data.IsAvailableCommonFile && sonotaTenpuFileRiyouFLG == 0)   //その他添付ファイル利用フラグ 0：利用しない
                    // 2024/02/05 修正 K.Imoto (232265)【本支店仕訳入力】【横展開230912】当ジョブでその他添付だけ利用しないよう設定した場合に、添付ボタン押下時に「その他添付ファイルは利用できない設定になっています」エラーになってしまいます。開始
                    //|| (!fileControlInfo.Data.IsAvailableCommonFile && sonotaTenpuFileRiyouFLG == 1)) //その他添付ファイル利用フラグ 1：利用する
                    )
                    // 2024/02/05 修正 K.Imoto (232265)【本支店仕訳入力】【横展開230912】当ジョブでその他添付だけ利用しないよう設定した場合に、添付ボタン押下時に「その他添付ファイルは利用できない設定になっています」エラーになってしまいます。開始
                {
                    //エラー表示
                    WinAToolLogicUI.Obic7MessageBox.Show(SYSTEMCATEGORYCD, CUSTOMIZESEQ, MESSAGE_CD1, "30410", null, null, GetType(),
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxButtons.OK,
                                                        WinAToolLogicUI.Obic7MessageBox.Obic7MessageBoxDefaultButton.Button1);

                    obic7ButtonWithLogicDensiShouhyou.Focus();
                    return;
                }
            }
            // 2022/07/27  追加   Y.Matuzawa  (205476)【電子証憑対応】その他添付の利用設定のずれをエラーとする ↑

            //表示対象の電子証憑Guidを取得
            DataTable evidence = new DataTable();
            var evidenceGetParams = new List<Guid>();
            string denpyouNO;
            if (obic7ComboBoxMode.Text == MODE_INSERT)
            {
                SQLGetDataTable(MakeSQLSelectEvidence(0), ref evidence, false);
                denpyouNO = "";
            }
            else
            {
                SQLGetDataTable(MakeSQLSelectEvidence(systemDenpyouNO), ref evidence, false);
                denpyouNO = obic7TextStringCalledDenpyouNO.Value;
            }
            if (evidence.Rows.Count != 0)
            {
                if (!string.IsNullOrEmpty(evidence.Rows[0]["EvidenceGuid"].ToString()))
                {
                    for (int i = 0; i < evidence.Rows.Count; i++)
                    {
                        {
                            evidenceGetParams.Add(ComATool.Function.AnyToGuid(evidence.Rows[i]["EvidenceGuid"].ToString()).Value);
                        };
                    }
                }
            }
            hyouziTaishouGuids = evidenceGetParams;

            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 開始
            ////「画面.[処理モード]=[新規]」もしくは「画面.[処理モード]=[修正]
            //// 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
            //////かつ 呼び出した伝票.[システム分類]=[10][12](財務会計での登録)」の場合
            ////if ((obic7ComboBoxMode.Text == MODE_INSERT) || ((obic7ComboBoxMode.Text == MODE_UPDATE) && ((systemCategory == 10) || (systemCategory == 12))))
            //if (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE)
            ////2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
            //「画面.[処理モード]=[新規]」もしくは「画面.[処理モード]=[修正]」もしくは「画面.[処理モード]=[添付]」
            if (obic7ComboBoxMode.Text == MODE_INSERT || obic7ComboBoxMode.Text == MODE_UPDATE || obic7ComboBoxMode.Text == MODE_TENPU)
            // 2023/12/20 修正 K.Imoto (228137-230110-230115)【電子帳簿改善2023】最終承認後添付 終了
            {
                var taishouGuids = new List<Guid>();
                if (shokiGuids != null)
                {
                    foreach (var item in shokiGuids)
                    {
                        taishouGuids.Add(item);
                    }
                }
                //<会計共通>電子証憑基盤接続クラス.[電子証憑登録呼出]を使用して、
                //電子証憑基盤.[電子証憑登録]を起動する。
                DataTable displayTargetEvidences = new DataTable();
                var EvidenceGuids = new List<Guid>();
                decimal? defaultKingaku = null;
                string defaultTorihikisakiName = "";
                string defaultHinName = "";
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                DateTime? shokiDate = null;
                shokiDate = ComATool.Function.AnyToDateTime(obic7TextDatetimeHasseiDate.Value);
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
                if (!string.IsNullOrEmpty(obic7TextNumberTotalKariSougaku.Text))
                {
                    defaultKingaku = ComATool.Function.AnyToDecimal(obic7TextNumberTotalKariSougaku.Value);
                }

                if (!string.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, 0, "Kari", "TorihikisakiCD")))
                {
                    DataTable Torihikisaki = new DataTable();
                    //マスタよりデータを取得
                    Torihikisaki = WinPToolSearchCom.P0000MS_Torihikisaki.SelectByKaiteiDate(
                          GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, 0, "Kari", "TorihikisakiCD")
                        , (DateTime)obic7TextDatetimeHasseiDate.Value
                        , 0
                        , ""
                        );

                    //2022/07/25 修正 Y.Matuzawa (205943)【電子証憑対応】取引先マスタで正式名の登録なし・社内用取引先名のみ登録の場合に添付ダイアログで取引先名が初期表示できない 対応 ↓
                    //defaultTorihikisakiName = Torihikisaki.Rows[0]["TorihikisakiName1"].ToString() + Torihikisaki.Rows[0]["TorihikisakiName2"].ToString();
                    if (string.IsNullOrEmpty(Torihikisaki.Rows[0]["TorihikisakiName1"].ToString()) && string.IsNullOrEmpty(Torihikisaki.Rows[0]["TorihikisakiName2"].ToString()))
                    {
                        defaultTorihikisakiName = Torihikisaki.Rows[0]["TorihikisakiShanaiName"].ToString();
                    }
                    else
                    {
                        defaultTorihikisakiName = Torihikisaki.Rows[0]["TorihikisakiName1"].ToString() + Torihikisaki.Rows[0]["TorihikisakiName2"].ToString();
                    }
                    //2022/07/25 修正 Y.Matuzawa (205943)【電子証憑対応】取引先マスタで正式名の登録なし・社内用取引先名のみ登録の場合に添付ダイアログで取引先名が初期表示できない 対応 ↑
                }
                else if (!string.IsNullOrEmpty(GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, 0, "Kasi", "TorihikisakiCD")))
                {
                    DataTable Torihikisaki = new DataTable();
                    //マスタよりデータを取得
                    Torihikisaki = WinPToolSearchCom.P0000MS_Torihikisaki.SelectByKaiteiDate(
                        GetStringColumnValue(KBN_KOUMOKUCHK_INPUT, 0, "Kasi", "TorihikisakiCD")
                        , (DateTime)obic7TextDatetimeHasseiDate.Value
                        , 0
                        , ""
                        );

                    //2022/07/25 修正 Y.Matuzawa (205943)【電子証憑対応】取引先マスタで正式名の登録なし・社内用取引先名のみ登録の場合に添付ダイアログで取引先名が初期表示できない 対応 ↓
                    //defaultTorihikisakiName = Torihikisaki.Rows[0]["TorihikisakiName1"].ToString() + Torihikisaki.Rows[0]["TorihikisakiName2"].ToString();
                    if (string.IsNullOrEmpty(Torihikisaki.Rows[0]["TorihikisakiName1"].ToString()) && string.IsNullOrEmpty(Torihikisaki.Rows[0]["TorihikisakiName2"].ToString()))
                    {
                        defaultTorihikisakiName = Torihikisaki.Rows[0]["TorihikisakiShanaiName"].ToString();
                    }
                    else
                    {
                        defaultTorihikisakiName = Torihikisaki.Rows[0]["TorihikisakiName1"].ToString() + Torihikisaki.Rows[0]["TorihikisakiName2"].ToString();
                    }
                    //2022/07/25 修正 Y.Matuzawa (205943)【電子証憑対応】取引先マスタで正式名の登録なし・社内用取引先名のみ登録の場合に添付ダイアログで取引先名が初期表示できない 対応 ↑
                }
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                //WinEvidence.Evidence.ShowInputEvidence(denpyouNO, hyouziTaishouGuids, taishouGuids, null, defaultKingaku, defaultTorihikisakiName, defaultHinName, out displayTargetEvidences, out EvidenceGuids);
                ////電子証憑登録画面で削除された電子証憑データを削除、追加する。
                //UpdateEvidenceData(displayTargetEvidences);
                //evidenceKensuu = displayTargetEvidences.Rows.Count;
                ////画面.[電子証憑枚数]に電子証憑関連クラスで取得した電子証憑の枚数を表示する。
                //this.obic7LabelStringDensiShouhyou.Text = "電子証憑" + evidenceKensuu.ToString() + "枚";

                //電子証憑一覧照会呼出
                var result = WinEvidence.Evidence.ShowEvidenceDialog(fileKidouGuid, (DateTime)shokiDate, (DateTime)shokiDate, (decimal)defaultKingaku, defaultHinName, defaultTorihikisakiName, "M_ET", "M_Evi", SYSTEMCATEGORYCD);
                if (result == System.Windows.Forms.DialogResult.OK)
                {
                    //電子証憑ワークを削除する
                    DeleteEvidenceWK();

                    //<会計共通>電子証憑基盤接続クラス.[電子証憑伝票WK取得処理]を使用して伝票WKの情報を取得する
                    //複数電子証憑データ のうち、データ状態が4:論理削除のもの以外を電子証憑ワークにINSERTする
                    //データ状態：1:未確定、2:新規登録、3:修正、4:論理削除、5:何もしない、6:復活_未確定、7:復活、8:紐づけ_未確定、9:紐づけ
                    var denpyouWKData = WinEvidence.Evidence.GetDenpyouWK(fileKidouGuid, false, false, true);
                    var updatableTaishou = denpyouWKData.AsEnumerable().Where(x => x["State"].ToString() != "4");

                    if (updatableTaishou.Count() > 0)
                    {
                        var updateTaishou = updatableTaishou.CopyToDataTable();

                        //電子証憑ワークに更新する
                        TaihiUpdateData(updateTaishou);
                        InsertEvidenceWK();
                    }
                }

                this.obic7LabelStringDensiShouhyou.Text = GetEvidenceMaisuu();
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
            }
            else
            {
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】開始
                ////<会計共通>電子証憑基盤接続クラス.[電子証憑照会呼出]を使用して、
                ////電子証憑基盤.[電子証憑照会]を起動する。
                //WinEvidence.Evidence.ShowEvidence(hyouziTaishouGuids);
                //電子証憑一覧照会呼出
                WinEvidence.Evidence.ShowEvidenceDialog(fileKidouGuid, "M_ET", "M_Evi", SYSTEMCATEGORYCD);
                // 2022/02/07 修正 M.Shimada (200046-200414-200483)【電子証憑対応】【本支店仕訳入力】終了
            }
        }
